package.preload["asi.nlu.assertions"] = function(...)
-- asi.nlu.assertions: record text -> typed assertions.
-- The extractor reuses the interpreter's lexicon and parse primitives, so a paraphrase in the data ("X founded Y", "Y was started by X", "the founder of
-- Y is X") lands on the SAME relation id and role direction as the question that will be asked about it.  Output per assertion:
--   rel, from, to (entity {key,type,status} or literal), polarity, modality, tense, former/current markers, validity interval or event time,
--   provenance (record, sentence, byte span).  Sentences that address the reader (imperatives, injection cues) are NEVER mined for facts.
local U = require("asi.nlu.util")
local Lex = require("asi.nlu.lex")
local Lattice = require("asi.nlu.lattice")
local P = require("asi.nlu.parse")
local H = require("asi.nlu.hyp")
local F = require("asi.nlu.frames2")
local Sem = require("asi.nlu.sem")

local A = {}
A.__index = A

local function C(S, k) return S.chunks[k] end
local function barrier(c) return c ~= nil and c.pre ~= nil end
local function other(role) return role == "to" and "from" or "to" end
local cat = P.cat

function A.new(lex, opts)
  opts = opts or {}
  return setmetatable({ lex = lex, meter = opts.meter, max_sentence_units = opts.max_sentence_units or 160 }, A)
end

---------------------------------------------------------------- binding a parsed NP to an entity / literal descriptor
local LITERAL_KINDS = { number = true, temporal = true, quote = true, literal = true }

local function describe_np(S, ctx, np, expected, role)
  if not np then return nil end
  if LITERAL_KINDS[np.head_kind] then
    local c = np.head
    local lit = { kind = np.head_kind, text = P.span_text(S, np) }
    if np.head_kind == "number" and c.number then lit.value = c.number.value; lit.unit = c.number.unit end
    if np.head_kind == "temporal" and c.temporal then lit.lo, lit.hi, lit.year = c.temporal.eff_lo or c.temporal.lo, c.temporal.eff_hi or c.temporal.hi, c.temporal.year end
    local d = { literal = lit, text = lit.text, type = np.head_kind == "number" and "number" or (np.head_kind == "temporal" and "date" or "text") }
    if expected and S.lex:compat(d.type, expected) == -1.0 then d.type_clash = true end
    return d
  end
  -- "88 days", "4 million people": a counted unit noun is a quantity literal when the relation expects a quantity
  if np.count and expected and (expected == "number" or expected == "quantity" or expected == "money") and (np.head_kind == "unknown" or np.head_kind == "typenoun" or np.head_kind == "concept") then
    local lit = { kind = "number", value = np.count, unit = np.head and np.head.form, text = P.span_text(S, np) }
    return { literal = lit, text = lit.text, type = "number" }
  end
  if np.head_kind == "pronoun" then
    -- inside a record, a subject pronoun refers to the record topic (title entity) or the previous sentence's subject, if it agrees in animacy
    local t = ctx.topic
    local feats = np.pron and np.pron.feats or {}
    if t and t.key and not (feats.person == "1" or feats.person == "2") then
      local person_like = t.type and S.lex:isa(t.type, "person")
      local an = tostring(feats.animate or "any")
      local ok = not ((an == "1" and t.type and not person_like) or (an == "0" and person_like))
      if ok then return { key = t.key, text = t.text, type = t.type, status = "resolved_by_topic", via_pronoun = np.pron.form } end
    end
    return { text = P.span_text(S, np), status = "pronoun", head_kind = "pronoun" }
  end
  local b = H.bind_np(S, ctx, np, expected, nil, role)
  -- the descriptor text is the mention WITHOUT its leading determiner ("the quokka" -> "quokka"); the surface span stays recoverable from the offsets
  local text = P.span_text(S, np)
  if np.det and np.head_kind ~= "entity" then text = text:gsub("^%a+%s+", "", 1) end
  -- "CEO Odalys Feurmann": a title in front of a name is not part of the name
  if np.head_kind == "entity" and np.head and np.head.u1 > np.u1 and #(np.mods or {}) > 0 then
    local all_titles = true
    for _, m in ipairs(np.mods) do if not (m.chunk and #(m.chunk.relnouns or {}) > 0) then all_titles = false end end
    if all_titles then text = S.an.original:sub(S.units[np.head.u1].s, S.units[np.u2].e) end
  end
  -- "the city of Grutuburn": the type noun only classifies; the descriptor names the entity itself
  if np.type_noun and np.head_kind == "entity" or (np.type_noun and np.head_kind == "unknown") then
    local u1 = np.type_noun.u2 + 2
    if u1 <= np.u2 then text = S.an.original:sub(S.units[u1].s, S.units[np.u2].e) end
  end
  local d = { text = text, type = b.type or (b.top and b.top.type), status = b.status, head_kind = np.head_kind }
  if b.top and (b.status == "resolved" or b.status == "unseen") then d.key = b.top.id
  elseif b.status == "ambiguous" then
    d.cands = U.map(b.cands or {}, function(c) return { id = c.id, type = c.type, p = c.p } end)
    d.key = nil
  elseif (np.head_kind == "typenoun" or np.head_kind == "concept") and b.senses and b.senses[1] then
    -- concepts are keyed by their lexicon sense, so "capital punishment" in a record and in a question meet at the same key
    d.key = "sense:" .. b.senses[1].id
    d.status = "concept"
    d.type = b.senses[1].type
    d.term = P.core_text(S, np)
  elseif np.head_kind == "typenoun" or np.head_kind == "concept" or np.head_kind == "unknown" then
    d.key = "term:" .. P.core_text(S, np)
    d.status = "term"
  end
  if np.head_kind == "entity" and b.fit == -1.0 then d.type_clash = true end
  return d
end

A.describe_np = describe_np

---------------------------------------------------------------- qualifiers
local function qualifier_range(S, a)
  -- chunks that qualify THIS assertion: a fronted adverbial before the subject, and what follows the object up to the next comma-delimited clause
  local keep = {}
  local first_used = a.used_np[1].c1
  for _, np in ipairs(a.used_np) do if np.c1 < first_used then first_used = np.c1 end end
  for k = S.first, first_used - 1 do keep[k] = true end
  local start = a.end_chunk or (S.last + 1)
  for k = start, S.last do
    local c = C(S, k)
    if c and c.pre and c.pre:find("comma") and not c.temporal then break end
    keep[k] = true
  end
  for k = S.lead_first or S.first, S.first - 1 do keep[k] = true end
  -- the predicate (copula / verb / negation) sits between the NPs
  for k = S.first, S.last do
    if a.copula and a.copula.used[k] then keep[k] = true end
    if a.vp and k >= a.vp.c1 and k <= a.vp.c2 then keep[k] = true end
  end
  for _, k in ipairs(a.copula and a.copula.skipped or {}) do keep[k] = true end
  for _, k in ipairs(a.skipped or {}) do keep[k] = true end
  return keep
end

local function qualifiers(self, S, used, info)
  local q = { polarity = info.neg and "negative" or "positive", modality = "asserted", tense = info.tense or "present", former = info.former }
  local lex = S.lex
  for k = S.lead_first or S.first, S.last do
    local c = C(S, k)
    if c and not c.masked and info.range[k] then
      if not used[k] then
        if P.is_neg(c) or (c.single and (c.unit.form == "never")) then q.polarity = "negative"
        elseif c.temporal then
          local t = c.temporal
          if t.kind == "marker" then
            local w = (t.text or c.form or ""):lower()
            if w == "formerly" or w == "previously" or w == "once" or w == "originally" or w == "historically" or w == "recently" and false then q.former = true end
            if w == "currently" or w == "now" or w == "today" or w == "presently" or w == "still" then q.current = true end
          else
            local lo, hi = t.eff_lo or t.lo, t.eff_hi or t.hi
            local op = t.op
            q.temporal = q.temporal or {}
            q.temporal[#q.temporal + 1] = { op = op or "in", lo = lo, hi = hi, year = t.year, text = t.text or c.form, kind = t.kind }
          end
          used[k] = true
        elseif lex:cue_at("hedge", S.units, c.u1) then q.modality = "hedged"
        elseif lex:cue_at("conditional", S.units, c.u1) then q.modality = "hypothetical" end
      end
    end
  end
  -- "no longer" marks an ended state
  for i = 1, #S.units - 1 do
    if S.units[i].form == "no" and S.units[i + 1].form == "longer" and S.units[i].sent == S.sentence.id then q.former = true; q.polarity = "positive" end
  end
  return q
end

-- turn raw temporal qualifiers into a validity interval (state relations) or an event time (event relations)
local function apply_time(a, q, rel_obj, lex)
  a.former, a.current, a.tense = q.former, q.current, q.tense
  local event = rel_obj and (rel_obj.when ~= nil or rel_obj.event == true or rel_obj.open == true)
  for _, t in ipairs(q.temporal or {}) do
    local op = t.op
    if event then
      -- "founded in 1999": the relation (founder) is not limited to 1999, the EVENT happened then
      a.event_time = a.event_time or { lo = t.lo, hi = t.hi, year = t.year, text = t.text, op = op }
    elseif op == "since" or op == "from" then a.valid_from = a.valid_from or t.lo
    elseif op == "until" or op == "till" or op == "to" then a.valid_to = a.valid_to or t.hi
    elseif op == "from_to" or op == "between" then a.valid_from, a.valid_to = t.lo, t.hi
    elseif op == "by" then a.valid_to = a.valid_to or t.hi
    elseif op == "after" then a.valid_from = a.valid_from or t.lo
    elseif op == "before" then a.valid_to = a.valid_to or (t.lo and t.lo - 1) or t.hi
    elseif op == "as_of" then a.as_of = { lo = t.lo, hi = t.hi, year = t.year, text = t.text }
    else a.valid_at = { lo = t.lo, hi = t.hi, year = t.year, text = t.text } end
  end
  if a.former and not a.valid_to and not a.valid_at then a.ended = true end
end

---------------------------------------------------------------- patterns
local COPULA = U.set({ "is", "are", "was", "were", "be", "been", "being" })
local function copula_at(S, k)
  local c = C(S, k)
  if not (c and c.single and not c.masked) then return nil end
  local f = c.unit.form
  local past = (f == "was" or f == "were" or f == "had")
  local nxt, neg, used = k + 1, false, { [k] = true }
  local j = k + 1
  local hedged_modal, future_modal
  if cat(c, "aux_have") and (f == "has" or f == "have" or f == "had") then
    -- "has been" / "had been": a perfect copula
    local b = C(S, k + 1)
    if b and b.single and b.unit.form == "been" and not barrier(b) then used[k + 1] = true; j = k + 2 else return nil end
  elseif cat(c, "modal") then
    -- "can be found in", "will be the capital": a modal + be is a copula (weak modals only hedge it)
    local b = C(S, k + 1)
    if b and b.single and not b.masked and not barrier(b) and cat(b, "aux_be") and (f == "can" or f == "will" or f == "must" or f == "shall" or f == "may" or f == "might" or f == "could" or f == "would" or f == "should") then
      used[k + 1] = true; j = k + 2
      hedged_modal = (f == "may" or f == "might" or f == "could" or f == "would" or f == "should")
      future_modal = (f == "will" or f == "shall")
    else return nil end
  elseif not (cat(c, "aux_be") or cat(c, "clitic_s")) then return nil end
  local skipped, former = {}, false
  while C(S, j) and C(S, j).single and not barrier(C(S, j)) and (P.is_neg(C(S, j)) or cat(C(S, j), "adv") or (C(S, j).temporal and C(S, j).temporal.kind == "marker")
    or (C(S, j).unit.form == "no" and C(S, j + 1) and C(S, j + 1).unit.form == "longer")) do
    if C(S, j).unit.form == "no" then former = true; used[j] = true; used[j + 1] = true; j = j + 1
    elseif P.is_neg(C(S, j)) then neg = true; used[j] = true
    elseif C(S, j).temporal then skipped[#skipped + 1] = j
    else used[j] = true end
    j = j + 1
  end
  return { nxt = j, neg = neg, past = past, used = used, form = f, skipped = skipped, former = former, hedged = c.hedged or hedged_modal, future = future_modal, onset = c.onset }
end

-- positions where the predicate may start after a subject NP ending at chunk `nxt`: directly, or after a comma-delimited appositive
-- ("France, officially the French Republic, is ...")
local function predicate_positions(S, nxt)
  local out = { nxt }
  local c = C(S, nxt)
  if c and c.pre and c.pre:find("comma") then
    for j = nxt + 1, math.min(#S.chunks, nxt + 10) do
      local cj = C(S, j)
      if cj and cj.pre and cj.pre:find("comma") then out[#out + 1] = j break end
    end
  end
  return out
end

local LOCATIVE_PARTICIPLE = U.set({ "situated", "located", "based", "found", "housed", "headquartered", "centred", "centered", "sited", "positioned", "established", "stationed" })
-- X BE (the|a)? RELNP-of-Y        |    RELNP-of-Y BE X       |    Y's RELNOUN BE X
local function copular_relational(self, S, ctx, out)
  local k = S.first
  for _, snp in ipairs(P.parse_np(S, k)) do
   for _, pos in ipairs(predicate_positions(S, snp.nxt)) do
    local cp = copula_at(S, pos)
    if cp then
      -- (1) subject is the value, complement is the relational NP
      for _, rnp in ipairs(P.parse_np(S, cp.nxt)) do
        if rnp.head_kind == "relnoun" then
          for _, o in ipairs(F.relnp_options(S, rnp)) do
            if o.arg and o.rel then
              local a = { rel = o.rel.id, rel_obj = o.rel, pattern = "copular_relnp", used_np = { snp, rnp }, neg = cp.neg, tense = cp.past and "past" or "present", copula = cp }
              a.roles = { [o.ask_role] = snp, [o.known_role] = o.arg }
              a.end_chunk = rnp.nxt
              out[#out + 1] = a
            end
          end
        end
      end
      -- (2) subject is the relational NP, complement is the value
      if snp.head_kind == "relnoun" then
        for _, o in ipairs(F.relnp_options(S, snp)) do
          if o.arg and o.rel then
            for _, vnp in ipairs(P.parse_np(S, cp.nxt)) do
              local a = { rel = o.rel.id, rel_obj = o.rel, pattern = "copular_value", used_np = { snp, vnp }, neg = cp.neg, tense = cp.past and "past" or "present", copula = cp }
              a.roles = { [o.known_role] = o.arg, [o.ask_role] = vnp }
              a.end_chunk = vnp.nxt
              out[#out + 1] = a
            end
            -- (2b) a location-valued noun takes a locative complement: "The headquarters of X is IN Oslo."
            local pk = cp.nxt
            do
              local pp = C(S, pk)
              if pp and pp.single and not pp.masked and LOCATIVE_PARTICIPLE[pp.unit.form] then pk = pk + 1 end
            end
            local pc = C(S, pk)
            if o.rel.locus and o.ask_role == "to" and pc and pc.single and not pc.masked and (pc.unit.form == "in" or pc.unit.form == "at") then
              for _, vnp in ipairs(P.parse_np(S, pk + 1)) do
                local a = { rel = o.rel.id, rel_obj = o.rel, pattern = "copular_locative", used_np = { snp, vnp }, neg = cp.neg, tense = cp.past and "past" or "present", copula = cp }
                a.roles = { [o.known_role] = o.arg, [o.ask_role] = vnp }
                a.end_chunk = vnp.nxt
                out[#out + 1] = a
              end
            end
          end
        end
      end
    end
   end
  end
end

local function comma_at(S, k) local c = C(S, k); return c ~= nil and c.pre ~= nil and c.pre:find("comma") ~= nil end

-- does relation `r` imply relation id `anc` through the isa chain (ceo isa leader)?
local function rel_isa(lex, r, anc)
  local cur, guard = r, 0
  while cur and cur.isa and guard < 6 do
    if cur.isa == anc then return true end
    cur = lex:get_rel(cur.isa); guard = guard + 1
  end
  return false
end

-- "CEO P leads O", "O is headed by chief executive P", "O is run by its chief executive officer, P": a title attached to the value names a MORE SPECIFIC
-- relation than the verb does ("leads" = leader); the more specific relation implies the verb's relation, so it is the better description of the sentence.
local function title_specialize(S, a)
  local rel = a.rel_obj
  if not rel or rel.open or not a.roles then return end
  for _, role in ipairs({ "to", "from" }) do
    local np = a.roles[role]
    if np then
      local titles = {}
      for _, m in ipairs(np.mods or {}) do
        if m.chunk then for _, ne in ipairs(m.chunk.relnouns or {}) do titles[#titles + 1] = { entry = ne, form = m.chunk.form } end end
      end
      for _, ne in ipairs(a.title_entries or {}) do titles[#titles + 1] = { entry = ne, form = ne.lemma } end
      for _, t in ipairs(titles) do
        local r2 = S.lex:get_rel(t.entry.rel)
        if r2 and not r2.open and r2.id ~= rel.id and t.entry.role == role and rel_isa(S.lex, r2, rel.id) then
          a.rel, a.rel_obj, a.specialized_by = r2.id, r2, t.form
          return
        end
      end
    end
  end
end

-- "was founded IN 1998 by P", "was started in Oslo by P": a temporal expression, an adverb or one prepositional phrase may sit between the participle
-- and its by-phrase.  Returns the chunk index of "by" and the chunks skipped (they still qualify the assertion), or nil.
local function skip_adjuncts_to_by(S, k)
  local skipped = {}
  for _ = 1, 3 do
    local c = C(S, k)
    if not c or c.masked then return nil end
    if c.single and c.unit.form == "by" then return k, skipped end
    if c.temporal and c.temporal.kind ~= "marker" then skipped[#skipped + 1] = k; k = k + 1
    elseif c.single and cat(c, "adv") and not barrier(c) then skipped[#skipped + 1] = k; k = k + 1
    elseif c.single and cat(c, "prep") and not barrier(c) then
      local hit
      for _, np in ipairs(P.parse_np(S, k + 1)) do
        local nc = C(S, np.nxt)
        if nc and nc.single and not nc.masked and nc.unit.form == "by" then hit = np; break end
      end
      if not hit then return nil end
      for i = k, hit.nxt - 1 do skipped[#skipped + 1] = i end
      k = hit.nxt
    else return nil end
  end
  return nil
end

-- Subject VERB Object  (active / passive-by / verb+prep), via the lexicon's role-directed relation verbs
local function verb_relational(self, S, ctx, out)
  local lex = S.lex
  for _, snp in ipairs(P.parse_np(S, S.first)) do
   for _, pos in ipairs(predicate_positions(S, snp.nxt)) do
    for _, vp in ipairs(P.parse_vp(S, pos)) do
      for _, e in ipairs(vp.analysis.entries) do
        local rel = lex:get_rel(e.rel)
        if rel and not e.as_only then
          local k = vp.nxt
          local patient_first = vp.voice == "passive" and not e.prep
          local skipped
          if e.prep then
            local pc = C(S, k)
            if pc and pc.single and pc.unit.form == e.prep and not pc.masked then k = k + 1 else k = nil end
          elseif vp.voice == "passive" then
            local kb
            kb, skipped = skip_adjuncts_to_by(S, k)
            if kb then k = kb + 1 else k = nil end
          end
          if k then
            for _, onp0 in ipairs(P.parse_np(S, k)) do
              local onp, titles = onp0, nil
              -- "... by its chief executive officer, P": the titled apposition names the participant
              if onp0.head_kind == "relnoun" and not onp0.of_arg and comma_at(S, onp0.nxt) then
                for _, ap in ipairs(P.parse_np(S, onp0.nxt)) do
                  if ap.head_kind == "entity" or (ap.head_kind == "unknown" and ap.head and ap.head.cap) then onp, titles = ap, onp0.relnouns; break end
                end
              end
              local a = { rel = rel.id, rel_obj = rel, pattern = vp.voice == "passive" and "passive_by" or "svo", used_np = { snp, onp }, neg = vp.neg,
                tense = (vp.vform == "past" or vp.perfect) and "past" or "present", vp = vp, skipped = skipped, title_entries = titles }
              if patient_first or (e.prep == nil and vp.voice == "passive") then
                a.roles = { [other(e.subj)] = snp, [e.subj] = onp }
              else
                a.roles = { [e.subj] = snp, [other(e.subj)] = onp }
              end
              a.end_chunk = onp.nxt
              title_specialize(S, a)
              out[#out + 1] = a
            end
          end
        end
      end
    end
   end
  end
end

-- X has/had a RELNOUN of VALUE   ("France has a population of 68 million")
local function have_attribute(self, S, ctx, out)
  for _, snp in ipairs(P.parse_np(S, S.first)) do
    local hc = C(S, snp.nxt)
    if hc and hc.single and not hc.masked and cat(hc, "aux_have") and (hc.unit.form == "has" or hc.unit.form == "have" or hc.unit.form == "had") then
      local k = snp.nxt + 1
      local neg = false
      while C(S, k) and C(S, k).single and not barrier(C(S, k)) and (P.is_neg(C(S, k)) or cat(C(S, k), "adv")) do
        if P.is_neg(C(S, k)) then neg = true end
        k = k + 1
      end
      for _, onp in ipairs(P.parse_np(S, k)) do
        if onp.head_kind == "relnoun" and onp.of_arg then
          for _, o in ipairs(F.relnp_options(S, onp)) do
            local rel = o.rel
            local to_t = rel.to
            if o.ask_role == "to" and (to_t == "number" or to_t == "money" or to_t == "date" or to_t == "quantity") then
              local a = { rel = rel.id, rel_obj = rel, pattern = "has_attribute", used_np = { snp, onp }, neg = neg, tense = (hc.unit.form == "had") and "past" or "present",
                copula = { used = { [snp.nxt] = true } } }
              a.roles = { from = snp, to = o.arg }
              a.end_chunk = onp.nxt
              out[#out + 1] = a
            end
          end
        end
      end
    end
  end
end

-- X is a/an N  -> classification (feeds terminology and entity typing, never relational answers)
local function classification(self, S, ctx, out)
  for _, snp in ipairs(P.parse_np(S, S.first)) do
    if snp.head_kind ~= "relnoun" then
     for _, pos in ipairs(predicate_positions(S, snp.nxt)) do
      local cp = copula_at(S, pos)
      if cp then
        local dc = C(S, cp.nxt)
        if dc and dc.single and cat(dc, "det") and (dc.unit.form == "a" or dc.unit.form == "an") then
          for _, tnp in ipairs(P.parse_np(S, cp.nxt)) do
            if (tnp.head_kind == "typenoun" or tnp.head_kind == "unknown" or tnp.head_kind == "concept") and not tnp.of_arg then
              local a = { rel = "instance_of", pattern = "classification", used_np = { snp, tnp }, neg = cp.neg, tense = cp.past and "past" or "present", copula = cp, is_class = true }
              a.roles = { from = snp, to = tnp }
              a.end_chunk = tnp.nxt
              out[#out + 1] = a
            end
          end
        end
      end
     end
    end
  end
end

-- "Financial capital refers to money used to fund businesses."  /  "X is defined as ..."  /  "X means ..."
local function definition(self, S, ctx, out)
  local lex = S.lex
  for _, snp in ipairs(P.parse_np(S, S.first)) do
    if snp.head_kind ~= "relnoun" and snp.head_kind ~= "pronoun" then
      local c = S.chunks[snp.nxt]
      if c and not c.masked and lex:cue_at("definition_verb", S.units, c.u1) then
        local n = lex:cue_at("definition_verb", S.units, c.u1)
        local k = snp.nxt
        local consumed = 0
        local used = {}
        while S.chunks[k] and consumed < n do consumed = consumed + (S.chunks[k].u2 - S.chunks[k].u1 + 1); used[k] = true; k = k + 1 end
        if S.chunks[k] and k <= S.last then
          local a = { rel = "defined_as", pattern = "definition", used_np = { snp }, tense = "present", copula = { used = used }, is_class = true, definitional = true }
          a.roles = { from = snp, to = nil }
          a.def_start = k
          a.end_chunk = S.last + 1
          out[#out + 1] = a
        end
      end
    end
  end
end

-- "Mercury is a chemical element with atomic number 80."  /  "Zorbland is a country with a population of 4 million."
local function with_attribute(self, S, ctx, out)
  for _, snp in ipairs(P.parse_np(S, S.first)) do
    for _, pos in ipairs(predicate_positions(S, snp.nxt)) do
      local cp = copula_at(S, pos)
      if cp then
        for _, tnp in ipairs(P.parse_np(S, cp.nxt)) do
          local wc = S.chunks[tnp.nxt]
          if wc and wc.single and wc.unit.form == "with" and not wc.masked then
            for _, rnp in ipairs(P.parse_np(S, tnp.nxt + 1)) do
              if rnp.head_kind == "relnoun" then
                for _, o in ipairs(F.relnp_options(S, rnp)) do
                  local rel = o.rel
                  if o.ask_role == "to" then
                    local value_np, nxt
                    if o.arg then value_np, nxt = o.arg, rnp.nxt   -- "with a population of 4 million"
                    else
                      for _, vnp in ipairs(P.parse_np(S, rnp.nxt)) do value_np, nxt = vnp, vnp.nxt break end   -- "with atomic number 80"
                    end
                    if value_np and (value_np.head_kind == "number" or value_np.head_kind == "temporal" or value_np.head_kind == "literal" or value_np.head_kind == "entity") then
                      local a = { rel = rel.id, rel_obj = rel, pattern = "with_attribute", used_np = { snp, rnp, value_np }, neg = cp.neg, tense = cp.past and "past" or "present", copula = cp }
                      a.roles = { from = snp, to = value_np }
                      a.end_chunk = nxt
                      out[#out + 1] = a
                    end
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

-- Support-verb statements.  The holder is the subject; the verb ("has", "keeps", "maintains", "uses") only carries the relation named by the noun:
--   X HAS|KEEPS|MAINTAINS its RELNOUN (in|at|of) VALUE      "Acme maintains its headquarters in Oslo."
--   X HAS|USES VALUE as its RELNOUN                          "Sweden uses the krona as its currency."  "France has Paris as its capital."
local SUPPORT_PREP = U.set({ "in", "at", "of", "as" })
local function supports(vp, rel)
  if vp.lemma == "have" then return rel.support_have == true end
  for _, e in ipairs(vp.analysis.entries or {}) do if e.support and e.rel == rel.id then return true end end
  return false
end
local function possessed_relnoun(S, onp)
  local dc = C(S, onp.c1)
  return onp.head_kind == "relnoun" and not onp.of_arg and dc and dc.single and (cat(dc, "poss_det") or cat(dc, "det")) and onp.c1 < onp.nxt - 1
end
local function support_statement(self, S, ctx, out)
  for _, snp in ipairs(P.parse_np(S, S.first)) do
   for _, pos in ipairs(predicate_positions(S, snp.nxt)) do
    for _, vp in ipairs(P.parse_vp(S, pos)) do
      if vp.voice == "active" then
        local tense = (vp.vform == "past") and "past" or "present"
        -- (1) verb [from|at|out of] + possessed relational noun + (preposition +) value        "operates from its headquarters in Oslo", "calls its currency the krona"
        local starts = { vp.nxt }
        do
          local fc = C(S, vp.nxt)
          if fc and fc.single and not fc.masked and (fc.unit.form == "from" or fc.unit.form == "at" or fc.unit.form == "out") then
            local k2 = vp.nxt + 1
            if fc.unit.form == "out" and C(S, k2) and C(S, k2).unit.form == "of" then k2 = k2 + 1 end
            starts[#starts + 1] = k2
          end
        end
        for _, k0 in ipairs(starts) do
          for _, onp in ipairs(P.parse_np(S, k0)) do
            if possessed_relnoun(S, onp) then
              local pc = C(S, onp.nxt)
              local vstart
              if pc and pc.single and not pc.masked and SUPPORT_PREP[pc.unit.form] and pc.unit.form ~= "as" then vstart = onp.nxt + 1
              elseif k0 == vp.nxt and vp.lemma == "call" then vstart = onp.nxt end      -- "calls its currency THE KRONA": no preposition
              if vstart then
                for _, vnp in ipairs(P.parse_np(S, vstart)) do
                  for _, o in ipairs(F.relnp_options(S, onp)) do
                    if o.rel and o.ask_role == "to" and supports(vp, o.rel) then
                      local a = { rel = o.rel.id, rel_obj = o.rel, pattern = "support_have", used_np = { snp, onp, vnp }, neg = vp.neg, tense = tense, vp = vp }
                      a.roles = { from = snp, to = vnp }
                      a.end_chunk = vnp.nxt
                      out[#out + 1] = a
                    end
                  end
                end
              end
            end
          end
        end
        -- (2) verb + value + "as" + relational noun:  "France has Paris as its capital", "Acme appointed Jane Doe as CEO" (bare), "... as the CEO"
        for _, vnp in ipairs(P.parse_np(S, vp.nxt)) do
          local ac = C(S, vnp.nxt)
          if ac and ac.single and not ac.masked and ac.unit.form == "as" then
            for _, onp in ipairs(P.parse_np(S, vnp.nxt + 1)) do
              if onp.head_kind == "relnoun" and not onp.possessor and not (onp.of_arg and vp.lemma == "have") then
                local pc2 = C(S, onp.nxt)
                local dangling_of = pc2 and pc2.single and not pc2.masked and pc2.unit.form == "of"
                for _, o in ipairs(F.relnp_options(S, onp)) do
                  if o.rel and o.ask_role == "to" and supports(vp, o.rel) and not dangling_of then
                    local a = { rel = o.rel.id, rel_obj = o.rel, pattern = "support_as", used_np = { snp, vnp, onp }, neg = vp.neg, tense = tense, vp = vp }
                    -- "the board appointed Jane Doe as CEO OF Acme": the holder is the argument of the noun, the subject is only the agent of the appointment
                    if o.arg and not onp.topic_arg then a.roles = { from = o.arg, to = vnp }
                    else a.roles = { from = snp, to = vnp } end
                    a.end_chunk = onp.nxt
                    out[#out + 1] = a
                  end
                end
              end
            end
          end
        end
      end
    end
   end
  end
end

-- "P is the person who founded O."  /  "P is the one that started O."  The head noun is generic; the relative clause carries the relation, and
-- the copular subject fills the gap.
local function relative_identity(self, S, ctx, out)
  local lex = S.lex
  for _, snp in ipairs(P.parse_np(S, S.first)) do
   if snp.head_kind ~= "relnoun" then
    for _, pos in ipairs(predicate_positions(S, snp.nxt)) do
      local cp = copula_at(S, pos)
      if cp then
        for _, tnp in ipairs(P.parse_np(S, cp.nxt, { no_of = true })) do
          local rc = C(S, tnp.nxt)
          if tnp.head_kind ~= "entity" and tnp.head_kind ~= "relnoun" and rc and rc.single and not rc.masked
            and (rc.unit.form == "who" or rc.unit.form == "that" or rc.unit.form == "which") then
            for _, vp in ipairs(P.parse_vp(S, tnp.nxt + 1)) do
              if vp.voice == "active" then
                for _, e in ipairs(vp.analysis.entries or {}) do
                  local rel = lex:get_rel(e.rel)
                  if rel and not e.prep and not rel.open and not e.support then
                    for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
                      local a = { rel = rel.id, rel_obj = rel, pattern = "relative_identity", used_np = { snp, tnp, onp }, neg = cp.neg or vp.neg,
                        tense = (cp.past or vp.vform == "past") and "past" or "present", copula = cp, vp = vp }
                      a.roles = { [e.subj] = snp, [other(e.subj)] = onp }
                      a.end_chunk = onp.nxt
                      out[#out + 1] = a
                    end
                  end
                end
              end
            end
          end
        end
      end
    end
   end
  end
end

-- "The person who started O is P."  /  "The city where O is headquartered is C."  /  "The city that functions as the capital of K is C."
-- A definite singular description with ONE relative clause names the value of the relation the clause expresses.
local function description_identity(self, S, ctx, out)
  for _, snp in ipairs(P.parse_np(S, S.first)) do
    if snp.head_kind == "typenoun" and not snp.plural and snp.det == "the" then
      local filters, kf = F.parse_filters(S, snp.nxt, snp)
      -- the relative clause ends where the copula begins
      for cut = #filters, 1, -1 do
        local f = filters[cut]
        if cut == 1 and f.kind == "relation" and f.value and f.rel then
          local rel = S.lex:get_rel(f.rel)
          local cp = copula_at(S, f.span.last + 1)
          if rel and not rel.open and cp then
            for _, vnp in ipairs(P.parse_np(S, cp.nxt)) do
              local a = { rel = rel.id, rel_obj = rel, pattern = "description_identity", used_np = { snp, f.value, vnp }, neg = cp.neg or f.polarity == "negative",
                tense = cp.past and "past" or "present", copula = cp }
              a.roles = { [f.target_role] = vnp, [other(f.target_role)] = f.value }
              for i = f.span.first, f.span.last do a.copula.used[i] = true end
              a.end_chunk = vnp.nxt
              out[#out + 1] = a
            end
          end
        end
      end
    end
  end
end

local function comma_before(S, k) local c = C(S, k); return c ~= nil and c.pre ~= nil and c.pre:find("comma") ~= nil end

-- A comma-delimited relational noun phrase next to a name states the relation between its argument and the name:
--   "Brelmont, the capital of Tavoria, is a coastal city."     "The founder of Brennick Dynamics, Odalys Feurmann, spoke yesterday."
--   "Tavoria's capital, Brelmont, hosts the parliament."       "Jane Doe, CEO of Acme Corp, said ..."
local function apposition_relational(self, S, ctx, out)
  for _, snp in ipairs(P.parse_np(S, S.first)) do
    if comma_before(S, snp.nxt) then
      for _, np2 in ipairs(P.parse_np(S, snp.nxt)) do
        local nc = C(S, np2.nxt)
        local closed = np2.nxt > S.last or (nc ~= nil and nc.pre ~= nil and (nc.pre:find("comma") ~= nil or nc.pre:find("dash") ~= nil))
        if closed then
          local function mk(o, valnp, argnp, pattern)
            local a = { rel = o.rel.id, rel_obj = o.rel, pattern = pattern, used_np = { snp, np2 }, neg = false, tense = "present" }
            a.roles = { [o.known_role] = o.arg, [o.ask_role] = valnp }
            a.end_chunk = np2.nxt
            out[#out + 1] = a
          end
          -- NAME , RELNP-of-X ,
          if np2.head_kind == "relnoun" and (snp.head_kind == "entity" or (snp.head_kind == "unknown" and snp.head and snp.head.cap)) and not snp.det and not snp.poss_det then
            for _, o in ipairs(F.relnp_options(S, np2)) do if o.arg and o.rel and not o.rel.open then mk(o, snp, o.arg, "apposition") end end
          end
          -- RELNP-of-X , NAME ,
          if snp.head_kind == "relnoun" and (np2.head_kind == "entity" or (np2.head_kind == "unknown" and np2.head and np2.head.cap)) and not np2.det and not np2.poss_det then
            for _, o in ipairs(F.relnp_options(S, snp)) do if o.arg and o.rel and not o.rel.open then mk(o, np2, o.arg, "apposition") end end
          end
        end
      end
    end
  end
end

-- A non-restrictive relative clause on the subject names the relation too:
--   "Odalys Feurmann, who founded Brennick Dynamics, lives in Oslo."       "Brennick Dynamics, which was founded by Odalys Feurmann, is based in Oslo."
local function relative_apposition(self, S, ctx, out)
  local lex = S.lex
  for _, snp in ipairs(P.parse_np(S, S.first)) do
    local rc = C(S, snp.nxt)
    if rc and rc.single and not rc.masked and comma_before(S, snp.nxt) and (rc.unit.form == "who" or rc.unit.form == "which")
      and (snp.head_kind == "entity" or (snp.head_kind == "unknown" and snp.head and snp.head.cap)) then
      for _, vp in ipairs(P.parse_vp(S, snp.nxt + 1)) do
        for _, e in ipairs(vp.analysis.entries or {}) do
          local rel = lex:get_rel(e.rel)
          if rel and not rel.open and not e.support and not e.as_only then
            local tense = (vp.vform == "past" or vp.perfect) and "past" or "present"
            if vp.voice == "active" and not e.prep then
              for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
                local a = { rel = rel.id, rel_obj = rel, pattern = "relative_apposition", used_np = { snp, onp }, neg = vp.neg, tense = tense, vp = vp }
                a.roles = { [e.subj] = snp, [other(e.subj)] = onp }
                a.end_chunk = onp.nxt
                out[#out + 1] = a
              end
            elseif vp.voice == "passive" and not e.prep then
              local bc = C(S, vp.nxt)
              if bc and bc.single and not bc.masked and bc.unit.form == "by" then
                for _, onp in ipairs(P.parse_np(S, vp.nxt + 1)) do
                  local a = { rel = rel.id, rel_obj = rel, pattern = "relative_apposition", used_np = { snp, onp }, neg = vp.neg, tense = tense, vp = vp }
                  a.roles = { [other(e.subj)] = snp, [e.subj] = onp }
                  a.end_chunk = onp.nxt
                  out[#out + 1] = a
                end
              end
            elseif e.prep then
              local pc = C(S, vp.nxt)
              if pc and pc.single and not pc.masked and pc.unit.form == e.prep then
                for _, onp in ipairs(P.parse_np(S, vp.nxt + 1)) do
                  local a = { rel = rel.id, rel_obj = rel, pattern = "relative_apposition", used_np = { snp, onp }, neg = vp.neg, tense = tense, vp = vp }
                  a.roles = { [e.subj] = snp, [other(e.subj)] = onp }
                  a.end_chunk = onp.nxt
                  out[#out + 1] = a
                end
              end
            end
          end
        end
      end
    end
  end
end

local PATTERNS = { copular_relational, verb_relational, have_attribute, support_statement, relative_identity, description_identity, classification, with_attribute, definition,
  apposition_relational, relative_apposition }

---------------------------------------------------------------- reader-directed content
-- Data that addresses the reader is evidence ABOUT the data, never a command: such sentences are flagged and excluded from fact extraction.
local function reader_directed(self, S, sent_text)
  local lex = S.lex
  local reasons = {}
  local c = C(S, S.first)
  if c and not sent_text:match("%?%s*$") then
    local ana = (c.single or c.kind == "mwe") and P.verb_analyses(S, c) or {}
    for _, a in ipairs(ana) do
      if a.form == "base" and a.act and (a.act == "retrieve" or a.act == "inform" or a.act == "task" or a.act == "constraint" or a.act == "exclude"
        or a.act == "include" or a.act == "compare" or a.act == "focus") and not cat(c, "wh") then
        -- an imperative must have a verb-initial sentence; "Paris" etc. never reach here
        if c.cap == nil or c.cap then reasons[#reasons + 1] = "imperative: " .. a.lemma end
        break
      end
    end
  end
  for i, u in ipairs(S.units) do
    if u.sent == S.sentence.id then
      if lex:cue_at("injection", S.units, i) then reasons[#reasons + 1] = "injection cue: " .. u.form; break end
    end
  end
  local addresses, ai = false, false
  for _, u in ipairs(S.units) do
    if u.sent == S.sentence.id then
      if u.form == "you" or u.form == "your" or u.form == "yourself" then addresses = true end
      if u.form == "assistant" or u.form == "chatbot" or u.form == "ai" or u.form == "llm" or u.form == "model" or u.form == "system" then ai = true end
    end
  end
  if addresses and ai then reasons[#reasons + 1] = "addresses the reader/assistant" end
  return reasons
end

---------------------------------------------------------------- mentions + aliases
local function mentions_of(S, cover_spans)
  local out, aliases = {}, {}
  for k, c in ipairs(S.chunks) do
    if c.kind == "entity" or c.kind == "name" or #c.entities > 0 or #c.names > 0 then
      local keys = {}
      for _, r in ipairs(c.entities) do if not r.fuzzy then keys[#keys + 1] = { key = r.entry.id, type = r.entry.etype } end end
      if #keys == 0 then for _, r in ipairs(c.names) do keys[#keys + 1] = { key = "mention:" .. c.form, type = r.type_guess, weak = r.weak } end end
      for _, kk in ipairs(keys) do
        out[#out + 1] = { key = kk.key, type = kk.type, weak = kk.weak, text = c.text or c.form, s = S.units[c.u1].s, e = S.units[c.u2].e, chunk = k, ambiguous = #keys > 1 or nil }
      end
      -- alias apposition: "France, officially the French Republic," / "X, also known as Y"
      local n1 = C(S, k + 1)
      if n1 and n1.pre and n1.pre:find("comma") and #keys == 1 then
        local j = k + 1
        local cue = S.lex:cue_at("alias_intro", S.units, n1.u1)
        if cue then
          local consumed = 0
          while C(S, j) and consumed < cue do consumed = consumed + (C(S, j).u2 - C(S, j).u1 + 1); j = j + 1 end
          local dc = C(S, j)
          if dc and dc.single and cat(dc, "det") then j = j + 1 end
          for _, np in ipairs(P.parse_np(S, j)) do
            if np.head_kind == "entity" or np.head_kind == "unknown" or np.head_kind == "typenoun" then
              aliases[#aliases + 1] = { key = keys[1].key, alias = P.core_text(S, np), text = P.span_text(S, np) }
              break
            end
          end
        end
      end
    end
  end
  return out, aliases
end

---------------------------------------------------------------- main
-- returns { assertions, mentions, aliases, reader_directed = {{text, reasons, s, e}}, sentences = n, limited = bool }
function A:extract(text, meta)
  meta = meta or {}
  local lex = self.lex
  local an = Lex.analyze(text, { spell = nil, meter = self.meter, max_bytes = meta.max_bytes })
  local res = { assertions = {}, mentions = {}, aliases = {}, reader_directed = {}, sentences = 0, status = an.status }
  if an.status == "rejected" then return res end
  local lat = Lattice.build(an, lex, { meter = self.meter })
  local ctx = { flags = {}, meter = self.meter, max_covers = 2, topic = meta.topic }
  for _, sent in ipairs(an.sentences) do
    local ua, ub = Sem.sentence_unit_range(an, sent.id)
    if ua and ub - ua < self.max_sentence_units then
      res.sentences = res.sentences + 1
      local stext = text:sub(sent.s, sent.e)
      local covers = lat:covers(2, ua, ub)
      local found_in
      local next_topic
      for ci, cover in ipairs(covers) do
        local S = P.new_state(an, lex, lat, cover, ctx)
        S.sentence = sent
        S.cover_index = ci
        if ci == 1 then
          local ms, als = mentions_of(S)
          for _, m in ipairs(ms) do m.sent = sent.id; m.s = m.s; res.mentions[#res.mentions + 1] = m end
          for _, al in ipairs(als) do al.sent = sent.id; res.aliases[#res.aliases + 1] = al end
          local rd = reader_directed(self, S, stext)
          if #rd > 0 then
            res.reader_directed[#res.reader_directed + 1] = { text = stext, reasons = rd, s = sent.s, e = sent.e, sent = sent.id }
            found_in = "reader_directed"
          end
        end
        if found_in == "reader_directed" then break end
        if not stext:match("%?%s*$") then
          local cands = {}
          -- fronted adverbials ("In 1999, Alice founded ...", "Formerly, ...") qualify the clause that follows the comma
          S.lead_first = S.first
          do
            local k = S.first
            while C(S, k) and C(S, k).temporal and C(S, k + 1) and C(S, k + 1).pre and C(S, k + 1).pre:find("comma") do k = k + 1 end
            S.first = k
          end
          P.take_topic(S)
          P.take_attribution(S)
          P.take_reported(S, true)
          P.normalize_cleft(S)
          P.normalize_inversion(S)
          for _, pat in ipairs(PATTERNS) do pat(self, S, ctx, cands) end
          -- "Officials confirmed that X is Y.": a reporting clause is tried only when the sentence as written yields nothing
          if #cands == 0 and P.take_reported(S) then
            P.normalize_cleft(S)
            P.normalize_inversion(S)
            for _, pat in ipairs(PATTERNS) do pat(self, S, ctx, cands) end
          end
          -- keep candidates that explain the most of the sentence; ties broken by pattern order (copular relational first)
          local best, best_cov = {}, -1
          for _, a in ipairs(cands) do
            local used = {}
            for _, np in ipairs(a.used_np) do for i = np.c1, np.c2 do used[i] = true end end
            local cov = 0
            for i in pairs(used) do cov = cov + 1 end
            a.coverage = cov
            if cov > best_cov then best_cov = cov end
          end
          for _, a in ipairs(cands) do if a.coverage >= best_cov - 1 then best[#best + 1] = a end end

          for _, a in ipairs(best) do
            local used = {}
            for _, np in ipairs(a.used_np) do for i = np.c1, np.c2 do used[i] = true end end
            if a.copula then for i in pairs(a.copula.used) do used[i] = true end end
            if a.vp then
              for i = a.vp.c1, a.vp.c2 do
                local ci = C(S, i)
                if not (ci and ci.temporal) then used[i] = true end
              end
            end
            local q = qualifiers(self, S, used, { neg = a.neg, tense = a.tense, range = qualifier_range(S, a), former = a.copula and a.copula.former })
            if a.neg then q.polarity = "negative" end
            if a.copula and a.copula.hedged then q.modality = "hedged" end          -- "is said to be", "is believed to be"
            if a.copula and a.copula.future then q.modality = "hypothetical" end    -- "will be": a prediction, not a present fact
            if S.attribution then q.attribution = S.attribution.text end
            local rel_obj = a.rel_obj
            local rec = { rel = a.rel, pattern = a.pattern, polarity = q.polarity, modality = q.modality, tense = q.tense, sent = sent.id,
              s = sent.s, e = sent.e, text = stext, cover = ci, coverage = a.coverage }
            if a.definitional then
              rec.is_class = true
              rec.definition = true
              rec.from = describe_np(S, ctx, a.roles.from, nil, "from")
              local ua = S.chunks[a.def_start]
              rec.class_text = text:sub(S.units[ua.u1].s, sent.e):gsub("[%.%s]+$", "")
            elseif a.is_class then
              rec.is_class = true
              rec.from = describe_np(S, ctx, a.roles.from, nil, "from")
              rec.class_text = P.core_text(S, a.roles.to)
              rec.class_type = a.roles.to.senses and a.roles.to.senses[1] and a.roles.to.senses[1].type or nil
              -- "Mercury is a planet": the class selects among the subject's candidate senses
              if rec.from and rec.from.cands and rec.class_type then
                local keep = {}
                for _, c in ipairs(rec.from.cands) do if c.type and lex:compat(c.type, rec.class_type) >= 0.9 then keep[#keep + 1] = c end end
                if #keep == 1 then rec.from.key, rec.from.status, rec.from.type, rec.from.resolved_by = keep[1].id, "resolved", keep[1].type, "classification" end
              end
            else
              rec.from = describe_np(S, ctx, a.roles.from, rel_obj and rel_obj.from, "from")
              rec.to = describe_np(S, ctx, a.roles.to, rel_obj and rel_obj.to, "to")
            end
            apply_time(rec, q, rel_obj, lex)
            rec.attribution = q.attribution
            -- "Brelmont became the capital in 1950": the time marks the START of the state
            if a.copula and a.copula.onset and rec.valid_at then rec.valid_from = rec.valid_at.lo; rec.valid_at = nil end
            -- a clash between the entity's known type and the relation signature means the pattern misfired (e.g. a city as a "founder")
            local clash = (rec.from and rec.from.type_clash) or (rec.to and rec.to.type_clash)
            if rel_obj and rel_obj.open then
              rec.open_relation = true
              -- an inferred relation is only trusted between two proper participants (entities or literals), never between generic nouns
              local function proper(d) return d and (d.literal or (d.key and (d.key:sub(1, 8) == "mention:" or not d.key:find("^term:") and not d.key:find("^sense:")))) end
              -- verb-based open relations connect proper participants only; "the X of Y is Z" (explicit relational noun) may have any value
              if (a.pattern == "svo" or a.pattern == "passive_by") and not (proper(rec.from) and proper(rec.to)) then clash = true end
            end
            local dedupe_key
            do
              local function dk(d) return d and (d.key or (d.literal and d.literal.text) or d.text) or "-" end
              dedupe_key = table.concat({ rec.rel, dk(rec.from), rec.is_class and (rec.definition and "def" or "class") or dk(rec.to), rec.polarity, tostring(sent.id) }, "|")
            end
            res._seen = res._seen or {}
            local valid = rec.from and rec.from.status ~= "pronoun" and (rec.is_class or (rec.to and rec.to.status ~= "pronoun")) and not clash
            -- a bare role word ("chief executive", "president") is a description of a participant, not a participant
            if valid and not rec.is_class and ((rec.to and rec.to.head_kind == "relnoun" and not rec.to.key) or (rec.from and rec.from.head_kind == "relnoun" and not rec.from.key)) then valid = false end
            -- one reading of the sentence per (relation, subject): among VALID candidates the one explaining most of the sentence wins over
            -- truncated parses ("88" vs "88 days"); an invalid (type-clashing) candidate never shadows a valid one
            local skip = false
            if valid then
              local gk = table.concat({ rec.rel, (rec.from.key or rec.from.text), rec.polarity, tostring(sent.id), rec.is_class and "c" or "r" }, "|")
              res._best = res._best or {}
              local prev = res._best[gk]
              if prev and (prev.coverage or 0) >= (rec.coverage or 0) then skip = true
              elseif prev then
                for i, x in ipairs(res.assertions) do if x == prev then table.remove(res.assertions, i) break end end
              end
              if not skip then res._best[gk] = rec end
            end
            if valid and not skip and not res._seen[dedupe_key] then
              res._seen[dedupe_key] = true
              res.assertions[#res.assertions + 1] = rec
              found_in = found_in or "assertion"
              local sd = a.used_np[1].head_kind == "entity" and describe_np(S, ctx, a.used_np[1], nil, "subject") or nil
              if sd and sd.key and not sd.literal and not next_topic then next_topic = sd end
            end
          end
        end
        if found_in == "assertion" then break end
      end
      if next_topic and not meta.topic_fixed then ctx.topic = next_topic end
    end
  end
  res.limited = self.meter and self.meter.over or false
  res._seen, res._best = nil, nil
  return res
end

return A

end

package.preload["asi.nlu.baseline"] = function(...)
-- asi.nlu.baseline: a DOCUMENTED NAIVE keyword router, used only as a comparison point.
-- No existing natural-language interpreter was available to me, so this is a strawman I wrote on purpose:
--   * words are whitespace/punctuation tokens, lower-cased; phrases are n-gram string matches (no lattice, no case-sensitivity)
--   * the FIRST relation keyword found wins, wherever it is and whatever it modifies ("capital punishment" -> capital)
--   * entities: first alphabetical-id name match; no types, no context, no ambiguity ("Mercury" is always resolved)
--   * no negation scope, no temporal operators, no coreference, no voice/direction analysis
--   * ambiguity is never reported.
-- It uses the SAME lexicon data as the real interpreter so the comparison isolates the interpretation machinery.
local U = require("asi.nlu.util")
local Morph = require("asi.nlu.morph")

local B = {}

local cache = setmetatable({}, { __mode = "k" })

local function words_of(text)
  local out = {}
  for w in text:lower():gmatch("[%w']+") do out[#out + 1] = w end
  return out
end

local function index_for(lex)
  if cache[lex] then return cache[lex] end
  local idx = { ents = {}, rels = {}, types = {} }
  local chain = {}
  local l = lex
  while l do table.insert(chain, 1, l); l = l.parent end
  for _, lx in ipairs(chain) do
    for id, e in pairs(lx.entities) do
      for _, nm in ipairs(e.names) do
        local key = table.concat(words_of(nm.text), " ")
        if key ~= "" then
          idx.ents[key] = idx.ents[key] or {}
          table.insert(idx.ents[key], { id = id, type = e.type })
        end
      end
    end
    for _, r in ipairs(lx:all_rels()) do
      local function add(phrase, role)
        for _, f in ipairs(Morph.noun_forms(phrase)) do
          local key = table.concat(words_of(f.form), " ")
          idx.rels[key] = idx.rels[key] or { rel = r, role = role }
        end
      end
      for _, n in ipairs(r.nouns_to) do add(n, "to") end
      for _, n in ipairs(r.nouns_from) do add(n, "from") end
      for _, v in ipairs(r.verbs) do
        for _, f in ipairs(Morph.verb_forms(v.lemma)) do
          local key = table.concat(words_of(f.form), " ")
          idx.rels[key] = idx.rels[key] or { rel = r, role = (v.subj == "to") and "to" or "from", verb = true }
        end
      end
    end
    for _, s in pairs(lx.senses) do
      if s.kind == "typenoun" then
        for _, f in ipairs(Morph.noun_forms(s.head)) do idx.types[table.concat(words_of(f.form), " ")] = s.type end
      end
    end
  end
  for k, list in pairs(idx.ents) do table.sort(list, function(a, b) return a.id < b.id end) end
  cache[lex] = idx
  return idx
end

function B.interpret(text, lex)
  local idx = index_for(lex)
  local w = words_of(text)
  local out = { schema = "nlu.sem/1", status = "ok", baseline = true, constraints = { positive = {}, negative = {}, preferences = {}, restrictions = {}, temporal = {}, geographic = {}, source = {} },
    hypotheses = {}, ambiguity = { state = "resolved", points = {} }, roles = {}, unexplained = {}, dependencies = {} }
  -- leftmost-longest entity
  local ent, ent_pos
  for i = 1, #w do
    for n = math.min(4, #w - i + 1), 1, -1 do
      local key = table.concat(w, " ", i, i + n - 1)
      if idx.ents[key] and not (n == 1 and #key <= 2) then ent = { key = key, list = idx.ents[key], n = n }; ent_pos = i; break end
    end
    if ent then break end
  end
  -- leftmost relation keyword (first wins, anywhere)
  local rel, rel_pos
  for i = 1, #w do
    for n = math.min(3, #w - i + 1), 1, -1 do
      local key = table.concat(w, " ", i, i + n - 1)
      if idx.rels[key] then rel = idx.rels[key]; rel_pos = i; break end
    end
    if rel then break end
  end
  local first = w[1] or ""
  local qwords = { what = true, who = true, which = true, when = true, where = true, how = true, why = true, whom = true, whose = true }
  local auxq = { is = true, are = true, does = true, did = true, do_ = true, was = true, were = true, can = true, could = true, will = true, has = true, have = true }
  local act = "statement"
  if qwords[first] or (text:find("%?%s*$")) then act = "question" end
  if auxq[first] then act = "question" end
  local imperative = { find = "search", list = "search", show = "search", get = "search", search = "search", give = "search", name = "lookup",
    compare = "comparison", use = "instruction_update", switch = "instruction_update", set = "instruction_update", choose = "instruction_update",
    prioritize = "instruction_update", exclude = "instruction_update", explain = "explanation", describe = "description", define = "definition", tell = "description" }
  local intent
  if imperative[first] then act = "request"; intent = imperative[first] end
  if not intent then
    if first == "why" then intent = "causal_explanation"
    elseif first == "how" and not rel then intent = "explanation"
    elseif auxq[first] then intent = "verification"
    elseif rel then intent = "factual_lookup"
    elseif first == "what" or first == "who" then intent = ent and "description" or "definition"
    elseif ent then intent = "factual_lookup"
    else intent = "unknown" end
  end
  if intent == "search" and rel and ent and false then intent = "factual_lookup" end
  if imperative[first] == "search" and rel and not text:lower():find("compan") then intent = "factual_lookup" end
  out.speech_act, out.intent = act, intent
  if rel then
    local r = rel.rel
    out.relation = { id = r.id, label = r.label, from_type = r.from, to_type = r.to }
    local known_role = (rel.role == "to") and "from" or "to"
    local ask_role = rel.role
    if rel.verb then known_role, ask_role = "from", "to" end
    out.query = { known_role = known_role, ask = ask_role, answer_type = r[ask_role] }
    if ent then
      local c = ent.list[1]
      out.roles[known_role] = { text = ent.key, resolved_id = c.id, type = c.type, status = "resolved" }
    end
  elseif ent then
    local c = ent.list[1]
    out.subject = { text = ent.key, resolved_id = c.id, type = c.type, status = "resolved" }
    out.concept = out.subject
  end
  for _, tok in ipairs(w) do
    local y = tonumber(tok:match("^(%d%d%d%d)$"))
    if y and y >= 1000 and y <= 2999 then out.constraints.temporal[#out.constraints.temporal + 1] = { kind = "year", op = "in", year = y, text = tostring(y), eff_lo = y * 10000 + 101, eff_hi = y * 10000 + 1231 } end
  end
  out.hypotheses = { { rank = 1, p = 1.0, summary = "keyword route" } }
  out.requires_external_evidence = (intent ~= "instruction_update")
  return out
end

-- Lexical-only ablation: the full lexical stack (UTF-8 lexer, MWE/entity lattice, case-sensitive aliases, typo alternatives)
-- but NO syntax, voice, types, negation scope or competing hypotheses: first relation reading + first entity reading win.
function B.lexical_only(text, lex)
  local Lex = require("asi.nlu.lex")
  local Lattice = require("asi.nlu.lattice")
  local an = Lex.analyze(text, { spell = lex.spell })
  local lat = Lattice.build(an, lex)
  local cover = lat:covers(1)[1]
  local out = { schema = "nlu.sem/1", status = "ok", lexical_only = true, constraints = { positive = {}, negative = {}, preferences = {}, restrictions = {}, temporal = {}, geographic = {}, source = {} },
    hypotheses = { { rank = 1, p = 1.0, summary = "lexical route" } }, ambiguity = { state = "resolved", points = {} }, roles = {}, unexplained = {}, dependencies = {} }
  local rel, ent, concept
  if cover then
    for _, sp in ipairs(cover.spans) do
      for _, r in ipairs(sp.readings) do
        if r.kind == "relnoun" and not rel then rel = { rel = lex:get_rel(r.entry.rel), role = r.entry.role } end
        if r.kind == "relverb" and not rel then rel = { rel = lex:get_rel(r.entry.rel), role = r.entry.subj == "to" and "to" or "from", verb = true } end
        if r.kind == "entity" and not ent then ent = { span = sp, e = r.entry } end
        if r.kind == "sense" and sp.kind == "mwe" and not concept then concept = { span = sp, sense = r.sense } end
      end
    end
  end
  local w = {}
  for x in text:lower():gmatch("[%w']+") do w[#w + 1] = x end
  local first = w[1] or ""
  local qwords = { what = true, who = true, which = true, when = true, where = true, how = true, why = true }
  out.speech_act = (qwords[first] or text:find("%?%s*$")) and "question" or "statement"
  if rel then
    out.intent = "factual_lookup"
    out.relation = { id = rel.rel.id, from_type = rel.rel.from, to_type = rel.rel.to }
    local known_role = (rel.role == "to") and "from" or "to"
    local ask_role = rel.role
    if rel.verb then known_role, ask_role = "from", "to" end
    out.query = { known_role = known_role, ask = ask_role, answer_type = rel.rel[ask_role] }
    if ent then out.roles[known_role] = { text = ent.span.text, resolved_id = ent.e.id, type = ent.e.etype, status = "resolved" } end
  elseif concept then
    out.intent = "definition"
    out.concept = { text = concept.span.text, type = concept.sense.type, senses = { { id = concept.sense.id, type = concept.sense.type } } }
  elseif ent then
    out.intent = (first == "what" or first == "who") and "description" or "factual_lookup"
    out.subject = { text = ent.span.text, resolved_id = ent.e.id, type = ent.e.etype, status = "resolved" }
  else out.intent = "unknown" end
  out.requires_external_evidence = true
  return out
end

return B

end

package.preload["asi.nlu.calibration"] = function(...)
-- asi.nlu.calibration: fit and evaluate probability calibration of raw confidence scores (pure Lua, deterministic).
--   samples: list of { x = raw score in [0,1], y = 1|0 (the prediction was right) }
-- Methods: isotonic regression (pool-adjacent-violators, monotone step function) and temperature scaling of the logit.  Nothing is hand-set: a
-- calibrated value is the empirical accuracy of that score range on labelled data, and `evaluate` reports ECE / Brier / log-loss on data that was
-- NOT used to fit.  A model is valid only for the distribution it was fitted on; `model.fit` records that distribution.
local U = require("asi.nlu.util")

local C = {}

local EPS = 1e-6
local function clamp(p) if p < EPS then return EPS elseif p > 1 - EPS then return 1 - EPS end return p end

---------------------------------------------------------------- isotonic regression (PAV)
function C.fit_isotonic(samples)
  local pts = {}
  for _, s in ipairs(samples) do pts[#pts + 1] = { x = s.x, y = s.y } end
  table.sort(pts, function(a, b) if a.x ~= b.x then return a.x < b.x end return a.y < b.y end)
  -- merge equal x first so the step function is well defined
  local blocks = {}
  for _, p in ipairs(pts) do
    local last = blocks[#blocks]
    if last and last.hi == p.x then last.sum = last.sum + p.y; last.n = last.n + 1
    else blocks[#blocks + 1] = { lo = p.x, hi = p.x, sum = p.y, n = 1 } end
  end
  -- pool adjacent violators
  local stack = {}
  for _, b in ipairs(blocks) do
    stack[#stack + 1] = b
    while #stack >= 2 do
      local a, c = stack[#stack - 1], stack[#stack]
      if a.sum / a.n > c.sum / c.n then
        a.sum, a.n, a.hi = a.sum + c.sum, a.n + c.n, c.hi
        stack[#stack] = nil
      else break end
    end
  end
  local steps = {}
  for _, b in ipairs(stack) do steps[#steps + 1] = { lo = b.lo, hi = b.hi, value = b.sum / b.n, n = b.n } end
  return { method = "isotonic", steps = steps, n = #samples }
end

local function apply_isotonic(model, x)
  local steps = model.steps
  if #steps == 0 then return x end
  if x <= steps[1].lo then return steps[1].value end
  for i, s in ipairs(steps) do
    if x <= s.hi then return s.value end
    local nx = steps[i + 1]
    if nx and x < nx.lo then
      -- between two blocks: interpolate linearly between the adjacent block values (keeps the map monotone and continuous)
      local t = (x - s.hi) / (nx.lo - s.hi)
      return s.value + t * (nx.value - s.value)
    end
  end
  return steps[#steps].value
end

---------------------------------------------------------------- temperature scaling
local function logit(p) p = clamp(p); return math.log(p / (1 - p)) end
local function sigmoid(z) return 1 / (1 + math.exp(-z)) end

function C.logloss(samples, f)
  local s = 0
  for _, d in ipairs(samples) do
    local p = clamp(f(d.x))
    s = s - (d.y * math.log(p) + (1 - d.y) * math.log(1 - p))
  end
  return s / math.max(1, #samples)
end

-- p' = sigmoid(a * logit(p) + b); fitted by a coarse-to-fine grid search on log-loss (deterministic, no gradients, no randomness)
function C.fit_platt(samples)
  local best = { a = 1, b = 0, loss = math.huge }
  local function try(a, b)
    local l = C.logloss(samples, function(x) return sigmoid(a * logit(x) + b) end)
    if l < best.loss then best = { a = a, b = b, loss = l } end
  end
  for ai = 1, 60 do for bi = -30, 30 do try(ai * 0.05, bi * 0.2) end end
  local a0, b0 = best.a, best.b
  for ai = -20, 20 do for bi = -20, 20 do if a0 + ai * 0.005 > 0 then try(a0 + ai * 0.005, b0 + bi * 0.01) end end end
  return { method = "platt", a = best.a, b = best.b, n = #samples, train_logloss = best.loss }
end

---------------------------------------------------------------- application
function C.apply(model, x)
  if model.method == "logistic" then return C.apply_features(model, x) end
  if model.method == "isotonic" then return apply_isotonic(model, x)
  elseif model.method == "platt" then return sigmoid(model.a * logit(x) + model.b)
  elseif model.method == "identity" then return x end
  error("unknown calibration method " .. tostring(model.method))
end

function C.identity() return { method = "identity", n = 0 } end

---------------------------------------------------------------- evaluation
-- reliability table with equal-mass bins (so every bin has data); ECE = mass-weighted |accuracy - mean confidence|
function C.evaluate(samples, model, nbins)
  nbins = nbins or 10
  local pts = {}
  for _, s in ipairs(samples) do
    local p = s.x
    if model then p = (model.method == "logistic") and C.apply_features(model, s.f) or C.apply(model, s.x) end
    pts[#pts + 1] = { p = p, y = s.y }
  end
  table.sort(pts, function(a, b) if a.p ~= b.p then return a.p < b.p end return a.y < b.y end)
  local n = #pts
  local out = { n = n, bins = {}, brier = 0, logloss = 0, accuracy = 0 }
  if n == 0 then return out end
  local ece, mce = 0, 0
  for i = 1, nbins do
    local lo, hi = math.floor((i - 1) * n / nbins) + 1, math.floor(i * n / nbins)
    if hi >= lo then
      local sp, sy = 0, 0
      for j = lo, hi do sp = sp + pts[j].p; sy = sy + pts[j].y end
      local cnt = hi - lo + 1
      local conf, acc = sp / cnt, sy / cnt
      local gap = math.abs(acc - conf)
      ece = ece + gap * cnt / n
      if gap > mce then mce = gap end
      out.bins[#out.bins + 1] = { n = cnt, mean_confidence = U.round(conf, 4), accuracy = U.round(acc, 4), lo = U.round(pts[lo].p, 4), hi = U.round(pts[hi].p, 4) }
    end
  end
  local sy = 0
  for _, d in ipairs(pts) do
    sy = sy + d.y
    out.brier = out.brier + (d.p - d.y) ^ 2
    local p = clamp(d.p)
    out.logloss = out.logloss - (d.y * math.log(p) + (1 - d.y) * math.log(1 - p))
  end
  out.brier, out.logloss, out.accuracy = out.brier / n, out.logloss / n, sy / n
  out.ece, out.mce = ece, mce
  return out
end

-- area under the ROC curve of the score as a ranker of correct vs incorrect predictions (ties count half); nil if one class is empty
function C.auroc(samples)
  local pos, neg = {}, {}
  for _, s in ipairs(samples) do if s.y == 1 then pos[#pos + 1] = s.x else neg[#neg + 1] = s.x end end
  if #pos == 0 or #neg == 0 then return nil end
  local all = {}
  for _, s in ipairs(samples) do all[#all + 1] = s end
  table.sort(all, function(a, b) return a.x < b.x end)
  local rank_sum, i = 0, 1
  while i <= #all do
    local j = i
    while j < #all and all[j + 1].x == all[i].x do j = j + 1 end
    local avg = (i + j) / 2
    for k = i, j do if all[k].y == 1 then rank_sum = rank_sum + avg end end
    i = j + 1
  end
  return (rank_sum - #pos * (#pos + 1) / 2) / (#pos * #neg)
end

-- stable digest of a sample list, recorded in the model so the fit set is identifiable
function C.digest(samples)
  local parts = {}
  for _, s in ipairs(samples) do parts[#parts + 1] = string.format("%.6f:%d", s.x, s.y) end
  return U.sha256(table.concat(parts, ";"))
end

---------------------------------------------------------------- multi-feature logistic regression (ridge, IRLS; deterministic)
-- samples: { f = {name -> number}, y = 0|1 }.  Features are standardised with the training mean / scale, so weights are comparable.
-- `signs` (optional) = { feature -> +1 | -1 }: monotonicity constraints (a risk feature may never RAISE the predicted probability).  Enforced by an
-- active-set loop: a feature whose fitted weight has the forbidden sign is removed (weight 0) and the model refitted.
function C.fit_logistic(samples, names, lambda, signs)
  if signs then
    local active = {}
    for _, nm in ipairs(names) do active[#active + 1] = nm end
    for _ = 1, #names do
      local m = C.fit_logistic_free(samples, active, lambda)
      local bad
      for j, nm in ipairs(active) do
        local sg = signs[nm]
        if sg and m.weights[j] * sg < -1e-9 then bad = j; break end
      end
      if not bad then
        -- re-express over the full feature list (removed features carry weight 0) so the model is self-describing
        local w, mean, scale = {}, {}, {}
        local pos = {}
        for j, nm in ipairs(active) do pos[nm] = j end
        for j, nm in ipairs(names) do
          local k = pos[nm]
          w[j], mean[j], scale[j] = k and m.weights[k] or 0, k and m.mean[k] or 0, k and m.scale[k] or 1
        end
        m.names, m.weights, m.mean, m.scale, m.constraints = names, w, mean, scale, signs
        return m
      end
      table.remove(active, bad)
    end
  end
  return C.fit_logistic_free(samples, names, lambda)
end

function C.fit_logistic_free(samples, names, lambda)
  lambda = lambda or 1.0
  local d, n = #names, #samples
  local mean, scale = {}, {}
  for j, nm in ipairs(names) do
    local sm = 0
    for _, s in ipairs(samples) do sm = sm + (s.f[nm] or 0) end
    mean[j] = sm / math.max(n, 1)
    local sv = 0
    for _, s in ipairs(samples) do sv = sv + ((s.f[nm] or 0) - mean[j]) ^ 2 end
    scale[j] = math.sqrt(sv / math.max(n, 1))
    if scale[j] < 1e-9 then scale[j] = 1 end
  end
  local w, b = {}, 0
  for j = 1, d do w[j] = 0 end
  local function row(s) local x = {}; for j, nm in ipairs(names) do x[j] = ((s.f[nm] or 0) - mean[j]) / scale[j] end return x end
  local X = {}
  for i, s in ipairs(samples) do X[i] = row(s) end
  for _ = 1, 40 do
    -- gradient and Hessian of the penalised log-likelihood (bias unpenalised); solve the (d+1)x(d+1) system by Gaussian elimination
    local g, H = {}, {}
    for a = 1, d + 1 do g[a] = 0; H[a] = {}; for c = 1, d + 1 do H[a][c] = 0 end end
    for i, s in ipairs(samples) do
      local z = b
      for j = 1, d do z = z + w[j] * X[i][j] end
      local p = sigmoid(z)
      local r, v = s.y - p, math.max(p * (1 - p), 1e-6)
      g[d + 1] = g[d + 1] + r
      for a = 1, d do
        g[a] = g[a] + r * X[i][a]
        for c = 1, d do H[a][c] = H[a][c] + v * X[i][a] * X[i][c] end
        H[a][d + 1] = H[a][d + 1] + v * X[i][a]
        H[d + 1][a] = H[d + 1][a] + v * X[i][a]
      end
      H[d + 1][d + 1] = H[d + 1][d + 1] + v
    end
    for a = 1, d do g[a] = g[a] - lambda * w[a]; H[a][a] = H[a][a] + lambda end
    H[d + 1][d + 1] = H[d + 1][d + 1] + 1e-6
    -- solve H * delta = g
    local M = {}
    for a = 1, d + 1 do M[a] = {}; for c = 1, d + 1 do M[a][c] = H[a][c] end; M[a][d + 2] = g[a] end
    for a = 1, d + 1 do
      local piv = a
      for r2 = a + 1, d + 1 do if math.abs(M[r2][a]) > math.abs(M[piv][a]) then piv = r2 end end
      M[a], M[piv] = M[piv], M[a]
      local diag = M[a][a]
      if math.abs(diag) < 1e-12 then diag = 1e-12 end
      for c = a, d + 2 do M[a][c] = M[a][c] / diag end
      for r2 = 1, d + 1 do
        if r2 ~= a then
          local f = M[r2][a]
          if f ~= 0 then for c = a, d + 2 do M[r2][c] = M[r2][c] - f * M[a][c] end end
        end
      end
    end
    local step = 0
    for a = 1, d do w[a] = w[a] + M[a][d + 2]; step = step + math.abs(M[a][d + 2]) end
    b = b + M[d + 1][d + 2]
    step = step + math.abs(M[d + 1][d + 2])
    if step < 1e-7 then break end
  end
  return { method = "logistic", names = names, mean = mean, scale = scale, weights = w, bias = b, lambda = lambda, n = n }
end

function C.apply_features(model, f)
  local z = model.bias
  for j, nm in ipairs(model.names) do z = z + model.weights[j] * (((f[nm] or 0) - model.mean[j]) / model.scale[j]) end
  return sigmoid(z)
end

-- features of one main interpretation (all derived from computed quantities of the interpretation itself)
function C.features(m)
  local f = { semantic_raw = (m.confidence and m.confidence.semantic_raw) or 0, coverage = (m.confidence and m.confidence.coverage) or 0 }
  f.repaired = (m.repairs and #m.repairs > 0) and 1 or 0
  f.n_repairs = m.repairs and #m.repairs or 0
  f.unknown_lowercase = (m.lexical and m.lexical.unknown_lowercase) or 0
  f.open_relation = (m.relation and tostring(m.relation.id):sub(1, 5) == "open:") and 1 or 0
  f.ambiguous = (m.ambiguity and m.ambiguity.state ~= "resolved") and 1 or 0
  local fuzzy, min_ent, unresolved = 0, 1, 0
  for _, r in pairs(m.roles or {}) do
    for _, c in ipairs(r.candidates or {}) do if c.fuzzy then fuzzy = 1 end end
    if r.candidates and r.candidates[1] and r.status ~= "ambiguous" then min_ent = math.min(min_ent, r.candidates[1].p or 1) end
    if r.needs_antecedent then unresolved = 1 end
  end
  f.fuzzy_entity, f.min_entity, f.unresolved_ref = fuzzy, min_ent, unresolved
  f.no_interpretation = (m.status ~= "ok") and 1 or 0
  return f
end

-- the calibration model shipped with the engine: embedded in the bundle as module asi.nlu.data.cal_interp_v1 (a JSON string), or read from data/ in a checkout
function C.default_model(root)
  local ok, raw = pcall(require, "asi.nlu.data.cal_interp_v1")
  if ok and type(raw) == "string" then
    local model = U.json_decode(raw)
    if model then return model end
  end
  if root then return C.load_file(root .. "/data/calibration/interp_v1.json") end
  return nil
end

function C.load_file(path)
  local f = io.open(path, "rb")
  if not f then return nil, "cannot read " .. tostring(path) end
  local raw = f:read("a")
  f:close()
  local model, err = U.json_decode(raw)
  if not model then return nil, err end
  return model
end

-- adapter for asi.nlu.record when the model works on whole-interpretation features: the Record then reports `interpretation_correct`
function C.record_adapter(model)
  return { method = model.method, n = model.n, source = model.fit and model.fit.valid_for or "labelled data", model = model, maps = {} }
end

-- adapter for asi.nlu.record: { method, n, source, maps = { <component> = function(raw) -> calibrated } }
function C.for_record(models, meta)
  local maps = {}
  for name, model in pairs(models) do maps[name] = function(raw) return U.round(C.apply(model, raw), 4) end end
  return { method = meta.method, n = meta.n, source = meta.source, maps = maps }
end

return C

end

package.preload["asi.nlu.cli"] = function(...)
-- asi.nlu.cli: command-line front end of the interpretation engine.  LM-independent, deterministic, no network.
--   interpret         interpret text (optionally against datasets and a conversation memory); human summary, JSON record, or the LM Input Package
--   interpret-eval    run a gold-case file (dev / val / test / any .cases file) with optional ablations
--   interpret-report  one-page status: the latest measured numbers (re-run on demand) in the Implemented/Verified/Measured/Unproven vocabulary
--   interpret-trace   full provenance of one request: tokens, segmentation, competing hypotheses with every named factor, repairs, constraints, evidence checks
--   interpret-memory  feed a conversation (U:/A: lines) into a memory namespace and show / save / load the memory state
--   interpret-replay  re-run a saved record's request and verify it reproduces bit-for-bit (determinism and integrity)
-- usage: lua asi.lua <command> [options]      (see `help`)
local U = require("asi.nlu.util")

local CLI = {}

local HELP = [=[
asi-nlu: LM-independent natural-language interpretation engine

  interpret [TEXT] [--file F] [--data F[:year=2020][:name=n]]... [--json] [--prompt] [--save-record F] [--calibration F] [--ns NS --user U]
  interpret-eval   [--split dev|val|test] [--file F] [--mode full|baseline|lexical_only|no_types|no_domain|no_hypotheses|no_coref|no_memory|no_repair] [--failures N]
  interpret-report [--run]
  interpret-trace  TEXT [--top N] [--data F]...
  interpret-memory [--turns FILE] [--ns NS --user U] [--save F] [--load F] [--ask TEXT]
  interpret-replay RECORD.json [--data F]...
  help
]=]

---------------------------------------------------------------- argument parsing
local function parse_args(argv)
  local opts, pos, multi = {}, {}, {}
  local i = 1
  local FLAGS = { json = true, prompt = true, run = true, help = true, verbose = true }
  while i <= #argv do
    local a = argv[i]
    if a:sub(1, 2) == "--" then
      local k = a:sub(3)
      if FLAGS[k] then opts[k] = true; i = i + 1
      else
        local v = argv[i + 1]
        if k == "data" then multi.data = multi.data or {}; table.insert(multi.data, v) else opts[k] = v end
        i = i + 2
      end
    else pos[#pos + 1] = a; i = i + 1 end
  end
  return opts, pos, multi
end

local function read_file(path)
  local f = io.open(path, "rb")
  if not f then return nil, "cannot read " .. tostring(path) end
  local s = f:read("a")
  f:close()
  return s
end

local function root_dir()
  local src = debug.getinfo(1, "S").source:gsub("^@", "")
  return (src:match("^(.*)/nlu/asi/nlu/cli%.lua$") or src:match("^(.*)/asi/nlu/cli%.lua$") or ".")
end

---------------------------------------------------------------- shared setup
local function build_engine(multi, opts)
  local R = require("asi.nlu.resources")
  local K = require("asi.nlu.knowledge")
  local Engine = require("asi.nlu.engine")
  local Cal = require("asi.nlu.calibration")
  local kb
  if multi.data and #multi.data > 0 then
    kb = K.new(R.core())
    for _, spec in ipairs(multi.data) do
      local path, rest = spec:match("^([^:]+)(.*)$")
      local text, err = read_file(path)
      if not text then return nil, err end
      local label, name = {}, path:match("[^/]+$")
      local dataset
      for kv in rest:gmatch(":([^:]+)") do
        local k, v = kv:match("^(%w+)=(.+)$")
        if k == "year" then label.year = tonumber(v) elseif k == "name" then dataset = v end
      end
      local rep = kb:ingest(text, { name = name, dataset = dataset or name:gsub("%..*$", ""), label = label, version = tostring(label.year or "1") })
      io.stderr:write(string.format("loaded %s: %d added, %d rejected\n", path, rep.added or 0, #(rep.rejected or {})))
    end
  end
  local cal
  local model = opts.calibration and Cal.load_file(opts.calibration) or Cal.default_model(root_dir())
  if model then cal = Cal.record_adapter(model) end
  return Engine.new({ knowledge = kb, calibration = cal }), kb
end

local function out(s) io.stdout:write(s .. "\n") end

---------------------------------------------------------------- human summary
local function fmt_ref(r)
  if not r then return "-" end
  local s = r.text or "?"
  if r.resolved_id then s = s .. " [" .. r.resolved_id .. "]" elseif r.status then s = s .. " (" .. r.status .. ")" end
  return s
end

local function summarize(o)
  local rec = o.record
  local lines = {}
  if not rec then lines[#lines + 1] = "(light observation only)"; return table.concat(lines, "\n") end
  lines[#lines + 1] = string.format("input      : %s", rec.original_input)
  local si = rec.semantic_intent or {}
  lines[#lines + 1] = string.format("status     : %s   speech act: %s   intent: %s   frame: %s", si.status or "?", si.speech_act or "?", si.intent or "?", si.frame or "?")
  local rr = rec.requested_relations or {}
  if rr.relation then
    lines[#lines + 1] = string.format("relation   : %s (from=%s, to=%s)   known role=%s  asks=%s   answer type: %s", rr.relation.id, tostring(rr.relation.from_type), tostring(rr.relation.to_type),
      rr.query and rr.query.known_role or "-", rr.query and rr.query.ask or "-", tostring(rec.requested_answer_type))
  end
  for _, e in ipairs(rec.resolved_entities or {}) do
    lines[#lines + 1] = string.format("entity     : %-28s -> %s (%s)", e.mention or "?", e.key or "?", e.type or "?")
  end
  local amb = rec.ambiguity_state
  if amb and amb.state ~= "resolved" then lines[#lines + 1] = "ambiguity  : " .. tostring(amb.state) end
  for _, kind in ipairs({ { "negative_constraints", "exclude" }, { "positive_constraints", "require" }, { "temporal_constraints", "time" }, { "source_constraints", "source" }, { "preferences", "prefer" } }) do
    for _, c in ipairs(rec[kind[1]] or {}) do lines[#lines + 1] = string.format("constraint : %-8s %s", kind[2], c.text or c.label or U.json_encode(c):sub(1, 90)) end
  end
  local c = rec.confidence or {}
  if c.interpretation_correct then
    lines[#lines + 1] = string.format("confidence : P(primary reading correct) = %.2f (calibrated; valid for %s)", c.interpretation_correct.calibrated, tostring(c.interpretation_correct.valid_for))
  elseif c.semantic_interpretation then
    lines[#lines + 1] = string.format("confidence : raw semantic score %.2f (uncalibrated, not a probability)", c.semantic_interpretation.raw or 0)
  end
  local es = rec.evidence_sufficiency
  if es and es.status ~= "not_applicable" then
    lines[#lines + 1] = string.format("evidence   : %s%s", es.status, es.answer and (" -> " .. tostring(es.answer.text)) or "")
    for _, ev in ipairs(rec.selected_evidence or {}) do lines[#lines + 1] = string.format("             [%s] %s (reliability %.2f, %s)", ev.role or "evidence", ev.record, ev.reliability or 0, ev.source and ev.source.name or "?") end
  end
  for _, u in ipairs(rec.unresolved_requirements or {}) do lines[#lines + 1] = string.format("unresolved : %s - %s", u.kind or "?", tostring(u.requirement or u.mention or "")) end
  return table.concat(lines, "\n")
end

---------------------------------------------------------------- commands
local function cmd_interpret(opts, pos, multi)
  local eng, err = build_engine(multi, opts)
  if not eng then io.stderr:write(err .. "\n"); return 2 end
  local text = pos[1]
  if opts.file then text = read_file(opts.file) elseif not text then text = io.read("a") end
  if not text or text == "" then io.stderr:write("no input text\n"); return 2 end
  local call = { cache = false, include_prompt = opts.prompt }
  if opts.ns then
    local mem, merr = eng:memory(opts.ns, opts.user or "user")
    if not mem then io.stderr:write(tostring(merr) .. "\n"); return 2 end
    call.memory = mem
  end
  local o = eng:process(text, call)
  if opts["save-record"] and o.record then
    local f = assert(io.open(opts["save-record"], "wb"))
    f:write(U.json_encode(o.record, { pretty = true, nan_null = true }))
    f:close()
  end
  if opts.json then out(U.json_encode(o.record or { light = true }, { pretty = true, nan_null = true }))
  elseif opts.prompt then out(o.package and o.package.prompt or "(no package)")
  else out(summarize(o)) end
  return 0
end

local function cmd_eval(opts, pos, multi)
  local E = require("asi.nlu.eval")
  local R = require("asi.nlu.resources")
  local path = opts.file or (root_dir() .. "/data/eval/" .. (opts.split or "dev") .. ".cases")
  local text, err = read_file(path)
  if not text then io.stderr:write(err .. "\n"); return 2 end
  if (opts.split == "test") and not opts.file then
    io.stderr:write("NOTE: the test split is frozen; every run is a use of the held-out set and must be logged in reports/heldout_log.md\n")
  end
  local cases, errs = E.parse_cases(text, path)
  if #errs > 0 then for _, e in ipairs(errs) do io.stderr:write(e .. "\n") end; return 2 end
  local lex = R.core()
  local rep = E.run(cases, E.make_runner(opts.mode or "full", lex), lex)
  out(E.summary(rep, (opts.mode or "full") .. "/" .. (opts.split or path)))
  local f = E.failures(rep, tonumber(opts.failures) or 15)
  if f ~= "" then out("\nFAILURES:\n" .. f) end
  return (rep.any_fail == 0) and 0 or 1
end

local function cmd_trace(opts, pos, multi)
  local R = require("asi.nlu.resources")
  local Interp = require("asi.nlu.interp")
  local text = pos[1]
  if not text then io.stderr:write("usage: interpret-trace TEXT\n"); return 2 end
  local interp = Interp.new({ lexicon = R.core() })
  local r = interp:interpret(text, {})
  local an = r.analysis
  out("TEXT: " .. an.original)
  local forms = {}
  for _, u in ipairs(an.units) do forms[#forms + 1] = string.format("%s[%d-%d]%s", u.form, u.s, u.e, u.surface_form and ("<" .. u.surface_form .. ">") or "") end
  out("UNITS: " .. table.concat(forms, " "))
  local top = tonumber(opts.top) or 5
  for si, s in ipairs(r.sentences) do
    local res, interp_s = s.res, s.interp
    out(string.format("\n--- sentence %d: %s", si, interp_s.sentence and interp_s.sentence.text or "?"))
    for ci, cv in ipairs(res.covers or {}) do
      local t = {}
      for _, sp in ipairs(cv.spans) do t[#t + 1] = sp.kind .. ":" .. (sp.text or "?") end
      out(string.format("cover #%d (score %.2f): %s", ci, cv.score, table.concat(t, " | ")))
    end
    if interp_s.repairs then
      for _, rp in ipairs(interp_s.repairs) do out(string.format("repair: %s", rp.kind == "ignored" and ("ignored '" .. tostring(rp.word) .. "'") or ("'" .. tostring(rp.from) .. "' read as '" .. tostring(rp.to) .. "' (edit distance " .. tostring(rp.dist) .. ")"))) end
    end
    out(string.format("hypotheses (%d ranked, %d vetoed):", #res.ranked, #(res.rejected or {})))
    for i, h in ipairs(res.ranked) do
      if i > top then break end
      out(string.format("  #%d  p=%.3f  score=%.2f  frame=%s  %s", i, h.p or 0, h.score or 0, tostring(h.frame), tostring(h.summary or "")))
      for _, f in ipairs(h.factors or {}) do out(string.format("        %+.2f  %-28s %s", f.v or 0, f.name or "?", f.note or "")) end
    end
    for _, rj in ipairs(res.rejected or {}) do out(string.format("  VETO %s: %s", tostring(rj.frame), tostring(rj.veto))) end
    out(string.format("ambiguity: %s", res.ambiguity and res.ambiguity.state or "?"))
    for _, pt in ipairs((res.ambiguity and res.ambiguity.points) or {}) do out(string.format("   - %s %s resolved=%s", tostring(pt.kind), tostring(pt.mention or pt.id), tostring(pt.resolved))) end
    local cons = interp_s.constraints or {}
    for _, kind in ipairs({ "negative", "positive", "temporal", "geographic", "source", "preferences", "restrictions" }) do
      for _, c in ipairs(cons[kind] or {}) do out(string.format("constraint[%s]: %s", kind, U.json_encode(c))) end
    end
  end
  return 0
end

local function cmd_memory(opts, pos, multi)
  local eng, err = build_engine(multi, opts)
  if not eng then io.stderr:write(err .. "\n"); return 2 end
  local Memory = require("asi.nlu.memory")
  local mem
  if opts.load then
    local text, rerr = read_file(opts.load)
    if not text then io.stderr:write(rerr .. "\n"); return 2 end
    local m, derr = Memory.deserialize(text)
    if not m then io.stderr:write(tostring(derr) .. "\n"); return 2 end
    mem = m
    out("loaded memory (checksum verified), " .. tostring(mem.index and mem.index.n or "?") .. " items")
  else
    mem = eng:memory(opts.ns or "cli", opts.user or "user")
  end
  if opts.turns then
    local text, rerr = read_file(opts.turns)
    if not text then io.stderr:write(rerr .. "\n"); return 2 end
    for line in (text .. "\n"):gmatch("(.-)\r?\n") do
      local who, body = line:match("^([UAD]):%s*(.*)$")
      if who and body ~= "" then
        local speaker = (who == "U" and "user") or (who == "A" and "assistant") or "doc"
        eng.interp:interpret(body, { memory = mem, speaker = speaker, light = (speaker ~= "user") })
      end
    end
  end
  if opts.ask then
    local o = eng:process(opts.ask, { memory = mem, speaker = "user", cache = false })
    out(summarize(o))
    local m = o.result and o.result.main
    for _, r in ipairs((m and m.context and m.context.references) or {}) do
      out(string.format("reference  : '%s' -> %s %s", r.mention, r.status, r.antecedent and (r.antecedent.text or r.antecedent.key) or ""))
    end
    for _, c in ipairs((m and m.context and m.context.active_constraints) or {}) do out(string.format("active     : %s %s=%s (%s)", c.kind or "?", tostring(c.slot or c.text), tostring(c.value), tostring(c.status))) end
    for _, it in ipairs((m and m.context and m.context.memory and m.context.memory.selected) or {}) do out(string.format("selected   : [turn %s %s] %s", tostring(it.turn), tostring(it.kind), tostring(it.text))) end
  end
  local d = mem.describe and mem:describe() or nil
  if d then out("memory     : " .. U.json_encode(d)) end
  if opts.save then
    local blob = mem:serialize()
    local f = assert(io.open(opts.save, "wb"))
    f:write(blob)
    f:close()
    out("saved memory to " .. opts.save)
  end
  return 0
end

local function cmd_replay(opts, pos, multi)
  local Record = require("asi.nlu.record")
  local path = pos[1]
  if not path then io.stderr:write("usage: interpret-replay RECORD.json\n"); return 2 end
  local text, err = read_file(path)
  if not text then io.stderr:write(err .. "\n"); return 2 end
  local saved, derr = U.json_decode(text)
  if not saved then io.stderr:write("bad record: " .. tostring(derr) .. "\n"); return 2 end
  local ok_integrity = Record.verify_integrity(saved)
  local eng, eerr = build_engine(multi, opts)
  if not eng then io.stderr:write(eerr .. "\n"); return 2 end
  local o = eng:process(saved.original_input, { cache = false })
  local again = o.record
  out(string.format("saved record integrity hash verifies : %s", tostring(ok_integrity)))
  out(string.format("re-run request id equals saved id      : %s", tostring(again.request_id == saved.request_id)))
  out(string.format("re-run integrity hash equals saved     : %s", tostring(again.integrity.sha256 == saved.integrity.sha256)))
  local same = ok_integrity and again.request_id == saved.request_id and again.integrity.sha256 == saved.integrity.sha256
  out(same and "REPLAY OK: identical record (deterministic)" or "REPLAY DIFFERS (different data, lexicon or engine version, or nondeterminism)")
  return same and 0 or 1
end

local function cmd_report(opts, pos, multi)
  local root = root_dir()
  local lines = { "asi-nlu status report", string.rep("=", 60) }
  local function sh(cmd) local p = io.popen(cmd .. " 2>&1"); local s = p:read("a"); p:close(); return s end
  if opts.run then
    local lua = arg and arg[-1] or "lua5.4"
    lines[#lines + 1] = "-- unit/acceptance tests"
    lines[#lines + 1] = sh(lua .. " " .. root .. "/tests/run_all.lua | tail -1")
    for _, sp in ipairs({ "dev", "val" }) do
      lines[#lines + 1] = "-- interpretation gold: " .. sp
      lines[#lines + 1] = sh(lua .. " " .. root .. "/tools/run_eval.lua --split " .. sp .. " --failures 0 | head -1")
    end
  end
  for _, rp in ipairs({ "reports/00_audit.md", "reports/performance.md", "reports/calibration.md", "reports/heldout_log.md", "reports/FINAL_REPORT.md" }) do
    local t = read_file(root .. "/" .. rp)
    lines[#lines + 1] = string.format("%-28s %s", rp, t and (#t .. " bytes") or "(not generated)")
  end
  lines[#lines + 1] = ""
  lines[#lines + 1] = "Vocabulary: Implemented = code exists and runs; Verified = covered by a passing test; Measured = a benchmark number with an interval exists;"
  lines[#lines + 1] = "            Unproven = no evidence in this environment (e.g. behaviour inside the user's own bundle, which was not available here)."
  lines[#lines + 1] = "See reports/FINAL_REPORT.md for the per-item classification."
  out(table.concat(lines, "\n"))
  return 0
end

local COMMANDS = {
  interpret = cmd_interpret, ["interpret-eval"] = cmd_eval, ["interpret-report"] = cmd_report,
  ["interpret-trace"] = cmd_trace, ["interpret-memory"] = cmd_memory, ["interpret-replay"] = cmd_replay,
}

function CLI.run(argv)
  local cmd = argv[1]
  if not cmd or cmd == "help" or cmd == "--help" or cmd == "-h" then out(HELP); return 0 end
  local fn = COMMANDS[cmd]
  if not fn then io.stderr:write("unknown command '" .. tostring(cmd) .. "'\n" .. HELP); return 2 end
  local rest = {}
  for i = 2, #argv do rest[#rest + 1] = argv[i] end
  local opts, pos, multi = parse_args(rest)
  local ok, res = xpcall(fn, function(e) return debug.traceback(tostring(e), 2) end, opts, pos, multi)
  if not ok then io.stderr:write(res .. "\n"); return 3 end
  return res or 0
end

CLI.COMMANDS = COMMANDS
return CLI

end

package.preload["asi.nlu.constraints"] = function(...)
-- asi.nlu.constraints: negation / exclusion / preference / restriction scopes + temporal, geographic and source constraints.
--   1. find_segments  : cue-led clauses ("not X", "excluding X", "prioritize X", "only using X") with STRUCTURAL extents
--   2. parse_segments : each segment is parsed on its own into a typed constraint (before any masking)
--   3. mask           : segment chunks are hidden from the positive frames, so negative scope cannot leak into the positive reading
--   4. attach         : leftover chunks of the chosen frame become temporal / geographic / source constraints
local U = require("asi.nlu.util")
local P = require("asi.nlu.parse")
local F = require("asi.nlu.frames2")

local cat = P.cat
local Cons = {}
local function C(S, k) return S.chunks[k] end

local function other(role) return role == "to" and "from" or "to" end

---------------------------------------------------------------- segment detection
local function verb_start(S, k)
  local c = C(S, k)
  if not c or not c.single then return false end
  for _, a in ipairs(P.verb_analyses(S, c)) do if a.form == "base" and a.act and not a.guessed then return true end end
  return false
end

-- returns kind, number-of-cue-chunks, cue text
-- negated inclusion / want: "Don't include X", "Never list X", "I'd rather you didn't show X", "I don't want any X" -> an exclusion cue of 2-4 chunks
local NEG_WANT = U.set({ "want", "need", "like" })
local function negated_inclusion(S, k)
  local c = C(S, k)
  if not (c and c.single) then return nil end
  local j
  if c.unit.form == "never" then j = k + 1
  elseif cat(c, "aux_do") or cat(c, "modal") or cat(c, "aux_have") then
    local n = C(S, k + 1)
    if n and n.single and P.is_neg(n) then j = k + 2 end
  end
  if not j then return nil end
  local v = C(S, j)
  if not (v and v.single and not v.masked) then return nil end
  -- "don't BOTHER including X" / "don't bother to include X"
  local bother = 0
  if v.unit.form == "bother" then
    bother = 1
    local t = C(S, j + 1)
    if t and t.single and t.unit.form == "to" then bother = 2 end
    v = C(S, j + bother)
    if not (v and v.single and not v.masked) then return nil end
  end
  for _, a in ipairs(P.verb_analyses(S, v)) do
    if (a.form == "base" or (bother > 0 and a.form == "ing")) and not a.guessed and (a.act == "include" or a.act == "retrieve" or a.act == "constraint" or NEG_WANT[a.lemma]) then return j - k + 1 + bother end
  end
  return nil
end

local function seg_start(S, k)
  local c = C(S, k)
  if not c or c.masked then return nil end
  local lex, units = S.lex, S.units
  do
    local nv = negated_inclusion(S, k)
    if nv then return "exclusion", nv, S.an.original:sub(units[c.u1].s, units[C(S, k + nv - 1).u2].e) end
  end
  local n = lex:cue_at("exclusion", units, c.u1)
  if n then
    -- count chunks covered by n units
    local cnt, consumed = 0, 0
    while C(S, k + cnt) and consumed < n do consumed = consumed + (C(S, k + cnt).u2 - C(S, k + cnt).u1 + 1); cnt = cnt + 1 end
    -- "without"/"except" inside an NP are still exclusions of the following NP; but "excluding" etc. need a body
    return "exclusion", cnt, S.an.original:sub(units[c.u1].s, units[C(S, k + cnt - 1).u2].e)
  end
  n = lex:cue_at("preference", units, c.u1)
  if n then
    local cnt, consumed = 0, 0
    while C(S, k + cnt) and consumed < n do consumed = consumed + (C(S, k + cnt).u2 - C(S, k + cnt).u1 + 1); cnt = cnt + 1 end
    -- "especially"/"just" style adverbs are weak; require something nominal to follow
    return "preference", cnt, S.an.original:sub(units[c.u1].s, units[C(S, k + cnt - 1).u2].e)
  end
  -- restriction: "only using", "only from", "based only on", "limited to", "restricted to"
  local rn = lex:cue_at("restriction", units, c.u1)
  if rn then
    local nxt = C(S, k + 1)
    if nxt and nxt.single and (nxt.unit.form == "using" or nxt.unit.form == "from" or nxt.unit.form == "in" or nxt.unit.form == "on" or nxt.unit.form == "with") then
      return "restriction", 2, S.an.original:sub(units[c.u1].s, units[nxt.u2].e)
    end
    if c.single and (c.unit.form == "limited" or c.unit.form == "restricted") and nxt and nxt.single and nxt.unit.form == "to" then
      return "restriction", 2, S.an.original:sub(units[c.u1].s, units[nxt.u2].e)
    end
  end
  -- constituent negation:  ", not X"  "but not X"  sentence-initial "not X"  "no X"
  if c.single and c.unit.form == "not" and not c.unit.neg_clitic then
    local nxt = C(S, k + 1)
    local prev = C(S, k - 1)
    if nxt and nxt.single and nxt.unit.form == "only" then return nil end
    local boundary = (k == S.first) or c.pre or (prev and prev.single and cat(prev, "conj") and (prev.unit.form == "but" or prev.unit.form == "and" or prev.unit.form == "or"))
    local verbal = prev and prev.single and (cat(prev, "aux_be") or cat(prev, "aux_do") or cat(prev, "aux_have") or cat(prev, "modal"))
    if boundary and not verbal and nxt then return "exclusion", 1, "not" end
  end
  if c.single and c.unit.form == "no" then
    local nxt = C(S, k + 1)
    local prev = C(S, k - 1)
    if nxt and not nxt.pre and not (k == S.first and nxt.pre) then
      local interjection = (k == S.first) and nxt.pre ~= nil
      local prep_before = prev and prev.single and (cat(prev, "prep") or cat(prev, "conj"))
      local verb_before = prev and verb_start(S, k - 1)
      if not interjection and (k == S.first or c.pre or prep_before or verb_before) and nxt.single == false or (nxt and nxt.single and not cat(nxt, "punct")) then
        if not interjection then return "exclusion", 1, "no" end
      end
    end
  end
  return nil
end

local function starts_new_clause(S, k)
  local c = C(S, k)
  if not c then return true end
  if c.single and cat(c, "conj") and (c.unit.form == "and" or c.unit.form == "or" or c.unit.form == "but") then
    local n = C(S, k + 1)
    if not n then return true end
    return seg_start(S, k + 1) ~= nil or verb_start(S, k + 1)
  end
  if seg_start(S, k) then return true end
  if verb_start(S, k) then return true end
  if c.single and c.unit.form == "but" then return true end
  return false
end

local function seg_end(S, body_first)
  local e = body_first - 1
  local k = body_first
  while k <= S.last do
    local c = C(S, k)
    if c.masked then break end
    if k > body_first then
      local pre = c.pre
      if pre and (pre:find("sent") or pre:find("semi") or pre:find("colon") or pre:find("paren")) then break end
      if pre and pre:find("comma") and starts_new_clause(S, k) then break end
      if c.single and c.unit.form == "but" then break end
      if c.single and cat(c, "conj") and (c.unit.form == "and" or c.unit.form == "or") and starts_new_clause(S, k) then break end
      if not (pre and pre:find("comma")) and seg_start(S, k) then break end
    end
    e = k
    k = k + 1
  end
  return e
end

function Cons.find_segments(S)
  local segs = {}
  local k = S.first
  while k <= S.last do
    local kind, ncue, cue = seg_start(S, k)
    if kind then
      local body_first = k + ncue
      local e = seg_end(S, body_first)
      if e >= body_first then
        segs[#segs + 1] = { kind = kind, cue = cue, a = k, b = e, body_first = body_first, body_last = e }
        k = e + 1
      else k = k + 1 end
    else k = k + 1 end
  end
  return segs
end

function Cons.apply_masks(S, segs)
  for _, sg in ipairs(segs) do
    for i = sg.a, sg.b do S.chunks[i].masked = true; S.chunks[i].mask_kind = sg.kind end
  end
  S.np_memo, S.vp_memo, S.wh_memo = {}, {}, {}
end

function Cons.clear_masks(S)
  for _, c in ipairs(S.chunks) do c.masked = nil; c.mask_kind = nil end
  S.np_memo, S.vp_memo, S.wh_memo = {}, {}, {}
end

---------------------------------------------------------------- segment bodies -> typed constraints
local JOINERS = U.set({ "and", "or", "nor" })

local function describe_target(S, np)
  local t = { text = P.span_text(S, np), head_kind = np.head_kind }
  if np.head_kind == "typenoun" then
    t.scope, t.type = "type", np.senses and np.senses[1] and np.senses[1].type
    t.plural = np.plural
  elseif np.head_kind == "entity" then
    t.scope = "entity"; t.cands = np.cands
  elseif np.head_kind == "pronoun" then
    t.scope = "reference"; t.pron = np.pron and np.pron.form
  elseif np.head_kind == "relnoun" then
    t.scope = "role"; t.rel = np.relnouns and np.relnouns[1] and np.relnouns[1].rel
  else
    t.scope = "topic"
  end
  if np.superlative then t.superlative = np.superlative; t.scope = "description" end -- "the largest city": a description, not a type
  if np.count then t.count = np.count end
  if np.temporal_scope then t.temporal_scope = np.temporal_scope end
  if np.of_arg then t.of = describe_target(S, np.of_arg) end
  if np.possessor then t.possessor = describe_target(S, np.possessor) end
  t.np = np
  return t
end

local function parse_items(S, first, last)
  local items, unparsed = {}, {}
  local k = first
  while k <= last do
    local c = C(S, k)
    if c.single and (JOINERS[c.unit.form] or false) and k > first then k = k + 1
    elseif c.pre and (c.pre:find("comma")) and k > first and not C(S, k).single and false then k = k + 1
    else
      local best
      for _, np in ipairs(P.parse_np(S, k)) do
        if np.nxt - 1 <= last and (not best or np.nxt > best.nxt or (np.nxt == best.nxt and np.score > best.score)) then best = np end
      end
      if best then
        local filters, nk = F.parse_filters(S, best.nxt, best, last)
        items[#items + 1] = { np = best, filters = filters, first = k, last = nk - 1 }
        k = nk
      else
        unparsed[#unparsed + 1] = k
        k = k + 1
      end
    end
  end
  return items, unparsed
end

function Cons.parse_segments(S, segs)
  local out = { negative = {}, preferences = {}, restrictions = {}, ordering = {}, unparsed = {} }
  for _, sg in ipairs(segs) do
    local items, unparsed = parse_items(S, sg.body_first, sg.body_last)
    for _, u in ipairs(unparsed) do out.unparsed[#out.unparsed + 1] = { chunk = u, seg = sg.kind } end
    for _, it in ipairs(items) do
      local tgt = describe_target(S, it.np)
      tgt.filters = it.filters
      local ent = { cue = sg.cue, kind = sg.kind, target = tgt, scope_chunks = { sg.a, sg.b },
        scope_text = S.an.original:sub(S.units[S.chunks[sg.a].u1].s, S.units[S.chunks[sg.b].u2].e), source_units = { S.chunks[sg.a].u1, S.chunks[sg.b].u2 } }
      if sg.kind == "exclusion" then out.negative[#out.negative + 1] = ent
      elseif sg.kind == "preference" then out.preferences[#out.preferences + 1] = ent
      elseif sg.kind == "restriction" then
        ent.resource = (it.np.head and S.lex:resource(it.np.head.form)) or nil
        if it.np.temporal_mod then ent.label = it.np.temporal_mod.text end
        ent.qualifiers = {}
        for _, m in ipairs(it.np.mods) do ent.qualifiers[#ent.qualifiers + 1] = m.form end
        out.restrictions[#out.restrictions + 1] = ent
      end
    end
    if #items == 0 and (sg.kind == "exclusion") then
      out.unparsed[#out.unparsed + 1] = { chunk = sg.body_first, seg = sg.kind, note = "exclusion cue without a parsable target" }
    end
  end
  return out
end

---------------------------------------------------------------- leftover chunks of the winning frame
local function temporal_constraint(expr, role_override)
  return { kind = expr.kind, text = expr.text, op = expr.op, eff_lo = expr.eff_lo, eff_hi = expr.eff_hi, lo = expr.lo, hi = expr.hi,
    role = role_override or expr.role, scope = expr.scope, precision = expr.precision, relative = expr.relative, resolved = expr.resolved,
    persist = expr.persist, unresolved = expr.unresolved, year = expr.year }
end

local function place_compatible(S, np)
  if np.head_kind ~= "entity" then return false end
  for _, cd in ipairs(np.cands or {}) do
    if cd.unseen or S.lex:compat(cd.type, "place") > 0 or S.lex:compat(cd.type, "organization") > 0 then return true end
  end
  return false
end

function Cons.attach(S, h)
  local cons = h.constraints
  cons.temporal = cons.temporal or {}
  cons.geographic = cons.geographic or {}
  cons.source = cons.source or {}
  cons.ordering = cons.ordering or {}
  cons.quantity = cons.quantity or {}
  local lex = S.lex
  local k = S.first
  local used = h.used
  while k <= S.last do
    local c = C(S, k)
    if not used[k] and not c.masked then
      local handled = false
      -- source phrases: "according to the supplied 2020 dataset", "based on the report", "from the 2020 census"
      local n = lex:cue_at("source_intro", S.units, c.u1)
      if n then
        local cnt, consumed = 0, 0
        while C(S, k + cnt) and consumed < n do consumed = consumed + (C(S, k + cnt).u2 - C(S, k + cnt).u1 + 1); cnt = cnt + 1 end
        for _, np in ipairs(P.parse_np(S, k + cnt)) do
          local canon = np.head and lex:resource(np.head.form)
          if canon then
            local src = { kind = "source", resource = canon, text = P.span_text(S, np), quals = {}, cue = c.text }
            if np.temporal_mod then src.label = np.temporal_mod.text; src.label_year = np.temporal_mod.year end
            for _, m in ipairs(np.mods) do if m.kind == "mod" or m.kind == "ordinal" or m.kind == "superlative" or m.kind == "temporal_adj" then src.quals[#src.quals + 1] = m.form end end
            cons.source[#cons.source + 1] = src
            for i = k, np.c2 do used[i] = true end
            k = np.c2; handled = true
            break
          end
        end
      end
      -- temporal expressions
      if not handled and c.temporal then
        local ex = c.temporal
        if ex.kind == "persist" or ex.persist then
          h.persist = true; used[k] = true; handled = true
        elseif ex.kind == "marker" then
          h.temporal_scope = h.temporal_scope or ex.scope; used[k] = true; handled = true
        elseif ex.kind == "weekday" then used[k] = true; handled = true
        elseif ex.role == "label" then
          -- a year-like label that modifies a resource noun is a source label, not a time scope
          local nx = C(S, k + 1)
          local canon = nx and nx.single and lex:resource(nx.unit.form)
          if canon then
            cons.source[#cons.source + 1] = { kind = "source", resource = canon, label = ex.text, label_year = ex.year, quals = {}, implicit = true }
            used[k] = true; used[k + 1] = true; k = k + 1; handled = true
          else
            cons.temporal[#cons.temporal + 1] = temporal_constraint(ex, "scope"); used[k] = true; handled = true
          end
        else
          cons.temporal[#cons.temporal + 1] = temporal_constraint(ex); used[k] = true; handled = true
          if ex.scope and not h.temporal_scope then h.temporal_scope = ex.scope end
        end
      end
      -- geographic phrases: "in Germany", "near Boston"
      if not handled and c.single and cat(c, "prep") and (c.unit.form == "in" or c.unit.form == "near" or c.unit.form == "around" or c.unit.form == "within" or c.unit.form == "across") then
        for _, np in ipairs(P.parse_np(S, k + 1, { no_of = true })) do
          if place_compatible(S, np) then
            cons.geographic[#cons.geographic + 1] = { prep = c.unit.form, value = np, text = P.span_text(S, np) }
            for i = k, np.c2 do used[i] = true end
            k = np.c2; handled = true
            break
          end
        end
      end
      -- temporal-scope adverbs and marker words  ("currently", "formerly")
      if not handled and c.single and c.unit.temporal_scope then
        h.temporal_scope = h.temporal_scope or c.unit.temporal_scope; used[k] = true
      end
    end
    k = k + 1
  end
end

-- unexplained content chunks (closed-class function words are not "content")
function Cons.unexplained(S, h)
  local out = {}
  -- a clause-suffix reading leaves everything before its first chunk unexplained
  for _, pc in ipairs(S.prefix_chunks or {}) do out[#out + 1] = pc.idx end
  for k = S.first, S.last do
    local c = C(S, k)
    if not c.masked and not h.used[k] and not P.is_function_chunk(S, c) then out[#out + 1] = k end
  end
  return out
end

return Cons

end

package.preload["asi.nlu.coref"] = function(...)
-- asi.nlu.coref: discourse reference resolution against layered memory.
--   View:pronoun_binding  candidate antecedents for a personal/demonstrative pronoun, scored from real evidence (salience, recency, focus,
--                         agreement, role type, co-argument exclusion) against an explicit "no antecedent" competitor.
--   C.resolve_references  definite back-references ("the business I mentioned earlier"), ordinal/labelled artifacts ("the second
--                         solution", "the revised version"), correction references and comparison sets -- or an explicit,
--                         inspectable "unresolved" requirement.  Nothing is ever fabricated to fill a missing antecedent.
local U = require("asi.nlu.util")

local C = {}
C.W = {
  salience = 1.0, recency = 0.45, focus = 0.8, topical = 0.2, user_intro = 0.1, type_fit = 0.6, unknown_animacy = -0.3,
  plural_mismatch = -0.6, none_personal = 0.15, none_demonstrative = 2.0, temperature = 0.35, resolve_p = 0.60, resolve_margin = 0.30,
}

local TOPICAL = U.set({ "focus", "subject", "stmt_subject", "clause_subject", "arg:from", "item", "chain_arg" })

---------------------------------------------------------------- view over one memory
local View = {}
View.__index = View

function C.view(mem, lex, opts)
  return setmetatable({ mem = mem, lex = lex, opts = opts or {} }, View)
end

-- previously mentioned entities -> weight in [0,1] (feeds entity-candidate scoring as discourse evidence)
function View:mention_weights()
  local out = {}
  for key, e in pairs(self.mem.entities) do
    local s = self.mem:salience(e)
    if s > 0.05 then out[key] = math.min(1, s) end
  end
  return out
end

-- domain cue words in recent turns -> hits per domain (decayed by turn distance; at most 2, like in-message cues)
function View:domain_profile()
  local mem, lex = self.mem, self.lex
  local acc = {}
  for _, id in ipairs(mem.order) do
    local it = mem.items[id]
    if it and it.kind == "utterance" and it.status == "active" and it.turn < mem.turn and mem.turn - it.turn <= 8 and it.speaker == "user" then
      local w = mem.decay ^ (mem.turn - it.turn)
      for word in (it.text or ""):lower():gmatch("[%a][%a'%-]*") do
        for d in pairs(lex:domains_of(word)) do
          acc[d] = acc[d] or {}
          acc[d][word] = math.max(acc[d][word] or 0, w)
        end
      end
    end
  end
  local prof = {}
  for d, words in pairs(acc) do
    local total = 0
    for _, w in pairs(words) do total = total + w end
    if total >= 1.5 then prof[d] = 2 elseif total >= 0.5 then prof[d] = 1 end
  end
  return prof
end

-- recency rank per entity: mentions within one sentence share a rank (their order is not a recency signal)
local function recency_ranks(mem)
  local keyed, seen = {}, {}
  for key, e in pairs(mem.entities) do
    local lm = e.mentions[#e.mentions]
    local rk = (lm and lm.turn or 0) * 1000 + ((lm and lm.sent) or 0)
    keyed[key] = rk
    seen[rk] = true
  end
  local list = {}
  for rk in pairs(seen) do list[#list + 1] = rk end
  table.sort(list, function(a, b) return a > b end)
  local rank_of = {}
  for i, rk in ipairs(list) do rank_of[rk] = i end
  local out = {}
  for key, rk in pairs(keyed) do out[key] = rank_of[rk] end
  return out
end

---------------------------------------------------------------- agreement
-- returns ok, penalty, reason
-- the type used for agreement: an attested type, or an inferred one that cannot be a supertype of person (an inferred 'agent' says nothing about animacy)
local function effective_type(lex, e)
  if e.type then return e.type end
  local it = e.itype
  if it and (lex:isa(it, "person") or not lex:isa("person", it)) then return it end
  return nil
end
C.effective_type = effective_type

local function agreement(lex, feats, e, form)
  local W = C.W
  local t = effective_type(lex, e)
  local an = tostring(feats.animate or "any")
  local person_like = t and lex:isa(t, "person") or false
  if an == "1" then
    if t and not person_like then return false, 0, "animate pronoun '" .. form .. "' cannot refer to a " .. t end
    if not t and e.pname then return true, W.unknown_animacy * 0.2, "multiword capitalised name without organisation or place cues: probably a person" end
    if not t then return true, W.unknown_animacy, "animacy of the candidate is unknown" end
  elseif an == "0" then
    if person_like then return false, 0, "'" .. form .. "' does not refer to a person (" .. t .. ")" end
    if not t and e.pname then return true, W.unknown_animacy * 1.5, "looks like a person's name; '" .. form .. "' is inanimate" end
    if not t then return true, W.unknown_animacy, "animacy of the candidate is unknown" end
  end
  local num = tostring(feats.number or "any")
  if num == "sg" and e.plural then return true, W.plural_mismatch, "singular pronoun vs plural antecedent" end
  if num == "pl" and not e.plural and e.type then return true, W.plural_mismatch * 0.5, "plural pronoun vs singular antecedent" end
  return true, 0, nil
end

-- other entity arguments of the same hypothesis may not be the antecedent of a non-reflexive pronoun
local function coarguments(H, S, ctx, h, np)
  local ex = {}
  local function consider(x)
    if x and x ~= np and x.head_kind == "entity" then
      local b = H.bind_np(S, ctx, x, nil, h, "coarg")
      if b and b.top and (b.status == "resolved" or b.status == "unseen") then ex[b.top.id] = true end
    end
  end
  for _, x in pairs(h.roles or {}) do consider(x) end
  consider(h.subject); consider(h.concept); consider(h.target); consider(h.focus); consider(h.object)
  for _, x in ipairs(h.items or {}) do consider(x) end
  if h.statement then consider(h.statement.subj); consider(h.statement.obj) end
  if h.clause then consider(h.clause.subj); consider(h.clause.obj) end
  return ex
end

---------------------------------------------------------------- pronoun binding (called from hyp.bind_np)
local function softmax(scores, T)
  local m = -math.huge
  for _, s in ipairs(scores) do if s > m then m = s end end
  local sum, ex = 0, {}
  for i, s in ipairs(scores) do ex[i] = math.exp((s - m) / T); sum = sum + ex[i] end
  for i = 1, #ex do ex[i] = ex[i] / sum end
  return ex
end

-- pleonastic "it": weather/ambient verbs ("It rained on the ferry"), ambient adjectives ("It was cold") and extraposition ("It is clear that ...",
-- "It seems to ...") have no antecedent.  Closed word lists live in the lexicon (cue extrapose_* / ambient_adj, verb act=ambient).
local function expletive_it(S, np, h)
  local lex = S.lex
  local P = require("asi.nlu.parse")
  local c1 = np.c1
  local nx = S.chunks[c1 + 1]
  if not nx then return false end
  for _, vp in ipairs(P.parse_vp(S, c1 + 1)) do
    local v = lex.verbs[vp.lemma]
    if v and v.act == "ambient" then return true end
  end
  local function is_cue(name, c) return c and c.single and lex:is_cue(name, c.unit.form) end
  local k = c1 + 1
  local is_be = nx.single and nx.cats and nx.cats.aux_be
  if is_be then k = k + 1 end
  while S.chunks[k] and S.chunks[k].cats and S.chunks[k].cats.adv do k = k + 1 end
  local c = S.chunks[k]
  if is_be and is_cue("ambient_adj", c) then return true end
  if (is_be and is_cue("extrapose_adj", c)) or (not is_be and is_cue("extrapose_verb", nx)) then
    for j = k, math.min(k + 4, #S.chunks) do
      local cj = S.chunks[j]
      if cj and cj.single and lex:is_cue("extrapose_comp", cj.unit.form) then return true end
    end
  end
  return false
end

function View:pronoun_binding(S, ctx, np, expected, h, role, b)
  local mem, lex, W = self.mem, self.lex, C.W
  local feats = np.pron.feats or {}
  local form = np.pron.form:lower()
  b.discourse, b.pronoun = true, form
  -- indefinites ("someone", "everything") are not anaphors; pleonastic "it" has no antecedent
  local pcats = np.pron.cats or {}
  if pcats.pron_indef and form ~= "one" and form ~= "ones" then b.status, b.fit, b.indefinite = "indefinite", 0.25, true return b end
  if form == "it" and expletive_it(S, np, h) then b.status, b.fit, b.expletive = "expletive", 0.25, true return b end
  -- a fronted topic ("Going back to X, who acquired it?") is the antecedent of the third-person pronouns of the sentence; the topic phrase is resolved in resolve_references
  if S.topic and (form == "it" or form == "its" or form == "they" or form == "their" or form == "them" or form == "he" or form == "she" or form == "his" or form == "her" or form == "him") then
    b.status, b.fit, b.topic_bound, b.cands = "topic_pending", 0.25, true, {}
    return b
  end
  local person = tostring(feats.person or "3")
  if person == "1" or person == "2" then
    local who = person == "1" and "speaker" or "addressee"
    local ty = person == "1" and "person" or "agent"
    local top = { id = who .. ":" .. (person == "1" and (mem.speaker or "user") or "assistant"), type = ty, name = form, p = 1.0, score = 1.0,
      reasons = { "first/second-person pronoun: deictic reference to the " .. who } }
    b.cands, b.top, b.status, b.deictic, b.type = { top }, top, "resolved", who, ty
    b.fit = lex:compat(ty, expected)
    return b
  end
  local H = require("asi.nlu.hyp")
  local exclude = h and coarguments(H, S, ctx, h, np) or {}
  local reflexive = (np.pron.cats and np.pron.cats.pron_refl) == true
  if reflexive then exclude = {} end
  local ranks = recency_ranks(mem)
  local order = {}
  for _, e in pairs(mem.entities) do order[#order + 1] = e end
  table.sort(order, function(a, c) if ranks[a.key] ~= ranks[c.key] then return ranks[a.key] < ranks[c.key] end return a.key < c.key end)
  local live, rejected = {}, {}
  for _, e in ipairs(order) do
    local key = e.key
    local rank = ranks[key]
    if exclude[key] then
      rejected[#rejected + 1] = { id = key, type = e.type, reasons = { "co-argument of the same predicate: a non-reflexive pronoun cannot corefer with it" } }
    else
      local ok, pen, why = agreement(lex, feats, e, form)
      if not ok then rejected[#rejected + 1] = { id = key, type = e.type, reasons = { why } }
      else
        local et = effective_type(lex, e)
        local fit = (expected and et) and lex:compat(et, expected) or 0.25
        if fit == -1.0 then
          rejected[#rejected + 1] = { id = key, type = et, reasons = { "type " .. tostring(et) .. " cannot fill " .. tostring(expected) } }
        else
          local reasons = {}
          local sal = math.min(1, mem:salience(e)) * (e.weak and 0.4 or 1)
          local s = W.salience * sal
          reasons[#reasons + 1] = string.format("salience %.2f%s", sal, e.weak and " (weak: capitalisation is the only name evidence)" or "")
          local rec = W.recency / rank
          s = s + rec; reasons[#reasons + 1] = string.format("mention recency rank %d (+%.2f)", rank, rec)
          if mem.focus and mem.focus.key == key then
            local fb = W.focus * (mem.decay ^ math.max(0, mem.turn - mem.focus.turn))
            s = s + fb; reasons[#reasons + 1] = string.format("current discourse focus (+%.2f)", fb)
          end
          local lm = e.mentions[#e.mentions]
          if lm and TOPICAL[lm.role or ""] then s = s + W.topical; reasons[#reasons + 1] = "last mentioned in a topical role (" .. lm.role .. ")" end
          if e.by_user then s = s + W.user_intro; reasons[#reasons + 1] = "introduced by the user" end
          if expected and e.type then s = s + W.type_fit * fit; reasons[#reasons + 1] = string.format("type fit %.2f for %s", fit, tostring(expected)) end
          if pen ~= 0 then s = s + pen; reasons[#reasons + 1] = why end
          local display = e.display or key
          if lm and lm.text then display = lm.text end
          live[#live + 1] = { id = key, type = e.type, name = display, score = s, fit = fit, reasons = reasons, turn = e.last_turn, first_turn = e.first_turn }
        end
      end
    end
  end
  -- plural / collective pronouns may denote the most recent comparison set
  local pl = tostring(feats.number or "any") ~= "sg"
  if pl and mem.comparison and #mem.comparison.keys >= 2 and (form == "they" or form == "them" or form == "these" or form == "those") then
    local sal = mem.decay ^ math.max(0, mem.turn - mem.comparison.turn)
    live[#live + 1] = { id = "group:" .. table.concat(mem.comparison.keys, "+"), type = nil, name = "the compared items", score = W.salience * sal + 0.4, fit = 0.25,
      reasons = { "most recent comparison set", string.format("decay %.2f", sal) }, turn = mem.comparison.turn, group = mem.comparison.keys }
  end
  local demo = (np.pron.cats and (np.pron.cats.pron_dem == true)) or form == "this" or form == "that"
  local none = demo and W.none_demonstrative or W.none_personal
  table.sort(live, function(a, c) if a.score ~= c.score then return a.score > c.score end return a.id < c.id end)
  b.rejected = rejected
  b.expected = expected
  if #live == 0 then
    b.status, b.fit = "unresolved", 0.25
    b.none_reason = #rejected > 0 and "candidate entities exist but none agrees with the pronoun and its role" or "no entity has been mentioned in the available context"
    return b
  end
  local scores = { none }
  for i, c in ipairs(live) do scores[i + 1] = c.score end
  local ps = softmax(scores, W.temperature)
  b.p_none = ps[1]
  for i, c in ipairs(live) do c.p = ps[i + 1] end
  b.cands, b.top = live, live[1]
  local second = math.max(live[2] and live[2].p or 0, b.p_none)
  local margin = live[1].p - second
  b.margin = margin
  if live[1].p >= W.resolve_p and margin >= W.resolve_margin then
    b.status = "resolved"
    b.fit = live[1].fit
    local mem_turn = mem.turn
    b.antecedent = { key = live[1].id, text = live[1].name, type = live[1].type, turn = live[1].turn, distance_turns = math.max(0, mem_turn - (live[1].turn or mem_turn)),
      via = "pronoun", p = live[1].p, group = live[1].group }
  elseif b.p_none >= live[1].p then
    b.status, b.fit = "unresolved", 0.25
    b.none_reason = "no candidate is salient enough to be the antecedent (no-antecedent hypothesis p=" .. string.format("%.2f", b.p_none) .. ")"
  else
    b.status, b.fit = "ambiguous", live[1].fit
    b.none_reason = "several antecedents remain plausible"
  end
  return b
end

---------------------------------------------------------------- non-pronoun references
-- walk every ref table of a rendered interpretation, giving each a role name and the role's expected type
function C.walk(interp, fn)
  local seen = {}
  local function visit(r, role, expected, depth)
    if not r or seen[r] then return end
    seen[r] = true
    fn(r, role, expected)
    if depth < 3 then
      if r.of then visit(r.of, role .. ".of", nil, depth + 1) end
      if r.possessor then visit(r.possessor, role .. ".poss", nil, depth + 1) end
    end
  end
  local rel = interp.relation
  for role, r in pairs(interp.roles or {}) do
    local exp = rel and ((role == "from" and rel.from_type) or (role == "to" and rel.to_type)) or nil
    visit(r, "arg:" .. role, exp, 0)
  end
  for _, k in ipairs({ "topic", "subject", "concept", "target", "focus", "object", "basis" }) do visit(interp[k], k, nil, 0) end
  for _, it in ipairs(interp.items or {}) do visit(it, "item", nil, 0) end
  if interp.statement then visit(interp.statement.subject, "stmt_subject", nil, 0); visit(interp.statement.object, "stmt_object", nil, 0) end
  if interp.clause then visit(interp.clause.subject, "clause_subject", nil, 0); visit(interp.clause.object, "clause_object", nil, 0) end
  if interp.instruction then visit(interp.instruction.object, "instruction_object", nil, 0) end
  for _, st in ipairs((interp.query and interp.query.steps) or {}) do visit(st.known, "chain_arg", nil, 0) end
  if interp.query and interp.query.qualifier then visit(interp.query.qualifier.arg, "qualifier", nil, 0) end
end

local function label_kind(lex, r)
  for _, m in ipairs(r.modifiers or {}) do
    local w = (m.text or ""):lower()
    if lex:is_cue("art_latest", w) then return "latest", w end
    if lex:is_cue("art_first", w) then return "first", w end
    if lex:is_cue("art_prev", w) then return "previous", w end
  end
  return nil
end

local function artifact_summary(a)
  return { key = "artifact:" .. a.class .. ":" .. tostring(a.ordinal), text = a.label or (a.class .. " " .. tostring(a.ordinal)), type = "artifact:" .. a.class,
    turn = a.turn, item = a.item, excerpt = (a.text or ""):sub(1, 160), ordinal = a.ordinal, via = "artifact" }
end

-- artifacts of the given classes from the latest enumeration of each class
local function latest_enumeration(mem, class)
  local list = mem.artifacts[class] or {}
  local best_turn = -1
  for _, a in ipairs(list) do if a.turn > best_turn then best_turn = a.turn end end
  local out = {}
  for _, a in ipairs(list) do if a.turn == best_turn then out[#out + 1] = a end end
  table.sort(out, function(a, b) return (a.ordinal or 0) < (b.ordinal or 0) end)
  return out
end

function View:resolve_artifact(r, classes)
  local mem = self.mem
  local lex = self.lex
  local reasons, found, tried = {}, {}, {}
  for class in pairs(classes) do
    if mem.artifacts[class] then
      tried[#tried + 1] = class
      local enum = latest_enumeration(mem, class)
      if r.ordinal then
        for _, a in ipairs(enum) do if a.ordinal == r.ordinal then found[#found + 1] = a; reasons[#reasons + 1] = "ordinal " .. r.ordinal .. " of the latest enumeration of '" .. class .. "' (turn " .. a.turn .. ")" end end
      else
        local kind, word = label_kind(lex, r)
        if kind == "latest" and #enum > 0 then found[#found + 1] = enum[#enum]; reasons[#reasons + 1] = "'" .. word .. "' selects the most recent '" .. class .. "'"
        elseif kind == "first" and #enum > 0 then found[#found + 1] = enum[1]; reasons[#reasons + 1] = "'" .. word .. "' selects the earliest '" .. class .. "'"
        elseif kind == "previous" and #enum > 1 then found[#found + 1] = enum[#enum - 1]; reasons[#reasons + 1] = "'" .. word .. "' selects the one before the latest '" .. class .. "'"
        end
      end
    end
  end
  return found, reasons, tried
end

-- corrections / standing instructions made by the user earlier (superseded ones are kept: they are still "the correction I made")
function View:resolve_correction(r, interp)
  local mem = self.mem
  local cands = {}
  for i = #mem.order, 1, -1 do
    local it = mem.items[mem.order[i]]
    if it and it.speaker == "user" and (it.kind == "correction" or it.kind == "instruction" or it.kind == "prohibition" or it.kind == "preference") and it.turn < mem.turn
      and it.status ~= "revoked" then
      cands[#cands + 1] = it
    end
  end
  local only_corr = {}
  for _, it in ipairs(cands) do if it.kind == "correction" then only_corr[#only_corr + 1] = it end end
  if (r.head == "correction" or r.head == "corrections" or r.head == "amendment") then cands = only_corr end
  return cands
end

function View:describe_item(it)
  return { key = "memory:" .. it.id, text = it.text, type = "memory:" .. it.kind, turn = it.turn, item = it.id, slot = it.slot, value = it.value,
    status = it.status, via = "memory_item" }
end

-- entity referred to by a definite description with a discourse-linked relative clause
function View:resolve_entity_backref(r, expected, exclude)
  local mem, lex, W = self.mem, self.lex, C.W
  local cands, rejected = {}, {}
  local kind_evidence = false -- some candidate is known (by type or by the conversation's own description) to be the kind the head noun names
  local ranks = recency_ranks(mem)
  local order = {}
  for _, e in pairs(mem.entities) do order[#order + 1] = e end
  table.sort(order, function(a, b) if ranks[a.key] ~= ranks[b.key] then return ranks[a.key] < ranks[b.key] end return a.key < b.key end)
  for _, e in ipairs(order) do
    local rank = ranks[e.key]
    if exclude[e.key] then
      rejected[#rejected + 1] = { id = e.key, reason = "argument of the same request" }
    else
      local fit = (expected and e.type) and lex:compat(e.type, expected) or 0.25
      local rtype = r.type
      if rtype and e.type then
        local f2 = lex:compat(e.type, rtype)
        if f2 < fit then fit = f2 end
      end
      if fit == -1.0 then rejected[#rejected + 1] = { id = e.key, reason = "type " .. tostring(e.type) .. " cannot be the described " .. tostring(r.type or expected) }
      elseif e.first_turn >= mem.turn and (e.last_turn or 0) >= mem.turn and #e.mentions <= 1 then
        rejected[#rejected + 1] = { id = e.key, reason = "mentioned only in the current request, not earlier" }
      else
        local reasons = {}
        local s = 0.6 * fit; reasons[#reasons + 1] = string.format("type fit %.2f", fit)
        local rec = W.recency / rank; s = s + rec; reasons[#reasons + 1] = string.format("recency rank %d", rank)
        local sal = math.min(1, mem:salience(e)); s = s + 0.5 * sal; reasons[#reasons + 1] = string.format("salience %.2f", sal)
        local who = r.backref_who
        if who and e.by_speaker and e.by_speaker[who] then s = s + 0.4; reasons[#reasons + 1] = "introduced by the " .. who .. " (the clause says so)"
        elseif who and e.by_speaker and not e.by_speaker[who] then s = s - 0.5; reasons[#reasons + 1] = "never mentioned by the " .. who end
        if r.head then
          local best = 0
          for _, d in pairs(e.descriptors or {}) do best = math.max(best, C.descriptor_match(self, r.head, d)) end
          if best > 0 then s = s + 1.2 * best; reasons[#reasons + 1] = string.format("described in the conversation as a matching kind of '%s' (%.1f)", r.head, best) end
          -- modifiers of the reference ("the SMALL company") that the description of the entity repeats
          if best > 0 and r.modifiers then
            for _, d in pairs(e.descriptors or {}) do
              if C.descriptor_match(self, r.head, d) > 0 then
                local dt = " " .. (d.text or ""):lower() .. " "
                for _, m in ipairs(r.modifiers) do
                  local w = (m.text or ""):lower()
                  if w ~= "" and dt:find(" " .. w .. " ", 1, true) then s = s + 0.5; reasons[#reasons + 1] = "its description repeats '" .. w .. "'"; break end
                end
                break
              end
            end
          end
          -- the head noun names a KIND ("the company ..."): a candidate with no evidence at all of being that kind (no matching type, no matching description)
          -- is a poor referent, however recently it was named
          local head_type
          for _, sn in ipairs(lex.sense_by_head[(r.head or ""):lower()] or {}) do if sn.type and sn.kind == "typenoun" then head_type = head_type or sn.type end end
          if head_type then
            local type_ok = e.type and lex:compat(e.type, head_type) >= 0.5
            if type_ok or best > 0 then kind_evidence = true end
            if not type_ok and best == 0 then s = s - 1.0; reasons[#reasons + 1] = "no evidence that it is a " .. r.head end
          end
        end
        if e.weak then s = s - 0.8; reasons[#reasons + 1] = "weak name evidence (sentence-initial capital only)" end
        cands[#cands + 1] = { id = e.key, type = e.type, name = e.names and next(e.names) and select(2, next(e.names)) or e.key, score = s, reasons = reasons, turn = e.last_turn }
      end
    end
  end
  -- an entity whose only evidence is a sentence-initial capital is a candidate of last resort, never a competitor of an established one
  local strong = {}
  for _, c in ipairs(cands) do if not (mem.entities[c.id] and mem.entities[c.id].weak) then strong[#strong + 1] = c end end
  if #strong > 0 and #strong < #cands then
    for _, c in ipairs(cands) do
      if mem.entities[c.id] and mem.entities[c.id].weak then rejected[#rejected + 1] = { id = c.id, reason = "weak name evidence (sentence-initial capital only) while established entities exist" } end
    end
    cands = strong
  end
  table.sort(cands, function(a, b) if a.score ~= b.score then return a.score > b.score end return a.id < b.id end)
  if #cands > 0 then
    local ps = softmax(U.map(cands, function(c) return c.score end), W.temperature)
    for i, c in ipairs(cands) do c.p = ps[i] end
  end
  -- the head noun names a KIND ("the company ...") but nothing in the conversation says that ANY candidate is one: ranking by recency alone is a guess
  local head_named = false
  if r.head then for _, sn in ipairs(lex.sense_by_head[(r.head or ""):lower()] or {}) do if sn.type and sn.kind == "typenoun" then head_named = true end end end
  cands.kind_unverified = head_named and not kind_evidence and #cands > 1 or nil
  return cands, rejected
end

-- classifying descriptors attached to entity mentions by apposition ("X, a small robotics business") or copula ("X is a robotics company")
-- items = { {key=, c1=, c2=}, ... } chunk ranges of entity mentions in state S
-- the entity/name spans of a sentence state, as {key, type, name, weak, c1, c2} (one key per span; ambiguous spans are skipped)
function C.mentions_from_state(S, text_of)
  local out = {}
  for k, c in ipairs(S.chunks) do
    local ids, name_r, n = {}, nil, 0
    for _, r in ipairs(c.entities) do if not r.fuzzy and r.entry then ids[r.entry.id] = r.entry.etype end end
    for _ in pairs(ids) do n = n + 1 end
    for _, r in ipairs(c.names) do name_r = name_r or r end
    local text = S.an.original:sub(S.units[c.u1].s, S.units[c.u2].e)
    if n == 1 then
      local id, ty = next(ids)
      out[#out + 1] = { key = id, type = ty, name = text, c1 = k, c2 = k }
    elseif n == 0 and name_r and not (c.single and #c.relnouns > 0) then
      out[#out + 1] = { key = "mention:" .. text:lower(), type = name_r.type_guess, name = text, weak = name_r.weak, c1 = k, c2 = k,
        pname = name_r.multiword and not name_r.head_cue and not name_r.type_guess or nil }
    end
  end
  return out
end

local NAMING_BEFORE = { { "called" }, { "named" }, { "dubbed" }, { "known", "as" }, { "by", "the", "name" }, { "by", "the", "name", "of" }, { "goes", "by" }, { "go", "by" }, { "labelled" }, { "labeled" } }

-- determiners that open a classifying noun phrase after a name ("X, a small business", "X, this little company", "X, my new supplier")
local DESCRIPTOR_DET = U.set({ "a", "an", "the", "this", "that", "another", "my", "our", "their", "his", "her", "your", "one" })
-- words that name a NAME, not a kind ("the name he gave me was X"): the kind is then given by the closest earlier noun phrase
local NAME_WORD = U.set({ "name", "names", "brand", "label" })
-- conjunctions that open a new clause: the subject of the introducer of a name starts after them
local SEG_CONJ = U.set({ "and", "but", "so", "because", "since", "while", "although", "though", "whereas", "yet", "or", "if", "when", "then" })

local function chunk_form(S, i)
  local ck = S.chunks[i]
  return ck and ck.single and ck.unit and ck.unit.form or nil
end

-- where does the introducer of the name at chunk k1 begin?  "is X", "was called X", "goes by the name X", "the name he gave me was X" -> index of its first chunk
local function name_introducer(S, k1)
  local q = k1 - 1
  if chunk_form(S, q) == "of" and chunk_form(S, q - 1) == "name" then q = q - 1 end
  if chunk_form(S, q) == "name" and (chunk_form(S, q - 1) == "the" or chunk_form(S, q - 1) == "a") then q = q - 2 end
  local f, ck = chunk_form(S, q), S.chunks[q]
  if not f then return nil end
  local function be(i) local c = S.chunks[i]; return c and c.single and c.cats and c.cats.aux_be == true end
  if be(q) then return q end
  if f == "called" or f == "named" or f == "dubbed" or f == "labelled" or f == "labeled" then return be(q - 1) and q - 1 or q end
  if f == "as" and chunk_form(S, q - 1) == "known" then return be(q - 2) and q - 2 or q - 1 end
  if f == "by" and (chunk_form(S, q - 1) == "go" or chunk_form(S, q - 1) == "goes" or chunk_form(S, q - 1) == "went") then return q - 1 end
  return nil
end

-- the classifying noun phrase that is the subject of the clause ending right before chunk e: first chunk index it may start at -> np
local function classifying_np_in(P, S, b, e, strict)
  local fallback
  for k0 = b, e do
    local c0 = S.chunks[k0]
    if c0 and c0.single and c0.cats and (c0.cats.det or c0.cats.poss_det) then
      for _, np in ipairs(P.parse_np(S, k0)) do
        if np.head and np.nxt <= e + 1 and (np.head_kind == "typenoun" or np.head_kind == "unknown" or np.head_kind == "concept") then
          -- punctuation or a clause-linking conjunction between the noun phrase and the introducer means the noun phrase belongs to a different clause
          -- (a relative clause such as "I'm vetting" or "we might partner with" has neither)
          local crosses = false
          for z = np.nxt, e do
            local cz = S.chunks[z]
            if cz and (cz.pre or (cz.single and SEG_CONJ[cz.unit.form])) then crosses = true end
          end
          if not crosses then
            if np.head_kind == "typenoun" then return np end
            if k0 == b and not fallback then fallback = np end
          end
          break
        end
      end
    end
  end
  return not strict and fallback or nil
end

-- "the small company I'm auditing for work this month IS Brindle Analytics", "the tiny business I'm vetting GOES BY THE NAME X", "a small company we might
-- partner with, and THE NAME he gave me WAS X": a noun phrase that opens the clause classifies the name that completes it
local function describe_by_introducer(P, S, mem, it, speaker)
  local ks = name_introducer(S, it.c1)
  if not ks or ks < 2 then return end
  local e = ks - 1
  local sent = S.chunks[e].sent
  local b, steps = e, 0
  while b >= 1 and steps < 20 do
    local ck = S.chunks[b]
    if ck.sent ~= sent then b = b + 1; break end
    if ck.single and SEG_CONJ[ck.unit.form] and b < e then b = b + 1; break end
    if ck.pre then
      if ck.single and SEG_CONJ[ck.unit.form] and b < e then b = b + 1 end
      break
    end
    b = b - 1; steps = steps + 1
  end
  if b < 1 then b = 1 end
  local np = classifying_np_in(P, S, b, e, false)
  if np and NAME_WORD[np.head.unit and np.head.unit.form or ""] then np = nil; b = b - 1
    -- the subject only names a name: the kind is given by the closest earlier classifying noun phrase of the sentence
    local lo = math.max(1, b - 20)
    for k0 = b, lo, -1 do
      local c0 = S.chunks[k0]
      if c0 and c0.sent ~= sent then break end
      if c0 and c0.single and c0.cats and (c0.cats.det or c0.cats.poss_det) then
        for _, cand in ipairs(P.parse_np(S, k0)) do
          if cand.head_kind == "typenoun" and cand.head and not NAME_WORD[cand.head.unit and cand.head.unit.form or ""] then np = cand; break end
        end
        if np then break end
      end
    end
  end
  if np and np.head and np.head.form then mem:describe(it.key, np.head.form, P.span_text(S, np), speaker) end
end

function C.describe_entities(view, S, items, speaker)
  local P = require("asi.nlu.parse")
  local mem = view.mem
  for _, it in ipairs(items) do
    -- "a small business CALLED X" / "a small firm that goes by the name X" / "this small company, X,": the noun phrase BEFORE the name describes it
    do
      local k1 = it.c1
      local found
      for _, pat in ipairs(NAMING_BEFORE) do
        local ok = true
        for i, w in ipairs(pat) do
          local ck = S.chunks[k1 - #pat + i - 1]
          if not (ck and ck.single and ck.unit.form == w) then ok = false break end
        end
        if ok then found = #pat break end
      end
      local np_end = found and (k1 - found - 1) or nil
      if not np_end then
        -- reversed apposition "this small company, X,": the name opens after a comma and a determined noun phrase ends right before it
        local ce = S.chunks[k1]
        if ce and ce.pre and ce.pre:find("comma") then np_end = k1 - 1 end
      end
      if np_end and np_end >= 1 then
        for k0 = math.max(1, np_end - 6), np_end do
          local c0 = S.chunks[k0]
          local det = c0 and c0.single and c0.cats and (c0.cats.det == true or c0.cats.poss_det == true)
          if det then
            for _, np in ipairs(P.parse_np(S, k0)) do
              if np.nxt == np_end + 1 + (found and found or 0) - (found and found or 0) and (np.head_kind == "typenoun" or np.head_kind == "unknown" or np.head_kind == "concept") and np.head then
                mem:describe(it.key, np.head.form, P.span_text(S, np), speaker)
                goto next_pattern
              end
            end
          end
        end
      end
      ::next_pattern::
    end
    describe_by_introducer(P, S, mem, it, speaker)
    local k = it.c2 + 1
    local c = S.chunks[k]
    -- "X, which is a small business" / "X, who is a founder": skip a relativiser + copula after the comma
    if c and c.pre and c.pre:find("comma") and c.single and (c.unit.form == "which" or c.unit.form == "who" or c.unit.form == "that") then
      local c2 = S.chunks[k + 1]
      if c2 and c2.single and c2.cats and c2.cats.aux_be then k = k + 1; c = S.chunks[k]; c.relcl = true end
    end
    if c then
      local copula = c.single and c.cats and (c.cats.aux_be == true) and (not c.pre or c.relcl)
      local appos = c.pre and c.pre:find("comma") and c.single and c.cats and (c.cats.det == true or c.cats.poss_det == true)
      if copula then k = k + 1; c = S.chunks[k] end
      if c and (copula or appos) then
        local det = c.single and c.cats and (c.cats.det == true or c.cats.poss_det == true) and DESCRIPTOR_DET[c.unit.form]
        if det then
          for _, np in ipairs(P.parse_np(S, k)) do
            if (np.head_kind == "typenoun" or np.head_kind == "unknown" or np.head_kind == "concept") and np.head then
              mem:describe(it.key, np.head.form, P.span_text(S, np), speaker)
              break
            end
          end
        end
      end
    end
  end
end

-- do two head nouns denote the same kind of thing? equal stems, or senses of compatible lexicon types
function C.descriptor_match(view, head, d)
  local Mem = require("asi.nlu.memory")
  if Mem.stem(head) == Mem.stem(d.head) then return 1.0 end
  local lex = view.lex
  local ta, tb
  for _, sn in ipairs(lex.sense_by_head[head] or {}) do ta = ta or sn.type end
  for _, sn in ipairs(lex.sense_by_head[d.head] or {}) do tb = tb or sn.type end
  if ta and tb then
    local ab, ba = lex:compat(ta, tb), lex:compat(tb, ta)
    if ab >= 0.9 and ba >= 0.9 then return 0.7 end
    -- "the organisation I mentioned" may denote what was described as "a company" (the description names a subtype of the reference's kind); the converse is weaker
    if ba >= 0.9 then return 0.6 end
    if ab >= 0.9 then return 0.4 end
  end
  return 0
end

-- resolve every context-dependent reference of one interpretation.  Returns {references = {...}, by_text = {...}, unresolved = {...}}
function C.resolve_references(view, interp)
  local mem, lex = view.mem, view.lex
  local out = { references = {}, by_text = {}, unresolved = {} }
  local exclude = {}
  C.walk(interp, function(r)
    local k = r.antecedent and r.antecedent.key or r.resolved_id
    if k and not r.backref and not r.pronoun then exclude[k] = true end
  end)
  local n = 0
  local function add(rec)
    n = n + 1
    rec.id = "ref" .. n
    out.references[#out.references + 1] = rec
    out.by_text[rec.mention] = rec
    if rec.status ~= "resolved" then out.unresolved[#out.unresolved + 1] = { reference = rec.id, mention = rec.mention, kind = rec.kind, requirement = rec.requirement } end
  end
  local handler
  handler = function(r, role, expected)
    if r.asked then return end
    if r.pronoun and r.topic_bound and interp.topic then
      -- the pronoun denotes the fronted topic
      local t = interp.topic
      local ant = t.antecedent or (t.resolved_id and { key = t.resolved_id, text = t.text, type = t.type })
      local trec
      if ant and ant.key and (t.status == "resolved" or t.status == "unseen" or t.resolved_id) then
        r.antecedent = { key = ant.key, text = ant.text, type = ant.type, turn = ant.turn, via = "topic", p = 1.0 }
        r.status, r.resolved_id = "resolved", ant.key
        trec = { kind = "pronoun", mention = r.text, role = role, status = "resolved", antecedent = r.antecedent, pronoun = r.pronoun, distance_turns = 0 }
      else
        trec = { kind = "pronoun", mention = r.text, role = role, status = (t.status == "ambiguous") and "ambiguous" or "unresolved", pronoun = r.pronoun,
          requirement = "the pronoun '" .. tostring(r.pronoun) .. "' refers to the fronted topic '" .. tostring(t.text) .. "', which is itself not resolved" }
      end
      add(trec)
      return
    end
    local classes = r.head and lex:refclasses(r.head) or {}
    local artifact_classes, corr = {}, false
    for c in pairs(classes) do
      if c == "correction" then corr = true else artifact_classes[c] = true end
    end
    local rec
    if r.pronoun then
      if r.deictic or r.non_anaphoric then return end
      local st = r.status
      rec = { kind = "pronoun", mention = r.text, role = role, status = (st == "resolved") and "resolved" or (st == "ambiguous" and "ambiguous" or "unresolved"),
        antecedent = r.antecedent, candidates = r.candidates, pronoun = r.pronoun }
      if rec.status == "resolved" then rec.distance_turns = r.antecedent and r.antecedent.distance_turns or 0
      elseif rec.status == "ambiguous" then rec.requirement = "the pronoun '" .. r.pronoun .. "' has several plausible antecedents; clarification or more context is needed"
      else rec.requirement = "no antecedent for '" .. r.pronoun .. "' is available in the context" end
    elseif r.ordinal and next(artifact_classes) and not r.asked then
      local found, reasons, tried = view:resolve_artifact(r, artifact_classes)
      rec = { kind = "ordinal_artifact", mention = r.text, role = role, ordinal = r.ordinal, reasons = reasons }
      if #found == 1 then
        rec.status, rec.antecedent = "resolved", artifact_summary(found[1])
        rec.distance_turns = mem.turn - found[1].turn
        r.status, r.antecedent = "resolved", rec.antecedent
      elseif #found > 1 then
        rec.status = "ambiguous"; rec.candidates = U.map(found, artifact_summary)
        rec.requirement = "several artifacts match '" .. r.text .. "'"
      else
        rec.status = "unresolved"
        rec.requirement = #tried > 0 and ("the conversation holds no " .. r.ordinal .. (r.ordinal == 1 and "st" or r.ordinal == 2 and "nd" or r.ordinal == 3 and "rd" or "th") .. " " .. tried[1])
          or ("no enumerated " .. (next(artifact_classes)) .. " exists in the conversation")
      end
    elseif corr and (r.backref or r.det == "my" or r.possessor) then
      local items = view:resolve_correction(r, interp)
      rec = { kind = "correction_ref", mention = r.text, role = role }
      if #items == 1 then
        rec.status, rec.antecedent = "resolved", view:describe_item(items[1])
        rec.distance_turns = mem.turn - items[1].turn
        r.status, r.antecedent = "resolved", rec.antecedent
      elseif #items > 1 then
        -- the most recent correction is the default reading of "the correction I made"; the others stay visible as alternatives
        rec.status = "ambiguous"
        rec.candidates = U.map({ table.unpack(items, 1, math.min(#items, 4)) }, function(it) return view:describe_item(it) end)
        rec.requirement = #items .. " earlier user corrections/instructions exist; the one meant by '" .. r.text .. "' is not determined by the text"
      else
        rec.status = "unresolved"
        rec.requirement = "no earlier correction by the user exists in the conversation (none is invented)"
      end
    elseif next(artifact_classes) and (label_kind(lex, r) or r.backref) then
      local found, reasons, tried = view:resolve_artifact(r, artifact_classes)
      rec = { kind = "label_artifact", mention = r.text, role = role, reasons = reasons }
      if #found == 1 then
        rec.status, rec.antecedent = "resolved", artifact_summary(found[1])
        rec.distance_turns = mem.turn - found[1].turn
        r.status, r.antecedent = "resolved", rec.antecedent
      elseif #found > 1 then
        rec.status = "ambiguous"; rec.candidates = U.map(found, artifact_summary)
        rec.requirement = "several artifacts match '" .. r.text .. "'"
      else
        rec.status = "unresolved"
        rec.requirement = "no " .. (next(artifact_classes)) .. " matching '" .. r.text .. "' exists in the conversation"
      end
    elseif r.backref then
      local cands, rejected = view:resolve_entity_backref(r, expected, exclude)
      rec = { kind = "entity_backref", mention = r.text, role = role, rejected = U.map(rejected, function(x) return { id = x.id, reason = x.reason } end) }
      if #cands == 0 then
        rec.status = "unresolved"
        rec.requirement = "'" .. r.text .. "' refers to something mentioned earlier, but no suitable entity exists in the conversation"
      else
        rec.candidates = U.map(cands, function(c) return { id = c.id, type = c.type, name = c.name, p = c.p, score = c.score, reasons = c.reasons, turn = c.turn } end)
        local top = cands[1]
        local margin = top.p - (cands[2] and cands[2].p or 0)
        if #cands == 1 or (top.p >= C.W.resolve_p and margin >= C.W.resolve_margin and not cands.kind_unverified) then
          rec.status = "resolved"
          rec.antecedent = { key = top.id, text = top.name, type = top.type, turn = top.turn, distance_turns = mem.turn - (top.turn or mem.turn), via = "backreference", p = top.p }
          rec.distance_turns = rec.antecedent.distance_turns
          r.status, r.antecedent, r.resolved_id = "resolved", rec.antecedent, top.id
          if top.type and not r.type then r.type = top.type end
        else
          rec.status = "ambiguous"
          rec.requirement = cands.kind_unverified and ("nothing in the conversation says which earlier entity is a " .. tostring(r.head) .. "; the intended one is not determined")
            or ("several earlier entities fit '" .. r.text .. "'; the intended one is not determined")
        end
      end
    end
    if rec then add(rec) end
  end
  local topic_done
  if interp.topic then handler(interp.topic, "topic", nil); topic_done = interp.topic end
  C.walk(interp, function(r, role, expected) if r ~= topic_done then handler(r, role, expected) end end)
  -- comparison sets: "Which one is older?", "both", "the latter" with no explicit items
  if interp.intent == "comparison" and (not interp.items or #interp.items < 2) then
    local cs = mem.comparison
    local rec = { kind = "comparison_set", mention = interp.sentence and interp.sentence.text or "", role = "items" }
    if cs and #cs.keys >= 2 then
      rec.status = "resolved"
      rec.antecedent = { key = "group:" .. table.concat(cs.keys, "+"), group = cs.keys, turn = cs.turn, via = "comparison", dimension = cs.dimension }
      rec.distance_turns = mem.turn - cs.turn
      rec.items = {}
      for _, k in ipairs(cs.keys) do
        local e = mem.entities[k]
        rec.items[#rec.items + 1] = { key = k, type = e and e.type, text = e and select(2, next(e.names or {})) or k }
      end
    else
      rec.status = "unresolved"
      rec.requirement = "the items to compare are not stated and no earlier comparison set exists"
    end
    add(rec)
  end
  return out
end

return C

end

package.preload["asi.nlu.dataset"] = function(...)
-- asi.nlu.dataset: safe ingestion of local knowledge as DATA.  Nothing here is ever executed or `load`ed.
-- Supported formats (implemented and tested, nothing more is claimed): jsonl, json (array / {records=[...]}), csv, tsv, txt/md (paragraph records),
-- and triple tables (subject/relation/object columns or keys).  PDF, DOCX, HTML and spreadsheets are NOT supported.
-- Records keep their original fields, provenance (source + line/row), checksum, optional date, and a reliability that is "default" unless the
-- data declares one.  Missing metadata is never invented.  Duplicates are detected (exact + bottom-k MinHash near-duplicates), versions are
-- tracked, and updates are incremental (a dataset digest changes whenever any record changes, so caches can key on it).
local U = require("asi.nlu.util")
local TU = require("asi.nlu.textutil")
local UC = require("asi.nlu.unicode")

local D = {}
D.__index = D
D.SCHEMA = "nlu.dataset/1"
D.LIMITS = { max_record_bytes = 262144, max_fields = 256, max_records = 2000000, max_depth = 16, sketch_bucket = 48, sketch_shared = 6 }

local TEXT_NAMES = U.set({ "text", "body", "content", "description", "abstract", "summary", "title", "name", "headline", "note", "notes", "comment", "sentence", "passage", "statement", "claim" })
local ID_NAMES = U.set({ "id", "uid", "key", "record_id", "doc_id", "document_id", "identifier", "uuid", "_id" })
local DATE_NAMES = U.set({ "date", "published", "published_at", "updated", "updated_at", "created", "created_at", "timestamp", "year", "as_of", "valid_from", "effective_date" })
local SUBJECT_NAMES = U.set({ "subject", "head", "entity", "source_entity", "s" })
local RELATION_NAMES = U.set({ "relation", "predicate", "rel", "property", "attribute", "p" })
local OBJECT_NAMES = U.set({ "object", "tail", "value", "target", "target_entity", "o" })
local RELIABILITY_NAMES = U.set({ "reliability", "confidence", "trust", "score_reliability" })

---------------------------------------------------------------- CSV / TSV (RFC 4180 subset: quotes, doubled quotes, embedded delimiters / newlines)
function D.parse_delimited(text, delim)
  delim = delim or ","
  local rows, row, field, i, n = {}, {}, {}, 1, #text
  local in_q, at_field_start = false, true
  local errs = {}
  local function push_field() row[#row + 1] = table.concat(field); field = {}; at_field_start = true end
  local function push_row()
    push_field()
    if not (#row == 1 and row[1] == "") then rows[#rows + 1] = row end
    row = {}
  end
  while i <= n do
    local c = text:sub(i, i)
    if in_q then
      if c == '"' then
        if text:sub(i + 1, i + 1) == '"' then field[#field + 1] = '"'; i = i + 1 else in_q = false end
      else field[#field + 1] = c end
    else
      if c == '"' and at_field_start then in_q = true; at_field_start = false
      elseif c == delim then push_field()
      elseif c == "\r" then if text:sub(i + 1, i + 1) == "\n" then i = i + 1 end push_row()
      elseif c == "\n" then push_row()
      else field[#field + 1] = c; at_field_start = false end
    end
    i = i + 1
  end
  if in_q then errs[#errs + 1] = "unterminated quoted field at end of input" end
  if #field > 0 or #row > 0 then push_row() end
  return rows, errs
end

---------------------------------------------------------------- schema induction (documented heuristics, never silent)
local function is_numberish(s) return tonumber(s) ~= nil end
local function looks_date(s)
  if type(s) ~= "string" then return false end
  return s:match("^%d%d%d%d%-%d%d%-%d%d") ~= nil or s:match("^%d%d%d%d/%d%d/%d%d") ~= nil or s:match("^%d%d%d%d$") ~= nil
end

-- rows: list of flat tables {field = scalar}; returns a schema description
function D.induce_schema(rows)
  local stats, order = {}, {}
  for _, r in ipairs(rows) do
    for k, v in pairs(r) do
      local st = stats[k]
      if not st then st = { n = 0, strings = 0, numbers = 0, dates = 0, total_len = 0, distinct = {}, nd = 0 }; stats[k] = st; order[#order + 1] = k end
      st.n = st.n + 1
      if type(v) == "number" then st.numbers = st.numbers + 1
      elseif type(v) == "string" then
        st.strings = st.strings + 1; st.total_len = st.total_len + #v
        if looks_date(v) then st.dates = st.dates + 1 end
        if is_numberish(v) then st.numbers = st.numbers + 1 end
      end
      if st.nd < 200 and not st.distinct[tostring(v)] then st.distinct[tostring(v)] = true; st.nd = st.nd + 1 end
    end
  end
  table.sort(order)
  local schema = { fields = {}, text_fields = {}, meta_fields = {}, notes = {} }
  local n = #rows
  for _, k in ipairs(order) do
    local st = stats[k]
    local lk = k:lower()
    local kind = "unknown"
    local avg = st.strings > 0 and st.total_len / st.strings or 0
    if ID_NAMES[lk] and st.nd == st.n then kind = "id"
    elseif DATE_NAMES[lk] and st.dates + st.numbers >= st.n * 0.8 then kind = "date"
    elseif st.dates >= st.n * 0.8 and st.strings > 0 then kind = "date"
    elseif st.numbers >= st.n * 0.9 then kind = "number"
    elseif TEXT_NAMES[lk] or avg > 60 then kind = "text"
    elseif st.nd <= math.max(10, n // 5) then kind = "category"
    elseif st.strings > 0 then kind = "text" end
    if SUBJECT_NAMES[lk] or RELATION_NAMES[lk] or OBJECT_NAMES[lk] then schema.triple_hint = schema.triple_hint or {} end
    schema.fields[k] = kind
  end
  -- triples need all three roles present
  local sub, rel, obj
  for _, k in ipairs(order) do
    local lk = k:lower()
    if SUBJECT_NAMES[lk] and not sub and #lk > 1 then sub = k end
    if RELATION_NAMES[lk] and not rel and #lk > 1 then rel = k end
    if OBJECT_NAMES[lk] and not obj and #lk > 1 then obj = k end
  end
  if sub and rel and obj then schema.triple = { subject = sub, relation = rel, object = obj } end
  for _, k in ipairs(order) do
    local kind = schema.fields[k]
    if kind == "id" and not schema.id_field then schema.id_field = k
    elseif kind == "date" and not schema.date_field then schema.date_field = k
    elseif kind == "text" then schema.text_fields[#schema.text_fields + 1] = k
    else schema.meta_fields[#schema.meta_fields + 1] = k end
    if RELIABILITY_NAMES[k:lower()] and stats[k].numbers >= stats[k].n * 0.9 then schema.reliability_field = k end
  end
  if schema.triple then
    -- triple columns are structured assertions, not free text
    local trip = U.set({ schema.triple.subject, schema.triple.relation, schema.triple.object })
    local keep = {}
    for _, k in ipairs(schema.text_fields) do if not trip[k] then keep[#keep + 1] = k end end
    schema.text_fields = keep
  end
  if not schema.id_field then schema.notes[#schema.notes + 1] = "no id column detected: record ids are generated and flagged id_generated" end
  if #schema.text_fields == 0 and not schema.triple then schema.notes[#schema.notes + 1] = "no text column detected: records are metadata-only" end
  return schema
end

---------------------------------------------------------------- construction
function D.new(opts)
  opts = opts or {}
  local self = setmetatable({}, D)
  self.schema_version = D.SCHEMA
  self.id = opts.id or "dataset"
  self.version = opts.version or "v1"
  self.label = opts.label                 -- e.g. { year = 2020, name = "supplied 2020 dataset" }  (declared, never guessed)
  self.revision = 0
  self.records, self.order = {}, {}
  self.by_checksum, self.sketch_index = {}, {}
  self.history = {}
  self.errors = {}
  self.formats = {}
  return self
end

---------------------------------------------------------------- normalisation of one raw record
local function flat_scalar(v)
  local t = type(v)
  if t == "string" or t == "number" or t == "boolean" then return v end
  return nil
end

-- shallow flattening: nested objects -> dotted keys (depth <= 3), arrays of scalars -> "a; b; c".  Arrays of objects are NOT indexed (reported).
local function flatten(raw, notes)
  local out = {}
  local function walk(prefix, v, depth)
    local t = type(v)
    if t == "string" or t == "number" or t == "boolean" then out[prefix] = v
    elseif t == "table" and v ~= U.NULL then
      if #v > 0 then
        local scal = {}
        for _, x in ipairs(v) do
          if type(x) == "string" or type(x) == "number" or type(x) == "boolean" then scal[#scal + 1] = tostring(x)
          else notes.nested = (notes.nested or 0) + 1 end
        end
        if #scal > 0 then out[prefix] = table.concat(scal, "; ") end
      elseif depth < 3 then
        for k, x in pairs(v) do walk(prefix .. "." .. tostring(k), x, depth + 1) end
      else notes.nested = (notes.nested or 0) + 1 end
    end
  end
  for k, v in pairs(raw) do walk(tostring(k), v, 1) end
  return out
end

-- shingle sketch (bottom-k MinHash over word 4-grams) for near-duplicate detection
local function sketch_of(text)
  local toks = TU.tokens(text, { raw = true, keep_stop = true })
  if #toks < 6 then return nil end
  local hs = {}
  for i = 1, #toks - 3 do
    local g = toks[i].w .. " " .. toks[i + 1].w .. " " .. toks[i + 2].w .. " " .. toks[i + 3].w
    hs[#hs + 1] = U.hash64(g)
  end
  table.sort(hs)
  local out, seen = {}, {}
  for _, h in ipairs(hs) do
    if not seen[h] then seen[h] = true; out[#out + 1] = h end
    if #out >= 16 then break end
  end
  return out
end

local function sketch_sim(a, b)
  local sa = {}
  for _, h in ipairs(a) do sa[h] = true end
  local inter = 0
  for _, h in ipairs(b) do if sa[h] then inter = inter + 1 end end
  local union = #a + #b - inter
  return union > 0 and inter / union or 0
end

local function norm_text_key(text)
  local toks = TU.tokens(text, { raw = true, keep_stop = true })
  local w = {}
  for i, t in ipairs(toks) do w[i] = t.w end
  return table.concat(w, " ")
end

local function year_of(v)
  if type(v) == "number" and v >= 1000 and v <= 2999 then return math.floor(v) end
  if type(v) == "string" then
    local y = v:match("^(%d%d%d%d)")
    if y then return tonumber(y) end
  end
end

-- raw: flat table of fields; opts: mapping.  Returns record or nil, err
function D:normalise(raw, map, source)
  local fields, nfields, bytes = {}, 0, 0
  for k, v in pairs(raw) do
    local sv = flat_scalar(v)
    if sv ~= nil then
      nfields = nfields + 1
      fields[tostring(k)] = sv
      bytes = bytes + #tostring(k) + #tostring(sv)
    end
  end
  if nfields > D.LIMITS.max_fields then return nil, "too many fields (" .. nfields .. ")" end
  if bytes > D.LIMITS.max_record_bytes then return nil, "record too large (" .. bytes .. " bytes)" end
  for k, v in pairs(fields) do
    if type(v) == "string" and not utf8.len(v) then return nil, "field '" .. k .. "' is not valid UTF-8" end
  end
  local rec = { dataset = self.id, version = self.version, fields = fields, source = source, meta = {}, flags = {} }
  -- identifier
  local idv = map.id_field and fields[map.id_field]
  if idv ~= nil and tostring(idv) ~= "" then rec.local_id = tostring(idv)
  else
    rec.local_id = (source.name or "rec") .. "#" .. tostring(source.row or source.line or (#self.order + 1))
    rec.flags.id_generated = true
  end
  rec.id = self.id .. ":" .. rec.local_id
  -- text (declared order, never reordered)
  local parts, names = {}, {}
  for _, f in ipairs(map.text_fields or {}) do
    local v = fields[f]
    if type(v) == "string" and v ~= "" then parts[#parts + 1] = v; names[#names + 1] = f end
  end
  rec.text = table.concat(parts, "\n")
  rec.text_fields = names
  rec.field_text = {}
  for i, f in ipairs(names) do rec.field_text[f] = parts[i] end
  for _, f in ipairs(map.meta_fields or {}) do if fields[f] ~= nil then rec.meta[f] = fields[f] end end
  -- time: declared field only
  if map.date_field and fields[map.date_field] ~= nil then
    local dv = fields[map.date_field]
    rec.date_text = tostring(dv)
    rec.year = year_of(dv)
    local y, mo, d = tostring(dv):match("^(%d%d%d%d)[%-/](%d%d)[%-/](%d%d)")
    if y then rec.date = tonumber(y) * 10000 + tonumber(mo) * 100 + tonumber(d) end
  end
  rec.dataset_year = map.dataset_year_field and year_of(fields[map.dataset_year_field]) or (self.label and self.label.year) or nil
  -- reliability: declared or default (and labelled as such)
  local rf = map.reliability_field and tonumber(fields[map.reliability_field])
  if rf then rec.reliability, rec.reliability_source = U.clamp(rf, 0, 1), "declared"
  else rec.reliability, rec.reliability_source = map.default_reliability or 0.5, "default" end
  -- structured triple
  if map.triple then
    local s, r, o = fields[map.triple.subject], fields[map.triple.relation], fields[map.triple.object]
    if s ~= nil and r ~= nil and o ~= nil and tostring(s) ~= "" and tostring(r) ~= "" and tostring(o) ~= "" then
      rec.triple = { subject = tostring(s), relation = tostring(r), object = tostring(o) }
      if map.triple.polarity and fields[map.triple.polarity] ~= nil then
        local pv = tostring(fields[map.triple.polarity]):lower()
        rec.triple.polarity = (pv == "false" or pv == "0" or pv == "negative" or pv == "no") and "negative" or "positive"
      end
      if rec.text == "" then rec.text = string.format("%s %s %s.", rec.triple.subject, rec.triple.relation:gsub("_", " "), rec.triple.object) ; rec.flags.text_synthesised = true end
    else
      rec.flags.incomplete_triple = true
    end
  end
  -- checksum of the ORIGINAL fields (canonical JSON), so any change is detectable
  rec.checksum = U.hash128(U.json_encode(fields, { nan_null = true }))
  rec.text_key = norm_text_key(rec.text)
  return rec
end

---------------------------------------------------------------- adding records (incremental, versioned, de-duplicating)
-- returns report { added, updated, unchanged, duplicates = {{id, of}}, rejected = {{index, reason}} }
function D:add_normalised(list, report)
  for idx, rec in ipairs(list) do
    if #self.order >= D.LIMITS.max_records then
      report.rejected[#report.rejected + 1] = { index = idx, reason = "dataset record limit reached" }
    else
      local old = self.records[rec.id]
      if old and old.checksum == rec.checksum then
        report.unchanged = report.unchanged + 1
      else
        if old then
          report.updated = report.updated + 1
          rec.supersedes = old.checksum
          rec.updates = (old.updates or 0) + 1
          self:drop_derived(old)
        else
          report.added = report.added + 1
          self.order[#self.order + 1] = rec.id
        end
        rec.added_in = old and old.added_in or (self.revision + 1)
        rec.revised_in = self.revision + 1
        self.records[rec.id] = rec
        -- duplicate detection
        if rec.text_key ~= "" then
          local twin = self.by_checksum[rec.text_key]
          if twin and twin ~= rec.id and self.records[twin] then
            rec.duplicate_of = twin
            rec.flags.exact_duplicate = true
            report.duplicates[#report.duplicates + 1] = { id = rec.id, of = twin, kind = "exact" }
          else
            self.by_checksum[rec.text_key] = rec.id
            local sk = sketch_of(rec.text)
            rec.sketch = sk
            if sk then
              local best, best_sim
              local cand_ids = {}
              -- A shingle shared by very many records (boilerplate such as "... is mentioned in many reports") carries no duplicate evidence and would make
              -- ingestion quadratic: buckets beyond D.LIMITS.sketch_bucket are skipped, and a candidate must share at least D.LIMITS.sketch_shared hashes.
              for _, h in ipairs(sk) do
                local bucket = self.sketch_index[h]
                if bucket and #bucket <= D.LIMITS.sketch_bucket then
                  for _, oid in ipairs(bucket) do cand_ids[oid] = (cand_ids[oid] or 0) + 1 end
                end
              end
              for oid, shared in pairs(cand_ids) do
                local o = self.records[oid]
                if shared >= D.LIMITS.sketch_shared and oid ~= rec.id and o and o.sketch and not o.duplicate_of then
                  local sim = sketch_sim(sk, o.sketch)
                  if sim >= 0.8 and (not best_sim or sim > best_sim or (sim == best_sim and oid < best)) then best, best_sim = oid, sim end
                end
              end
              if best then
                rec.duplicate_of = best
                rec.flags.near_duplicate = true
                rec.dup_similarity = best_sim
                report.duplicates[#report.duplicates + 1] = { id = rec.id, of = best, kind = "near", similarity = best_sim }
              else
                for _, h in ipairs(sk) do
                  local l = self.sketch_index[h]
                  if not l then l = {}; self.sketch_index[h] = l end
                  l[#l + 1] = rec.id
                end
              end
            end
          end
        end
      end
    end
  end
end

function D:drop_derived(old)
  if old.text_key and self.by_checksum[old.text_key] == old.id then self.by_checksum[old.text_key] = nil end
  for _, h in ipairs(old.sketch or {}) do
    local l = self.sketch_index[h]
    if l then for i = #l, 1, -1 do if l[i] == old.id then table.remove(l, i) end end end
  end
end

function D:remove(id)
  local rec = self.records[id]
  if not rec then return false end
  self:drop_derived(rec)
  self.records[id] = nil
  for i, oid in ipairs(self.order) do if oid == id then table.remove(self.order, i) break end end
  self.revision = self.revision + 1
  self.history[#self.history + 1] = { revision = self.revision, op = "remove", ids = { id } }
  self.removed = self.removed or {}
  self.removed[#self.removed + 1] = id
  return true
end

-- stable digest over (id, checksum) pairs: changes whenever any record is added, changed or removed
function D:digest()
  -- cached per revision: every mutation (ingest / remove) bumps `revision`, so the cached digest can never be stale
  if self._digest and self._digest_rev == self.revision then return self._digest end
  local d = self:compute_digest()
  self._digest, self._digest_rev = d, self.revision
  return d
end

function D:compute_digest()
  local parts = {}
  local ids = U.copy(self.order)
  table.sort(ids)
  for _, id in ipairs(ids) do parts[#parts + 1] = id .. "=" .. self.records[id].checksum end
  return U.sha256(self.id .. "|" .. self.version .. "|" .. table.concat(parts, "\n"))
end

---------------------------------------------------------------- ingestion front ends
local function parse_json_records(text)
  local doc, err = U.json_decode(text, { max_depth = D.LIMITS.max_depth })
  if doc == nil then return nil, err end
  local list = doc
  if type(doc) == "table" and not (#doc > 0) then
    list = doc.records or doc.data or doc.items or doc.documents
    if type(list) ~= "table" then return nil, "json: expected an array of records or an object with a 'records' array" end
  end
  return list
end

-- format: jsonl | json | csv | tsv | txt | md  (inferred from opts.name extension when absent)
-- opts: { name, format, mapping = {id_field, text_fields, meta_fields, date_field, triple, reliability_field, default_reliability} }
function D:ingest(text, opts)
  opts = opts or {}
  local name = opts.name or "input"
  local fmt = opts.format
  if not fmt then fmt = (name:match("%.(%w+)$") or "txt"):lower() end
  if fmt == "ndjson" then fmt = "jsonl" end
  if fmt == "markdown" then fmt = "md" end
  local report = { format = fmt, name = name, added = 0, updated = 0, unchanged = 0, duplicates = {}, rejected = {}, notes = {} }
  if type(text) ~= "string" then report.rejected[1] = { reason = "input is not a string" }; return report end
  if not utf8.len(text) then
    report.rejected[1] = { reason = "input is not valid UTF-8; nothing ingested" }
    return report
  end
  local raws = {}   -- list of { fields = flat table, source = {...} }
  if fmt == "jsonl" then
    local line = 0
    for l in (text .. "\n"):gmatch("(.-)\r?\n") do
      line = line + 1
      if l:match("%S") then
        local v, err = U.json_decode(l, { max_depth = D.LIMITS.max_depth })
        if type(v) == "table" and #v == 0 then raws[#raws + 1] = { fields = v, source = { name = name, line = line } }
        else report.rejected[#report.rejected + 1] = { index = line, reason = "line " .. line .. ": " .. tostring(err or "not a JSON object") } end
      end
    end
  elseif fmt == "json" then
    local list, err = parse_json_records(text)
    if not list then report.rejected[1] = { reason = tostring(err) }; return report end
    for i, v in ipairs(list) do
      if type(v) == "table" and #v == 0 then raws[#raws + 1] = { fields = v, source = { name = name, row = i } }
      else report.rejected[#report.rejected + 1] = { index = i, reason = "record " .. i .. " is not an object" } end
    end
  elseif fmt == "csv" or fmt == "tsv" then
    local rows, errs = D.parse_delimited(text, fmt == "tsv" and "\t" or ",")
    for _, e in ipairs(errs) do report.notes[#report.notes + 1] = e end
    if #rows < 1 then report.rejected[1] = { reason = "empty table" }; return report end
    local header = rows[1]
    local seen = {}
    for i, h in ipairs(header) do
      h = U.trim(h)
      if h == "" or seen[h] then report.rejected[1] = { reason = "header column " .. i .. " is empty or duplicated" }; return report end
      seen[h] = true; header[i] = h
    end
    for r = 2, #rows do
      local row = rows[r]
      if #row ~= #header then
        report.rejected[#report.rejected + 1] = { index = r, reason = string.format("row %d has %d fields, expected %d", r, #row, #header) }
      else
        local f = {}
        for i, h in ipairs(header) do
          local v = row[i]
          if v ~= "" then f[h] = v end
        end
        raws[#raws + 1] = { fields = f, source = { name = name, row = r } }
      end
    end
  elseif fmt == "txt" or fmt == "md" then
    -- paragraph records; markdown headings become the `section` of the paragraphs that follow
    local section
    local para, pn = {}, 0
    local function flush()
      if #para > 0 then
        pn = pn + 1
        raws[#raws + 1] = { fields = { id = name .. "#p" .. pn, text = table.concat(para, " "), section = section }, source = { name = name, row = pn } }
        para = {}
      end
    end
    for l in (text .. "\n"):gmatch("(.-)\r?\n") do
      local h = fmt == "md" and l:match("^#+%s+(.-)%s*$")
      if h then flush(); section = h
      elseif l:match("^%s*$") then flush()
      else para[#para + 1] = U.trim(l) end
    end
    flush()
    opts.mapping = opts.mapping or { id_field = "id", text_fields = { "text" }, meta_fields = { "section" } }
  else
    report.rejected[1] = { reason = "unsupported format '" .. tostring(fmt) .. "' (supported: jsonl, json, csv, tsv, txt, md)" }
    return report
  end
  -- mapping: declared or induced (induction is reported, not silent)
  local fnotes0 = {}
  for _, r in ipairs(raws) do r.flat = flatten(r.fields, fnotes0) end
  if fnotes0.nested then report.notes[#report.notes + 1] = fnotes0.nested .. " nested value(s) (arrays of objects / deep objects) were not indexed" end
  local map = opts.mapping
  if not map then
    local flat = {}
    for _, r in ipairs(raws) do flat[#flat + 1] = r.flat end
    map = D.induce_schema(flat)
    report.induced_schema = { id_field = map.id_field, text_fields = map.text_fields, meta_fields = map.meta_fields, date_field = map.date_field, triple = map.triple, notes = map.notes }
  end
  local good = {}
  local fnotes = {}
  for i, r in ipairs(raws) do
    local rec, err = self:normalise(r.flat or r.fields, map, r.source)
    if rec then good[#good + 1] = rec
    else report.rejected[#report.rejected + 1] = { index = i, reason = err, source = r.source } end
  end
  self:add_normalised(good, report)
  self.revision = self.revision + 1
  self.formats[fmt] = (self.formats[fmt] or 0) + 1
  local ids = {}
  for _, rec in ipairs(good) do ids[#ids + 1] = rec.id end
  self.history[#self.history + 1] = { revision = self.revision, op = "ingest", name = name, format = fmt, added = report.added, updated = report.updated,
    unchanged = report.unchanged, rejected = #report.rejected, ids_sha256 = U.sha256(table.concat(ids, "\n")) }
  report.revision = self.revision
  report.records = good
  return report
end

-- records that count as independent evidence (duplicates are kept but do not corroborate)
function D:active_records()
  local out = {}
  for _, id in ipairs(self.order) do
    local r = self.records[id]
    if r and not r.duplicate_of then out[#out + 1] = r end
  end
  return out
end

return D

end

package.preload["asi.nlu.engine"] = function(...)
-- asi.nlu.engine: the complete LM-independent pipeline.
--   text -> lexical analysis -> semantic interpretation (competing hypotheses) -> context / memory -> retrieval plan -> candidate generation
--        -> semantic verification -> Interpretation Record -> LM Input Package
-- No stage calls a language model, a network service or a clock.  Every stage is metered; a resource limit yields an explicit `limited` status
-- and an unresolved requirement, never a confident guess.
local U = require("asi.nlu.util")
local Interp = require("asi.nlu.interp")
local Memory = require("asi.nlu.memory")
local Resources = require("asi.nlu.resources")
local Plan = require("asi.nlu.plan")
local Verify = require("asi.nlu.verify")
local Record = require("asi.nlu.record")
local Package = require("asi.nlu.package")

local E = {}
E.__index = E
E.VERSION = Record.ENGINE_VERSION

-- opts: { lexicon, knowledge, flags, budget, calibration, package_chars, cache_size, validate }
function E.new(opts)
  opts = opts or {}
  local self = setmetatable({}, E)
  self.base_lexicon = opts.lexicon or Resources.core()
  self.kb = opts.knowledge
  self.flags = opts.flags or {}
  self.budget = opts.budget or 2000000
  self.calibration = opts.calibration
  self.package_chars = opts.package_chars or 6000
  self.validate = opts.validate ~= false
  self.cache, self.cache_order, self.cache_size = {}, {}, opts.cache_size or 256
  self.store = Memory.store()
  self.stats = { requests = 0, cache_hits = 0 }
  self:rebuild_interpreter()
  return self
end

function E:rebuild_interpreter()
  local lex = self.kb and self.kb.lex or self.base_lexicon
  self.interp = Interp.new({ lexicon = lex, flags = self.flags, budget = self.budget })
end

function E:set_knowledge(kb)
  self.kb = kb
  self:rebuild_interpreter()
  self.cache, self.cache_order = {}, {}
end

-- open (or create) a conversation memory; a principal that does not own the namespace is refused
function E:memory(ns, principal)
  return self.store:open(ns, principal)
end

local function recent_turns(mem, n)
  local out = {}
  if not mem then return out end
  for i = #mem.order, 1, -1 do
    local it = mem.items[mem.order[i]]
    if it and it.kind == "utterance" and it.turn < mem.turn and it.status == "active" then
      table.insert(out, 1, { speaker = it.speaker, text = it.text, turn = it.turn })
      if #out >= n then break end
    end
  end
  return out
end

local function flags_signature(flags)
  local ks = U.sorted_keys(flags)
  local parts = {}
  for _, k in ipairs(ks) do parts[#parts + 1] = k .. "=" .. tostring(flags[k]) end
  return table.concat(parts, ",")
end

function E:cache_key(text, call)
  return U.sha256(table.concat({ text, self.kb and self.kb:digest() or "nokb", tostring((self.kb and self.kb.lex or self.base_lexicon).revision), flags_signature(self.flags),
    Record.SCHEMA, E.VERSION, tostring(call.now), tostring(self.package_chars) }, "\0"))
end

-- call: { memory, speaker, now, budget, include_prompt, cache }
function E:process(text, call)
  call = call or {}
  self.stats.requests = self.stats.requests + 1
  local key
  -- results are cached only for stateless calls: a call with a memory has side effects and depends on the memory revision
  if not call.memory and call.cache ~= false then
    key = self:cache_key(text, call)
    local hit = self.cache[key]
    if hit then self.stats.cache_hits = self.stats.cache_hits + 1; return hit, true end
  end
  local result = self.interp:interpret(text, { memory = call.memory, speaker = call.speaker, now = call.now, budget = call.budget, domains = call.domains, light = call.light })
  local out = { result = result }
  if result.light then out.light = true; return out end
  local m = result.main
  local plan = Plan.build(m, self.kb)
  local evidence
  if self.kb and plan.kind ~= "none" and not (self.flags.no_retrieval) then
    -- verification ablations (each flag disables exactly one check; production runs with none)
    local skip
    for flag, name in pairs({ v_no_time = "time", v_no_type = "type", v_no_source = "source", v_no_polarity = "polarity", v_no_duplicates = "duplicates",
      v_no_reliability = "reliability", v_no_exclusion = "exclusion", v_no_modality = "modality", v_no_typed = "typed", v_no_specialization = "specialization" }) do
      if self.flags[flag] then skip = skip or {}; skip[name] = true end
    end
    evidence = Verify.run(self.kb, plan, { skip = skip })
  end
  local rec = Record.build({ result = result, plan = plan, evidence = evidence, flags = self.flags, calibration = self.calibration,
    lexicon_revision = (self.kb and self.kb.lex or self.base_lexicon).revision, interpreter_version = Interp.VERSION, recent = recent_turns(call.memory, 3) })
  out.plan, out.evidence, out.record = plan, evidence, rec
  if self.validate then
    local ok, errs = Record.validate(rec)
    out.valid, out.validation_errors = ok, errs
    if not ok then rec.unresolved_requirements[#rec.unresolved_requirements + 1] = { kind = "schema_violation", requirement = table.concat(errs, "; "):sub(1, 400) } end
  end
  out.package = Package.build(rec, { max_chars = call.package_chars or self.package_chars, include_prompt = call.include_prompt })
  if key then
    self.cache[key] = out
    self.cache_order[#self.cache_order + 1] = key
    if #self.cache_order > self.cache_size then
      local old = table.remove(self.cache_order, 1)
      self.cache[old] = nil
    end
  end
  return out, false
end

-- convenience: a conversation bound to one namespace and owner
function E:conversation(ns, principal, defaults)
  local mem, err = self:memory(ns, principal)
  if not mem then return nil, err end
  local conv = { engine = self, memory = mem }
  function conv:say(text, speaker, opts)
    local call = U.shallow(opts or {})
    call.memory, call.speaker = mem, speaker or "user"
    if call.speaker ~= "user" and call.light == nil then call.light = true end
    return self.engine:process(text, call)
  end
  return conv
end

return E

end

package.preload["asi.nlu.eval"] = function(...)
-- asi.nlu.eval: gold-case evaluation harness (LM-independent).
--   case line:   ID | category | text | gold            gold = key=value; key=value; ...
--   keys: act intent rel rel! from to subject concept target focus object ask atype temporal tc neg pos pref src amb alts ctx items inst evid pol status
-- Matching is field-by-field; a case passes only if every gold field it specifies matches. Serious fields are tracked separately.
local U = require("asi.nlu.util")

local E = {}

E.SERIOUS = U.set({ "intent", "rel", "rel!", "from", "to", "subject", "concept", "target", "focus", "object", "ask", "neg", "amb", "alts", "items",
  "inst", "tc", "pos", "pol", "src", "ctx", "pref", "dep", "ref", "active", "inactive", "sel", "unres" })

---------------------------------------------------------------- parsing
function E.parse_cases(text, source)
  local cases, errs = {}, {}
  local ln = 0
  for line in (text .. "\n"):gmatch("(.-)\r?\n") do
    ln = ln + 1
    local l = U.trim(line)
    if l ~= "" and l:sub(1, 1) ~= "#" then
      local parts = {}
      for part in (l .. " | "):gmatch("(.-)%s%|%s") do parts[#parts + 1] = part end
      if #parts < 4 then errs[#errs + 1] = string.format("%s:%d: expected 'ID | category | text | gold'", source or "?", ln)
      else
        local gold = {}
        for kv in (parts[4] .. ";"):gmatch("(.-);") do
          kv = U.trim(kv)
          if kv ~= "" then
            local k, v = kv:match("^([%w_!]+)%s*=%s*(.*)$")
            if k then gold[k] = v else errs[#errs + 1] = string.format("%s:%d: bad gold item '%s'", source or "?", ln, kv) end
          end
        end
        local cs = { id = parts[1], category = parts[2], text = parts[3], gold = gold, line = ln, source = source }
        -- multi-turn case:  U: first turn // A: assistant turn // U: the request being evaluated   (gold applies to the last turn)
        if cs.text:match("^[UAD]:%s") then
          cs.turns = {}
          for seg in (cs.text .. " // "):gmatch("(.-) //%s") do
            local who, body = seg:match("^([UAD]):%s*(.*)$")
            if who then cs.turns[#cs.turns + 1] = { speaker = (who == "U" and "user") or (who == "A" and "assistant") or "doc", text = body }
            elseif #cs.turns > 0 then cs.turns[#cs.turns].text = cs.turns[#cs.turns].text .. " // " .. seg end
          end
          cs.final_text = cs.turns[#cs.turns].text
        end
        cases[#cases + 1] = cs
      end
    end
  end
  return cases, errs
end

---------------------------------------------------------------- matching helpers
local DETS = U.set({ "the", "a", "an", "this", "that", "these", "those", "his", "her", "its", "their", "our", "my", "your" })
local function norm_text(s)
  s = (s or ""):lower():gsub("[%?%!%.,;:\"]+$", ""):gsub("^[\"']", ""):gsub("%s+", " ")
  local words = {}
  for w in s:gmatch("%S+") do words[#words + 1] = w end
  while #words > 1 and DETS[words[1]] do table.remove(words, 1) end
  return table.concat(words, " ")
end

local function type_of(r)
  if not r then return nil end
  return r.type or (r.senses and r.senses[1] and r.senses[1].type)
end

local function ref_ok(lex, pred, gold)
  if not pred then return false, "missing" end
  local text, ty, id = gold:match("^([^:]*):?([^:]*):?(.*)$")
  -- a resolved pronoun / back-reference is judged by what it was resolved TO
  local ptext = (pred.antecedent and pred.antecedent.text) or pred.text
  if text ~= "*" and text ~= "" and norm_text(ptext) ~= norm_text(text) then return false, "text '" .. tostring(ptext) .. "' ~= '" .. text .. "'" end
  if ty ~= "" and ty ~= "*" then
    local pt = type_of(pred)
    if not pt then
      -- an ambiguous/unresolved mention has no single type; accept when any candidate satisfies the gold type
      local any = false
      for _, c in ipairs(pred.candidates or {}) do if c.type and (c.type == ty or lex:isa(c.type, ty)) then any = true end end
      if not any then return false, "type nil ~= " .. ty end
    elseif pt ~= ty and not lex:isa(pt, ty) then return false, "type " .. pt .. " ~= " .. ty end
  end
  if id ~= "" and id ~= "*" and pred.resolved_id ~= id then return false, "id " .. tostring(pred.resolved_id) .. " ~= " .. id end
  return true
end

local function list_of(v) local t = {}; for x in ((v or "") .. ","):gmatch("(.-),") do x = U.trim(x); if x ~= "" then t[#t + 1] = x end end; return t end

local function neg_matches(lex, n, spec)
  local scope, key = spec:match("^([%w_]+):(.*)$")
  local tgt = n.target or {}
  if scope and tgt.scope ~= scope and not (scope == "type" and tgt.scope == "filtered") then return false end
  local k = (key or ""):lower()
  local plus = nil
  local base, filt = k:match("^(.-)%+(.*)$")
  if base then k = base; plus = filt end
  local ok = false
  if k == "" or k == "*" then ok = true
  elseif tgt.type and (tgt.type == k or lex:isa(tgt.type, k)) then ok = true
  elseif (tgt.text or ""):lower():find(k, 1, true) then ok = true
  elseif tgt.candidates then for _, c in ipairs(tgt.candidates) do if c.id:find(k, 1, true) then ok = true end end end
  if ok and plus then
    local rel_name, val = plus:match("^([%w_]+):?(.*)$")
    local found = false
    for _, f in ipairs(n.filters or {}) do
      if f.relation == rel_name and (val == "" or (f.value and (f.value.text or ""):lower():find(val, 1, true))) then found = true end
    end
    ok = found
  end
  return ok
end

local function tc_matches(c, spec)
  -- spec: op:year   or   label:2020   or   derived:2020   or   between:2010-2015
  local op, val = spec:match("^([%w_]+):(.*)$")
  if not op then return false end
  local function inrange(lo, hi, y)
    if y == nil then return false end
    if lo and lo > y * 10000 + 1231 then return false end
    if hi and hi < y * 10000 + 101 then return false end
    return true
  end
  if op == "label" or op == "derived" then
    return tostring(c.year or c.text or ""):find(val, 1, true) ~= nil and ((op == "label" and c.role == "label") or (op == "derived" and c.role == "derived"))
  end
  local a, b = val:match("^(%d+)%-(%d+)$")
  if op == "between" and a then
    return c.eff_lo ~= nil and c.eff_hi ~= nil and math.floor(c.eff_lo / 10000) == tonumber(a) and math.floor(c.eff_hi / 10000) == tonumber(b)
  end
  local y = tonumber(val)
  if not y then return false end
  if op == "as_of" then return c.op == "as_of" and (c.year == y or (c.eff_lo ~= nil and math.floor(c.eff_lo / 10000) == y)) end
  if op == "in" then return c.eff_lo ~= nil and c.eff_hi ~= nil and math.floor(c.eff_lo / 10000) == y and math.floor(c.eff_hi / 10000) == y end
  if op == "before" then return c.eff_hi ~= nil and c.eff_lo == nil and math.floor(c.eff_hi / 10000) <= y end
  if op == "after" then return c.eff_lo ~= nil and c.eff_hi == nil and math.floor(c.eff_lo / 10000) >= y end
  if op == "since" then return c.eff_lo ~= nil and c.eff_hi == nil and math.floor(c.eff_lo / 10000) == y end
  if op == "until" then return c.eff_hi ~= nil and c.eff_lo == nil and math.floor(c.eff_hi / 10000) == y end
  return false
end

-- all temporal constraints of an interpretation: standalone ones and temporal filters attached to the target set
local function all_temporal(m)
  local out = {}
  for _, t in ipairs(m.constraints.temporal or {}) do out[#out + 1] = t end
  for _, p in ipairs(m.constraints.positive or {}) do if p.kind == "temporal" then out[#out + 1] = p end end
  return out
end

function E.compare(lex, m, gold)
  local res, ok_all = {}, true
  local function chk(key, ok, got)
    res[key] = { ok = ok, got = got, expected = gold[key] }
    if not ok then ok_all = false end
  end
  if not m then
    for k in pairs(gold) do chk(k, false, "no interpretation") end
    return { ok = false, fields = res }
  end
  local c = m.constraints or { positive = {}, negative = {}, temporal = {}, geographic = {}, source = {}, preferences = {}, restrictions = {} }
  if gold.status then chk("status", (m.status or "ok") == gold.status, m.status) end
  if gold.act then chk("act", m.speech_act == gold.act, m.speech_act) end
  if gold.intent then chk("intent", m.intent == gold.intent, m.intent) end
  if gold.rel then
    local got = m.relation and m.relation.id or "-"
    chk("rel", got == gold.rel, got)
  end
  if gold["rel!"] then
    local got = m.relation and m.relation.id or "-"
    chk("rel!", got ~= gold["rel!"], got)
  end
  for _, role in ipairs({ "from", "to" }) do
    if gold[role] then
      local ok, why = ref_ok(lex, m.roles and m.roles[role], gold[role])
      chk(role, ok, why or (m.roles and m.roles[role] and m.roles[role].text))
    end
  end
  for _, k in ipairs({ "subject", "concept", "target", "focus", "object" }) do
    if gold[k] then
      local ok, why = ref_ok(lex, m[k], gold[k])
      chk(k, ok, why or (m[k] and m[k].text))
    end
  end
  if gold.ask then chk("ask", m.query and m.query.ask == gold.ask, m.query and m.query.ask) end
  if gold.atype then
    local got = m.query and (m.query.answer_type or m.query.relation_answer_type)
    chk("atype", got ~= nil and (got == gold.atype or lex:isa(got, gold.atype)), got)
  end
  if gold.temporal then chk("temporal", m.temporal_scope == gold.temporal, m.temporal_scope) end
  if gold.tc then
    local ok, got = true, {}
    local temps = all_temporal(m)
    for _, spec in ipairs(list_of(gold.tc)) do
      local found = false
      for _, t in ipairs(temps) do if tc_matches(t, spec) then found = true end end
      if not found then ok = false end
    end
    for _, t in ipairs(temps) do got[#got + 1] = tostring(t.op) .. ":" .. tostring(t.year or t.text) end
    chk("tc", ok, table.concat(got, ","))
  end
  if gold.neg then
    local specs = list_of(gold.neg)
    local ok, got = true, {}
    if specs[1] == "none" then ok = (#c.negative == 0)
    else
      for _, spec in ipairs(specs) do
        local found = false
        for _, n in ipairs(c.negative) do if neg_matches(lex, n, spec) then found = true end end
        if not found then ok = false end
      end
    end
    for _, n in ipairs(c.negative) do got[#got + 1] = tostring(n.target and n.target.scope) .. ":" .. tostring(n.target and (n.target.type or n.target.text)) end
    chk("neg", ok, table.concat(got, ","))
  end
  if gold.pos then
    local ok, got = true, {}
    for _, spec in ipairs(list_of(gold.pos)) do
      local kind, key = spec:match("^([%w_]+):(.*)$")
      local found = false
      if kind == "relation" then
        for _, p in ipairs(c.positive) do if p.kind == "relation" and p.relation == key then found = true end end
      elseif kind == "temporal" then
        for _, p in ipairs(c.positive) do if p.kind == "temporal" and p.relation == key then found = true end end
      elseif kind == "geo" then
        for _, g in ipairs(c.geographic or {}) do if (g.text or ""):lower():find(key:lower(), 1, true) then found = true end end
        for _, p in ipairs(c.positive) do if p.kind == "geographic" and p.value and (p.value.text or ""):lower():find(key:lower(), 1, true) then found = true end end
      elseif kind == "has" then
        for _, p in ipairs(c.positive) do if p.kind == "has" and p.value and (p.value.text or ""):lower():find(key:lower(), 1, true) then found = true end end
      end
      if not found then ok = false end
    end
    for _, p in ipairs(c.positive) do got[#got + 1] = tostring(p.kind) .. ":" .. tostring(p.relation) end
    chk("pos", ok, table.concat(got, ","))
  end
  if gold.pref then
    local ok = true
    for _, s in ipairs(list_of(gold.pref)) do
      local found = false
      for _, p in ipairs(c.preferences or {}) do if (p.text or ""):lower():find(s:lower(), 1, true) then found = true end end
      if not found then ok = false end
    end
    chk("pref", ok, tostring(#(c.preferences or {})) .. " preference(s)")
  end
  if gold.src then
    local res_, label = gold.src:match("^([%w_]+):?(.*)$")
    local ok = false
    for _, s in ipairs(c.source or {}) do
      if s.resource == res_ and (label == "" or tostring(s.label or ""):find(label, 1, true)) then ok = true end
    end
    for _, s in ipairs(c.restrictions or {}) do
      if s.resource == res_ and (label == "" or tostring(s.text or ""):lower():find(label:lower(), 1, true)) then ok = true end
    end
    chk("src", ok, tostring(#(c.source or {})) .. " source constraint(s)")
  end
  if gold.amb then chk("amb", m.ambiguity and m.ambiguity.state == gold.amb, m.ambiguity and m.ambiguity.state) end
  if gold.alts then
    local want = {}
    for id in gold.alts:gmatch("[^|]+") do want[id] = true end
    local have = {}
    local function scan(r) if r and r.candidates then for _, cd in ipairs(r.candidates) do have[cd.id] = true end end end
    for _, r in pairs(m.roles or {}) do scan(r) end
    for _, k in ipairs({ "subject", "concept", "target", "focus", "object" }) do scan(m[k]) end
    for _, p in ipairs(m.ambiguity and m.ambiguity.points or {}) do for _, cd in ipairs(p.candidates or {}) do if cd.id then have[cd.id] = true end end end
    local ok = true
    for id in pairs(want) do if not have[id] then ok = false end end
    chk("alts", ok, table.concat(U.sorted_keys(have), "|"))
  end
  if gold.ctx then
    local want = list_of(gold.ctx)
    local have = {}
    for _, d in ipairs(m.dependencies or {}) do have[d.kind] = true end
    local ok = true
    if want[1] == "none" then ok = next(have) == nil else for _, w in ipairs(want) do if not have[w] then ok = false end end end
    chk("ctx", ok, table.concat(U.sorted_keys(have), ","))
  end
  if gold.items then
    local want = {}
    for x in gold.items:gmatch("[^|]+") do want[#want + 1] = norm_text(x) end
    local ok = m.items ~= nil and #m.items == #want
    if ok then for i, w in ipairs(want) do if norm_text(m.items[i].text) ~= w then ok = false end end end
    chk("items", ok, m.items and table.concat(U.map(m.items, function(r) return r.text end), "|") or "none")
  end
  if gold.inst then
    local ins = m.instruction
    local ok = ins ~= nil
    local got = {}
    if ins then
      for kv in (gold.inst .. ","):gmatch("(.-),") do
        local k, v = kv:match("^(%w+)=(.*)$")
        if k == "slot" then if ins.slot ~= v then ok = false end
        elseif k == "value" then
          local val = ins.value and (tostring(ins.value.year or ins.value.word or ins.value.label or "")) or ""
          if not val:lower():find(v:lower(), 1, true) then ok = false end
        elseif k == "corr" then if (ins.correction and "1" or "0") ~= v then ok = false end
        elseif k == "persist" then if (ins.persist and "1" or "0") ~= v then ok = false end
        elseif k == "verb" then if ins.verb ~= v then ok = false end end
      end
      got = { tostring(ins.slot), ins.value and tostring(ins.value.year or ins.value.word) or "-", tostring(ins.correction), tostring(ins.persist) }
    end
    chk("inst", ok, table.concat(got, "/"))
  end
  local cx = m.context or {}
  if gold.dep then
    local got = cx.dependency and cx.dependency.primary or "-"
    chk("dep", got == gold.dep, got)
  end
  if gold.ref then
    -- ref=<mention>><antecedent text | resolved | ambiguous | unresolved>, ...
    local ok, got = true, {}
    for _, spec in ipairs(list_of(gold.ref)) do
      local mention, want = spec:match("^(.-)>(.*)$")
      local found
      for _, r in ipairs(cx.references or {}) do if norm_text(r.mention) == norm_text(mention) then found = r end end
      if not found then ok = false; got[#got + 1] = mention .. ">(none)"
      else
        local w = norm_text(want)
        local have = found.status
        if w == "resolved" or w == "ambiguous" or w == "unresolved" then
          if have ~= w then ok = false end
        else
          if have ~= "resolved" or norm_text((found.antecedent and found.antecedent.text) or "") ~= w then ok = false end
        end
        got[#got + 1] = mention .. ">" .. have .. ((found.antecedent and found.antecedent.text) and (":" .. found.antecedent.text:sub(1, 30)) or "")
      end
    end
    chk("ref", ok, table.concat(got, ","))
  end
  if gold.active or gold.inactive then
    local act = {}
    for _, c in ipairs(cx.active_constraints or {}) do if c.slot then act[c.slot .. ":" .. tostring(c.value)] = true end end
    local ok = true
    for _, spec in ipairs(list_of(gold.active)) do if not act[spec] then ok = false end end
    for _, spec in ipairs(list_of(gold.inactive)) do if act[spec] then ok = false end end
    chk(gold.active and "active" or "inactive", ok, table.concat(U.sorted_keys(act), ","))
  end
  if gold.sel then
    -- sel=+fragment,-fragment : memory items whose text contains the fragment must (not) have been selected
    local ok, sel = true, (cx.memory and cx.memory.selected) or {}
    for _, spec in ipairs(list_of(gold.sel)) do
      local sign, frag = spec:sub(1, 1), spec:sub(2):lower()
      local hit = false
      for _, it in ipairs(sel) do if (it.text or ""):lower():find(frag, 1, true) then hit = true end end
      if (sign == "+" and not hit) or (sign == "-" and hit) then ok = false end
    end
    chk("sel", ok, tostring(#sel) .. " selected")
  end
  if gold.unres then chk("unres", #(cx.unresolved or {}) == tonumber(gold.unres), tostring(#(cx.unresolved or {}))) end
  if gold.chain then
    local got = m.query and m.query.chain and table.concat(m.query.chain, ">") or ""
    chk("chain", got == gold.chain, got)
  end
  if gold.pol then chk("pol", (m.polarity or "positive") == gold.pol, m.polarity) end
  if gold.evid then chk("evid", (m.requires_external_evidence and "1" or "0") == gold.evid, tostring(m.requires_external_evidence)) end
  return { ok = ok_all, fields = res }
end

---------------------------------------------------------------- semantic signature (metamorphic tests)
function E.signature(m)
  if not m then return "none" end
  -- the asked role's wh-noun ("Which city ...") is a type constraint on the answer, not an argument: it is not part of the signature
  local function r(x) if not x or x.asked then return "-" end return x.resolved_id or norm_text(x.text) end
  local negs = {}
  for _, n in ipairs(m.constraints and m.constraints.negative or {}) do negs[#negs + 1] = tostring(n.target and (n.target.type or n.target.text) or "?") end
  table.sort(negs)
  local tcs = {}
  for _, t in ipairs(all_temporal(m)) do
    if t.role ~= "derived" then tcs[#tcs + 1] = tostring(t.op) .. ":" .. tostring(t.year or t.text) end
  end
  table.sort(tcs)
  return table.concat({ m.intent or "?", m.relation and m.relation.id or "-", r(m.roles and m.roles.from), r(m.roles and m.roles.to), r(m.subject), r(m.concept),
    m.query and m.query.ask or "-", table.concat(negs, "+"), table.concat(tcs, "+"), m.ambiguity and m.ambiguity.state or "?", m.temporal_scope or "-" }, "|")
end

---------------------------------------------------------------- runner factory (shared by tools, tests and the CLI)
-- mode: "full" | "baseline" | "lexical_only" | comma-separated ablation flags (no_types,no_domain,no_hypotheses,no_coref,no_memory,...)
local MAIN_FALLBACK = { status = "no_interpretation", speech_act = "unknown", intent = "unknown",
  constraints = { positive = {}, negative = {}, temporal = {}, geographic = {}, source = {}, preferences = {}, restrictions = {} },
  ambiguity = { state = "unresolvable", points = {} }, roles = {}, dependencies = {} }

function E.make_runner(mode, lex, extra)
  mode = mode or "full"
  extra = extra or {}
  if mode == "baseline" then
    local B = require("asi.nlu.baseline")
    return function(t) return B.interpret(t, lex), 0 end
  elseif mode == "lexical_only" then
    local B = require("asi.nlu.baseline")
    return function(t) return B.lexical_only(t, lex), 0 end
  end
  local I = require("asi.nlu.interp")
  local Memory = require("asi.nlu.memory")
  local flags = {}
  if mode ~= "full" then for f in mode:gmatch("[^,]+") do flags[f] = true end end
  local interp = I.new({ flags = flags, lexicon = lex, budget = extra.budget })
  return function(t, cs)
    local turns = cs and cs.turns
    if not turns or flags.no_memory then
      local r = interp:interpret((turns and cs.final_text) or t, {})
      return r.main or MAIN_FALLBACK, r.work and r.work.total or 0
    end
    local mem = Memory.new({ ns = { user = "eval", project = "eval", conversation = cs.id } })
    local last, work = nil, 0
    for i, turn in ipairs(turns) do
      local r = interp:interpret(turn.text, { memory = mem, speaker = turn.speaker, light = (turn.speaker ~= "user") })
      work = work + (r.work and r.work.total or 0)
      if i == #turns then last = r end
    end
    return (last and last.main) or MAIN_FALLBACK, work
  end
end

---------------------------------------------------------------- running + aggregation
-- runner(text, case) -> interpretation table (the "main" sentence interpretation)
function E.run(cases, runner, lex, opts)
  opts = opts or {}
  local out = { results = {}, by_cat = {}, field_fail = {}, serious_fail = 0, any_fail = 0, n = #cases, work = 0, wall = 0 }
  local sigs = {}
  for _, cs in ipairs(cases) do
    local t0 = os.clock()
    local ok, m, work = pcall(runner, cs.text, cs)
    out.wall = out.wall + (os.clock() - t0)
    local cmp
    if not ok then
      cmp = { ok = false, fields = { crash = { ok = false, got = tostring(m) } } }
      m = nil
    else
      cmp = E.compare(lex, m, cs.gold)
      out.work = out.work + (work or 0)
    end
    local serious_bad = false
    for k, f in pairs(cmp.fields) do
      if not f.ok then
        out.field_fail[k] = (out.field_fail[k] or 0) + 1
        if E.SERIOUS[k] or k == "crash" then serious_bad = true end
      end
    end
    local cat = out.by_cat[cs.category]
    if not cat then cat = { n = 0, pass = 0, serious = 0 }; out.by_cat[cs.category] = cat end
    cat.n = cat.n + 1
    if cmp.ok then cat.pass = cat.pass + 1 else out.any_fail = out.any_fail + 1 end
    if serious_bad then cat.serious = cat.serious + 1; out.serious_fail = out.serious_fail + 1 end
    local r = { case = cs, ok = cmp.ok, serious = serious_bad, fields = cmp.fields, interp = m }
    out.results[#out.results + 1] = r
    if cs.gold.mm then
      local gid, rel_, other = cs.gold.mm:match("^([%w_]+):(%a+):?([%w_]*)$")
      if gid then sigs[#sigs + 1] = { id = cs.id, group = gid, kind = rel_, other = other, sig = E.signature(m), case = cs } end
    end
  end
  -- metamorphic checks: members of one class must share a signature; `ne` classes must differ from the class they name
  local classes = {}
  for _, s in ipairs(sigs) do classes[s.group] = classes[s.group] or {}; table.insert(classes[s.group], s) end
  out.metamorphic = { eq_total = 0, eq_ok = 0, ne_total = 0, ne_ok = 0, failures = {} }
  for gid, members in pairs(classes) do
    local base = members[1].sig
    for i = 2, #members do
      out.metamorphic.eq_total = out.metamorphic.eq_total + 1
      if members[i].sig == base then out.metamorphic.eq_ok = out.metamorphic.eq_ok + 1
      else table.insert(out.metamorphic.failures, { kind = "equivalence", group = gid, a = members[1].id, b = members[i].id, sig_a = base, sig_b = members[i].sig }) end
    end
    for _, m in ipairs(members) do
      if m.kind == "ne" and m.other ~= "" and classes[m.other] then
        out.metamorphic.ne_total = out.metamorphic.ne_total + 1
        if classes[m.other][1].sig ~= m.sig then out.metamorphic.ne_ok = out.metamorphic.ne_ok + 1
        else table.insert(out.metamorphic.failures, { kind = "distinction", group = gid, other = m.other, a = m.id, sig = m.sig }) end
      end
    end
  end
  return out
end

function E.summary(rep, label)
  local lines = {}
  local n = rep.n
  local lo, hi = U.wilson(n - rep.any_fail, n)
  local slo, shi = U.wilson(n - rep.serious_fail, n)
  lines[#lines + 1] = string.format("%s: n=%d  all-fields accuracy=%.3f [%.3f,%.3f]  serious-error rate=%.3f [%.3f,%.3f]  (any-error %.3f)",
    label or "eval", n, (n - rep.any_fail) / n, lo, hi, rep.serious_fail / n, 1 - shi, 1 - slo, rep.any_fail / n)
  for _, cat in ipairs(U.sorted_keys(rep.by_cat)) do
    local c = rep.by_cat[cat]
    local l, h = U.wilson(c.pass, c.n)
    lines[#lines + 1] = string.format("  %-28s n=%-3d pass=%-3d acc=%.2f [%.2f,%.2f] serious=%d", cat, c.n, c.pass, c.pass / c.n, l, h, c.serious)
  end
  local ff = {}
  for k, v in pairs(rep.field_fail) do ff[#ff + 1] = { k, v } end
  table.sort(ff, function(a, b) if a[2] ~= b[2] then return a[2] > b[2] end return a[1] < b[1] end)
  local parts = {}
  for _, x in ipairs(ff) do parts[#parts + 1] = x[1] .. "=" .. x[2] end
  lines[#lines + 1] = "  failing fields: " .. (#parts > 0 and table.concat(parts, " ") or "none")
  if rep.metamorphic and (rep.metamorphic.eq_total + rep.metamorphic.ne_total) > 0 then
    local m = rep.metamorphic
    lines[#lines + 1] = string.format("  metamorphic: equivalence %d/%d  distinction %d/%d", m.eq_ok, m.eq_total, m.ne_ok, m.ne_total)
  end
  return table.concat(lines, "\n")
end

function E.failures(rep, limit)
  local out = {}
  for _, r in ipairs(rep.results) do
    if not r.ok then
      local bad = {}
      for k, f in pairs(r.fields) do if not f.ok then bad[#bad + 1] = string.format("%s: got [%s] want [%s]", k, tostring(f.got), tostring(f.expected)) end end
      table.sort(bad)
      out[#out + 1] = string.format("%s [%s] %q%s\n    %s", r.case.id, r.case.category, r.case.text, r.serious and " (SERIOUS)" or "", table.concat(bad, "\n    "))
      if limit and #out >= limit then break end
    end
  end
  return table.concat(out, "\n")
end

---------------------------------------------------------------- manifests (dev / val / test integrity)
function E.read_file(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local s = f:read("*a")
  f:close()
  return s
end

function E.checksum(path)
  local s = E.read_file(path)
  return s and U.sha256(s) or nil
end

return E

end

package.preload["asi.nlu.frames"] = function(...)
-- asi.nlu.frames: construction-level semantics. Every frame turns parsed chunks into zero or more competing
-- hypotheses.  Roles are never guessed from word proximity: they come from (1) voice and wh-gap position,
-- (2) the relation lexicon's subj=to|from direction, and (3) type compatibility with the relation signature.
local U = require("asi.nlu.util")
local P = require("asi.nlu.parse")

local F = {}

local cat = P.cat
local function C(S, k) return S.chunks[k] end
local function barrier(c) return c ~= nil and c.pre ~= nil end
local function other(role) return role == "to" and "from" or "to" end

---------------------------------------------------------------- hypothesis helpers
local function newh(S, frame, speech_act, intent, op)
  return { frame = frame, speech_act = speech_act, intent = intent, op = op, roles = {}, used = {}, factors = {}, notes = {}, constraints = {},
    polarity = "positive", S = S }
end
local function addf(h, name, v, note) h.factors[#h.factors + 1] = { name = name, v = v, note = note } end
local function use(h, a, b) for i = a, b or a do h.used[i] = true end end
local function use_np(h, np)
  if not np then return end
  for i = np.c1, np.c2 do h.used[i] = true end
  if np.of_arg then use_np(h, np.of_arg) end
  if np.possessor then use_np(h, np.possessor) end
  for _, m in ipairs(np.mods or {}) do if m.chunk then h.used[m.chunk.idx] = true end end
end
local function use_wh(h, wh)
  if not wh then return end
  for i = wh.c1, wh.c2 do h.used[i] = true end
  if wh.pied_adv then h.pied_consumed = true end   -- "In which city" read as "Where": the preposition is part of the wh-adverbial
end
local function use_vp(h, vp)
  for i = vp.c1, vp.c2 do h.used[i] = true end
end
F.newh, F.addf, F.use_np = newh, addf, use_np

local function is_be(c) return c and c.single and (cat(c, "aux_be") or cat(c, "clitic_s")) and not c.masked end
local function is_do(c) return c and c.single and cat(c, "aux_do") and not c.masked end
-- the auxiliary that licenses a subject-verb inversion with an object gap: do-support ("Which company did P found?") or the perfect ("Which company has P founded?")
local function is_have_aux(c) return c and c.single and cat(c, "aux_have") and not c.masked and not barrier(c) end
local function gap_aux(c) return (is_do(c) and "do") or (is_have_aux(c) and "have") or nil end
local function is_prep(c, form) return c and c.single and not c.masked and cat(c, "prep") and (form == nil or c.unit.form == form) end

-- a relational NP exposes (relation entry, argument NP, role of the known argument, role asked for)
local function relnp_options(S, np)
  local out = {}
  if np.head_kind ~= "relnoun" then return out end
  local arg = np.of_arg or np.possessor
  local compound = false
  if not arg then
    local last = np.mods[#np.mods]
    if last and last.kind == "entity_mod" and last.chunk.idx + 1 == np.hchunk_idx then
      arg = { head_kind = "entity", cands = last.cands, head = last.chunk, u1 = last.chunk.u1, u2 = last.chunk.u2, c1 = last.chunk.idx, c2 = last.chunk.idx,
        mods = {}, score = 0.2, compound = true, nxt = np.hchunk_idx, notes = {} }
      compound = true
    end
  end
  for _, e in ipairs(np.relnouns) do
    local rel = S.lex:get_rel(e.rel)
    if rel then
      local known_role = (e.role == "to") and "from" or "to"
      local base = { rel = rel, arg = arg, known_role = known_role, ask_role = e.role, compound = compound, entry = e, comma = np.comma_arg, fuzzy = e.fuzzy }
      -- kind modifiers ("financial capital of X": either a separate word or a lexicalised prefix) re-target the relation
      local kinds = {}
      if e.kind_prefix then kinds[#kinds + 1] = { form = e.kind_prefix } end
      for _, m in ipairs(np.mods) do kinds[#kinds + 1] = m end
      local derived_found = false
      for _, m in ipairs(kinds) do
        local derived = rel.kinds and rel.kinds[m.form]
        if derived and derived ~= rel.id and S.lex:get_rel(derived) then
          out[#out + 1] = { rel = S.lex:get_rel(derived), arg = arg, known_role = known_role, ask_role = e.role, kind_mod = m, compound = compound, entry = e,
            comma = np.comma_arg, fuzzy = e.fuzzy }
          derived_found = true
        elseif derived == rel.id then base.political_mod = m end
      end
      base.kind_ignored = derived_found -- the base relation silently ignores a kind word: strongly disfavoured
      out[#out + 1] = base
    end
  end
  return out
end
F.relnp_options = relnp_options

-- factors shared by every consumer of a relational-NP option
local function option_factors(h, o)
  if o.kind_mod then
    h.kind_mod = o.kind_mod.form
    if o.kind_mod.chunk then use(h, o.kind_mod.chunk.idx) end
    addf(h, "kind_modifier", 0.2, "kind modifier '" .. tostring(o.kind_mod.form) .. "' selects " .. o.rel.id)
  end
  if o.political_mod and o.political_mod.chunk then use(h, o.political_mod.chunk.idx) end
  if o.kind_ignored then addf(h, "kind_modifier_ignored", -0.9, "a kind word is present but this relation ignores it") end
  if o.comma then addf(h, "comma_apposition", -0.3, "argument attached across a comma") end
  if o.compound then addf(h, "compound_arg", -0.25, "entity+noun compound instead of 'of'/'s'") end
end
F.option_factors = option_factors

local function span_end_ok(S, k)
  -- true when nothing but sentence-final constraints can follow chunk k (used only for scoring, not as a hard gate)
  return k > S.last
end

-- A support verb ("use", "keep", "have", "call", "recognize") carries no relation by itself: the relation comes from the noun it supports.  In a plain
-- verb frame it is licensed only when the wh-phrase NAMES that noun ("WHICH CURRENCY does Sweden use?"); a bare "What does Acme keep?" is not a
-- headquarters question.  (The possessed-noun and "as"-complement frames below license it with their own noun.)
local function support_licensed(S, e, rel, wh, ask_role)
  if not e.support then return true end
  if e.as_only then return false end
  if wh and wh.relnoun and wh.np then
    for _, ne in ipairs(wh.np.relnouns or {}) do if ne.rel == rel.id then return true end end
  end
  -- the wh-phrase asks for the HOLDER and its type agrees with the relation's holder type: "WHICH COUNTRIES use the euro?"
  if ask_role == "from" and wh and wh.type and S.lex:compat(rel.from, wh.type) >= 0.9 then return true end
  return false
end
F.support_licensed = support_licensed

-- a relational wh-noun ("What CURRENCY does X use?") names the relation asked about: it must agree with the relation the rest of the clause expresses
local function wh_relnoun_agreement(h, wh, rel)
  if not (wh and wh.relnoun and wh.np) then return end
  local same = false
  for _, ne in ipairs(wh.np.relnouns or {}) do if ne.rel == rel.id then same = true end end
  if same then addf(h, "wh_noun_names_relation", 0.5, "the wh-noun '" .. tostring(wh.np.head and wh.np.head.form) .. "' names the relation " .. rel.id)
  else addf(h, "wh_noun_other_relation", -0.5, "the wh-noun names a different relation than " .. rel.id) end
end
F.wh_relnoun_agreement = wh_relnoun_agreement

-- record how a relation hypothesis binds its arguments (type fit is computed in hyp.lua)
local function set_lookup(h, rel, known_role, known_np, ask_role, wh)
  h.rel, h.rel_obj = rel.id, rel
  h.roles[known_role] = known_np
  h.known_role, h.ask = known_role, ask_role
  h.ask_type = rel[ask_role]
  if wh and wh.type then h.wh_type = wh.type end
  h.wh = wh
  h.op = "lookup"
  h.intent = "factual_lookup"
  h.requires_evidence = true
end

local function mark_unresolved_pron(h, np)
  if np and np.head_kind == "pronoun" then h.pronouns = h.pronouns or {}; h.pronouns[#h.pronouns + 1] = np end
  if np and np.of_arg then mark_unresolved_pron(h, np.of_arg) end
  if np and np.possessor then mark_unresolved_pron(h, np.possessor) end
end
F.mark_pron = mark_unresolved_pron

---------------------------------------------------------------- frame: wh + be + NP
function F.wh_copular(S, out)
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    if not wh.adverbial and wh.wh ~= "how_many" and wh.wh ~= "how_much" and wh.wh ~= "how_adj" then
      local bk = wh.nxt
      local be = C(S, bk)
      if is_be(be) and not barrier(be) then
        -- "Who is CURRENTLY the CEO of X?", "Who is NOW in charge of Y?": adverbs between the copula and the predicate carry no content here
        local nk, advs = bk + 1, {}
        while C(S, nk) and C(S, nk).single and not C(S, nk).masked and not barrier(C(S, nk)) and cat(C(S, nk), "adv") and not P.is_neg(C(S, nk)) do
          advs[#advs + 1] = nk; nk = nk + 1
        end
        for _, np in ipairs(P.parse_np(S, nk)) do
          local base = function(frame)
            local h = newh(S, frame, "question", nil, nil)
            use_wh(h, wh); use(h, bk); use_np(h, np)
            for _, a in ipairs(advs) do use(h, a) end
            -- "What is France's capital city CALLED?" -- the closing participle only asks for the name of the noun phrase
            local tail = C(S, np.nxt)
            if tail and tail.single and not tail.masked and np.nxt == S.last and (tail.unit.form == "called" or tail.unit.form == "named") then
              use(h, np.nxt)
              addf(h, "name_asking_participle", 0.1, "closing 'called' asks for the name of the noun phrase")
            end
            h.wh = wh; h.last_chunk = np.c2
            mark_unresolved_pron(h, np)
            return h
          end
          if np.head_kind == "relnoun" then
            local opts = relnp_options(S, np)
            for _, o in ipairs(opts) do
              local h = base("wh_copular:relnp")
              if o.arg then
                set_lookup(h, o.rel, o.known_role, o.arg, o.ask_role, wh)
                addf(h, "relnp_arg", 0.7, "relational noun with explicit argument")
                option_factors(h, o)
                mark_unresolved_pron(h, o.arg)
              else
                h.op, h.intent, h.rel, h.rel_obj = "define", "definition", o.rel.id, o.rel
                h.concept = np
                addf(h, "relnoun_no_arg", -1.0, "relational noun without its argument")
              end
              if np.temporal_scope then h.temporal_scope = np.temporal_scope end
              if np.superlative then h.ordering = { superlative = np.superlative } end
              out[#out + 1] = h
            end
          elseif np.head_kind == "entity" then
            local h = base("wh_copular:entity")
            h.op, h.intent = "describe", "entity_description"
            h.subject = np
            h.roles.subject = np
            h.requires_evidence = true
            if wh.wh == "who" then h.expect_type = "agent"; addf(h, "wh_who_expects_agent", 0.0, "who expects an agent") end
            if wh.type then h.expect_type = wh.type end
            out[#out + 1] = h
          elseif np.head_kind == "typenoun" or np.head_kind == "concept" or np.head_kind == "unknown" then
            local h = base("wh_copular:concept")
            h.op, h.intent = "define", "definition"
            h.concept = np
            h.requires_evidence = true
            if np.head_kind == "unknown" then addf(h, "unknown_term", -0.15, "term not in the lexicon: dataset-specific meaning must be learned from evidence") end
            if np.of_arg then addf(h, "concept_of_arg", -0.4, "a non-relational concept noun with an 'of' argument is a weaker structure than a relational noun") end
            out[#out + 1] = h
          elseif np.head_kind == "pronoun" then
            local h = base("wh_copular:pronoun")
            h.op, h.intent = "describe", "entity_description"
            h.subject = np
            out[#out + 1] = h
          elseif np.head_kind == "temporal" or np.head_kind == "number" or np.head_kind == "quote" or np.head_kind == "literal" then
            local h = base("wh_copular:literal")
            h.op, h.intent = "describe", "entity_description"
            h.subject = np
            out[#out + 1] = h
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- frame: wh + VERB(active) + NP    ("Who founded X?")
-- also "Which company is based in Germany?" (stative prep verbs) and "Which claims are not supported by the documents?" (passive)
function F.wh_verb(S, out)
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    if not wh.adverbial and wh.wh ~= "how_adj" and wh.wh ~= "how_many" and wh.wh ~= "how_much" then
      local vk = wh.nxt
      for _, vp in ipairs(P.parse_vp(S, vk)) do
        for _, e in ipairs(vp.analysis.entries) do
          local rel = S.lex:get_rel(e.rel)
          if rel and support_licensed(S, e, rel, wh, (vp.voice == "active") and e.subj or other(e.subj)) then
            local function finish(h, known_np, known_role, ask_role)
              set_lookup(h, rel, known_role, known_np, ask_role, wh)
              h.wh = wh
              use_wh(h, wh); use_vp(h, vp); use_np(h, known_np)
              if vp.neg then h.polarity = "negative"; use(h, vp.neg_chunk.idx) end
              addf(h, "direction_explicit", 0.35, "role direction fixed by voice/lexicon (" .. vp.voice .. ", subj=" .. e.subj .. ")")
              if vp.analysis.guessed then addf(h, "guessed_verb", -0.3, "verb form guessed") end
              wh_relnoun_agreement(h, wh, rel)
              mark_unresolved_pron(h, known_np)
              out[#out + 1] = h
            end
            if vp.voice == "active" then
              if e.prep then
                -- "Which company invested in B?": prep object fills the other role
                local pk = vp.nxt
                if is_prep(C(S, pk), e.prep) then
                  for _, np in ipairs(P.parse_np(S, pk + 1)) do
                    local h = newh(S, "wh_verb:active_prep", "question")
                    use(h, pk)
                    finish(h, np, other(e.subj), e.subj)
                  end
                end
              else
                for _, np in ipairs(P.parse_np(S, vp.nxt)) do
                  local h = newh(S, "wh_verb:active", "question")
                  finish(h, np, other(e.subj), e.subj)
                end
              end
            else -- passive / stative:  wh is the grammatical subject
              if e.prep then
                -- "Which company is based in Germany?": subject keeps e.subj role, PP object the other
                local pk = vp.nxt
                if is_prep(C(S, pk), e.prep) then
                  for _, np in ipairs(P.parse_np(S, pk + 1)) do
                    local h = newh(S, "wh_verb:stative", "question")
                    use(h, pk)
                    finish(h, np, other(e.subj), e.subj)
                  end
                end
              else
                -- "Which claims are not supported by the documents?"  by-agent fills e.subj; wh is the other role
                local pk = vp.nxt
                if is_prep(C(S, pk), "by") then
                  for _, np in ipairs(P.parse_np(S, pk + 1)) do
                    local h = newh(S, "wh_verb:passive_by", "question")
                    use(h, pk)
                    finish(h, np, e.subj, other(e.subj))
                  end
                elseif e.support and (is_prep(C(S, pk), "in") or is_prep(C(S, pk), "at") or is_prep(C(S, pk), "across") or is_prep(C(S, pk), "throughout")) then
                  -- locative passive of a support verb: "Which currency is used IN Sweden?" = the currency Sweden uses
                  for _, np in ipairs(P.parse_np(S, pk + 1)) do
                    local h = newh(S, "wh_verb:locative_passive", "question")
                    use(h, pk)
                    finish(h, np, e.subj, other(e.subj))
                    addf(h, "locative_passive", 0.15, "support verb '" .. tostring(e.lemma) .. "' with a locative holder")
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- frame: wh + do + NP(subject) + VERB(base)   ("Which company did P found?")
function F.wh_do(S, out)
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    if not wh.adverbial and wh.wh ~= "how_adj" then
      local dk = wh.nxt
      local embedded_no_aux = S.embedded and not gap_aux(C(S, dk)) and not is_be(C(S, dk))
      local aux = gap_aux(C(S, dk))
      if aux or embedded_no_aux then
        local nk = embedded_no_aux and dk or dk + 1
        local neg_chunk
        if P.is_neg(C(S, nk)) then neg_chunk = C(S, nk); nk = nk + 1 end
        for _, snp in ipairs(P.parse_np(S, nk, { no_of = false })) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = aux or "do", finite_ok = embedded_no_aux })) do
            for _, e in ipairs(vp.analysis.entries) do
              local rel = S.lex:get_rel(e.rel)
              if rel and support_licensed(S, e, rel, wh, other(e.subj)) then
                -- subject NP fills e.subj; the wh-gap is the object (other role). Stranded or absent preposition is fine.
                local h = newh(S, "wh_do:object_gap", "question")
                set_lookup(h, rel, e.subj, snp, other(e.subj), wh)
                use_wh(h, wh); use(h, dk); use_np(h, snp); use_vp(h, vp)
                if neg_chunk then h.polarity = "negative"; use(h, neg_chunk.idx) end
                local pk = vp.nxt
                if e.prep then
                  if is_prep(C(S, pk), e.prep) then use(h, pk)
                  elseif wh.pied == e.prep then h.pied_consumed = true
                  else addf(h, "prep_missing", -0.5, "expected stranded preposition '" .. e.prep .. "'") end
                elseif wh.pied then
                  -- "For which company does P work?": the fronted preposition belongs to the verb; a verb without one cannot absorb it
                  addf(h, "pied_prep_unused", -0.6, "fronted preposition '" .. wh.pied .. "' does not belong to this verb")
                end
                wh_relnoun_agreement(h, wh, rel)
                addf(h, "direction_explicit", 0.35, "role direction fixed by do-support gap (subject=" .. e.subj .. ")")
                mark_unresolved_pron(h, snp)
                out[#out + 1] = h
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- frame: wh + be + NP + VERB-ed (+ by)   ("Who was X founded by?")
function F.wh_passive(S, out)
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    if not wh.adverbial then
      local bk = wh.nxt
      if is_be(C(S, bk)) then
        for _, snp in ipairs(P.parse_np(S, bk + 1)) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = "be" })) do
            if vp.voice == "passive" then
              for _, e in ipairs(vp.analysis.entries) do
                local rel = S.lex:get_rel(e.rel)
                local lic_prep = rel and support_licensed(S, e, rel, wh, other(e.subj))
                local lic_by = rel and support_licensed(S, e, rel, wh, e.subj)
                if rel and lic_prep and e.prep and (is_prep(C(S, vp.nxt), e.prep) or wh.pied == e.prep) then
                  -- stative-prep verb: the grammatical subject keeps its own role, the wh-gap is the object of the (stranded or fronted) preposition
                  local h = newh(S, "wh_passive:stranded_prep", "question")
                  set_lookup(h, rel, e.subj, snp, other(e.subj), wh)
                  use_wh(h, wh); use(h, bk); use_np(h, snp); use_vp(h, vp)
                  if is_prep(C(S, vp.nxt), e.prep) then use(h, vp.nxt) else h.pied_consumed = true end
                  addf(h, "direction_explicit", 0.35, "stative verb with a preposition gap (subject=" .. e.subj .. ")")
                  mark_unresolved_pron(h, snp)
                  out[#out + 1] = h
                end
                if rel and lic_by and not e.prep then
                  local pk = vp.nxt
                  local pc = C(S, pk)
                  -- a passive followed by ANOTHER preposition ("is Java used for", "is X known for") is a different construction, not a stranded by-phrase
                  local other_prep = pc and pc.single and not pc.masked and cat(pc, "prep") and pc.unit.form ~= "by" and not barrier(pc)
                  -- a support verb ("is called", "is used") has no agentless passive: "What is X called?" asks about X itself, it does not gap an agent
                  if not other_prep and (not e.support or is_prep(pc, "by")) then
                    local h = newh(S, "wh_passive:stranded_by", "question")
                    -- X (grammatical subject) is the logical object; the wh-gap is the agent (e.subj role)
                    set_lookup(h, rel, other(e.subj), snp, e.subj, wh)
                    use_wh(h, wh); use(h, bk); use_np(h, snp); use_vp(h, vp)
                    if is_prep(pc, "by") then use(h, pk) else addf(h, "by_missing", -0.4, "passive without by-phrase") end
                    addf(h, "direction_explicit", 0.35, "agent gap of a passive")
                    mark_unresolved_pron(h, snp)
                    out[#out + 1] = h
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- frame: when / where / how-many / how-old questions
function F.wh_adverbial(S, out)
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    local f = wh.wh
    if f == "where" or f == "when" then
      local bk = wh.nxt
      -- "Where is X?"  /  "When was X founded?"  /  "When did X acquire Y?"
      if is_be(C(S, bk)) then
        for _, np in ipairs(P.parse_np(S, bk + 1)) do
          -- X followed by a participle:  "Where is X located?"  "When was X founded/born?"
          local vps = P.parse_vp(S, np.nxt, { aux_hint = "be" })
          for _, vp in ipairs(vps) do
            if vp.voice == "passive" then
              for _, e in ipairs(vp.analysis.entries) do
                local rel = S.lex:get_rel(e.rel)
                if rel then
                  local target_rel, known_role, ask_role
                  if f == "where" then
                    -- stative-prep verbs map directly ("located in", "based in", "born in"); others use rel.where
                    if e.prep then target_rel, known_role, ask_role = rel, e.subj, other(e.subj)
                    elseif rel.where and S.lex:get_rel(rel.where) then target_rel = S.lex:get_rel(rel.where); known_role, ask_role = "from", "to" end
                  else
                    if rel.when and S.lex:get_rel(rel.when) then target_rel = S.lex:get_rel(rel.when); known_role, ask_role = "from", "to" end
                  end
                  if target_rel then
                    local h = newh(S, "wh_adv:" .. f .. ":passive", "question")
                    set_lookup(h, target_rel, known_role, np, ask_role, wh)
                    h.derived_via = rel.id
                    use_wh(h, wh); use(h, bk); use_np(h, np); use_vp(h, vp)
                    addf(h, "direction_explicit", 0.3, f .. "-question on passive participle")
                    mark_unresolved_pron(h, np)
                    out[#out + 1] = h
                    -- "Where is the headquarters of X located?": 'located' adds nothing to a location-valued noun, which is answered by its own value
                    if f == "where" and target_rel.id == "located_in" and np.head_kind == "relnoun" then
                      for _, o in ipairs(relnp_options(S, np)) do
                        if o.arg and o.rel.locus and o.ask_role == "to" then
                          addf(h, "redundant_location_hop", -0.7, "the noun's own relation already gives a location; 'where ... located' needs no second hop")
                          local hl = newh(S, "wh_adv:where:locus_passive", "question")
                          set_lookup(hl, o.rel, o.known_role, o.arg, o.ask_role, wh)
                          use_wh(hl, wh); use(hl, bk); use_np(hl, np); use_vp(hl, vp)
                          addf(hl, "relnp_arg", 0.7, "relational noun with explicit argument")
                          addf(hl, "where_locus", 0.3, "'where' asks for the location this relation's value gives")
                          option_factors(hl, o)
                          mark_unresolved_pron(hl, o.arg)
                          out[#out + 1] = hl
                          break
                        end
                      end
                    end
                  end
                end
              end
            end
          end
          if f == "where" then
            -- "Where is the headquarters of X?": a noun whose relation value IS a location (rel.locus) is answered by that value directly;
            -- asking for the location of the location-valued attribute is a redundant extra hop
            local locus_opts = {}
            if np.head_kind == "relnoun" then
              for _, o in ipairs(relnp_options(S, np)) do if o.arg and o.rel.locus and o.ask_role == "to" then locus_opts[#locus_opts + 1] = o end end
            end
            local lrel = S.lex:get_rel("located_in")
            if lrel then
              local h = newh(S, "wh_adv:where:copula", "question")
              set_lookup(h, lrel, "from", np, "to", wh)
              use_wh(h, wh); use(h, bk); use_np(h, np)
              if #locus_opts > 0 then addf(h, "redundant_location_hop", -0.7, "the noun's own relation already gives a location; 'where' needs no second hop") end
              mark_unresolved_pron(h, np)
              out[#out + 1] = h
            end
            for _, o in ipairs(locus_opts) do
              local h = newh(S, "wh_adv:where:locus", "question")
              set_lookup(h, o.rel, o.known_role, o.arg, o.ask_role, wh)
              use_wh(h, wh); use(h, bk); use_np(h, np)
              addf(h, "relnp_arg", 0.7, "relational noun with explicit argument")
              addf(h, "where_locus", 0.3, "'where' asks for the location this relation's value gives")
              option_factors(h, o)
              mark_unresolved_pron(h, o.arg)
              out[#out + 1] = h
            end
          end
        end
      elseif is_do(C(S, bk)) then
        -- "When did X acquire Y?"  /  "When did X die?"
        for _, snp in ipairs(P.parse_np(S, bk + 1)) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = "do" })) do
            for _, e in ipairs(vp.analysis.entries) do
              local rel = S.lex:get_rel(e.rel)
              local trel_id = rel and ((f == "when") and rel.when or rel.where)
              local trel = trel_id and S.lex:get_rel(trel_id)
              if trel then
                local obj_nps = P.parse_np(S, vp.nxt)
                local function build(onp)
                  local h = newh(S, "wh_adv:" .. f .. ":do", "question")
                  local known, kr
                  if onp then known, kr = onp, "from"; h.qualifier = { rel = rel.id, role = e.subj, np = snp }
                  else known, kr = snp, "from" end
                  set_lookup(h, trel, kr, known, "to", wh)
                  h.derived_via = rel.id
                  use_wh(h, wh); use(h, bk); use_np(h, snp); use_vp(h, vp)
                  if onp then use_np(h, onp) end
                  mark_unresolved_pron(h, snp); mark_unresolved_pron(h, onp)
                  addf(h, "direction_explicit", 0.3, f .. "-question on active verb")
                  out[#out + 1] = h
                end
                if e.subj == "from" then build(nil) end -- intransitive-like: "When did X die?"
                for _, onp in ipairs(obj_nps) do build(onp) end
                if e.subj == "to" and #obj_nps == 0 then build(nil) end
              end
            end
          end
        end
      end
    elseif f == "how_many" or f == "how_much" then
      -- "How many employees does X have?"  "How much revenue does X generate?"
      local np = wh.np
      local dk = wh.nxt
      if np and np.head_kind == "relnoun" and is_do(C(S, dk)) then
        for _, snp in ipairs(P.parse_np(S, dk + 1)) do
          local vk = snp.nxt
          local vc = C(S, vk)
          local consumed_verb = false
          if vc and vc.single and (cat(vc, "aux_have") or (vc.verbs or vc.relverbs[1])) and not barrier(vc) then consumed_verb = true end
          for _, e in ipairs(np.relnouns) do
            local rel = S.lex:get_rel(e.rel)
            if rel then
              local h = newh(S, "wh_adv:" .. f, "question")
              set_lookup(h, rel, other(e.role), snp, e.role, wh)
              h.answer_form = "number"
              use_wh(h, wh); use_np(h, np); use(h, dk); use_np(h, snp)
              if consumed_verb then use(h, vk) end
              addf(h, "relnp_arg", 0.6, "how-many over a relational noun")
              mark_unresolved_pron(h, snp)
              out[#out + 1] = h
            end
          end
        end
      elseif np and (np.head_kind == "typenoun" or np.head_kind == "unknown") then
        -- "How many cities are there in France?" -> count query over a type
        local h = newh(S, "wh_adv:count", "question", "count", "count")
        h.target = np
        h.wh = wh
        h.requires_evidence = true
        use_wh(h, wh); use_np(h, np)
        local k = wh.nxt
        while C(S, k) and is_be(C(S, k)) or (C(S, k) and C(S, k).single and (C(S, k).unit.form == "there")) do use(h, k); k = k + 1 end
        h.count_target = true
        addf(h, "count_query", 0.3, "how many <type>")
        out[#out + 1] = h
      end
    elseif f == "how_adj" then
      -- "How old is X?"  "How tall is Y?"
      local bk = wh.nxt
      if is_be(C(S, bk)) then
        for _, np in ipairs(P.parse_np(S, bk + 1)) do
          local dim = wh.dim and S.lex:dim(wh.dim)
          for _, rid in ipairs(dim and dim.rels or {}) do
            local rel = S.lex:get_rel(rid)
            if rel then
              local h = newh(S, "wh_adv:how_adj", "question")
              set_lookup(h, rel, "from", np, "to", wh)
              h.answer_form = "number"
              h.dimension = wh.dim
              use_wh(h, wh); use(h, bk); use_np(h, np)
              mark_unresolved_pron(h, np)
              addf(h, "dimension_relation", 0.2, "how-" .. tostring(wh.adj) .. " via dimension " .. tostring(wh.dim))
              out[#out + 1] = h
            end
          end
        end
      end
    elseif f == "why" or f == "how" then
      local k = wh.nxt
      local h = newh(S, "wh_adv:" .. f, "question", f == "why" and "causal_explanation" or "explanation", "explain")
      h.wh = wh
      h.requires_evidence = true
      use_wh(h, wh)
      -- clause = [aux] NP VERB ...  captured generically
      local cl = F.parse_clause(S, k)
      if cl then
        h.clause = cl
        for i = k, cl.last do h.used[i] = true end
        addf(h, "clause_parsed", 0.4, "explanatory clause identified")
      else
        addf(h, "clause_missing", -0.6, "no clause to explain")
      end
      out[#out + 1] = h
    end
  end
end

-- Support verb + a POSSESSED relational noun, asked about:
--   "Where does Acme have/keep its headquarters?"   "In which city does France have its capital?"   "What does Sweden call its currency?"
--   embedded: "Tell me where Acme keeps its headquarters."
-- The holder is the verb's subject and the possessive pronoun is bound to it; the asked value is the relation's `to` side.
function F.where_support(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh.wh == "where" or wh.wh == "what" or wh.wh == "which" then
      local dk = wh.nxt
      local embedded_no_aux = S.embedded and not is_do(C(S, dk))
      if is_do(C(S, dk)) or embedded_no_aux then
        local nk = embedded_no_aux and dk or dk + 1
        for _, snp in ipairs(P.parse_np(S, nk)) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = "do", finite_ok = embedded_no_aux })) do
            for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
              local dc = C(S, onp.c1)
              if onp.head_kind == "relnoun" and not onp.of_arg and dc and dc.single and (cat(dc, "poss_det") or cat(dc, "det")) and onp.c1 < onp.nxt - 1 then
                for _, o in ipairs(relnp_options(S, onp)) do
                  local rel = o.rel
                  local supported = (vp.lemma == "have" and rel.support_have) or false
                  for _, e in ipairs(vp.analysis.entries or {}) do if e.support and e.rel == rel.id then supported = true end end
                  local type_ok
                  if wh.wh == "where" then type_ok = rel.locus or (wh.type and S.lex:compat(rel.to, wh.type) >= 0.9)
                  else type_ok = (not wh.type) or S.lex:compat(rel.to, wh.type) >= 0.5 end
                  if supported and type_ok and o.ask_role == "to" then
                    local h = newh(S, "wh_adv:support_possessed", "question")
                    set_lookup(h, rel, "from", snp, "to", wh)
                    use_wh(h, wh); if not embedded_no_aux then use(h, dk) end; use_np(h, snp); use_vp(h, vp); use_np(h, onp)
                    addf(h, "support_construction", 0.8, "'" .. tostring(vp.lemma) .. "' + possessed '" .. rel.id .. "' noun")
                    if wh.wh == "where" then addf(h, "where_locus", 0.3, "'where' asks for the location this relation's value gives") end
                    mark_unresolved_pron(h, snp)
                    out[#out + 1] = h
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

-- Support verb with an "as" complement, the wh-phrase being the value:
--   "Who does Acme have as its CEO?"   "Whom did the board name as chief executive?"   "Which city does France recognize as its capital?"
--   "What does Sweden use as its currency?"   embedded: "Tell me who Acme has as its CEO."
-- The verb's subject is the holder, the (possessed or bare) relational noun after "as" names the relation, the wh-phrase is the relation's `to` side.
function F.wh_support_as(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and wh.wh ~= "how_adj" and wh.wh ~= "how_many" and wh.wh ~= "how_much" and wh.wh ~= "where" and wh.wh ~= "when" then
      local dk = wh.nxt
      local embedded_no_aux = S.embedded and not is_do(C(S, dk))
      if is_do(C(S, dk)) or embedded_no_aux then
        local nk = embedded_no_aux and dk or dk + 1
        for _, snp in ipairs(P.parse_np(S, nk)) do
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, { aux_hint = "do", finite_ok = embedded_no_aux })) do
            if is_prep(C(S, vp.nxt), "as") then
              for _, onp in ipairs(P.parse_np(S, vp.nxt + 1)) do
                -- "name X as chief executive OF Acme" has its holder inside the noun phrase and an extra agent we cannot represent: not this frame
                if onp.head_kind == "relnoun" and not onp.of_arg and not onp.possessor and not is_prep(C(S, onp.nxt), "of") then
                  for _, o in ipairs(relnp_options(S, onp)) do
                    local rel = o.rel
                    local supported = (vp.lemma == "have" and rel.support_have) or false
                    for _, e in ipairs(vp.analysis.entries or {}) do if e.support and e.rel == rel.id then supported = true end end
                    local type_ok = (not wh.type) or S.lex:compat(rel.to, wh.type) >= 0.5
                    if supported and type_ok and o.ask_role == "to" then
                      local h = newh(S, "wh_do:support_as", "question")
                      set_lookup(h, rel, "from", snp, "to", wh)
                      use_wh(h, wh); if not embedded_no_aux then use(h, dk) end; use_np(h, snp); use_vp(h, vp); use(h, vp.nxt); use_np(h, onp)
                      addf(h, "support_construction", 0.8, "'" .. tostring(vp.lemma) .. "' + 'as' + '" .. rel.id .. "' noun")
                      wh_relnoun_agreement(h, wh, rel)
                      mark_unresolved_pron(h, snp)
                      out[#out + 1] = h
                    end
                  end
                end
              end
            end
          end
        end
      end
    end
  end
end

-- The wh-phrase is the HOLDER (subject) of a support verb:
--   "Which country has Paris as its capital?"   "Which companies have their headquarters in Oslo?"   "Which firm keeps its head office in Lyon?"
-- The value is the known side, the wh-phrase fills the relation's `from` role.
function F.wh_support_subject(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and wh.wh ~= "how_adj" and wh.wh ~= "how_many" and wh.wh ~= "how_much" and wh.wh ~= "where" and wh.wh ~= "when" and wh.wh ~= "why" and wh.wh ~= "how" then
      for _, vp in ipairs(P.parse_vp(S, wh.nxt)) do
        if vp.voice == "active" then
          local function supported(rel)
            local ok = (vp.lemma == "have" and rel.support_have) or false
            for _, e in ipairs(vp.analysis.entries or {}) do if e.support and e.rel == rel.id then ok = true end end
            return ok
          end
          local function emit(rel, vnp, onp, frame, extra_used)
            if wh.type and S.lex:compat(rel.from, wh.type) < 0.5 then return end
            local h = newh(S, frame, "question")
            set_lookup(h, rel, "to", vnp, "from", wh)
            use_wh(h, wh); use_vp(h, vp); use_np(h, vnp); use_np(h, onp)
            if extra_used then use(h, extra_used) end
            addf(h, "support_construction", 0.8, "'" .. tostring(vp.lemma) .. "' + '" .. rel.id .. "' noun with the wh-phrase as holder")
            wh_relnoun_agreement(h, wh, rel)
            mark_unresolved_pron(h, vnp)
            out[#out + 1] = h
          end
          -- (a) VERB value as RELNOUN
          for _, vnp in ipairs(P.parse_np(S, vp.nxt)) do
            if is_prep(C(S, vnp.nxt), "as") then
              for _, onp in ipairs(P.parse_np(S, vnp.nxt + 1)) do
                if onp.head_kind == "relnoun" and not onp.of_arg and not onp.possessor and not is_prep(C(S, onp.nxt), "of") then
                  for _, o in ipairs(relnp_options(S, onp)) do
                    if o.ask_role == "to" and supported(o.rel) then emit(o.rel, vnp, onp, "wh_subject:support_as", vnp.nxt) end
                  end
                end
              end
            end
          end
          -- (b) VERB its RELNOUN in|at VALUE
          for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
            local dc = C(S, onp.c1)
            if onp.head_kind == "relnoun" and not onp.of_arg and dc and dc.single and cat(dc, "poss_det") and onp.c1 < onp.nxt - 1 and (is_prep(C(S, onp.nxt), "in") or is_prep(C(S, onp.nxt), "at")) then
              for _, vnp in ipairs(P.parse_np(S, onp.nxt + 1)) do
                for _, o in ipairs(relnp_options(S, onp)) do
                  if o.ask_role == "to" and supported(o.rel) then emit(o.rel, vnp, onp, "wh_subject:support_possessed", onp.nxt) end
                end
              end
            end
          end
        end
      end
    end
  end
end

-- The wh-phrase is the HOLDER of a post that a role noun names:
--   "Who holds the CEO position at Acme?"   "Who currently occupies the prime minister role in Spain?"   "Who has the president's job in France?"
-- The role noun carries the relation, the verb only says that the wh-phrase holds the post: the answer is the relation's value for the argument.
local ROLE_HOLD = { hold = true, occupy = true, fill = true, have = true, assume = true }
function F.wh_role_holder(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial and (wh.wh == "who" or wh.wh == "which" or wh.wh == "whom") then
      for _, vp in ipairs(P.parse_vp(S, wh.nxt)) do
        if vp.voice == "active" and ROLE_HOLD[vp.lemma] then
          for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
            if onp.head_kind == "relnoun" and (onp.of_arg or onp.possessor) then
              for _, o in ipairs(relnp_options(S, onp)) do
                if o.entry and o.entry.rolesuffix and o.ask_role == "to" and o.arg and ((not wh.type) or S.lex:compat(o.rel.to, wh.type) >= 0.5) then
                  local h = newh(S, "wh_role_holder", "question")
                  set_lookup(h, o.rel, "from", o.arg, "to", wh)
                  use_wh(h, wh); use_vp(h, vp); use_np(h, onp)
                  addf(h, "role_holder_construction", 0.9, "'" .. tostring(vp.lemma) .. "' + the post noun of " .. o.rel.id)
                  option_factors(h, o)
                  mark_unresolved_pron(h, o.arg)
                  out[#out + 1] = h
                end
              end
            end
          end
        end
      end
    end
  end
end

-- generic clause: [aux]* [NP-subject] [aux]* [not] VERB [NP-object] -> {subj, verb, obj, neg, last}
function F.parse_clause(S, k)
  local best
  for _, snp in ipairs(P.parse_np(S, k)) do
    for _, vp in ipairs(P.parse_vp(S, snp.nxt)) do
      local cl = { subj = snp, vp = vp, lemma = vp.lemma, neg = vp.neg, voice = vp.voice, last = vp.c2 }
      local objs = P.parse_np(S, vp.nxt)
      if objs[1] then cl.obj = objs[1]; cl.last = objs[1].c2 end
      best = best or cl
    end
  end
  if not best then
    -- inverted: aux NP VERB  ("did X fail", "does X work")
    local c = C(S, k)
    if c and c.single and (cat(c, "aux_do") or cat(c, "aux_be") or cat(c, "aux_have") or cat(c, "modal")) then
      for _, snp in ipairs(P.parse_np(S, k + 1)) do
        local neg
        local vk = snp.nxt
        if P.is_neg(C(S, vk)) then neg = true; vk = vk + 1 end
        for _, vp in ipairs(P.parse_vp(S, vk, { aux_hint = (cat(c, "aux_do") and "do") or (cat(c, "aux_be") and "be") or "have" })) do
          local cl = { subj = snp, vp = vp, lemma = vp.lemma, neg = neg or vp.neg, voice = vp.voice, last = vp.c2 }
          local objs = P.parse_np(S, vp.nxt)
          if objs[1] then cl.obj = objs[1]; cl.last = objs[1].c2 end
          best = best or cl
        end
      end
    end
  end
  return best
end

---------------------------------------------------------------- frame: yes/no verification
function F.yes_no(S, out)
  local k0 = S.first
  local c0 = C(S, k0)
  if not (c0 and c0.single and (cat(c0, "aux_be") or cat(c0, "aux_do") or cat(c0, "aux_have") or cat(c0, "modal")) and not cat(c0, "wh")) then return end
  local akind = P.aux_kind(c0)
  for _, np1 in ipairs(P.parse_np(S, k0 + 1)) do
    local function base(frame)
      local h = newh(S, frame, "question", "verification", "verify")
      use(h, k0); use_np(h, np1)
      h.requires_evidence = true
      mark_unresolved_pron(h, np1)
      return h
    end
    if akind == "be" then
      local nk = np1.nxt
      -- "Is Paris the capital of France?"  /  "Is the capital of France Paris?"
      for _, np2 in ipairs(P.parse_np(S, nk)) do
        for _, pair in ipairs({ { np1, np2 }, { np2, np1 } }) do
          local value, relnp = pair[1], pair[2]
          if relnp.head_kind == "relnoun" and value.head_kind ~= "relnoun" then
            for _, o in ipairs(relnp_options(S, relnp)) do
              if o.arg then
                local h = base("yes_no:be_rel")
                use_np(h, np2)
                h.rel, h.rel_obj = o.rel.id, o.rel
                h.roles[o.known_role] = o.arg
                h.roles[o.ask_role] = value
                h.verify = { rel = o.rel.id, from = h.roles.from, to = h.roles.to }
                h.known_role, h.ask = o.known_role, nil
                addf(h, "relnp_arg", 0.6, "verification of a relational statement")
                mark_unresolved_pron(h, o.arg); mark_unresolved_pron(h, value)
                out[#out + 1] = h
              end
            end
          end
        end
        if np2.head_kind == "typenoun" and np1.head_kind == "entity" then
          local h = base("yes_no:be_type")
          use_np(h, np2)
          h.verify = { type_assertion = np2.senses and np2.senses[1] and np2.senses[1].type, subject = np1 }
          h.roles.subject = np1
          out[#out + 1] = h
        end
      end
      -- "Is Paris in France?"  "Is X located in Y?"
      local pk = nk
      local vps = P.parse_vp(S, nk, { aux_hint = "be" })
      for _, vp in ipairs(vps) do
        if vp.voice == "passive" then
          for _, e in ipairs(vp.analysis.entries) do
            local rel = S.lex:get_rel(e.rel)
            if rel then
              if e.prep and is_prep(C(S, vp.nxt), e.prep) then
                for _, np2 in ipairs(P.parse_np(S, vp.nxt + 1)) do
                  local h = base("yes_no:be_stative")
                  use_vp(h, vp); use(h, vp.nxt); use_np(h, np2)
                  h.rel, h.rel_obj = rel.id, rel
                  h.roles[e.subj] = np1; h.roles[other(e.subj)] = np2
                  h.verify = { rel = rel.id, from = h.roles.from, to = h.roles.to }
                  out[#out + 1] = h
                end
              elseif not e.prep and is_prep(C(S, vp.nxt), "by") then
                for _, np2 in ipairs(P.parse_np(S, vp.nxt + 1)) do
                  local h = base("yes_no:be_passive")
                  use_vp(h, vp); use(h, vp.nxt); use_np(h, np2)
                  h.rel, h.rel_obj = rel.id, rel
                  h.roles[other(e.subj)] = np1; h.roles[e.subj] = np2
                  h.verify = { rel = rel.id, from = h.roles.from, to = h.roles.to }
                  if vp.neg then h.polarity = "negative" end
                  out[#out + 1] = h
                end
              end
            end
          end
        end
      end
      if is_prep(C(S, pk), "in") then
        local lrel = S.lex:get_rel("located_in")
        for _, np2 in ipairs(P.parse_np(S, pk + 1)) do
          local h = base("yes_no:be_in")
          use(h, pk); use_np(h, np2)
          h.rel, h.rel_obj = "located_in", lrel
          h.roles.from, h.roles.to = np1, np2
          h.verify = { rel = "located_in", from = np1, to = np2 }
          out[#out + 1] = h
        end
      end
    elseif akind == "do" or akind == "have" or akind == "modal" then
      for _, vp in ipairs(P.parse_vp(S, np1.nxt, { aux_hint = (akind == "do" and "do") or (akind == "have" and "have") or "modal" })) do
        for _, e in ipairs(vp.analysis.entries) do
          local rel = S.lex:get_rel(e.rel)
          if rel then
            local pk = vp.nxt
            local has_prep = e.prep and is_prep(C(S, pk), e.prep)
            local ok_start = has_prep and pk + 1 or (not e.prep and pk)
            if ok_start then
              for _, np2 in ipairs(P.parse_np(S, ok_start)) do
                local h = base("yes_no:aux_verb")
                use_vp(h, vp); use_np(h, np2)
                if has_prep then use(h, pk) end
                h.rel, h.rel_obj = rel.id, rel
                h.roles[e.subj] = np1; h.roles[other(e.subj)] = np2
                h.verify = { rel = rel.id, from = h.roles.from, to = h.roles.to }
                if vp.neg then h.polarity = "negative" end
                addf(h, "direction_explicit", 0.3, "role direction fixed by active verb")
                mark_unresolved_pron(h, np2)
                out[#out + 1] = h
              end
            end
          end
        end
      end
    end
  end
end

return F

end

package.preload["asi.nlu.frames2"] = function(...)
-- asi.nlu.frames2: request-side constructions (imperatives, search with filters, comparison, definition/description,
-- statements, focus, instructions/corrections).  Extends asi.nlu.frames.
local U = require("asi.nlu.util")
local P = require("asi.nlu.parse")
local F = require("asi.nlu.frames")

local cat = P.cat
local newh, addf, use_np = F.newh, F.addf, F.use_np
local function C(S, k) return S.chunks[k] end
local function barrier(c) return c ~= nil and c.pre ~= nil end
local function other(role) return role == "to" and "from" or "to" end
local function use(h, a, b) for i = a, b or a do h.used[i] = true end end

local WRAPPER_NOUNS = U.set({ "concept", "term", "notion", "idea", "meaning", "definition", "word", "phrase", "topic" })

-- "the concept of X" / "the meaning of X" -> X
local function unwrap(np)
  if np and np.of_arg and (np.head_kind == "typenoun" or np.head_kind == "concept" or np.head_kind == "unknown")
    and np.head and WRAPPER_NOUNS[np.head.form] then
    return np.of_arg, true
  end
  return np, false
end

local function skip_fillers(S, k)
  -- "me", "for", "about", "up", "out", "the following" style fillers after a request verb
  local used = {}
  while true do
    local c = C(S, k)
    if c and c.single and not c.masked and (c.unit.form == "me" or c.unit.form == "for" or c.unit.form == "about" or c.unit.form == "up"
      or c.unit.form == "out" or c.unit.form == "regarding" or c.unit.form == "on" and false) then
      used[#used + 1] = k; k = k + 1
    else break end
  end
  return k, used
end

---------------------------------------------------------------- filters on a target set  (shared with constraints.lua)
-- parse modifiers that follow a target NP:  [that|which|who] [adv] V NP  |  V-ing NP  |  V-ed <temporal|by NP>  |  in/based in PLACE  |  with N X
-- returns list of filters and the next chunk index.  Every filter records exactly the chunks it consumed.
function F.parse_filters(S, k, target_np, limit_idx)
  local filters = {}
  local lex = S.lex
  limit_idx = limit_idx or S.last
  local function last_unmasked(i) return i <= limit_idx and C(S, i) and not C(S, i).masked end
  local guard = 0
  while last_unmasked(k) and guard < 8 do
    guard = guard + 1
    local c = C(S, k)
    local start = k
    local progressed = false
    -- optional list joiner
    if c.single and (cat(c, "conj") and (c.unit.form == "and" or c.unit.form == "or") ) and not (c.pre and c.pre:find("sent")) then
      k = k + 1; c = C(S, k)
      if not c or c.masked then break end
    end
    -- locative relative clause:  "the country where Mount Fuji is"  ->  located_in(from=Mount Fuji, to=<target>)
    if c.single and c.unit.form == "where" and lex:get_rel("located_in") then
      local done
      for _, np in ipairs(P.parse_np(S, k + 1)) do
        local bc = C(S, np.nxt)
        if bc and bc.single and not bc.masked and (cat(bc, "aux_be") or cat(bc, "clitic_s")) then
          -- "where O is headquartered" (stative verb with a preposition): the place plays the OTHER role of that relation
          for _, vp in ipairs(P.parse_vp(S, np.nxt, { aux_hint = nil })) do
            if vp.voice == "passive" then
              for _, e in ipairs(vp.analysis.entries) do
                local r = lex:get_rel(e.rel)
                if r and e.prep and not r.open then
                  filters[#filters + 1] = { kind = "relation", rel = r.id, target_role = other(e.subj), value = np, chunks = { k, vp.c2 },
                    span = { first = k, last = vp.c2 }, locative_clause = true }
                  k = vp.nxt
                  done = true
                  break
                end
              end
            end
            if done then break end
          end
          if done then break end
          filters[#filters + 1] = { kind = "relation", rel = "located_in", target_role = "to", value = np, chunks = { k, np.nxt },
            span = { first = k, last = np.nxt }, locative_clause = true }
          k = np.nxt + 1
          done = true
          break
        end
        -- "where O has its head office": a support verb + a possessed location-valued noun
        for _, vp in ipairs(P.parse_vp(S, np.nxt, {})) do
          for _, onp in ipairs(P.parse_np(S, vp.nxt)) do
            local dc = C(S, onp.c1)
            if onp.head_kind == "relnoun" and not onp.of_arg and dc and dc.single and (cat(dc, "poss_det") or cat(dc, "det")) and onp.c1 < onp.nxt - 1 then
              for _, o in ipairs(F.relnp_options(S, onp)) do
                local supported = (vp.lemma == "have" and o.rel.support_have) or false
                for _, e in ipairs(vp.analysis.entries or {}) do if e.support and e.rel == o.rel.id then supported = true end end
                if supported and o.rel.locus and o.ask_role == "to" then
                  filters[#filters + 1] = { kind = "relation", rel = o.rel.id, target_role = "to", value = np, chunks = { k, onp.nxt - 1 },
                    span = { first = k, last = onp.nxt - 1 }, locative_clause = true }
                  k = onp.nxt
                  done = true
                  break
                end
              end
            end
            if done then break end
          end
          if done then break end
        end
        if done then break end
      end
      if done then goto continue_filters end
    end
    -- relativiser
    local rel_marker
    if c.single and (c.unit.form == "that" or c.unit.form == "which" or c.unit.form == "who") then rel_marker = true; k = k + 1 end
    -- copular relative clause: "the city that IS / FUNCTIONS AS the capital of K"
    if rel_marker and C(S, k) and C(S, k).single and cat(C(S, k), "aux_be") and not C(S, k).masked then
      local done
      for _, np in ipairs(P.parse_np(S, k + 1)) do
        if np.head_kind == "relnoun" then
          for _, o in ipairs(F.relnp_options(S, np)) do
            if o.arg and o.rel and not o.rel.open then
              filters[#filters + 1] = { kind = "relation", rel = o.rel.id, target_role = o.ask_role, value = o.arg, chunks = { start, np.c2 },
                span = { first = start, last = np.nxt - 1 }, copular_relative = true }
              k = np.nxt
              done = true
              break
            end
          end
        end
        if done then break end
      end
      if done then goto continue_filters end
    end
    -- object relative clause, with or without a relativiser:  "the companies (that) Google acquired",  "the startups Sequoia Capital has invested in"
    -- the subject is a proper name; the verb is followed only by (a stranded preposition and) the end of the clause, so the target set fills the gap
    if not (rel_marker and C(S, k) and C(S, k).single and cat(C(S, k), "aux_be")) then
      local done
      for _, snp in ipairs(P.parse_np(S, k, { no_of = true })) do
        if snp.head_kind == "entity" or (snp.head_kind == "unknown" and snp.head and snp.head.cap) then
          for _, vp in ipairs(P.parse_vp(S, snp.nxt, {})) do
            if vp.voice == "active" then
              for _, e in ipairs(vp.analysis.entries) do
                local rel = lex:get_rel(e.rel)
                if rel and not e.support and not e.as_only and not rel.open then
                  local nxt, ok = vp.nxt, true
                  if e.prep then
                    local pc2 = C(S, nxt)
                    if pc2 and pc2.single and not pc2.masked and pc2.unit.form == e.prep then nxt = nxt + 1 else ok = false end
                  end
                  local fc = C(S, nxt)
                  local gap_end = (nxt > limit_idx) or (fc ~= nil and (fc.pre ~= nil or fc.temporal ~= nil or (fc.single and (cat(fc, "conj") or cat(fc, "prep")))))
                  if ok and gap_end then
                    filters[#filters + 1] = { kind = "relation", rel = rel.id, target_role = other(e.subj), value = snp, chunks = { start, nxt - 1 },
                      span = { first = start, last = nxt - 1 }, adv = vp.tscope, polarity = vp.neg and "negative" or "positive", object_relative = true }
                    k = nxt; done = true; progressed = true
                    break
                  end
                end
              end
            end
            if done then break end
          end
        end
        if done then break end
      end
      if done then goto continue_filters end
    end
    -- verb phrase (participial or relative)
    -- with a relativiser ("that currently offer ...") any finite form is fine; without one only participles can modify a noun
    local tmp = rel_marker and P.parse_vp(S, k, {}) or P.parse_vp(S, k, { participle_ok = true })
    for _, vp in ipairs(tmp) do
      for _, e in ipairs(vp.analysis.entries) do
        local rel = lex:get_rel(e.rel)
        if rel and not e.as_only then
          local f
          local nxt = vp.nxt
          local tc = C(S, nxt)
          -- (a) passive participle + temporal expression:  "established after 2020"  -> rel.when
          if (vp.vform == "pp" or vp.vform == "past") and tc and tc.temporal and tc.temporal.kind ~= "marker" and rel.when and lex:get_rel(rel.when) and not tc.masked then
            local trel = lex:get_rel(rel.when)
            f = { kind = "temporal_relation", rel = trel.id, via = rel.id, role = "from", expr = tc.temporal, chunks = { start, vp.c2, nxt }, adv = vp.tscope }
            nxt = nxt + 1
          elseif e.prep then
            if C(S, nxt) and C(S, nxt).single and cat(C(S, nxt), "prep") and C(S, nxt).unit.form == e.prep then
              for _, np in ipairs(P.parse_np(S, nxt + 1, { no_of = false })) do
                local t_role = e.subj
                f = { kind = "relation", rel = rel.id, target_role = t_role, value = np, chunks = { start, vp.c2, nxt }, adv = vp.tscope, polarity = vp.neg and "negative" or "positive" }
                nxt = np.nxt
                break
              end
            end
          else
            for _, np in ipairs(P.parse_np(S, nxt)) do
              local pass = vp.voice == "passive" or vp.vform == "pp"
              local t_role = pass and other(e.subj) or e.subj
              if pass and not (C(S, np.c1) and false) then
                -- passive with by-agent:  "founded by X"
              end
              f = { kind = "relation", rel = rel.id, target_role = t_role, value = np, chunks = { start, vp.c2 }, adv = vp.tscope, polarity = vp.neg and "negative" or "positive" }
              nxt = np.nxt
              break
            end
            if not f and (vp.vform == "pp" or vp.voice == "passive") and C(S, nxt) and C(S, nxt).single and C(S, nxt).unit.form == "by" then
              for _, np in ipairs(P.parse_np(S, nxt + 1)) do
                f = { kind = "relation", rel = rel.id, target_role = other(e.subj), value = np, chunks = { start, vp.c2, nxt }, adv = vp.tscope }
                nxt = np.nxt
                break
              end
            end
          end
          if f then
            f.span = { first = start, last = nxt - 1 }
            filters[#filters + 1] = f
            k = nxt
            progressed = true
            break
          end
        end
      end
      if progressed then break end
    end
    if not progressed then
      -- PP filters: geography ("in Germany"), attribute quantities ("with more than 100 employees")
      local pc = C(S, start)
      if rel_marker then pc = nil end
      if pc and pc.single and cat(pc, "prep") and not pc.masked then
        local f = pc.unit.form
        if f == "in" or f == "near" or f == "around" or f == "within" or f == "across" then
          for _, np in ipairs(P.parse_np(S, start + 1, { no_of = false })) do
            if np.head_kind == "entity" then
              filters[#filters + 1] = { kind = "geo", prep = f, value = np, chunks = { start }, span = { first = start, last = np.nxt - 1 } }
              k = np.nxt; progressed = true
              break
            end
          end
        elseif f == "with" then
          local nk = start + 1
          -- quantity comparator:  "with more than 100 employees"
          local cmp_n = lex:cue_at("quantifier_cmp", S.units, C(S, nk) and C(S, nk).u1 or 0)
          for _, np in ipairs(P.parse_np(S, nk, { no_of = false })) do
            f = { kind = "has", value = np, chunks = { start }, span = { first = start, last = np.nxt - 1 } }
            filters[#filters + 1] = f
            k = np.nxt; progressed = true
            break
          end
        end
      end
    end
    if not progressed then k = start; break end
    ::continue_filters::
  end
  return filters, k
end

---------------------------------------------------------------- multi-hop chains
-- A known argument that is itself a relational NP ("the founder of Example Labs") or a type noun modified by a relative clause
-- ("the country where Mount Fuji is", "the company that acquired Beta Systems") is expanded into ordered lookup steps with
-- typed intermediate variables:  steps[1] runs first; the hypothesis' own relation consumes the last variable.
local function lex_rel(S, id) return S.lex:get_rel(id) end

local function relativizer(c)
  return c and c.single and not c.masked and (c.unit.form == "that" or c.unit.form == "which" or c.unit.form == "who" or c.unit.form == "where")
end

function F.expand_chain(S, h)
  if h.chain_done or not h.known_role or not h.rel then return end
  h.chain_done = true
  local top_np = h.roles[h.known_role]
  if not top_np or top_np.head_kind == "pronoun" then return end
  local steps = {}
  local used_extra = {}
  local last_chunk = top_np.c2

  local function build(np, depth)
    if depth > 3 or not np then return nil end
    if np.head_kind == "relnoun" then
      for _, o in ipairs(F.relnp_options(S, np)) do
        if o.arg then
          local inner = build(o.arg, depth + 1)
          steps[#steps + 1] = { rel = o.rel.id, rel_obj = o.rel, known_role = o.known_role, known = inner and inner.var_np or o.arg, ask_role = o.ask_role,
            result_type = o.rel[o.ask_role], source_np = np }
          return { var_np = { head_kind = "var", var = "?" .. #steps, type = o.rel[o.ask_role], step = #steps, u1 = np.u1, u2 = np.u2, c1 = np.c1, c2 = np.c2,
            mods = {}, score = 0, notes = {} } }
        end
      end
    elseif (np.head_kind == "typenoun" or np.head_kind == "unknown") and relativizer(C(S, np.nxt)) then
      local filters, k = F.parse_filters(S, np.nxt, np)
      local made
      for _, f in ipairs(filters) do
        if f.kind == "relation" then
          local rel = lex_rel(S, f.rel)
          if rel then
            local ntype = np.senses and np.senses[1] and np.senses[1].type
            steps[#steps + 1] = { rel = rel.id, rel_obj = rel, known_role = other(f.target_role), known = f.value, ask_role = f.target_role,
              result_type = ntype or rel[f.target_role], source_np = np, via_clause = true }
            for i = f.span.first, f.span.last do used_extra[i] = true end
            last_chunk = math.max(last_chunk, f.span.last)
            made = #steps
          end
        end
      end
      if made then
        local ntype = np.senses and np.senses[1] and np.senses[1].type
        return { var_np = { head_kind = "var", var = "?" .. made, type = ntype or steps[made].result_type, step = made, u1 = np.u1, u2 = np.u2, c1 = np.c1,
          c2 = np.c2, mods = {}, score = 0, notes = {} } }
      end
    end
    return nil
  end

  local res = build(top_np, 0)
  if res and #steps > 0 then
    local var = res.var_np
    var.u1, var.c1 = top_np.u1, top_np.c1
    var.c2 = math.max(last_chunk, top_np.c2)
    var.u2 = S.chunks[var.c2].u2
    var.steps = steps
    h.chain = steps
    h.roles[h.known_role] = var
    for i = top_np.c1, var.c2 do h.used[i] = true end
    for i in pairs(used_extra) do h.used[i] = true end
    h.factors[#h.factors + 1] = { name = "multi_hop", v = 0.3, note = #steps .. "-step chain before " .. h.rel }
    -- "the location of X's headquarters": a location-valued noun is answered by its own value; a second 'located_in' hop is redundant unless the
    -- question asks for a narrower kind of place ("in which COUNTRY is ...")
    local top = steps[#steps]
    local wt = h.wh and h.wh.type
    if h.rel == "located_in" and top and top.rel_obj.locus and top.ask_role == "to" and (not wt or wt == "place" or wt == "location") then
      h.factors[#h.factors + 1] = { name = "redundant_location_hop", v = -0.9, note = "the noun's own relation already gives a location; a second located_in hop is redundant" }
    end
  end
end

---------------------------------------------------------------- request frames
local ACT_INFORM_DEFINE = U.set({ "define" })

local function finish_target_h(S, h, np, k_after, filters)
  h.target = np
  h.filters = filters
  for _, f in ipairs(filters) do
    for i = f.span.first, f.span.last do h.used[i] = true end
  end
end

-- build hypotheses from a request object NP (shared by imperatives, polite wrappers and "I want ...")
local function from_object_np(S, out, np, verb_info, speech_act, prefix_used, fprefix)
  local act = verb_info and verb_info.act
  local lemma = verb_info and verb_info.lemma
  local function base(frame)
    if fprefix then frame = frame:gsub("^request", fprefix) end
    local h = newh(S, frame, speech_act or "request")
    use_np(h, np)
    for _, u in ipairs(prefix_used or {}) do h.used[u] = true end
    if verb_info and verb_info.chunk_idx then h.used[verb_info.chunk_idx] = true end
    h.request_verb = lemma
    F.mark_pron(h, np)
    return h
  end
  local subj, unwrapped = unwrap(np)
  if unwrapped then np = subj end
  if np.head_kind == "relnoun" then
    for _, o in ipairs(F.relnp_options(S, np)) do
      local h = base("request:relnp")
      if o.arg then
        h.rel, h.rel_obj = o.rel.id, o.rel
        h.roles[o.known_role] = o.arg
        h.known_role, h.ask = o.known_role, o.ask_role
        h.ask_type = o.rel[o.ask_role]
        h.op, h.intent, h.requires_evidence = "lookup", "factual_lookup", true
        addf(h, "relnp_arg", 0.7, "relational noun with explicit argument")
        F.option_factors(h, o)
        if np.temporal_scope then h.temporal_scope = np.temporal_scope end
        if np.superlative then h.ordering = { superlative = np.superlative } end
        F.mark_pron(h, o.arg)
      else
        h.op, h.intent, h.rel, h.rel_obj, h.concept = "define", "definition", o.rel.id, o.rel, np
        addf(h, "relnoun_no_arg", -1.0, "relational noun without its argument")
      end
      out[#out + 1] = h
    end
  elseif np.head_kind == "entity" then
    local h = base("request:entity")
    h.op, h.intent, h.requires_evidence = "describe", "entity_description", true
    h.subject = np; h.roles.subject = np
    if act == "inform" and lemma == "define" then h.op, h.intent = "define", "definition"; h.concept = np end
    out[#out + 1] = h
  elseif np.head_kind == "typenoun" or np.head_kind == "concept" or np.head_kind == "unknown" then
    -- "Name the person who set up O." / "Give me the city where O keeps its head office.": a definite SINGULAR description with one relative clause asks
    -- for the one referent -- a lookup of the clause's relation, not a search for a set
    if np.head_kind == "typenoun" and not np.plural and np.det == "the" and (act == "retrieve" or act == "inform") then
      local filters, kf = F.parse_filters(S, np.nxt, np)
      local f = filters[1]
      if #filters == 1 and f.kind == "relation" and f.value and kf > S.last then
        local drel = S.lex:get_rel(f.rel)
        if drel and not drel.open then
          local h = base("request:description")
          h.rel, h.rel_obj = drel.id, drel
          h.roles[other(f.target_role)] = f.value
          h.known_role, h.ask = other(f.target_role), f.target_role
          h.ask_type = drel[f.target_role]
          h.op, h.intent, h.requires_evidence = "lookup", "factual_lookup", true
          h.wh_type = np.senses and np.senses[1] and np.senses[1].type or nil
          for i = f.span.first, f.span.last do h.used[i] = true end
          addf(h, "description_lookup", 0.9, "definite singular description with one relative clause names a single referent")
          F.mark_pron(h, f.value)
          out[#out + 1] = h
        end
      end
    end
    -- "give me a SUMMARY of the figures", "send me an overview of the results": a task noun requested through a retrieval verb is a task
    local hf = np.head and np.head.single and np.head.unit and np.head.unit.form
    if hf and (S.lex:cats(hf) or {}).tasknoun and (act == "retrieve" or act == "inform" or act == "task") then
      local h = base("request:task_nominal")
      h.op, h.intent = "task", "task"
      h.task_verb, h.object, h.requires_context = hf, np.of_arg or np, true
      addf(h, "task_noun", 0.9, "'" .. hf .. "' names a task (summary, analysis, overview ...) requested through the verb '" .. tostring(lemma) .. "'")
      out[#out + 1] = h
    end
    -- plural typenoun => search for a set;  singular typenoun after find/list => search too;  concept/unknown => define/describe
    local plural = np.plural
    -- "Find/Show/List <noun>" requests items of that kind, also when the noun is not in the lexicon
    if ((np.head_kind == "typenoun") and (plural or act == "retrieve")) or (np.head_kind == "unknown" and act == "retrieve") then
      local h = base("request:search")
      if np.head_kind == "unknown" then addf(h, "unknown_target_type", -0.1, "search target type is not in the lexicon") end
      -- a target that swallows a named entity plus a lowercase word ("the companies Google acquired") has swallowed a clause, not named a set
      if np.head_kind == "unknown" and np.head and np.head.single and not np.head.cap then
        for _, md in ipairs(np.mods or {}) do
          if md.kind == "entity_mod" then addf(h, "target_swallows_clause", -0.8, "the target phrase contains a named entity followed by a lowercase word: a clause, not a noun phrase"); break end
        end
      end
      h.op, h.intent, h.requires_evidence = "search", "search", true
      local filters, kf = F.parse_filters(S, np.nxt, np)
      finish_target_h(S, h, np, kf, filters)
      addf(h, "search_target", 0.5, "typed target set")
      if #filters > 0 then addf(h, "filters_parsed", 0.15 * #filters, #filters .. " filter(s) from relative/participial clauses") end
      out[#out + 1] = h
    end
    local h = base("request:concept")
    if act == "retrieve" and (np.head_kind == "unknown" or (np.head_kind == "typenoun" and plural)) then addf(h, "retrieval_verb_not_definition", -0.6, "a retrieval verb asks for items, not a definition") end
    if act == "inform" and lemma == "explain" then h.op, h.intent = "explain", "explanation"
    elseif act == "inform" and lemma == "describe" then h.op, h.intent = "describe", "entity_description"
    else h.op, h.intent = "define", "definition" end
    h.concept = np
    h.requires_evidence = true
    if np.head_kind == "unknown" then addf(h, "unknown_term", -0.15, "term not in the lexicon") end
    if np.of_arg then addf(h, "concept_of_arg", -0.4, "a non-relational concept noun with an 'of' argument is a weaker structure than a relational noun") end
    out[#out + 1] = h
  elseif np.head_kind == "pronoun" then
    local h = base("request:pronoun")
    h.op, h.intent = "describe", "entity_description"
    h.subject = np
    out[#out + 1] = h
  elseif np.head_kind == "quote" or np.head_kind == "literal" then
    local h = base("request:literal")
    h.op, h.intent, h.requires_evidence = "describe", "entity_description", true
    h.subject = np
    out[#out + 1] = h
  end
end

function F.request(S, out)
  local k = S.first
  local c = C(S, k)
  if not c or c.masked then return end
  local w = S.wrapper or { kinds = {} }
  local wrapped = #w.kinds > 0
  -- 1. imperative verb at the start of the core
  local vana = (c.single or c.kind == "mwe") and P.verb_analyses(S, c) or {}
  for _, a in ipairs(vana) do
    if a.form == "base" and (a.act or #a.entries > 0) and not cat(c, "wh") then
      local act = a.act or "task"
      local nk, fill_used = skip_fillers(S, k + 1)
      local vinfo = { act = act, lemma = a.lemma, chunk_idx = k }
      if act == "inform" or act == "retrieve" or act == "task" or act == "focus" then
        -- explain why/how ...
        local wh = P.parse_wh(S, nk)
        local sub_h
        for _, wq in ipairs(wh) do
          if wq.adverbial and (wq.wh == "why" or wq.wh == "how") and a.lemma == "explain" then
            local h = newh(S, "request:explain_clause", "request", wq.wh == "why" and "causal_explanation" or "explanation", "explain")
            h.wh = wq; h.request_verb = a.lemma; h.requires_evidence = true
            use(h, k); for _, u in ipairs(fill_used) do h.used[u] = true end
            for i = wq.c1, wq.c2 do h.used[i] = true end
            local cl = F.parse_clause(S, wq.nxt)
            if cl then h.clause = cl; for i = wq.nxt, cl.last do h.used[i] = true end; addf(h, "clause_parsed", 0.4, "explanatory clause identified")
            else addf(h, "clause_missing", -0.6, "no clause to explain") end
            out[#out + 1] = h
          end
        end
        for _, np in ipairs(P.parse_np(S, nk)) do
          if act == "task" or act == "focus" then
            local h = newh(S, "request:task", "request", "task", "task")
            use(h, k); use_np(h, np); for _, u in ipairs(fill_used) do h.used[u] = true end
            h.task_verb = a.lemma; h.object = np; h.requires_context = true
            F.mark_pron(h, np)
            out[#out + 1] = h
          else
            from_object_np(S, out, np, vinfo, "request", fill_used)
          end
        end
      elseif act == "compare" then
        for _, np1 in ipairs(P.parse_np(S, nk)) do
          local items, endk = { np1 }, np1.nxt
          while true do
            local jc = C(S, endk)
            if jc and jc.single and (jc.unit.form == "and" or jc.unit.form == "with" or jc.unit.form == "to" or jc.unit.form == "versus" or jc.unit.form == "vs"
              or (jc.pre and jc.pre:find("comma") and false)) then
              local nps = P.parse_np(S, endk + 1)
              if nps[1] then items[#items + 1] = nps[1]; endk = nps[1].nxt else break end
            else break end
          end
          if #items >= 2 then
            local h = newh(S, "request:compare", "request", "comparison", "compare")
            use(h, k); for _, u in ipairs(fill_used) do h.used[u] = true end
            h.items = items
            for _, it in ipairs(items) do use_np(h, it) end
            for i = np1.nxt, endk - 1 do h.used[i] = true end
            h.requires_evidence = true
            addf(h, "comparison_items", 0.5, #items .. " items to compare")
            out[#out + 1] = h
          end
        end
      end
    end
  end
  -- 2. wrapper-led requests ("I want the capital of France", "Could you tell me about Mercury")
  if wrapped then
    local nk, fill_used = skip_fillers(S, k)
    local c0 = C(S, nk)
    local prefix = fill_used
    if c0 and c0.single and not c0.masked and (c0.unit.form == "about" or c0.unit.form == "regarding") then prefix = { nk }; nk = nk + 1 end
    for _, np in ipairs(P.parse_np(S, nk)) do
      from_object_np(S, out, np, { act = "inform", lemma = w.verb }, "request", prefix)
    end
  end
end

---------------------------------------------------------------- bare NP (fragment)  "capital of France"  "france capital?"  "Mercury"
function F.np_only(S, out)
  if S.wrapper and #S.wrapper.kinds > 0 then return end -- wrapper-led requests are handled by F.request
  for _, np in ipairs(P.parse_np(S, S.first)) do
    from_object_np(S, out, np, nil, "fragment", {}, "fragment")
    -- "Chile - capital" / "Egypt, capital?" : the argument comes first, the relational noun after a separator
    if np.head_kind == "entity" and not np.of_arg and not np.possessor then
      local nx = C(S, np.nxt)
      if nx and nx.pre and (nx.pre:find("comma") or nx.pre:find("dash") or nx.pre:find("colon")) and not nx.masked then
        for _, rn in ipairs(P.parse_np(S, np.nxt)) do
          if rn.head_kind == "relnoun" and not rn.of_arg and not rn.possessor then
            local cp = U.shallow(rn)
            cp.of_arg, cp.comma_arg = np, true
            cp.c1, cp.u1 = np.c1, np.u1
            from_object_np(S, out, cp, nil, "fragment", {}, "fragment")
            break
          end
        end
      end
    end
    -- "capital, France": a relational noun whose argument follows across a comma
    if np.head_kind == "relnoun" and not np.of_arg and not np.possessor then
      local nx = C(S, np.nxt)
      if nx and nx.pre and nx.pre:find("comma") and not nx.masked then
        for _, arg in ipairs(P.parse_np(S, np.nxt)) do
          if arg.head_kind == "entity" then
            local cp = U.shallow(np)
            cp.of_arg, cp.comma_arg, cp.nxt, cp.u2, cp.c2 = arg, true, arg.nxt, arg.u2, arg.c2
            from_object_np(S, out, cp, nil, "fragment", {}, "fragment")
            break
          end
        end
      end
    end
  end
end

-- a sentence that is nothing but an exclusion / preference / restriction clause ("Exclude universities.", "Don't include reposts.")
function F.segment_only(S, out)
  local segs = S.segs or {}
  if #segs == 0 then return end
  for k = S.first, S.last do
    local c = C(S, k)
    if not c.masked and not P.is_function_chunk(S, c) then return end
  end
  local sg = segs[1]
  local h = newh(S, "segment_only:" .. sg.kind, "instruction", "instruction_update", "instruct")
  h.instruction = { verb = sg.cue, act = (sg.kind == "exclusion") and "exclude" or "constraint", kind = sg.kind }
  h.polarity = (sg.kind == "exclusion") and "negative" or "positive"
  addf(h, "segment_only", 0.9, "the whole sentence is a " .. sg.kind .. " clause")
  out[#out + 1] = h
end

---------------------------------------------------------------- comparison questions
-- "What changed between the first version and the revised version?"
function F.wh_change(S, out)
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if not wh.adverbial then
      for _, vp in ipairs(P.parse_vp(S, wh.nxt)) do
        if vp.lemma == "change" or vp.lemma == "differ" or vp.lemma == "vary" then
          local pk = vp.nxt
          local pc = C(S, pk)
          if pc and pc.single and (pc.unit.form == "between" or pc.unit.form == "from") then
            for _, np1 in ipairs(P.parse_np(S, pk + 1)) do
              local jc = C(S, np1.nxt)
              if jc and jc.single and (jc.unit.form == "and" or jc.unit.form == "to") then
                for _, np2 in ipairs(P.parse_np(S, np1.nxt + 1)) do
                  local h = newh(S, "wh_change:diff", "question", "comparison", "diff")
                  use(h, wh.c1, wh.c2); F.use_np(h, np1); F.use_np(h, np2)
                  for i = vp.c1, np2.c1 - 1 do h.used[i] = true end
                  h.items = { np1, np2 }
                  h.requires_evidence = true
                  F.mark_pron(h, np1); F.mark_pron(h, np2)
                  addf(h, "diff_between_two", 0.6, "what-changed between two items")
                  out[#out + 1] = h
                end
              end
            end
          end
        end
      end
    end
  end
end

-- "Which one is older?"  "Which is larger, A or B?"  "Is A older than B?"
function F.compare_q(S, out)
  local lex = S.lex
  local function comp_adj(c)
    if not (c and c.single) then return nil end
    local f = c.unit.form
    for _, r in ipairs(lex:readings(f)) do
      if r.pos == "adj" and (r.feat == "comp" or r.feat == "sup") then return r end
    end
    return nil
  end
  local k0 = S.first
  for _, wh in ipairs(P.parse_wh(S, k0)) do
    if not wh.adverbial then
      local bk = wh.nxt
      local be = C(S, bk)
      if be and be.single and (cat(be, "aux_be") or cat(be, "clitic_s")) then
        local ac = C(S, bk + 1)
        local r = comp_adj(ac)
        if r then
          local h = newh(S, "compare_q:wh_adj", "question", "comparison", "rank_attribute")
          use(h, wh.c1, wh.c2); use(h, bk, bk + 1)
          h.wh = wh; h.dimension = r.dim; h.degree = r.feat; h.adj = r.lemma
          h.requires_evidence = true
          addf(h, "comparative_adjective", 0.5, r.lemma .. " (" .. r.feat .. ") on dimension " .. tostring(r.dim))
          -- candidates "A or B"
          local nk = bk + 2
          local items = {}
          local c3 = C(S, nk)
          if c3 and c3.pre and c3.pre:find("comma") then nk = nk end
          for _, np in ipairs(P.parse_np(S, nk)) do
            items[#items + 1] = np; use_np(h, np)
            local oc = C(S, np.nxt)
            if oc and oc.single and oc.unit.form == "or" then
              local nps = P.parse_np(S, np.nxt + 1)
              if nps[1] then items[#items + 1] = nps[1]; use(h, np.nxt); use_np(h, nps[1]) end
            end
            break
          end
          if #items > 0 then h.items = items end
          out[#out + 1] = h
        end
      end
    end
  end
  -- "Is A older than B?"
  local c0 = C(S, k0)
  if c0 and c0.single and cat(c0, "aux_be") then
    for _, np1 in ipairs(P.parse_np(S, k0 + 1)) do
      local ac = C(S, np1.nxt)
      local r = comp_adj(ac)
      local tc = C(S, np1.nxt + 1)
      if r and tc and tc.single and tc.unit.form == "than" then
        for _, np2 in ipairs(P.parse_np(S, np1.nxt + 2)) do
          local h = newh(S, "compare_q:yes_no", "question", "verification", "verify_comparison")
          use(h, k0); use_np(h, np1); use(h, np1.nxt, np1.nxt + 1); use_np(h, np2)
          h.items = { np1, np2 }; h.dimension = r.dim; h.degree = r.feat; h.adj = r.lemma
          h.requires_evidence = true
          addf(h, "comparative_adjective", 0.5, r.lemma .. " on " .. tostring(r.dim))
          out[#out + 1] = h
        end
      end
    end
  end
end

---------------------------------------------------------------- "What does X mean?" / "What does X stand for?"
function F.what_means(S, out)
  local lex = S.lex
  for _, wh in ipairs(P.parse_wh(S, S.first)) do
    if wh.wh == "what" and not wh.np and not wh.adverbial then
      local ac = C(S, wh.nxt)
      local aux_ok = ac and ac.single and cat(ac, "aux_do") and not ac.masked
      if aux_ok or S.embedded then
        for _, np in ipairs(P.parse_np(S, aux_ok and wh.nxt + 1 or wh.nxt)) do
          local vc = C(S, np.nxt)
          local n = vc and lex:cue_at("definition_verb", S.units, vc.u1)
          if n then
            local h = newh(S, "what_means:definition", "question", "definition", "define")
            use(h, wh.c1, wh.c2); if aux_ok then use(h, wh.nxt) end; use_np(h, np)
            local consumed, k = 0, np.nxt
            while C(S, k) and consumed < n do consumed = consumed + (C(S, k).u2 - C(S, k).u1 + 1); h.used[k] = true; k = k + 1 end
            h.concept = np
            h.requires_evidence = true
            addf(h, "definition_question", 0.9, "'what does X mean' asks for the meaning of X")
            F.mark_pron(h, np)
            out[#out + 1] = h
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- recall questions about the conversation itself
-- "What did we decide about the inventory service?"  "Why did we pick that for billing?"  "Remind me what I said about X."
local RECALL_PREP = U.set({ "about", "on", "regarding", "for", "with", "to", "over", "around", "concerning" })
function F.recall(S, out)
  local lex = S.lex
  local c0 = C(S, S.first)
  if not c0 then return end
  local k = S.first
  local intro = lex:cue_at("recall_intro", S.units, c0.u1)
  local intro_used = {}
  if intro then
    local consumed = 0
    while C(S, k) and consumed < intro do consumed = consumed + (C(S, k).u2 - C(S, k).u1 + 1); intro_used[#intro_used + 1] = k; k = k + 1 end
  end
  for _, wh in ipairs(P.parse_wh(S, k)) do
    local nk = wh.nxt
    local aux = C(S, nk)
    local has_aux = aux and aux.single and (cat(aux, "aux_do") or cat(aux, "aux_have")) and not aux.masked
    if has_aux then nk = nk + 1 end
    local sc = C(S, nk)
    local pf = sc and sc.single and sc.unit.form
    if pf == "we" or pf == "i" or pf == "you" then
      for _, vp in ipairs(P.parse_vp(S, nk + 1, { aux_hint = has_aux and "do" or nil })) do
        local v = lex.verbs[vp.lemma]
        -- the construction itself (wh + do-support + first/second person subject) marks a question about the conversation; the verb only has to
        -- be one that people use about what was said, chosen, proposed or planned
        if v and (v.act == "discourse" or v.act == "inform" or v.act == "focus" or v.act == "constraint" or v.act == "task") then
          local topic, object
          local ek = vp.nxt
          local ec = C(S, ek)
          if ec and ec.single and RECALL_PREP[ec.unit.form] and not ec.masked then
            for _, np in ipairs(P.parse_np(S, ek + 1)) do topic = np break end
            if topic then ek = topic.nxt end
          else
            for _, np in ipairs(P.parse_np(S, ek)) do object = np break end
            if object then
              ek = object.nxt
              local pc = C(S, ek)
              if pc and pc.single and RECALL_PREP[pc.unit.form] and not pc.masked then
                for _, np in ipairs(P.parse_np(S, ek + 1)) do topic = np break end
                if topic then ek = topic.nxt end
              end
            end
          end
          local h = newh(S, "recall:wh", "question", "conversation_recall", "recall")
          for _, u in ipairs(intro_used) do h.used[u] = true end
          use(h, wh.c1, wh.c2)
          if has_aux then use(h, wh.nxt) end
          use(h, nk); for i = vp.c1, vp.c2 do h.used[i] = true end
          if wh.np then F.use_np(h, wh.np) end
          if topic then use_np(h, topic) end
          if object then use_np(h, object) end
          h.recall = { verb = vp.lemma, wh = wh.wh, participant = pf, topic = topic or object, object = object }
          h.subject = topic or object
          h.requires_context = true
          if h.subject then F.mark_pron(h, h.subject) end
          addf(h, "recall_construction", 0.9, "wh-question about what the participants said or decided ('" .. pf .. " " .. vp.lemma .. "')")
          out[#out + 1] = h
        end
      end
    end
  end
end

---------------------------------------------------------------- basis clause
-- "..., considering the correction I made earlier"  /  "... given the revised budget"  /  "... taking X into account"
-- The NP is an input the request must respect; it is kept as a (possibly context-dependent) argument, never dropped.
function F.attach_basis(S, h)
  if h.basis ~= nil or not h.speech_act or h.speech_act == "statement" then return end
  local lex = S.lex
  for k = S.first, S.last do
    local c = C(S, k)
    if c and not c.masked and not h.used[k] and c.single and lex:cue_at("basis", S.units, c.u1) == 1 then
      local form = c.unit.form
      local nxt = C(S, k + 1)
      if not (form == "given" and nxt and nxt.single and nxt.unit.form == "that") then
        for _, np in ipairs(P.parse_np(S, k + 1)) do
          local c1, c2 = C(S, np.nxt), C(S, np.nxt + 1)
          local closed = c1 and c2 and c1.single and c2.single and c1.unit.form == "into" and c2.unit.form == "account"
          if form ~= "taking" or closed then
            h.basis = { cue = form, np = np }
            h.used[k] = true; use_np(h, np)
            if closed then h.used[np.nxt] = true; h.used[np.nxt + 1] = true end
            addf(h, "basis_clause", 0.3, "'" .. form .. "' introduces a basis the request must take into account")
            F.mark_pron(h, np)
            return
          end
        end
      end
    end
  end
end

---------------------------------------------------------------- statements, focus, instructions, corrections
local function resource_slot(S, np)
  if not np or not np.head then return nil end
  local canon = S.lex:resource(np.head.form)
  if not canon and np.head.single then canon = S.lex:resource(np.head.unit.form) end
  return canon
end

function F.instruction(S, out)
  local lex = S.lex
  local k = S.first
  local c = C(S, k)
  if not c or c.masked then return end
  -- correction / persistence cues at the start: "Actually, ...", "No, wait, ...", "From now on ..."
  local corr_n = lex:cue_at("correction", S.units, c.u1)
  local persist_n = lex:cue_at("persist", S.units, c.u1)
  local skipped = {}
  local correction, persist = false, false
  local function skip_units(n)
    local consumed = 0
    while C(S, k) and consumed < n do
      consumed = consumed + (C(S, k).u2 - C(S, k).u1 + 1)
      skipped[#skipped + 1] = k; k = k + 1
    end
  end
  if corr_n then
    correction = true; skip_units(corr_n)
    -- several markers may open one sentence: "Wait, no, I meant ...", "Correction: I meant ...", "Sorry, quick fix: ..."
    for _ = 1, 3 do
      local cn = C(S, k)
      local n2 = cn and not cn.masked and lex:cue_at("correction", S.units, cn.u1)
      if n2 then skip_units(n2)
      elseif cn and cn.single and not cn.masked and (cn.unit.form == "no" or cn.unit.form == "yes" or cn.unit.form == "okay" or cn.unit.form == "ok" or cn.unit.form == "well" or cn.unit.form == "so") then skipped[#skipped + 1] = k; k = k + 1
      else break end
    end
  end
  c = C(S, k)
  if c and lex:cue_at("persist", S.units, c.u1) then persist = true; skip_units(lex:cue_at("persist", S.units, c.u1)) end
  -- a correction / retraction clause anywhere before the instruction ("I got that wrong before, so please switch ...", "Disregard what I said, and go with ...")
  local preamble_to
  if not correction then
    for kk = S.first, S.last do
      local ck = C(S, kk)
      if ck and not ck.masked and (lex:cue_at("correction", S.units, ck.u1) or lex:cue_at("revoke", S.units, ck.u1)) then correction = true; preamble_to = kk break end
    end
  end
  c = C(S, k)
  -- temporal persist marker already lexed as a temporal chunk ("From now on", "Going forward")
  while c and c.temporal and (c.temporal.kind == "persist" or c.temporal.persist) do persist = true; skipped[#skipped + 1] = k; k = k + 1; c = C(S, k) end
  c = C(S, k)
  if not c or c.masked then return end
  -- a persistence marker anywhere in the sentence ("Use the 2025 dataset from now on.") makes the instruction standing
  for _, ch in ipairs(S.chunks) do
    if ch.temporal and (ch.temporal.kind == "persist" or ch.temporal.persist) then persist = true end
  end
  local REPLACE_VERBS = U.set({ "replace", "swap", "substitute", "change", "exchange" })
  local PARTICLE_EXCLUDERS = U.set({ "keep", "leave", "take", "filter", "screen", "weed", "cut", "strike", "rule", "block", "hide", "push", "sort" })
  -- one clause: [please|just|then|also]* VERB [to|with|over to] NP        (also "replace THAT with NP")
  local function try_clause(k0, prefix_used, allow_ing)
    local kk = k0
    local pre = {}
    while C(S, kk) and C(S, kk).single and not C(S, kk).masked and (cat(C(S, kk), "polite") or cat(C(S, kk), "adv") or (cat(C(S, kk), "conj") and kk > k0 - 1 and C(S, kk).unit.form ~= "if")) do
      pre[#pre + 1] = kk; kk = kk + 1
    end
    local cv = C(S, kk)
    if not (cv and cv.single and not cv.masked) then return end
    for _, a in ipairs(P.verb_analyses(S, cv)) do
      if (a.form == "base" or (allow_ing and a.form == "ing")) and (a.act == "constraint" or a.act == "exclude" or a.act == "include") then
        local nk = kk + 1
        local fill = {}
        local nc = C(S, nk)
        -- "switch to X" / "go with X" / "stick with X" / "switch over to X"
        if nc and nc.single and (nc.unit.form == "over") and C(S, nk + 1) and C(S, nk + 1).unit.form == "to" then fill[#fill + 1] = nk; nk = nk + 1; nc = C(S, nk) end
        if nc and nc.single and (nc.unit.form == "to" or nc.unit.form == "with" or nc.unit.form == "on" or nc.unit.form == "from") then fill[#fill + 1] = nk; nk = nk + 1 end
        local tries = {}
        if REPLACE_VERBS[a.lemma] then
          -- "replace THAT with the 2021 dataset": the replacement is the second noun phrase
          for _, np1 in ipairs(P.parse_np(S, nk)) do
            local wc = C(S, np1.nxt)
            if wc and wc.single and (wc.unit.form == "with" or wc.unit.form == "by") then
              for _, np2 in ipairs(P.parse_np(S, np1.nxt + 1)) do tries[#tries + 1] = { np = np2, extra = { np1 = np1, joiner = np1.nxt } } end
            end
          end
        end
        if #tries == 0 then for _, np in ipairs(P.parse_np(S, nk)) do tries[#tries + 1] = { np = np } end end
        for _, tr in ipairs(tries) do
          local np = tr.np
          if np.head_kind == "pronoun" then
            -- "I meant the 2024 dataset, so please switch to THAT": the pronoun stands for the resource named earlier in the same sentence
            for k2 = S.first, kk - 1 do
              local found
              for _, np2 in ipairs(P.parse_np(S, k2)) do
                if resource_slot(S, np2) and np2.nxt <= kk then found = np2 break end
              end
              if found then tr.antecedent_np = found; break end
            end
          end
          local act_eff = a.act
          local ptc = C(S, np.nxt)
          -- "swap the earlier dataset OUT": the object is what is being removed, not the new value
          if REPLACE_VERBS[a.lemma] and ptc and ptc.single and not ptc.masked and (ptc.unit.form == "out" or ptc.unit.form == "off") then goto next_try end
          -- "KEEP hospitals OUT of ...", "LEAVE X OUT", "FILTER X OUT": a particle after the object turns the verb into an exclusion
          if PARTICLE_EXCLUDERS[a.lemma] and ptc and ptc.single and not ptc.masked and (ptc.unit.form == "out" or ptc.unit.form == "off" or ptc.unit.form == "away") then
            act_eff = "exclude"
            tr.particle = np.nxt
          end
          local h = newh(S, "instruction:" .. act_eff, "instruction", "instruction_update", "instruct")
          if tr.particle then h.used[tr.particle] = true end
          for _, s_ in ipairs(skipped) do h.used[s_] = true end
          for _, s_ in ipairs(prefix_used or {}) do h.used[s_] = true end
          -- a retraction / correction clause that precedes the instruction is explained by the correction marker itself
          if preamble_to and kk > preamble_to then for i2 = S.first, kk - 1 do if i2 ~= kk then h.used[i2] = true end end end
          for _, s_ in ipairs(pre) do h.used[s_] = true end
          use(h, kk); for _, f in ipairs(fill) do h.used[f] = true end; use_np(h, np)
          if tr.extra then use_np(h, tr.extra.np1); h.used[tr.extra.joiner] = true end
          local vnp = tr.antecedent_np or np
          if tr.antecedent_np then use_np(h, vnp) end
          local slot = resource_slot(S, vnp)
          local value
          if vnp.temporal_mod then value = { year = vnp.temporal_mod.year, label = vnp.temporal_mod.text, expr = vnp.temporal_mod }
          else
            for _, m in ipairs(vnp.mods) do if m.kind == "mod" or m.kind == "ordinal" then value = value or { word = m.form, label = m.text } end end
          end
          h.instruction = { verb = a.lemma, act = act_eff, np = vnp, slot = slot, value = value, correction = correction, persist = persist }
          if act_eff == "exclude" then h.polarity = "negative" end
          h.correction, h.persist = correction, persist
          if slot then addf(h, "resource_slot", 0.5, "instruction targets the '" .. slot .. "' slot") end
          if correction then addf(h, "correction_cue", 0.4, "explicit correction marker") end
          if persist then addf(h, "persist_cue", 0.3, "applies from now on") end
          F.mark_pron(h, np)
          out[#out + 1] = h
          ::next_try::
        end
      end
    end
  end
  try_clause(k, nil, S.wrapper and S.wrapper.progressive)
  -- later clauses: "..., and go with the 2022 dataset", "..., so please switch over to the 2021 dataset", "Sorry: use the 2020 dataset"
  for kk = k + 1, S.last do
    local ck = C(S, kk)
    if ck and not ck.masked then
      local pc = C(S, kk - 1)
      local after_conj = pc and pc.single and cat(pc, "conj") and not pc.masked
      if (ck.pre and (ck.pre:find("comma") or ck.pre:find("colon") or ck.pre:find("semi"))) or after_conj then
        if not (correction and false) then try_clause(kk, nil, false) end
      end
    end
  end
  -- "The 2023 dataset is the one I actually want you to use from now on." / "... is the one to use": a resource named as THE ONE to use
  if #out == 0 then
    for _, np in ipairs(P.parse_np(S, k)) do
      local slot = resource_slot(S, np)
      local cb = C(S, np.nxt)
      if slot and cb and cb.single and cat(cb, "aux_be") and not cb.masked then
        local one_k
        for j = np.nxt + 1, math.min(S.last, np.nxt + 4) do
          local cj = C(S, j)
          if cj and cj.single and (cj.unit.form == "one") then one_k = j break end
        end
        if one_k then
          for j = one_k + 1, S.last do
            local cj = C(S, j)
            local verb
            if cj and cj.single and not cj.masked then
              for _, a in ipairs(P.verb_analyses(S, cj)) do
                if a.form == "base" and (a.act == "constraint") then verb = a end
              end
            end
            if verb then
              local h = newh(S, "instruction:the_one_to_use", "instruction", "instruction_update", "instruct")
              for _, s_ in ipairs(skipped) do h.used[s_] = true end
              use_np(h, np); for i = np.nxt, S.last do if not (C(S, i).temporal and not (C(S, i).temporal.persist or C(S, i).temporal.kind == "persist")) then h.used[i] = true end end
              local value
              if np.temporal_mod then value = { year = np.temporal_mod.year, label = np.temporal_mod.text, expr = np.temporal_mod }
              else for _, m in ipairs(np.mods) do if m.kind == "mod" or m.kind == "ordinal" then value = value or { word = m.form, label = m.text } end end end
              h.instruction = { verb = verb.lemma, act = "constraint", np = np, slot = slot, value = value, correction = correction, persist = persist }
              h.correction, h.persist = correction, persist
              addf(h, "resource_slot", 0.5, "the sentence names a '" .. slot .. "' as the one to use")
              if correction then addf(h, "correction_cue", 0.4, "explicit correction marker") end
              if persist then addf(h, "persist_cue", 0.3, "applies from now on") end
              out[#out + 1] = h
              break
            end
          end
        end
      end
    end
  end
  -- A resource value stated as a fact about the resource, not as an imperative:
  --   "The 2025 dataset replaces the one I named before."        (the subject is the NEW value)
  --   "The right dataset is 2026."  "The dataset should be 2026 not what I said before."  "The one you should be using from now on is 2026."
  do
    local REPLACERS = U.set({ "replace", "replaces", "replacing", "supersede", "supersedes", "override", "overrides", "overrule", "overrules", "supplant", "supplants", "trump", "trumps" })
    local CORRECT_ADJ = U.set({ "right", "correct", "proper", "actual", "real", "true", "intended", "new", "updated", "current" })
    local function value_of_np(np)
      if np.temporal_mod then return { year = np.temporal_mod.year, label = np.temporal_mod.text, expr = np.temporal_mod } end
      if np.head_kind == "temporal" and np.head.temporal then return { year = np.head.temporal.year, label = np.head.temporal.text or P.span_text(S, np) } end
      if np.head_kind == "number" then return { word = P.span_text(S, np), label = P.span_text(S, np) } end
      if np.count then return { word = tostring(np.count), label = tostring(np.count) } end
      return nil
    end
    local any_resource
    for kk = S.first, S.last do
      local ck = C(S, kk)
      if ck and ck.single and S.lex:resource(ck.unit.form) then any_resource = S.lex:resource(ck.unit.form) end
    end
    -- candidate clause starts: the sentence start and every position after a comma / semicolon / colon / conjunction
    local starts = { k }
    for kk = k + 1, S.last do
      local ck, pc = C(S, kk), C(S, kk - 1)
      if ck and not ck.masked and ((ck.pre and (ck.pre:find("comma") or ck.pre:find("semi") or ck.pre:find("colon"))) or (pc and pc.single and cat(pc, "conj") and not pc.masked)) then starts[#starts + 1] = kk end
    end
    local np_list = {}
    for _, st in ipairs(starts) do for _, np in ipairs(P.parse_np(S, st)) do np_list[#np_list + 1] = np end end
    for _, np in ipairs(np_list) do
      local slot = resource_slot(S, np) or ((np.head and np.head.single and np.head.unit.form == "one") and any_resource) or nil
      local cb = C(S, np.nxt)
      -- (a) "the 2025 dataset replaces the one I named before"
      if slot and cb and cb.single and not cb.masked and REPLACERS[cb.unit.form] then
        local val = value_of_np(np)
        if val then
          local h = newh(S, "instruction:subject_replaces", "instruction", "instruction_update", "instruct")
          for _, s_ in ipairs(skipped) do h.used[s_] = true end
          use_np(h, np); h.used[np.nxt] = true
          for i = np.nxt + 1, S.last do if not C(S, i).masked then h.used[i] = true end end
          h.instruction = { verb = "replace", act = "constraint", np = np, slot = slot, value = val, correction = true, persist = persist }
          h.correction, h.persist = true, persist
          addf(h, "resource_slot", 0.5, "the sentence says which '" .. slot .. "' replaces the earlier one")
          addf(h, "replacement_statement", 0.5, "'" .. cb.unit.form .. "' marks the subject as the new value")
          out[#out + 1] = h
        end
      end
      -- (b) "the right dataset is 2026", "the dataset should be 2026 not what I said before", "the one you should be using from now on is 2026"
      if slot then
        local bk = np.nxt
        -- skip a relative clause after "the one": "... you should be using from now on"
        if np.head and np.head.single and np.head.unit.form == "one" then
          local jj = bk
          while C(S, jj) and not (C(S, jj).single and cat(C(S, jj), "aux_be") and C(S, jj + 1) and value_of_np((P.parse_np(S, jj + 1))[1] or {}) ) and jj < S.last do jj = jj + 1 end
          bk = jj
        end
        local bc = C(S, bk)
        -- optional modal: "should be", "must be", "needs to be", "will be"
        local mk = bk
        while C(S, mk) and C(S, mk).single and not C(S, mk).masked and (cat(C(S, mk), "modal") or cat(C(S, mk), "adv") or C(S, mk).unit.form == "to" or C(S, mk).unit.form == "need" or C(S, mk).unit.form == "needs") and mk < S.last do mk = mk + 1 end
        local bc2 = C(S, mk)
        if bc2 and bc2.single and not bc2.masked and cat(bc2, "aux_be") then
          for _, vnp in ipairs(P.parse_np(S, mk + 1)) do
            local val = value_of_np(vnp)
            if val then
              local adj_correct = false
              for _, md in ipairs(np.mods) do if md.form and CORRECT_ADJ[md.form:lower()] then adj_correct = true end end
              local h = newh(S, "instruction:resource_is_value", "instruction", "instruction_update", "instruct")
              for _, s_ in ipairs(skipped) do h.used[s_] = true end
              use_np(h, np); use_np(h, vnp)
              for i = np.nxt, vnp.c1 do h.used[i] = true end
              for i = vnp.nxt, S.last do if not C(S, i).masked then h.used[i] = true end end
              h.instruction = { verb = "be", act = "constraint", np = np, slot = slot, value = val, correction = correction or adj_correct, persist = persist }
              h.correction, h.persist = correction or adj_correct, persist
              addf(h, "resource_slot", 0.5, "the sentence states which '" .. slot .. "' is the right one")
              addf(h, "resource_is_value", 0.5, "a resource noun is equated with a value")
              out[#out + 1] = h
              break
            end
          end
        end
      end
    end
  end
  -- bare correction followed by a plain fragment: "Actually, the 2025 one."  handled as statement with correction flag
  if correction and #out == 0 then
    local nk = k
    for _, np in ipairs(P.parse_np(S, nk)) do
      local h = newh(S, "instruction:correction_fragment", "correction", "correction", "instruct")
      for _, s in ipairs(skipped) do h.used[s] = true end
      use_np(h, np)
      h.instruction = { verb = nil, np = np, slot = resource_slot(S, np), correction = true, persist = persist }
      h.correction = true
      F.mark_pron(h, np)
      out[#out + 1] = h
      break
    end
  end
end

-- Exclusions and prohibitions that are NOT plain imperatives (F.instruction handles "Leave out X.", "Do not include X.", "Keep X out of ..."):
--   passive / deontic   "Universities need to be excluded."  "Reposts should be left out."  "X are not to be included."  "make sure X are left out of the list"
--   modal active        "The results should exclude X."  "Results must not contain any X."  "My brief says to exclude X."
--   progressive         "We are ruling out X for this exercise."  "I'm leaving out X."
--   wishes              "I don't want any X in the results."  "I'd rather not see any X."  "I'd really like X excluded."  "I'd rather you skipped X."
--   states of affairs   "Anything involving X is off limits."  "No X in the output, please."
--   a pronoun object    "If you come across any X, just drop them from the results."
-- Each yields an instruction_update hypothesis shaped like the imperative ones, so memory treats it identically (a standing prohibition).
local DEONTIC_WORDS = U.set({ "should", "must", "shall", "ought", "need", "needs", "needed", "supposed", "required", "expected" })
local DIRECTIVE_WORDS = U.set({ "please", "ensure", "sure", "remember", "mind", "must", "should", "shall", "ought", "need", "needs", "needed", "want", "wants", "wanted", "prefer",
  "rather", "always", "never", "require", "required", "requirement", "rule", "insist", "important", "essential", "crucial", "necessary", "wish" })
local CHAIN_WORDS = U.set({ "to", "get", "gets", "got", "be", "been", "being", "is", "are", "was", "were", "am", "do", "does", "did", "rather", "just", "really", "please", "kindly",
  "also", "then", "still", "actually", "simply", "now", "not", "never", "n't", "should", "must", "shall", "ought", "need", "needs", "needed", "supposed", "required", "expected",
  "have", "has", "had", "will", "would", "can", "could", "may", "might", "going", "'d", "'ll", "'re", "'m", "'s", "'ve", "gotta", "always", "definitely", "absolutely", "all" })
local OFF_LIMITS = { { "off", "limits" }, { "off", "the", "table" }, { "out", "of", "scope" }, { "out", "of", "bounds" }, { "banned" }, { "forbidden" }, { "prohibited" },
  { "taboo" }, { "unwanted" }, { "not", "wanted" }, { "irrelevant" }, { "not", "relevant" }, { "excluded" }, { "out" }, { "off", "limit" } }
local INDEF_LINK = U.set({ "involving", "with", "about", "from", "containing", "concerning", "featuring", "mentioning", "regarding", "on", "of", "by", "related", "relating" })
local OUTPUT_NOUNS = U.set({ "results", "result", "output", "outputs", "list", "lists", "answer", "answers", "response", "responses", "report", "summary", "table", "search", "findings" })
local WISH_VERBS = U.set({ "want", "wants", "wanted", "need", "needs", "needed", "like", "likes", "prefer", "prefers", "wish", "expect", "require", "requires", "insist" })
local PERCEPTION_VERBS = U.set({ "see", "have", "get", "receive", "hear", "find", "want", "need", "like", "include", "use", "show", "contain", "list", "return", "mention", "feature",
  "display", "give", "output", "surface", "produce", "present", "report", "read", "spot", "notice", "add", "incorporate" })
local INSTRUCT_VERBS = U.set({ "says", "said", "say", "asks", "asked", "ask", "tells", "told", "tell", "requires", "required", "instructs", "instructed", "decided", "agreed", "wants", "wanted",
  "needs", "needed", "want", "need", "prefer", "prefers", "wish", "plan", "plans", "idea", "goal", "aim" })

function F.exclusion_clause(S, out)
  if S.sentence and S.sentence.question_mark then return end
  -- the constraint-segment masks (set because exclusion cue words such as "exclude" / "rule out" are in the sentence) hide exactly the words this frame reads:
  -- lift them while scanning, restore them afterwards
  local saved
  for i, ch in ipairs(S.chunks) do if ch.masked then saved = saved or {}; saved[i] = ch.mask_kind or true end end
  if saved then
    for i in pairs(saved) do S.chunks[i].masked = nil end
    S.np_memo, S.vp_memo, S.wh_memo = {}, {}, {}
  end
  local ok, err = pcall(F.exclusion_clause_scan, S, out)
  if saved then
    for i, kind in pairs(saved) do S.chunks[i].masked = true; S.chunks[i].mask_kind = kind ~= true and kind or nil end
    S.np_memo, S.vp_memo, S.wh_memo = {}, {}, {}
  end
  if not ok then error(err, 0) end
end

function F.exclusion_clause_scan(S, out)
  local function form_of(c) return c and c.single and c.unit and c.unit.form or nil end
  local directive, persist = false, false
  for k = S.first, S.last do
    local c = C(S, k)
    if c and not c.masked then
      local f = form_of(c)
      if f and DIRECTIVE_WORDS[f] then directive = true end
      if c.temporal and (c.temporal.kind == "persist" or c.temporal.persist) then directive, persist = true, true end
    end
  end
  -- "Someone asked whether universities should be excluded": a REPORTED question or a third party's debate is not an instruction to the system
  local QUESTION_REPORT = U.set({ "whether", "asked", "asks", "asking", "wondered", "wonders", "wondering", "debated", "debating", "argued", "arguing", "questioned", "discussed", "discussing", "unclear", "unsure" })
  local reported_question_at = {}
  do
    local seen_q = false
    for k = S.first, S.last do
      local c = C(S, k)
      local f = c and c.single and c.unit and c.unit.form
      if f and QUESTION_REPORT[f] then seen_q = true end
      if f == "if" and k > S.first then seen_q = true end
      reported_question_at[k] = seen_q
    end
  end
  local seen = {}
  local function emit(frame, np, used_from, used_to, verb, more_used)
    local key = np.c1 .. ":" .. np.c2 .. ":" .. frame
    if seen[key] then return end
    -- the construction must not sit inside a reported question / conditional (the imperative-with-pronoun case below is the one place "if" is expected)
    if frame ~= "pronoun_object" and reported_question_at[used_from] then return end
    seen[key] = true
    local h = newh(S, "instruction:" .. frame, "instruction", "instruction_update", "instruct")
    for i = used_from, used_to do if C(S, i) then h.used[i] = true end end
    for _, u in ipairs(more_used or {}) do h.used[u] = true end
    use_np(h, np)
    h.instruction = { verb = verb, act = "exclude", np = np, correction = false, persist = persist }
    h.polarity = "negative"
    h.persist = persist
    addf(h, "exclusion_clause", 0.9, "an exclusion is stated (" .. frame .. ")")
    if directive then addf(h, "directive_context", 0.2, "the sentence carries a directive marker") end
    if persist then addf(h, "persist_cue", 0.3, "applies from now on") end
    F.mark_pron(h, np)
    out[#out + 1] = h
  end
  -- the NP that ends right before chunk `e` (longest first)
  local function np_ending_before(e)
    for i = S.first, e - 1 do
      for _, np in ipairs(P.parse_np(S, i)) do if np.nxt == e then return np end end
    end
  end
  -- "any X", "all X": the quantifier is part of the determiner; the target is the NP after it
  for kv = S.first, S.last do
    local c = C(S, kv)
    if c and not c.masked and (c.single or c.kind == "mwe") then
      for _, a in ipairs(P.verb_analyses(S, c)) do
        local is_excl = a.act == "exclude"
        local is_percep = a.act == "include" or PERCEPTION_VERBS[a.lemma] == true
        if is_excl or is_percep then
          -- the verb group in front of the verb
          local j = kv - 1
          local forms, has_neg, has_be, deontic, rather = {}, false, false, false, false
          while j >= S.first and C(S, j) and C(S, j).single and not C(S, j).masked and not barrier(C(S, j)) and CHAIN_WORDS[form_of(C(S, j))] and kv - j <= 6 do
            local f = form_of(C(S, j))
            if f == "do" and forms[1] == "do" then break end      -- "whatever you DO don't include X": two do's are two clauses
            table.insert(forms, 1, f)
            if P.is_neg(C(S, j)) or f == "never" then has_neg = true end
            if f == "be" or f == "been" or f == "being" or f == "is" or f == "are" or f == "was" or f == "were" or f == "am" or f == "get" or f == "gets" or f == "got" or f == "'re" or f == "'m" then has_be = true end
            if DEONTIC_WORDS[f] then deontic = true end
            if f == "rather" then rather = true end
            j = j - 1
          end
          local chain_first = j + 1
          for i, f in ipairs(forms) do
            if f == "to" and i > 1 and (forms[i - 1] == "have" or forms[i - 1] == "has" or forms[i - 1] == "had" or forms[i - 1] == "going" or forms[i - 1] == "ought") then deontic = true end
          end
          local subj_form = j >= S.first and form_of(C(S, j)) or nil
          local subj_pron = subj_form == "we" or subj_form == "i" or subj_form == "you"
          local after, verb_end = kv + 1, kv
          local nc = C(S, after)
          if is_excl and c.kind ~= "mwe" and nc and nc.single and not nc.masked and not barrier(nc) and (nc.unit.form == "out" or nc.unit.form == "off") then after = after + 1; verb_end = after - 1 end
          local to_before = forms[#forms] == "to"
          local imperative_chain = true       -- nothing but do / not / please-like words in front: a plain imperative, F.instruction's business
          for _, f in ipairs(forms) do
            if not (f == "do" or f == "does" or f == "did" or f == "not" or f == "n't" or f == "never" or f == "please" or f == "just" or f == "kindly" or f == "also" or f == "then" or f == "always" or f == "really" or f == "definitely" or f == "absolutely" or f == "now") then imperative_chain = false end
          end
          if subj_pron then imperative_chain = false end

          -- (1) passive: NP be/get ... excluded
          if is_excl and (a.form == "pp" or a.form == "past") and has_be and not has_neg then
            local np = np_ending_before(chain_first)
            if np and (deontic or directive or rather or persist) then emit("passive", np, np.c1, verb_end) end
          end
          -- (1b) a negated passive of an include-like verb: "X are not to be included", "X should not be shown", "X must not appear"
          if is_percep and not is_excl and (a.form == "pp" or a.form == "past") and has_be and has_neg and (deontic or to_before or directive) then
            local np = np_ending_before(chain_first)
            if np then emit("negated_passive", np, np.c1, verb_end) end
          end
          -- (2) modal / infinitive active: "the results should exclude X", "my brief says to exclude X"
          if is_excl and a.form == "base" and not has_neg and not imperative_chain then
            local pv = j >= S.first and C(S, j)
            local instruct_prev = pv and pv.single and INSTRUCT_VERBS[form_of(pv)] or false
            if deontic or (to_before and (instruct_prev or directive)) then
              -- "My brief says to exclude X": the introducing clause is part of the directive
              for _, np in ipairs(P.parse_np(S, after)) do emit("modal", np, instruct_prev and S.first or chain_first, np.c2, a.lemma); break end
            end
          end
          -- (3) progressive with a first/second-person subject: "We are ruling out X"
          if is_excl and a.form == "ing" and has_be and subj_pron and not has_neg then
            for _, np in ipairs(P.parse_np(S, after)) do emit("progressive", np, j, np.c2, a.lemma); break end
          end
          -- (4) subjunctive wish: "I'd rather you skipped X"
          if is_excl and (a.form == "past" or a.form == "base") and subj_form == "you" then
            local before1, before2 = form_of(C(S, j - 1)), form_of(C(S, j - 2))
            if before1 == "rather" or before2 == "rather" or before1 == "prefer" or before1 == "wish" then
              for _, np in ipairs(P.parse_np(S, after)) do emit("subjunctive", np, j - 1, np.c2, a.lemma); break end
            end
          end
          -- (5) negated include-like verbs: "Results must not contain any X", "I don't want any X", "I'd rather not see any X"
          if is_percep and not is_excl and a.form == "base" and has_neg and not imperative_chain then
            if deontic or rather or (subj_pron and WISH_VERBS[a.lemma]) or (subj_pron and rather) then
              for _, np in ipairs(P.parse_np(S, after)) do emit("negated_wish", np, chain_first, np.c2, a.lemma); break end
            end
          end
          -- (5b) a negated imperative that is not the first clause: "..., but whatever you do don't include X"
          if is_percep and not is_excl and a.form == "base" and has_neg and imperative_chain and chain_first > S.first then
            for _, np in ipairs(P.parse_np(S, after)) do emit("negated_imperative", np, chain_first, np.c2, a.lemma); break end
          end
          -- (6) wish + participle: "I'd really like X excluded", "we need X left out"
          if WISH_VERBS[a.lemma] and not has_neg then
            for _, np in ipairs(P.parse_np(S, kv + 1)) do
              local k2 = np.nxt
              local tc, bc = C(S, k2), C(S, k2 + 1)
              if tc and tc.single and form_of(tc) == "to" and bc and bc.single and cat(bc, "aux_be") then k2 = k2 + 2 end
              local vc = C(S, k2)
              if vc and (vc.single or vc.kind == "mwe") and not vc.masked then
                for _, a2 in ipairs(P.verb_analyses(S, vc)) do
                  if a2.act == "exclude" and (a2.form == "pp" or a2.form == "past") then emit("wish_participle", np, kv, k2, a2.lemma) end
                end
              end
            end
          end
          -- (7) imperative exclusion whose object is a pronoun: "If you come across any X, just drop THEM from the results"
          if is_excl and a.form == "base" and imperative_chain and not has_neg then
            for _, np in ipairs(P.parse_np(S, after)) do
              if np.head_kind == "pronoun" and np.pron and (np.pron.form == "them" or np.pron.form == "those" or np.pron.form == "it") then
                -- the antecedent: the nearest earlier noun phrase (not a pronoun) before this clause
                local ante
                for e = kv - 1, S.first, -1 do
                  for i = e, S.first, -1 do
                    for _, np2 in ipairs(P.parse_np(S, i)) do
                      if np2.nxt == e + 1 and np2.head_kind ~= "pronoun" and (np2.head_kind == "typenoun" or np2.head_kind == "unknown" or np2.head_kind == "entity") then ante = ante or np2 end
                    end
                    if ante then break end
                  end
                  if ante then break end
                end
                if ante then emit("pronoun_object", ante, kv, np.c2, a.lemma, { np.c1 }) end
              end
              break
            end
          end
        end
      end
    end
  end
  -- (8) states of affairs: "Anything involving X is off limits."
  for kb = S.first + 1, S.last do
    local bc = C(S, kb)
    if bc and bc.single and not bc.masked and cat(bc, "aux_be") then
      for _, pat in ipairs(OFF_LIMITS) do
        local ok = true
        for i, w in ipairs(pat) do
          local ck = C(S, kb + i)
          if not (ck and ck.single and not ck.masked and form_of(ck) == w) then ok = false break end
        end
        if ok then
          local np = np_ending_before(kb)
          local target = np
          -- "anything involving X": the indefinite only introduces the target
          for i = S.first, kb - 1 do
            local ci = C(S, i)
            local fi = form_of(ci)
            if fi == "anything" or fi == "everything" or fi == "anyone" or fi == "all" then
              local link = C(S, i + 1)
              if link and link.single and INDEF_LINK[form_of(link)] then
                local k3 = i + 2
                if form_of(link) == "related" or form_of(link) == "relating" then if form_of(C(S, i + 2)) == "to" then k3 = i + 3 end end
                for _, np2 in ipairs(P.parse_np(S, k3)) do if np2.nxt == kb then target = np2; break end end
              end
            end
          end
          if target then emit("off_limits", target, target.c1, kb + #pat) end
          break
        end
      end
    end
  end
  -- (9) "No X in the output, please."
  do
    local c0 = C(S, S.first)
    if c0 and c0.single and not c0.masked and form_of(c0) == "no" then
      for _, np in ipairs(P.parse_np(S, S.first + 1)) do
        local pc = C(S, np.nxt)
        if pc and pc.single and cat(pc, "prep") and not pc.masked then
          for _, np2 in ipairs(P.parse_np(S, np.nxt + 1)) do
            if np2.head and OUTPUT_NOUNS[np2.head.single and np2.head.unit.form or ""] then emit("no_x_in_output", np, S.first, np2.c2) end
          end
        end
      end
    end
  end
end

-- "I'm researching Company A." / "Let's talk about X." / "We are looking at Y."
function F.focus(S, out)
  local lex = S.lex
  local c = C(S, S.first)
  if not c then return end
  local n = lex:cue_at("focus_intro", S.units, c.u1)
  if n then
    local k = S.first
    local consumed = 0
    while C(S, k) and consumed < n do consumed = consumed + (C(S, k).u2 - C(S, k).u1 + 1); k = k + 1 end
    for _, np in ipairs(P.parse_np(S, k)) do
      local h = newh(S, "statement:focus", "statement", "statement", "focus")
      for i = S.first, k - 1 do h.used[i] = true end
      use_np(h, np)
      h.focus = np
      F.mark_pron(h, np)
      addf(h, "focus_cue", 0.6, "explicit topic-focus statement")
      out[#out + 1] = h
    end
  end
end

-- declarative statements: NP + VP + NP  /  NP be NP  (used for memory and for extracting assertions)
function F.statement(S, out)
  local k = S.first
  for _, snp in ipairs(P.parse_np(S, k)) do
    for _, vp in ipairs(P.parse_vp(S, snp.nxt)) do
      local objs = P.parse_np(S, vp.nxt)
      local h = newh(S, "statement:svo", "statement", "statement", "assert")
      use_np(h, snp); for i = vp.c1, vp.c2 do h.used[i] = true end
      -- "Results must not contain X", "universities should be excluded": a deontic verb group is a directive, not an assertion of fact
      for i = snp.nxt, vp.c2 do
        local ci = C(S, i)
        local fi = ci and ci.single and ci.unit and ci.unit.form
        if fi == "must" or fi == "should" or fi == "shall" or fi == "ought" then addf(h, "deontic_not_assertion", -0.9, "a verb group with '" .. fi .. "' is a directive, not a statement of fact"); break end
      end
      h.statement = { subj = snp, vp = vp, lemma = vp.lemma, neg = vp.neg }
      if objs[1] then use_np(h, objs[1]); h.statement.obj = objs[1] end
      for _, e in ipairs(vp.analysis.entries) do
        local rel = S.lex:get_rel(e.rel)
        if rel and objs[1] and not rel.open then
          h.rel, h.rel_obj = rel.id, rel
          h.roles[vp.voice == "passive" and other(e.subj) or e.subj] = snp
          h.roles[vp.voice == "passive" and e.subj or other(e.subj)] = objs[1]
          addf(h, "relation_verb", 0.4, "statement over relation verb")
          break
        end
      end
      F.mark_pron(h, snp)
      out[#out + 1] = h
    end
  end
end

return F

end

package.preload["asi.nlu.hook"] = function(...)
-- asi.nlu.hook: the ONE integration point for a host program (for example the user's exec_eval bundle).
--   local Hook = require("asi.nlu.hook")
--   local out  = Hook.prepare("Which company acquired the business I mentioned earlier?", { memory = Hook.memory("session-1", "alice") })
--   -- out.prompt  : the LM Input Package text (authority boundaries, verified evidence, ambiguity and unresolved requirements)
--   -- out.record  : the versioned Interpretation Record (inspectable without any language model)
-- The hook never calls a language model, a network service or a clock; it never routes text into any other interface of the host.  Natural-language
-- text goes in, a structured interpretation and a bounded, authority-labelled input package come out.
local Hook = {}

local engine

-- datasets: optional list of { text = <file contents>, name = "world_2020.jsonl", dataset = "w2020", label = { year = 2020 }, version = "2020" }
function Hook.configure(opts)
  opts = opts or {}
  local Resources = require("asi.nlu.resources")
  local K = require("asi.nlu.knowledge")
  local Engine = require("asi.nlu.engine")
  local Cal = require("asi.nlu.calibration")
  local kb
  if opts.datasets and #opts.datasets > 0 then
    kb = K.new(Resources.core())
    for _, d in ipairs(opts.datasets) do kb:ingest(d.text, { name = d.name, dataset = d.dataset or d.name, label = d.label, version = d.version }) end
  end
  local model = opts.calibration or Cal.default_model()
  engine = Engine.new({ knowledge = kb, flags = opts.flags, budget = opts.budget, package_chars = opts.package_chars,
    calibration = (model and not opts.no_calibration) and Cal.record_adapter(model) or nil })
  return engine
end

function Hook.engine()
  return engine or Hook.configure({})
end

-- a conversation memory owned by `principal` (another principal is refused access to the namespace)
function Hook.memory(namespace, principal)
  return Hook.engine():memory(namespace, principal)
end

-- text -> { record, package, prompt, result, evidence }.  call = { memory = , speaker = , include_prompt = , package_chars = , budget = }
function Hook.prepare(text, call)
  call = call or {}
  if call.include_prompt == nil then call.include_prompt = true end
  local out = Hook.engine():process(text, call)
  return { record = out.record, package = out.package, prompt = out.package and out.package.prompt, result = out.result, evidence = out.evidence,
    valid = out.valid, light = out.light }
end

function Hook.version()
  local Engine = require("asi.nlu.engine")
  local Record = require("asi.nlu.record")
  return { engine = Engine.VERSION, record_schema = Record.SCHEMA }
end

return Hook

end

package.preload["asi.nlu.hyp"] = function(...)
-- asi.nlu.hyp: competing interpretation hypotheses.
-- Scores are sums of NAMED, bounded factors (so provenance is real: it lists the computations that produced the score).
-- Hard constraints (type clash on a required role) VETO a hypothesis; soft evidence only ranks.
local U = require("asi.nlu.util")
local P = require("asi.nlu.parse")
local Cons = require("asi.nlu.constraints")

local H = {}

-- weights are fixed constants; they were only ever adjusted against the DEV split (see reports/)
H.W = {
  type_fit = 1.1,       -- multiplier on compat(-1..1) per bound role
  coverage = 1.6,       -- fraction of content chunks explained
  unexplained = -0.30,  -- per unexplained content chunk
  lex_entity = 0.15,    -- attested entity span used
  lex_mwe = 0.20,       -- attested multiword unit used
  domain = 0.35,
  discourse = 0.30,
  support = 0.25,
  fuzzy = -0.45,
  unseen = -0.05,
  exact_case = 0.15,
  temperature = 0.55,
  entity_temperature = 0.30,
  resolve_p = 0.60, resolve_margin = 0.30,
}

local FRAME_PRIOR = {
  ["wh_copular:relnp"] = 0.12, ["wh_verb:active"] = 0.10, ["wh_do:object_gap"] = 0.10, ["wh_passive:stranded_by"] = 0.10,
  ["request:relnp"] = 0.08, ["request:search"] = 0.05, ["request:entity"] = 0.0, ["request:concept"] = 0.0,
}

local function softmax(scores, T)
  local m = -math.huge
  for _, s in ipairs(scores) do if s > m then m = s end end
  local sum, ex = 0, {}
  for i, s in ipairs(scores) do ex[i] = math.exp((s - m) / T); sum = sum + ex[i] end
  for i = 1, #ex do ex[i] = ex[i] / sum end
  return ex
end
H.softmax = softmax

---------------------------------------------------------------- context domains (see parse.lua: P.domain_hits / P.domain_gain)
-- best domain support among an NP's candidate senses (used to rank typenoun/concept readings such as program.academic vs software)
local function sense_domain(S, ctx, np)
  local best_hits, best_sense = 0, nil
  for _, s in ipairs(np.senses or {}) do
    local h = P.domain_hits(S, ctx, s.domain, np.u1, np.u2)
    if h > best_hits then best_hits, best_sense = h, s end
  end
  return best_hits, best_sense
end
H.sense_domain = sense_domain

---------------------------------------------------------------- binding an NP argument to candidates + types
-- expected: type name (or union) or nil.  Returns bound table and the best type-fit in [-1, 1]
function H.bind_np(S, ctx, np, expected, h, role)
  if np.bound and np.bound_for == expected and (np.head_kind ~= "pronoun" or np.bound_h == h) then return np.bound, np.bound.fit end
  local lex = S.lex
  local W = H.W
  local b = { cands = {}, status = "unresolved", expected = expected }
  if np.head_kind == "entity" then
    local scored = {}
    -- "the country Georgia", "the company Apple": a type noun in front of a name tells which kind of thing the name denotes
    local cls_types = {}
    for _, md in ipairs(np.mods or {}) do
      if md.kind == "mod" and md.chunk then
        for _, sn in ipairs(md.chunk.senses or {}) do
          if sn.sense and sn.sense.kind == "typenoun" and sn.sense.type then cls_types[#cls_types + 1] = sn.sense.type end
        end
      end
    end
    for _, cd in ipairs(np.cands or {}) do
      local s, reasons = 0, {}
      local ty = cd.type
      if ty and #cls_types > 0 then
        local best = -1.0
        for _, ct in ipairs(cls_types) do best = math.max(best, lex:compat(ty, ct)) end
        if best >= 0.9 then s = s + 0.8; reasons[#reasons + 1] = "agrees with the type noun in front of the name"
        elseif best == -1.0 then s = s - 0.8; reasons[#reasons + 1] = "contradicts the type noun in front of the name" end
      end
      local fit
      if cd.unseen then
        s = s + W.unseen
        if ty then fit = lex:compat(ty, expected) else fit = 0.25; reasons[#reasons + 1] = "type inferred from relation signature" end
        reasons[#reasons + 1] = "not in any loaded entity table (open-set mention)"
      else
        fit = lex:compat(ty, expected)
      end
      if ctx.flags and ctx.flags.no_types then fit = 0.25 end
      s = s + 0.6 * fit
      if fit == -1.0 and expected then reasons[#reasons + 1] = "type " .. tostring(ty) .. " incompatible with expected " .. tostring(expected) end
      if cd.exact_case then s = s + W.exact_case; reasons[#reasons + 1] = "exact-case name match" end
      if cd.fuzzy then s = s + W.fuzzy * (1 - cd.fuzzy) - 0.15; reasons[#reasons + 1] = "fuzzy match from '" .. tostring(cd.fuzzy_from) .. "'" end
      if not (ctx.flags and ctx.flags.no_domain) then
        local dh = P.domain_hits(S, ctx, cd.domain, np.u1, np.u2)
        local gain = P.domain_gain(dh)
        if gain > 0 then s = s + gain; reasons[#reasons + 1] = dh .. " domain cue(s) in context" end
      end
      if ctx.mentioned and ctx.mentioned[cd.id] then s = s + W.discourse * ctx.mentioned[cd.id]; reasons[#reasons + 1] = "previously mentioned in the conversation" end
      if ctx.support then
        local n = ctx.support(cd.id) or 0
        if n > 0 then
          s = s + (n >= 3 and 0.6 or 0.3)
          reasons[#reasons + 1] = n .. (cd.unseen and " dataset mention(s)" or " supporting dataset record(s)")
        end
      end
      s = s + 0.1 * ((cd.prior or 0.5) - 0.5)
      scored[#scored + 1] = { id = cd.id, type = ty, name = cd.name, score = s, fit = fit, vetoed = (fit == -1.0 and expected ~= nil),
        reasons = reasons, unseen = cd.unseen, weak = cd.weak, fuzzy = cd.fuzzy, source = cd.source, domain = cd.domain }
    end
    local live = {}
    for _, c in ipairs(scored) do if not c.vetoed then live[#live + 1] = c end end
    table.sort(live, function(a, b) if a.score ~= b.score then return a.score > b.score end return a.id < b.id end)
    local rejected = {}
    for _, c in ipairs(scored) do if c.vetoed then rejected[#rejected + 1] = c end end
    if #live > 0 then
      local ps = softmax(U.map(live, function(c) return c.score end), W.entity_temperature)
      for i, c in ipairs(live) do c.p = ps[i] end
      b.cands = live
      b.top = live[1]
      b.rejected = rejected
      local margin = live[1].p - (live[2] and live[2].p or 0)
      if #live == 1 or (live[1].p >= W.resolve_p and margin >= W.resolve_margin) then
        b.status = live[1].unseen and "unseen" or "resolved"
      else b.status = "ambiguous" end
      b.margin = margin
      b.fit = live[1].fit
      -- an open-set mention that fills a typed role is probably of that type ("Ninefold" as the work of 'author'); kept apart from attested types
      if live[1].unseen and expected and not expected:find("|", 1, true) then b.itype = expected end
    else
      b.rejected = rejected
      b.status = "unresolved"
      b.fit = (#rejected > 0) and -1.0 or 0.25
    end
  elseif np.head_kind == "typenoun" or np.head_kind == "concept" then
    -- rank the NP's senses by domain support; the best one defines the type
    local senses = U.copy(np.senses or {})
    local hits, best = sense_domain(S, ctx, np)
    if best then
      for i, s in ipairs(senses) do if s.id == best.id then table.remove(senses, i); table.insert(senses, 1, s) break end end
      if not (ctx.flags and ctx.flags.no_domain) then b.domain_gain = P.domain_gain(hits) end
    end
    local ty = senses[1] and senses[1].type
    b.type, b.fit = ty, lex:compat(ty, expected)
    if ctx.flags and ctx.flags.no_types then b.fit = 0.25 end
    b.status = "resolved"
    b.senses = senses
    np.senses = senses
  elseif np.head_kind == "relnoun" then
    local e = np.relnouns and np.relnouns[1]
    local rel = e and lex:get_rel(e.rel)
    b.type = rel and rel[e.role] or nil
    b.fit = lex:compat(b.type, expected)
    b.status = "resolved"
  elseif np.head_kind == "var" then
    -- intermediate result of an earlier step of a multi-hop chain: its type comes from that step
    b.type, b.fit, b.status, b.chain_var = np.type, lex:compat(np.type, expected), "resolved", np.var
  elseif np.head_kind == "pronoun" then
    if ctx.discourse and not (ctx.flags and ctx.flags.no_coref) then
      ctx.discourse:pronoun_binding(S, ctx, np, expected, h, role, b)
    else
      b.status, b.fit, b.pending = "pending", 0.25, true
    end
  elseif np.head_kind == "temporal" then b.type, b.fit, b.status = "date", lex:compat("date", expected), "resolved"
  elseif np.head_kind == "number" then b.type, b.fit, b.status = "number", lex:compat("number", expected), "resolved"
  elseif np.head_kind == "quote" or np.head_kind == "literal" then b.type, b.fit, b.status = "text", 0.25, "resolved"
  else
    b.fit, b.status = 0.25, "unknown_term"
  end
  np.bound, np.bound_for, np.bound_h = b, expected, h
  return b, b.fit
end

---------------------------------------------------------------- per-hypothesis finalisation
local function content_chunks(S)
  if S.content_count then return S.content_count end
  local n = 0
  for k = S.first, S.last do
    local c = S.chunks[k]
    if not c.masked and not P.is_function_chunk(S, c) then n = n + 1 end
  end
  S.content_count = n
  return n
end

local function bind_all(S, ctx, h)
  local W = H.W
  local function fit_factor(name, fit, note)
    if fit == nil then return end
    h.factors[#h.factors + 1] = { name = name, v = W.type_fit * fit * 0.5, note = note }
    if fit == -1.0 then h.veto = h.veto or note end
  end
  -- a fronted preposition ("In which city ...", "By whom ...") must be accounted for by the construction
  if h.wh and h.wh.pied and not h.pied_consumed then
    h.factors[#h.factors + 1] = { name = "pied_prep_unused", v = -0.8, note = "the fronted preposition '" .. tostring(h.wh.pied) .. "' is not accounted for" }
  end
  if h.rel_obj and h.rel_obj.open then
    -- the relation word is not in the lexicon: it is kept under its own name, at a cost, so any lexicon reading of the same words wins
    h.factors[#h.factors + 1] = { name = "open_relation", v = -0.35, note = "relation inferred from a word the lexicon does not know ('" .. tostring(h.rel_obj.id) .. "'); not mapped onto any known relation" }
  end
  if h.rel_obj then
    for _, role in ipairs({ "from", "to" }) do
      local np = h.roles[role]
      if np then
        -- an open relation has no type signature: its arguments are neither rewarded nor vetoed
        local b, fit = H.bind_np(S, ctx, np, (not h.rel_obj.open) and h.rel_obj[role] or nil, h, role)
        local what = (b.top and b.top.name) or P.span_text(S, np)
        if b.status == "unresolved" and fit == -1.0 then
          fit_factor("type_fit:" .. role, -1.0, "'" .. P.span_text(S, np) .. "' cannot be a " .. tostring(h.rel_obj[role]) .. " (role '" .. role .. "' of " .. h.rel_obj.id .. ")")
        else
          fit_factor("type_fit:" .. role, fit, string.format("'%s' as %s of %s (fit %.2f)", what, role, h.rel_obj.id, fit))
        end
        if b.top and b.top.fuzzy then h.factors[#h.factors + 1] = { name = "fuzzy", v = W.fuzzy, note = "entity matched through a spelling variant" } end
      end
    end
    if h.wh_type and h.ask then
      local fit = S.lex:compat(h.wh_type, h.rel_obj[h.ask])
      if ctx.flags and ctx.flags.no_types then fit = 0.25 end
      fit_factor("answer_type_fit", fit, string.format("wh-type '%s' vs %s of %s (fit %.2f)", h.wh_type, h.ask, h.rel_obj.id, fit))
    end
  end
  -- every step of a multi-hop chain is typed against its own relation signature
  for si, st in ipairs(h.chain or {}) do
    local b, fit = H.bind_np(S, ctx, st.known, st.rel_obj[st.known_role], h, "chain" .. si)
    local what = (b.top and b.top.name) or P.span_text(S, st.known)
    fit_factor("chain_fit:" .. si, fit, string.format("step %d: '%s' as %s of %s (fit %.2f)", si, what, st.known_role, st.rel, fit))
  end
  if h.subject then H.bind_np(S, ctx, h.subject, h.expect_type, h, "subject") end
  if h.concept then H.bind_np(S, ctx, h.concept, nil, h, "concept") end
  if h.target then H.bind_np(S, ctx, h.target, nil, h, "target") end
  for _, it in ipairs(h.items or {}) do H.bind_np(S, ctx, it, nil, h, "item") end
  if h.focus then H.bind_np(S, ctx, h.focus, nil, h, "focus") end
  if h.object then H.bind_np(S, ctx, h.object, nil, h, "object") end
  if h.basis then H.bind_np(S, ctx, h.basis.np, nil, h, "basis") end
  if h.statement then
    if h.statement.subj then H.bind_np(S, ctx, h.statement.subj, nil, h, "subject") end
    if h.statement.obj then H.bind_np(S, ctx, h.statement.obj, nil, h, "object") end
  end
  -- sense-level domain evidence for typenoun/concept readings (competing readings of a word such as "program")
  for _, np in ipairs({ h.concept, h.target, h.object, h.focus }) do
    if np and np.bound and np.bound.domain_gain and np.bound.domain_gain > 0 then
      h.factors[#h.factors + 1] = { name = "sense_domain", v = np.bound.domain_gain, note = "context domain supports the chosen sense of '" .. P.span_text(S, np) .. "'" }
    end
  end
  -- unaided fuzzy lexemes (typos of relation words / senses) cost confidence once per chunk
  for k in pairs(h.used) do
    local c = S.chunks[k]
    if c and c.fuzzy and #c.entities == 0 then
      h.factors[#h.factors + 1] = { name = "fuzzy_lexeme", v = W.fuzzy * (1 - c.fuzzy) - 0.15, note = "'" .. tostring(c.fuzzy_from) .. "' matched through a spelling variant" }
    end
  end

end

function H.finalize(S, ctx, h)
  local W = H.W
  local F2 = require("asi.nlu.frames2")
  F2.expand_chain(S, h)   -- turn nested relational NPs / relative clauses into ordered lookup steps
  F2.attach_basis(S, h)   -- "considering X" / "given X" arguments
  Cons.attach(S, h)
  bind_all(S, ctx, h)

  -- lexical attestation of the spans actually used
  local lex_bonus = 0
  for k in pairs(h.used) do
    local c = S.chunks[k]
    if c then
      if c.kind == "entity" and #c.entities > 0 then lex_bonus = lex_bonus + W.lex_entity
      elseif c.kind == "mwe" then lex_bonus = lex_bonus + W.lex_mwe end
    end
  end
  if lex_bonus > 0 then h.factors[#h.factors + 1] = { name = "lexical_attestation", v = lex_bonus, note = "attested multiword/entity spans used" } end

  -- coverage
  local total = math.max(1, content_chunks(S) + #(S.prefix_chunks or {}))
  local unexplained = Cons.unexplained(S, h)
  local explained = total - #unexplained
  local cov = explained / total
  h.coverage = cov
  h.unexplained = unexplained
  h.factors[#h.factors + 1] = { name = "coverage", v = W.coverage * cov, note = string.format("%d of %d content chunks explained", explained, total) }
  if #unexplained > 0 then
    h.factors[#h.factors + 1] = { name = "unexplained", v = W.unexplained * #unexplained, note = #unexplained .. " content chunk(s) not accounted for" }
  end
  local prior = FRAME_PRIOR[h.frame]
  if prior then h.factors[#h.factors + 1] = { name = "frame_prior", v = prior, note = "construction prior for " .. h.frame } end
  local s = 0
  for _, f in ipairs(h.factors) do s = s + f.v end
  h.score = s
  return h
end

-- NP objects are shared between competing hypotheses, so np.bound can belong to the last hypothesis finalised.  Rebinding the
-- winner restores its own bindings before anything is rendered or audited; factors added again are discarded (scores unchanged).
function H.rebind(S, ctx, h)
  local n = #h.factors
  local veto = h.veto
  bind_all(S, ctx, h)
  for i = #h.factors, n + 1, -1 do h.factors[i] = nil end
  h.veto = veto
end

---------------------------------------------------------------- selection
local function hyp_signature(S, h)
  local parts = { h.intent or "?", h.op or "?", h.rel or "-", h.ask or "-", h.polarity or "+" }
  for _, role in ipairs({ "from", "to", "subject" }) do
    local np = h.roles[role]
    if np then
      -- resolved entities compare by id; open-set mentions by their normalised text (the same name under two segmentations is one reading)
      local id = np.bound and np.bound.top and np.bound.top.id
      if not id or id:sub(1, 8) == "mention:" then id = P.core_text(S, np) end
      parts[#parts + 1] = role .. "=" .. id
    end
  end
  local obj = h.concept or h.target or h.focus or h.object
  if obj then
    -- same words + same semantic type == same reading, regardless of how the lattice segmented them
    local ty = obj.bound and (obj.bound.type or (obj.bound.senses and obj.bound.senses[1] and obj.bound.senses[1].type))
    parts[#parts + 1] = "obj=" .. P.core_text(S, obj) .. ":" .. tostring(ty)
  end
  for _, it in ipairs(h.items or {}) do parts[#parts + 1] = "item=" .. (it.head and it.head.form or "?") end
  if h.instruction then parts[#parts + 1] = "inst=" .. tostring(h.instruction.verb) .. ":" .. tostring(h.instruction.slot) end
  if h.clause then parts[#parts + 1] = "clause=" .. tostring(h.clause.lemma) end
  if h.statement then parts[#parts + 1] = "stmt=" .. tostring(h.statement.lemma) end
  return table.concat(parts, "|")
end

local function summarize(S, h)
  local function np_text(np) return np and P.span_text(S, np) or nil end
  local t = {}
  if h.rel then t[#t + 1] = h.rel end
  if h.known_role and h.roles[h.known_role] then t[#t + 1] = h.known_role .. "=" .. np_text(h.roles[h.known_role]) end
  if h.ask then t[#t + 1] = "ask=" .. h.ask end
  local obj = h.concept or h.target or h.focus or h.object or h.subject
  if obj then t[#t + 1] = "obj=" .. np_text(obj) end
  return (h.intent or "?") .. ": " .. table.concat(t, " ")
end
H.summarize = summarize

-- ranks finalised hypotheses; returns {ranked, rejected, top, posterior...}
function H.select(S, ctx, hyps)
  local W = H.W
  local live, rejected = {}, {}
  for _, h in ipairs(hyps) do
    if h.veto then rejected[#rejected + 1] = h else live[#live + 1] = h end
  end
  -- merge duplicates by signature, keep the best score and remember the other frames that agreed
  table.sort(live, function(a, b)
    if a.score ~= b.score then return a.score > b.score end
    return (a.frame or "") < (b.frame or "")
  end)
  local merged, seen = {}, {}
  for _, h in ipairs(live) do
    h.sig = hyp_signature(S, h)
    -- readings that are indistinguishable once summarised (same intent, relation, arguments, constraints) are ONE reading however many frames produced them
    local key = h.sig .. "\1" .. summarize(S, h)
    local m = seen[key]
    if m then m.agreeing_frames[#m.agreeing_frames + 1] = h.frame
    else h.agreeing_frames = {}; seen[key] = h; merged[#merged + 1] = h end
  end
  local ps = softmax(U.map(merged, function(h) return h.score end), (ctx.temperature or W.temperature))
  for i, h in ipairs(merged) do h.p = ps[i]; h.summary = summarize(S, h) end
  return { ranked = merged, rejected = rejected }
end

-- ambiguity points between the top hypothesis and its serious competitors + unresolved entity bindings inside the top hypothesis
function H.ambiguity(S, ctx, sel)
  local W = H.W
  local points = {}
  local top = sel.ranked[1]
  if not top then return { state = "unresolvable", points = points } end
  local function np_roles(h)
    local out = {}
    for _, role in ipairs({ "from", "to", "subject" }) do if h.roles[role] then out[role] = h.roles[role] end end
    if h.concept then out.concept = h.concept end
    if h.focus then out.focus = h.focus end
    if h.target then out.target = h.target end
    return out
  end
  -- (1) unresolved entity candidates inside the winning hypothesis
  for role, np in pairs(np_roles(top)) do
    local b = np.bound
    if b and b.status == "ambiguous" then
      local cands = {}
      for _, c in ipairs(b.cands) do if c.p >= 0.08 then cands[#cands + 1] = { id = c.id, type = c.type, p = c.p, reasons = c.reasons } end end
      points[#points + 1] = { id = "entity:" .. P.span_text(S, np), kind = "entity", role = role, mention = P.span_text(S, np), material = true, resolved = false,
        candidates = cands, rejected = U.map(b.rejected or {}, function(r) return { id = r.id, reason = r.reasons[#r.reasons] } end) }
    elseif b and b.status == "resolved" and b.top and #b.cands > 1 then
      points[#points + 1] = { id = "entity:" .. P.span_text(S, np), kind = "entity", role = role, mention = P.span_text(S, np), material = true, resolved = true,
        chosen = b.top.id, candidates = U.map(b.cands, function(c) return { id = c.id, type = c.type, p = c.p } end),
        rejected = U.map(b.rejected or {}, function(r) return { id = r.id, reason = r.reasons[#r.reasons] } end) }
    end
  end
  -- (2) competing hypotheses that differ in relation / intent / sense
  local function obj_type(h)
    local obj = h.concept or h.target or h.focus or h.object
    return obj and obj.bound and (obj.bound.type or (obj.bound.senses and obj.bound.senses[1] and obj.bound.senses[1].type)) or nil
  end
  for i = 2, #sel.ranked do
    local alt = sel.ranked[i]
    -- the same reading with a weaker lexical grounding (e.g. the word read as untyped instead of as the typed noun) is not a competing MEANING
    local same_reading = alt.summary == top.summary and alt.intent == top.intent and alt.rel == top.rel
    if same_reading then
      local ta, tb = obj_type(top), obj_type(alt)
      same_reading = (ta == nil or tb == nil or ta == tb)
    end
    if alt.p >= 0.12 and not same_reading then
      local kind
      if alt.rel ~= top.rel then kind = "relation"
      elseif alt.intent ~= top.intent then kind = "intent"
      elseif alt.ask ~= top.ask then kind = "role_direction"
      else kind = "sense" end
      points[#points + 1] = { id = "hyp:" .. i, kind = kind, material = true, resolved = (top.p >= W.resolve_p and (top.p - alt.p) >= W.resolve_margin),
        chosen = top.summary, candidates = { { summary = top.summary, p = top.p }, { summary = alt.summary, p = alt.p } } }
    end
  end
  local state = "resolved"
  for _, pt in ipairs(points) do if pt.material and not pt.resolved then state = "ambiguous" end end
  if (top.p < W.resolve_p or (sel.ranked[2] and top.p - sel.ranked[2].p < W.resolve_margin)) and sel.ranked[2] and sel.ranked[2].p >= 0.2 then
    local hasHyp = false
    for _, pt in ipairs(points) do if pt.kind ~= "entity" and not pt.resolved then hasHyp = true end end
    if hasHyp then state = "ambiguous" end
  end
  return { state = state, points = points }
end

return H

end

package.preload["asi.nlu.index"] = function(...)
-- asi.nlu.index: layered, incrementally updatable retrieval index.
--   1. exact entity postings         entity key -> records that MENTION it (identity, not substring)
--   2. phrase-aware field-weighted lexical postings (BM25F) with positions
--   3. typed assertion store         (relation, subject key) / (relation, object key) -> assertions extracted from records
--   4. metadata / time filters
-- BM25F is ONE component; semantic verification (asi.nlu.verify) decides whether a candidate actually supports the interpreted request.
local U = require("asi.nlu.util")
local TU = require("asi.nlu.textutil")

local X = {}
X.__index = X

X.FIELD_WEIGHT = { title = 2.2, name = 2.2, headline = 2.2, heading = 2.0, section = 1.4, text = 1.0, body = 1.0, summary = 1.2, abstract = 1.2, tags = 1.3 }
local K1, B = 1.2, 0.75

function X.new(opts)
  opts = opts or {}
  local self = setmetatable({}, X)
  self.docs, self.doc_of, self.n, self.live = {}, {}, 0, 0
  self.terms = {}                -- term -> { [doc] = { [field] = tf } }
  self.positions = {}            -- term -> { [doc] = { pos... } }  (field offsets baked into the position)
  self.df = {}
  self.len = {}                  -- field -> { [doc] = length }
  self.total_len, self.field_count = {}, {}
  self.entity_post = {}          -- key -> { [doc] = n }
  self.assertions = {}           -- list (index = assertion id)
  self.by_from, self.by_to, self.by_any = {}, {}, {}
  self.classes = {}              -- subject key -> list of classification assertion ids
  self.meta = {}                 -- field -> value -> { [doc] = true }
  self.revision = 0
  self.weights = opts.field_weight or X.FIELD_WEIGHT
  return self
end

local function fw(self, field) return self.weights[field] or self.weights[field:lower()] or 1.0 end

---------------------------------------------------------------- adding / removing documents
-- doc: the dataset record; analysis: result of assertions:extract (may be nil for metadata-only records)
function X:add(rec, analysis)
  if self.doc_of[rec.id] then self:remove(rec.id) end
  self.n = self.n + 1
  local d = self.n
  self.docs[d] = { id = rec.id, rec = rec, terms = {}, entities = {}, assertions = {}, meta = {} }
  self.doc_of[rec.id] = d
  self.live = self.live + 1
  local offset = 0
  local fields = rec.text_fields
  if not fields or #fields == 0 then fields = {} end
  for fi, f in ipairs(fields) do
    local text = rec.field_text and rec.field_text[f] or ""
    local toks = TU.tokens(text)
    local per = {}
    for _, t in ipairs(toks) do
      local term = t.t
      local ft = self.terms[term]
      if not ft then ft = {}; self.terms[term] = ft end
      local dt = ft[d]
      if not dt then dt = {}; ft[d] = dt; self.df[term] = (self.df[term] or 0) + 1; self.docs[d].terms[#self.docs[d].terms + 1] = term end
      dt[f] = (dt[f] or 0) + 1
      local pt = self.positions[term]
      if not pt then pt = {}; self.positions[term] = pt end
      local pl = pt[d]
      if not pl then pl = {}; pt[d] = pl end
      pl[#pl + 1] = offset + t.pos
      per[#per + 1] = t
    end
    offset = offset + 10000
    self.len[f] = self.len[f] or {}
    self.len[f][d] = #toks
    self.total_len[f] = (self.total_len[f] or 0) + #toks
    self.field_count[f] = (self.field_count[f] or 0) + 1
  end
  for k, v in pairs(rec.meta or {}) do
    local sv = tostring(v):lower()
    self.meta[k] = self.meta[k] or {}
    self.meta[k][sv] = self.meta[k][sv] or {}
    self.meta[k][sv][d] = true
    self.docs[d].meta[#self.docs[d].meta + 1] = { k, sv }
  end
  if analysis then
    local seen = {}
    for _, m in ipairs(analysis.mentions) do
      local key = m.key
      if not seen[key] then
        seen[key] = true
        local ep = self.entity_post[key]
        if not ep then ep = {}; self.entity_post[key] = ep end
        ep[d] = (ep[d] or 0) + 1
        self.docs[d].entities[#self.docs[d].entities + 1] = key
      end
    end
    for _, a in ipairs(analysis.assertions) do self:add_assertion(d, a) end
    self.docs[d].reader_directed = analysis.reader_directed
    self.docs[d].aliases = analysis.aliases
  end
  self.revision = self.revision + 1
  return d
end

function X:add_assertion(d, a)
  a.doc = d
  a.record = self.docs[d].id
  local id = #self.assertions + 1
  a.id = id
  self.assertions[id] = a
  self.docs[d].assertions[#self.docs[d].assertions + 1] = id
  local function post(map, key)
    if not key then return end
    local l = map[key]
    if not l then l = {}; map[key] = l end
    l[#l + 1] = id
  end
  if a.is_class then
    if a.from and a.from.key then post(self.classes, a.from.key) end
    return
  end
  local from_keys, to_keys = {}, {}
  if a.from then
    if a.from.key then from_keys[1] = a.from.key end
    for _, c in ipairs(a.from.cands or {}) do from_keys[#from_keys + 1] = c.id end
  end
  if a.to and not a.to.literal then
    if a.to.key then to_keys[1] = a.to.key end
    for _, c in ipairs(a.to.cands or {}) do to_keys[#to_keys + 1] = c.id end
  end
  for _, k in ipairs(from_keys) do post(self.by_from, a.rel .. "|" .. k); post(self.by_any, k) end
  for _, k in ipairs(to_keys) do post(self.by_to, a.rel .. "|" .. k); post(self.by_any, k) end
end

function X:remove(id)
  local d = self.doc_of[id]
  if not d then return false end
  local doc = self.docs[d]
  for _, term in ipairs(doc.terms) do
    if self.terms[term] then
      self.terms[term][d] = nil
      self.positions[term][d] = nil
      self.df[term] = math.max(0, (self.df[term] or 1) - 1)
    end
  end
  for f, lens in pairs(self.len) do
    if lens[d] then
      self.total_len[f] = self.total_len[f] - lens[d]
      self.field_count[f] = self.field_count[f] - 1
      lens[d] = nil
    end
  end
  for _, key in ipairs(doc.entities) do if self.entity_post[key] then self.entity_post[key][d] = nil end end
  for _, m in ipairs(doc.meta) do if self.meta[m[1]] and self.meta[m[1]][m[2]] then self.meta[m[1]][m[2]][d] = nil end end
  for _, aid in ipairs(doc.assertions) do self.assertions[aid].removed = true end
  doc.removed = true
  self.doc_of[id] = nil
  self.live = self.live - 1
  self.revision = self.revision + 1
  return true
end

---------------------------------------------------------------- lookups
function X:record(d) return self.docs[d] and self.docs[d].rec end

-- live assertions of a list of ids
local function live(self, ids)
  local out = {}
  for _, id in ipairs(ids or {}) do
    local a = self.assertions[id]
    if a and not a.removed then out[#out + 1] = a end
  end
  return out
end

function X:assertions_from(rel, key) return live(self, self.by_from[rel .. "|" .. key]) end
function X:assertions_to(rel, key) return live(self, self.by_to[rel .. "|" .. key]) end
function X:assertions_about(key) return live(self, self.by_any[key]) end
function X:classifications(key) return live(self, self.classes[key]) end

function X:docs_mentioning(key)
  local out = {}
  for d in pairs(self.entity_post[key] or {}) do if self.docs[d] and not self.docs[d].removed then out[#out + 1] = d end end
  table.sort(out)
  return out
end

---------------------------------------------------------------- BM25F with optional phrase constraint
local function idf(self, term)
  local df = self.df[term] or 0
  return math.log(1 + (self.live - df + 0.5) / (df + 0.5))
end

-- do the stemmed terms occur consecutively in document d?  (positions carry a field offset, so a phrase never spans two fields)
function X:phrase_in(d, terms)
  if #terms == 0 then return false end
  local first = self.positions[terms[1]] and self.positions[terms[1]][d]
  if not first then return false end
  for _, p in ipairs(first) do
    local ok = true
    for i = 2, #terms do
      local pl = self.positions[terms[i]] and self.positions[terms[i]][d]
      local found = false
      if pl then for _, q in ipairs(pl) do if q == p + i - 1 then found = true break end end end
      if not found then ok = false break end
    end
    if ok then return true end
  end
  return false
end

-- query = { terms = {t...}, phrases = { {t1,t2}, ... } }; returns list {doc, score, matched_terms, phrases} sorted by score desc
function X:search(query, limit)
  local scores, hits = {}, {}
  for _, term in ipairs(query.terms or {}) do
    local postings = self.terms[term]
    if postings then
      local w = idf(self, term)
      for d, per_field in pairs(postings) do
        if not self.docs[d].removed then
          local tfn = 0
          for f, tf in pairs(per_field) do
            local avg = (self.total_len[f] or 1) / math.max(1, self.field_count[f] or 1)
            local len = (self.len[f] and self.len[f][d]) or avg
            tfn = tfn + fw(self, f) * tf / (1 - B + B * len / math.max(avg, 1e-9))
          end
          scores[d] = (scores[d] or 0) + w * tfn / (K1 + tfn)
          hits[d] = hits[d] or {}
          hits[d][#hits[d] + 1] = term
        end
      end
    end
  end
  local out = {}
  for d, s in pairs(scores) do
    local ph = {}
    for _, p in ipairs(query.phrases or {}) do if self:phrase_in(d, p) then ph[#ph + 1] = table.concat(p, " ") end end
    out[#out + 1] = { doc = d, score = s + 1.5 * #ph, lexical = s, matched = hits[d], phrases = ph }
  end
  table.sort(out, function(a, b) if a.score ~= b.score then return a.score > b.score end return a.doc < b.doc end)
  if limit and #out > limit then for i = #out, limit + 1, -1 do out[i] = nil end end
  return out
end

function X:stats()
  return { documents = self.live, terms = (function() local c = 0; for _ in pairs(self.terms) do c = c + 1 end return c end)(),
    assertions = (function() local c = 0; for _, a in ipairs(self.assertions) do if not a.removed then c = c + 1 end end return c end)(),
    entities = (function() local c = 0; for _ in pairs(self.entity_post) do c = c + 1 end return c end)(), revision = self.revision }
end

return X

end

package.preload["asi.nlu.interp"] = function(...)
-- asi.nlu.interp: the interpreter facade.  text -> lexical analysis -> lattice -> semantic hypotheses -> interpretation.
-- LM-independent, deterministic (no clock/randomness), metered (explicit `limited` status instead of silent guessing).
local U = require("asi.nlu.util")
local Lex = require("asi.nlu.lex")
local Lattice = require("asi.nlu.lattice")
local Sem = require("asi.nlu.sem")
local Resources = require("asi.nlu.resources")
local Memory = require("asi.nlu.memory")
local Coref = require("asi.nlu.coref")
local P = require("asi.nlu.parse")

local I = {}
I.__index = I
I.VERSION = "0.1.0"

function I.new(opts)
  opts = opts or {}
  local self = setmetatable({}, I)
  self.lex = opts.lexicon or Resources.core()
  self.flags = opts.flags or {}           -- ablation switches: no_types, no_domain, no_hypotheses, no_semantics, ...
  self.budget = opts.budget or 2000000    -- integer work units per call
  self.temperature = opts.temperature
  self.max_covers = opts.max_covers or 3
  self.calibration = opts.calibration
  return self
end

-- main sentence: the last question/request, else the last sentence
local function pick_main(rendered)
  local main
  for i, r in ipairs(rendered) do
    if r.speech_act == "question" or r.speech_act == "request" or r.speech_act == "instruction" or r.speech_act == "correction" then main = i end
  end
  return main or #rendered
end

-- scan a sentence's units for discourse cues that change how it is remembered
-- A stated decision is a decision VERB (decided, agreed, settled on, resolved, chose, picked, voted ...) with a collective or first-person subject nearby, or the
-- noun "decision" introducing the outcome ("Team decision: X for Y").  Closed word lists, no phrase templates.
local DECISION_VERBS = U.set({ "decided", "agreed", "settled", "resolved", "concluded", "determined", "opted", "committed", "chose", "chosen", "picked", "selected", "voted", "went" })
-- verbs that are also ordinary actions ("I picked up the kids", "we went to the lake"): they count only with a collective subject and without a particle
local WEAK_DECISION_VERBS = U.set({ "chose", "chosen", "picked", "selected", "voted", "went" })
local DECISION_PARTICLES = U.set({ "up", "out", "off", "over", "on", "through", "back", "down", "away", "around", "in" })
local DECISION_SUBJECTS = U.set({ "we", "our", "i", "us", "team", "group", "everyone", "engineers", "engineer", "committee", "board", "management", "company", "they", "squad", "staff",
  "leadership", "council", "all", "crew", "department", "organisation", "organization" })
local function decision_statement(an, ua, ub)
  for i = ua, ub do
    local f = an.units[i].form
    if DECISION_VERBS[f] then
      -- "went"/"go" only count as "went with" / "go with"; the others need a collective / first-person subject within the six words before
      if f == "went" then
        local nx = an.units[i + 1]
        if not (nx and nx.form == "with") then goto continue end
      end
      if WEAK_DECISION_VERBS[f] then
        local nx = an.units[i + 1]
        if nx and DECISION_PARTICLES[nx.form] then goto continue end
        for j = math.max(ua, i - 5), i - 1 do
          local sf = an.units[j].form
          if sf ~= "i" and DECISION_SUBJECTS[sf] then return true end
        end
        goto continue
      end
      for j = math.max(ua, i - 6), i - 1 do if DECISION_SUBJECTS[an.units[j].form] then return true end end
      -- "It was decided by the whole team that ...", "The decision was made ..."
      for j = math.max(ua, i - 3), i - 1 do if an.units[j].form == "was" or an.units[j].form == "been" or an.units[j].form == "is" then return true end end
    elseif f == "decision" then
      local nx, nx2 = an.units[i + 1], an.units[i + 2]
      if i > ua and an.units[i - 1].form ~= "the" and nx and nx.pre and (nx.pre:find("colon") or nx.pre:find("dash")) then return true end       -- "Team decision: ..."
      if nx and (nx.form == "is" or nx.form == "was") and nx2 and (nx2.form == "to" or (nx2.pre and nx2.pre:find("colon"))) then return true end
    end
    ::continue::
  end
  return false
end

local function sentence_cues(an, sent, lex)
  local cues = {}
  local ua, ub = Sem.sentence_unit_range(an, sent.id)
  if not ua then return cues end
  -- a question about a decision is not a decision
  if not sent.question_mark and decision_statement(an, ua, ub) then cues.decision = true end
  for i = ua, ub do
    local u = an.units[i]
    do
      if lex:cue_at("hedge", an.units, i) then cues.hedged = true end
      local rn = lex:cue_at("revoke", an.units, i)
      if rn and not cues.revoke then
        -- a revocation needs a TARGET: a slot noun ("the dataset instruction"), an instruction-class noun ("my last constraint"), or nothing but
        -- anaphora ("never mind." / "scratch that").  "Never mind the noise outside" revokes nothing.
        local rv = { bare = true }
        for k = i + rn, #an.units do
          local u = an.units[k]
          if u.sent ~= sent.id then break end
          local cats = lex:cats(u.form) or {}
          local closed = cats.det or cats.pron or cats.prep or cats.aux_be or cats.aux_do or cats.adv or cats.polite or cats.conj or cats.particle or u.kind ~= "word"
          local slot = lex:resource(u.form)
          if slot and slot ~= "year" then rv.slot = rv.slot or slot; rv.bare = false
          elseif lex:refclasses(u.form).correction then rv.class = true; rv.bare = false
          elseif not closed then rv.bare = false end
        end
        cues.revoke = rv
      end
      if lex:cue_at("additive", an.units, i) then cues.additive = true end
      if lex:cue_at("scoped", an.units, i) then cues.scoped = true end
      if lex:cue_at("decision", an.units, i) then cues.decision = true end
      if lex:cue_at("decision_ref", an.units, i) then cues.decision_ref = true end
    end
  end
  return cues
end

local function trim_selection(sel, max_excluded)
  local out = { selected = {}, excluded = {}, n_selected = #sel.selected, n_excluded = #sel.excluded }
  for _, c in ipairs(sel.selected) do
    local it = c.item
    out.selected[#out.selected + 1] = { id = it.id, kind = it.kind, layer = it.layer, turn = it.turn, speaker = it.speaker, status = it.status, slot = it.slot,
      value = it.value, text = (it.text or ""):sub(1, 200), score = U.round(c.score, 3), factors = c.factors, reliability = it.reliability }
  end
  for i, x in ipairs(sel.excluded) do
    if i > (max_excluded or 8) then break end
    out.excluded[#out.excluded + 1] = { id = x.item.id, kind = x.item.kind, turn = x.item.turn, reason = x.reason, text = (x.item.text or ""):sub(1, 120) }
  end
  return out
end

-- Interpret `text`.  call = { memory = <asi.nlu.memory>, speaker = "user"|"assistant"|"doc", now = <date>, budget = n, domains = {}, support = fn }
-- With a memory, pronouns / back-references / corrections resolve against it and every sentence is observed into it.
-- Without one, a transient memory covers references inside this single message.
function I:interpret(text, call)
  call = call or {}
  local meter = U.meter(call.budget or self.budget)
  local an = Lex.analyze(text, { spell = self.lex.spell, now = call.now, meter = meter, max_bytes = call.max_bytes })
  local result = { original = an.original, analysis = an, status = an.status, sentences = {} }
  if an.status == "rejected" then return result end
  local lat = Lattice.build(an, self.lex, { meter = meter })
  result.lattice = lat
  local flags = self.flags
  local mem = call.memory
  if not mem and not flags.no_memory then mem = Memory.new({ transient = true }) end
