package.preload["asi.nlu.knowledge"] = function(...)
-- asi.nlu.knowledge: a searchable knowledge base built from supplied datasets.
--   datasets (asi.nlu.dataset)  ->  assertion extraction (asi.nlu.assertions)  ->  index (asi.nlu.index)  +  a lexicon OVERLAY.
-- The overlay is how unseen terminology becomes usable without rewriting the interpreter: entities discovered in the data are registered with
-- the same keys the interpreter produces for open-set mentions, relations named by structured columns are induced from their names, and every
-- overlay item records the records that justified it.  Nothing is learned from the interpreter's own outputs (no self-reinforcement).
local U = require("asi.nlu.util")
local Lex = require("asi.nlu.lex")
local Lattice = require("asi.nlu.lattice")
local P = require("asi.nlu.parse")
local Lexicon = require("asi.nlu.lexicon")
local Dataset = require("asi.nlu.dataset")
local Index = require("asi.nlu.index")
local Assertions = require("asi.nlu.assertions")
local UC = require("asi.nlu.unicode")

local K = {}
K.__index = K
K.SCHEMA = "nlu.knowledge/1"

function K.new(base_lex, opts)
  opts = opts or {}
  local self = setmetatable({}, K)
  self.base = base_lex
  self.lex = Lexicon.new(base_lex)
  self.lex.spell = self.lex:build_spell(base_lex.spell)
  self.datasets, self.dataset_order = {}, {}
  self.index = Index.new()
  self.meter_budget = opts.record_budget or 400000
  self.vocab = {}            -- mention key -> { text, count, records = {id...}, types = {type -> n}, class_votes = {...} }
  self.aliases = {}          -- folded alias -> { key, evidence = {record ids} }  (an alias is accepted only when the data itself states it)
  self.alias_keys = {}       -- canonical key -> { mention keys that denote it }
  self.rel_induced = {}      -- relation id -> { name, records }
  self.reader_directed = {}  -- record id -> list of flagged sentences
  self.revision = 0
  self.errors = {}
  return self
end

---------------------------------------------------------------- linking short strings (titles, triple cells)
local function fold(s) return UC.fold(s):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "") end

function K:link_text(text, expected)
  local an = Lex.analyze(text, {})
  if an.status == "rejected" or #an.units == 0 then return { text = text, key = "mention:" .. fold(text), status = "unseen", unverified_link = true } end
  local lat = Lattice.build(an, self.lex, {})
  local cover = lat:covers(1, 1, #an.units)[1]
  if cover then
    local S = P.new_state(an, self.lex, lat, cover, { flags = {} })
    S.sentence = an.sentences[1]
    for _, np in ipairs(P.parse_np(S, 1)) do
      if np.nxt > #S.chunks then
        local d = Assertions.describe_np(S, { flags = {} }, np, expected, "link")
        if d.key or d.literal or d.cands then return d end
      end
    end
  end
  return { text = text, key = "mention:" .. fold(text), status = "unseen", unverified_link = true }
end

---------------------------------------------------------------- per-record indexing
local function topic_of(self, rec)
  for _, f in ipairs(rec.text_fields or {}) do
    local lf = f:lower()
    if lf == "title" or lf == "name" or lf == "headline" or lf == "heading" then
      local d = self:link_text(rec.field_text[f])
      if d.key and not d.unverified_link then return d end
    end
  end
end

function K:index_record(rec)
  local analysis = { assertions = {}, mentions = {}, aliases = {}, reader_directed = {}, sentences = 0 }
  if rec.duplicate_of then
    -- duplicates stay searchable but never corroborate: no assertions, flagged
    self.index:add(rec, analysis)
    return analysis
  end
  local meter = U.meter(self.meter_budget)
  local ex = Assertions.new(self.lex, { meter = meter })
  local topic = topic_of(self, rec)
  for _, f in ipairs(rec.text_fields or {}) do
    local text = rec.field_text[f]
    if text and text ~= "" then
      local r = ex:extract(text, { topic = topic })
      for _, a in ipairs(r.assertions) do a.field = f; a.reliability = rec.reliability; analysis.assertions[#analysis.assertions + 1] = a end
      for _, m in ipairs(r.mentions) do m.field = f; analysis.mentions[#analysis.mentions + 1] = m end
      for _, al in ipairs(r.aliases) do analysis.aliases[#analysis.aliases + 1] = al end
      for _, rd in ipairs(r.reader_directed) do rd.field = f; analysis.reader_directed[#analysis.reader_directed + 1] = rd end
      analysis.sentences = analysis.sentences + r.sentences
      if r.limited then analysis.limited = true end
    end
  end
  if topic and topic.key then analysis.mentions[#analysis.mentions + 1] = { key = topic.key, type = topic.type, text = topic.text, field = "title", topic = true } end
  -- structured triple rows are explicit assertions (highest precision, still tagged with their provenance)
  if rec.triple then
    local t = rec.triple
    local rel = self.lex:rel_by_name(t.relation)
    local induced = false
    if not rel then
      local norm = t.relation:lower():gsub("[%s%-]+", "_"):gsub("[^%w_]", "")
      -- a relation named only by the data lives in the same "open:" namespace as relations inferred from unknown words in text or questions
      rel = self.lex:induce_relation(norm, { id = "open:" .. norm:gsub("e$", ""), source = "induced" })
      induced = true
      self.rel_induced[rel.id] = self.rel_induced[rel.id] or { name = t.relation, records = {} }
      table.insert(self.rel_induced[rel.id].records, rec.id)
    end
    local from = self:link_text(t.subject, rel.from)
    local to = self:link_text(t.object, rel.to)
    analysis.assertions[#analysis.assertions + 1] = { rel = rel.id, from = from, to = to, polarity = t.polarity or "positive", modality = "asserted", tense = "present",
      pattern = "structured_triple", structured = true, induced_relation = induced or nil, text = rec.text, sent = 0, s = 1, e = #rec.text, reliability = rec.reliability }
    for _, d in ipairs({ from, to }) do
      if d.key and not d.literal then analysis.mentions[#analysis.mentions + 1] = { key = d.key, type = d.type, text = d.text, field = "triple" } end
    end
  end
  -- vocabulary + alias evidence
  for _, m in ipairs(analysis.mentions) do
    if m.key and m.key:sub(1, 8) == "mention:" and not m.weak then
      local v = self.vocab[m.key]
      if not v then v = { text = m.text, count = 0, records = {}, seen = {}, types = {}, class_votes = {} }; self.vocab[m.key] = v end
      v.count = v.count + 1
      if not v.seen[rec.id] then v.seen[rec.id] = true; v.records[#v.records + 1] = rec.id end
      if m.type then v.types[m.type] = (v.types[m.type] or 0) + 1 end
    end
  end
  for _, a in ipairs(analysis.assertions) do
    if a.is_class and a.from and a.from.key and self.vocab[a.from.key] and a.class_type then
      local v = self.vocab[a.from.key]
      v.class_votes[a.class_type] = (v.class_votes[a.class_type] or 0) + 1
    end
    -- role-signature type evidence for unseen participants
    if not a.is_class and a.rel then
      local rel = self.lex:get_rel(a.rel)
      for _, role in ipairs({ "from", "to" }) do
        local d = a[role]
        if rel and d and d.key and d.key:sub(1, 8) == "mention:" and self.vocab[d.key] and not d.literal then
          local v = self.vocab[d.key]
          v.sig_votes = v.sig_votes or {}
          v.sig_votes[rel[role]] = (v.sig_votes[rel[role]] or 0) + 1
        end
      end
    end
  end
  for _, al in ipairs(analysis.aliases) do
    local fa = fold(al.alias)
    local e = self.aliases[fa]
    if not e then e = { key = al.key, evidence = {} }; self.aliases[fa] = e end
    if e.key == al.key then
      e.evidence[#e.evidence + 1] = rec.id
      local list = self.alias_keys[al.key]
      if not list then list = {}; self.alias_keys[al.key] = list end
      local mk = "mention:" .. fa
      local dup = false
      for _, x in ipairs(list) do if x == mk then dup = true end end
      if not dup then list[#list + 1] = mk end
    else e.conflict = true end
  end
  if #analysis.reader_directed > 0 then self.reader_directed[rec.id] = analysis.reader_directed end
  self.index:add(rec, analysis)
  return analysis
end

---------------------------------------------------------------- overlay: dataset-discovered entities
local function best_vote(votes)
  local best, bn
  for t, n in pairs(votes or {}) do if not bn or n > bn or (n == bn and t < best) then best, bn = t, n end end
  return best, bn
end

function K:refresh_overlay()
  local added = 0
  for key, v in pairs(self.vocab) do
    if not self.lex.entities[key] and not self.base:get_entity(key) then
      local ty = best_vote(v.class_votes) or best_vote(v.types) or best_vote(v.sig_votes) or "entity"
      if not self.lex:has_type(ty) then ty = "entity" end
      local names = { { text = v.text, cs = false } }
      self.lex:add_entity({ id = key, type = ty, names = names, domain = {}, prior = 0.4, attr = {}, source = "dataset",
        evidence = { records = #v.records, mentions = v.count } })
      added = added + 1
    end
  end
  for fa, al in pairs(self.aliases) do
    if not al.conflict and not al.registered then
      local target = self.lex:get_entity(al.key)
      if target then
        self.lex:add_entity({ id = "alias:" .. fa, type = target.type, names = { { text = fa, cs = false } }, domain = target.domain, prior = 0.4, attr = {}, source = "dataset_alias",
          alias_of = al.key, evidence = al.evidence })
        al.registered = true
        added = added + 1
      end
    end
  end
  if added > 0 then self.lex.spell = self.lex:build_spell(self.base.spell) end
  return added
end

---------------------------------------------------------------- public API
-- opts: { dataset = id, version, label = {year=}, format, name, mapping }
function K:ingest(text, opts)
  opts = opts or {}
  local did = opts.dataset or "dataset"
  local ds = self.datasets[did]
  if not ds then
    ds = Dataset.new({ id = did, version = opts.version, label = opts.label })
    self.datasets[did] = ds
    self.dataset_order[#self.dataset_order + 1] = did
  end
  local report = ds:ingest(text, opts)
  local n_assert, n_flag = 0, 0
  for _, rec in ipairs(report.records or {}) do
    if self.datasets[did].records[rec.id] == rec then
      local an = self:index_record(rec)
      n_assert = n_assert + #an.assertions
      n_flag = n_flag + #an.reader_directed
    end
  end
  self.revision = self.revision + 1
  report.assertions = n_assert
  report.reader_directed = n_flag
  report.overlay_added = self:refresh_overlay()
  report.records = nil   -- the per-record table stays inside the dataset
  return report
end

function K:remove(record_id)
  local did = record_id:match("^([^:]+):")
  local ds = did and self.datasets[did]
  if not ds then return false end
  ds:remove(record_id)
  self.index:remove(record_id)
  self.revision = self.revision + 1
  return true
end

-- every key under which the data may refer to the same thing (canonical key + evidence-backed aliases)
function K:variants(key)
  local out = { key }
  for _, k in ipairs(self.alias_keys[key] or {}) do out[#out + 1] = k end
  return out
end

function K:canonical(key)
  local e = self.lex:get_entity(key)
  if e and e.alias_of then return e.alias_of end
  if key:sub(1, 8) == "mention:" then
    local al = self.aliases[key:sub(9)]
    if al and not al.conflict then return al.key end
  end
  return key
end

-- a stable key for caches: changes whenever any dataset record, the overlay, or the schema version changes
function K:digest()
  local parts = { K.SCHEMA }
  for _, did in ipairs(self.dataset_order) do parts[#parts + 1] = self.datasets[did]:digest() end
  parts[#parts + 1] = tostring(self.index.revision)
  return U.sha256(table.concat(parts, "|"))
end

function K:record(id)
  local did = id:match("^([^:]+):")
  return did and self.datasets[did] and self.datasets[did].records[id]
end

-- is `ds` the dataset a constraint such as "the 2020 dataset" refers to?
function K:dataset_label_of(rec)
  local ds = self.datasets[rec.dataset]
  return ds and ds.label or nil
end

-- terminology report: unfamiliar terms in the supplied data, what the data says about them, and whether their meaning is ambiguous
function K:terminology(limit)
  local out = {}
  for key, v in pairs(self.vocab) do
    local entry = { key = key, text = v.text, mentions = v.count, records = #v.records, kind = "entity" }
    entry.types = {}
    for t, n in pairs(v.class_votes) do entry.types[#entry.types + 1] = { type = t, evidence = "classification", n = n } end
    for t, n in pairs(v.types) do entry.types[#entry.types + 1] = { type = t, evidence = "mention", n = n } end
    table.sort(entry.types, function(a, b) if a.n ~= b.n then return a.n > b.n end return a.type < b.type end)
    entry.ambiguous = (best_vote(v.class_votes) ~= nil) and (function() local c = 0; for _ in pairs(v.class_votes) do c = c + 1 end return c > 1 end)() or nil
    local defs = {}
    for _, a in ipairs(self.index:classifications(key)) do defs[#defs + 1] = { class = a.class_text, record = a.record, text = a.text } end
    entry.definitions = defs
    out[#out + 1] = entry
  end
  table.sort(out, function(a, b) if a.mentions ~= b.mentions then return a.mentions > b.mentions end return a.key < b.key end)
  if limit and #out > limit then for i = #out, limit + 1, -1 do out[i] = nil end end
  return out
end

function K:stats()
  local s = self.index:stats()
  s.datasets = #self.dataset_order
  s.vocabulary = (function() local c = 0; for _ in pairs(self.vocab) do c = c + 1 end return c end)()
  s.induced_relations = (function() local c = 0; for _ in pairs(self.rel_induced) do c = c + 1 end return c end)()
  s.reader_directed_records = (function() local c = 0; for _ in pairs(self.reader_directed) do c = c + 1 end return c end)()
  s.digest = self:digest()
  return s
end

return K

end

package.preload["asi.nlu.lattice"] = function(...)
-- asi.nlu.lattice: phrase + entity recognition as a LATTICE of competing spans over the lexer's units.
-- Nothing is committed here: every attested reading of every span is kept, and a k-best dynamic program
-- proposes alternative non-overlapping covers (segmentations) for the semantic stage to compete over.
local U = require("asi.nlu.util")
local UC = require("asi.nlu.unicode")

local Lattice = {}

local NAME_CONNECTORS = U.set({ "of", "de", "van", "von", "der", "la", "le", "du", "di", "da", "del", "for", "the", "&", "den", "al", "bin" })
local TITLE_PREFIX = U.set({ "dr", "mr", "mrs", "ms", "prof", "sir", "lady", "lord", "president", "senator", "gen", "col", "capt", "rev" })

local function span_key(i, j) return i .. ":" .. j end

-- a word the lexicon knows as an ordinary word (function word, verb, adjective, relational/type noun) -- not a name
local function is_common(lex, u)
  local f = u.form
  if lex:cats(f) then return true end
  for _, r in ipairs(lex:readings(f)) do if r.pos == "verb" or r.pos == "adj" then return true end end
  local has_entity, has_word = false, false
  for _, m in ipairs(lex:match_at({ u }, 1)) do
    if m.j == 1 then
      for _, e in ipairs(m.entries) do
        if e.kind == "entity" then has_entity = true else has_word = true end
      end
    end
  end
  return has_word and not has_entity
end

local function joined_forms(units, i, j)
  local t = {}
  for k = i, j do t[#t + 1] = units[k].form end
  return table.concat(t, " ")
end

local function joined_raw(units, i, j)
  local t = {}
  for k = i, j do t[#t + 1] = units[k].raw end
  return table.concat(t, " ")
end

-- does the surface text honour the entry's case sensitivity? (US vs us)
local function cs_ok(units, i, j, entry)
  if not entry.cs then return true end
  local want = entry.name:gsub("%.", ""):gsub("%s+", "")
  local have = joined_raw(units, i, j):gsub("%.", ""):gsub("%s+", "")
  return want == have
end

local function case_exact(units, i, j, entry)
  return joined_raw(units, i, j):gsub("%.", "") == entry.name:gsub("%.", "")
end

---------------------------------------------------------------- build
function Lattice.build(an, lex, opts)
  opts = opts or {}
  local units = an.units
  local n = #units
  local spans, by_ext = {}, {}
  local meter = opts.meter

  local function add(i, j, reading, kind, score)
    local key = span_key(i, j)
    local sp = by_ext[key]
    if not sp then
      sp = { i = i, j = j, readings = {}, kind = kind, score = score, text = an.original:sub(units[i].s, units[j].e) }
      by_ext[key] = sp
      spans[#spans + 1] = sp
    end
    -- one reading per entity id (several names of one entity may match the same extent): keep the best-matching one
    if reading.kind == "entity" then
      for idx, r in ipairs(sp.readings) do
        if r.kind == "entity" and r.entry.id == reading.entry.id and not r.fuzzy == not reading.fuzzy then
          if reading.exact_case and not r.exact_case then sp.readings[idx] = reading end
          return sp
        end
      end
    end
    sp.readings[#sp.readings + 1] = reading
    if score > sp.score then sp.score = score; sp.kind = kind end
    return sp
  end

  -- 1. attested spans from the phrase trie (core lexicon + dataset overlay)
  for i = 1, n do
    if meter and not meter:tick("lattice_match", 1) then break end
    for _, m in ipairs(lex:match_at(units, i)) do
      local len = m.j - i + 1
      for _, e in ipairs(m.entries) do
        if e.kind == "entity" then
          if cs_ok(units, i, m.j, e) then
            local exact = case_exact(units, i, m.j, e)
            add(i, m.j, { kind = "entity", entry = e, exact_case = exact }, "entity", 2.0 + 0.5 * (len - 1) + (exact and 0.2 or 0))
          end
        elseif e.kind == "sense" then
          local sc = (len > 1) and (1.8 + 0.5 * (len - 1)) or 0.4
          local sp = add(i, m.j, { kind = "sense", sense = e.sense, num = e.num }, len > 1 and "mwe" or "word_sense", sc)
        elseif e.kind == "relnoun" then
          add(i, m.j, { kind = "relnoun", entry = e }, len > 1 and "mwe" or "word_sense", (len > 1) and (1.6 + 0.4 * (len - 1)) or 0.6)
        elseif e.kind == "relverb" then
          add(i, m.j, { kind = "relverb", entry = e }, len > 1 and "mwe" or "word_sense", (len > 1) and (1.6 + 0.4 * (len - 1)) or 0.5)
        elseif e.kind == "actverb" then
          add(i, m.j, { kind = "actverb", entry = e }, "mwe", 1.6 + 0.4 * (len - 1))
        end
      end
    end
  end

  -- 2. temporal expressions and numbers (typed spans keep dates from being split into words)
  for _, t in ipairs(an.temporal or {}) do
    if t.u1 and t.u2 and t.kind ~= "weekday" then
      add(t.u1, t.u2, { kind = "temporal", expr = t }, "temporal", 1.0 + 0.3 * (t.u2 - t.u1))
    end
  end
  for _, nm in ipairs(an.numbers or {}) do
    if nm.kind ~= "digit" or nm.u2 > nm.u1 then
      add(nm.u1, nm.u2, { kind = "number", num = nm }, "number", 0.9 + 0.2 * (nm.u2 - nm.u1))
    end
  end

  -- 3. atomic literals: identifiers, URLs, paths, handles, versions
  for i = 1, n do
    local u = units[i]
    if u.case_sensitive and not u.hy then
      add(i, i, { kind = "literal", unit = u }, "literal", 1.5)
    end
  end

  -- 4. quoted strings (titles, exact phrases)
  do
    local toks = an.tokens
    local tok2unit = {}
    for ui, u in ipairs(units) do tok2unit[u.tok] = tok2unit[u.tok] or ui end
    local k = 1
    while k <= #toks do
      local t = toks[k]
      if t.kind == "punct" and (t.role == "open_quote" or t.role == "quote") and not t.single then
        local close
        for z = k + 1, math.min(#toks, k + 14) do
          local c = toks[z]
          if c.kind == "punct" and (c.role == "close_quote" or c.role == "quote") and not c.single then close = z break end
          if c.kind == "punct" and c.role == "sent_end" then break end
        end
        if close and close > k + 1 then
          local a, b
          for z = k + 1, close - 1 do
            if tok2unit[toks[z].i] then a = a or tok2unit[toks[z].i]; b = tok2unit[toks[z].i] end
          end
          if a and b then
            local ub = b
            while units[ub + 1] and units[ub + 1].tok == units[b].tok do ub = ub + 1 end
            add(a, ub, { kind = "quote", text = an.original:sub(units[a].s, units[ub].e) }, "quote", 1.4 + 0.1 * (ub - a))
          end
          k = close
        end
      end
      k = k + 1
    end
  end

  -- 5. unseen proper names (open-set): capitalised runs typed by head words
  local function sentence_initial(u) return u.i == 1 or units[u.i - 1].sent ~= u.sent end
  local i = 1
  while i <= n do
    local u = units[i]
    local sent = an.sentences[u.sent or 0]
    local shout = sent and sent.shout
    local capital = u.cap and not shout and (u.kind == "word" or u.kind == "abbrev" or u.kind == "acronym" or u.kind == "initial") and not u.case_sensitive
    local initial = capital and sentence_initial(u)
    local common = capital and is_common(lex, u)
    -- "Compare", "Did", "Is" ... are capitalised only by position: they must not swallow the names that follow them
    if capital and not (initial and common) then
      local j = i
      -- connectors ("of", "for", ...) join a name only after an organisation/place head word ("University of X", "Bank of X"),
      -- never after an ordinary common word ("CEO of Acme": CEO is a relational noun, not the start of a name)
      local connect_ok = lex:headcue(u.form) ~= nil or not common
      -- extend over capitalised units and name connectors (never "and")
      while true do
        local nx = units[j + 1]
        if not nx or nx.pre or nx.sent ~= u.sent then break end
        if nx.cap and not shout and (nx.kind == "word" or nx.kind == "abbrev" or nx.kind == "acronym" or nx.kind == "initial" or nx.kind == "number") then j = j + 1
        elseif NAME_CONNECTORS[nx.form] and not nx.cap and connect_ok then
          local nn = units[j + 2]
          if nn and not nn.pre and nn.cap and nn.sent == u.sent then j = j + 2 else break end
        else break end
      end
      local multi = j > i
      local last = units[j]
      local type_guess = lex:headcue(last.form) or lex:headcue(u.form) or (TITLE_PREFIX[u.form] and "person") or nil
      local sc = 0.8 + 0.3 * (j - i)
      -- "West Germany", "Northern Ireland": a capitalised modifier + an attested entity is a DIFFERENT, open-set entity of the attested one's type
      local extends
      if multi and not type_guess and not TITLE_PREFIX[u.form] then
        for _, m in ipairs(lex:match_at(units, j)) do
          for _, e in ipairs(m.entries) do
            if e.kind == "entity" and m.j == j then extends = e end
          end
        end
        if extends then type_guess = extends.etype; sc = sc + 1.7 end
      end
      local ok = true
      if initial and not multi and not type_guess and not u.hy then
        -- sentence-initial single unknown word: weak name guess only if the lexicon has never seen the word
        if is_common(lex, u) then ok = false else sc = 0.45 end
      end
      if common and not multi and not initial and u.form ~= "i" then
        -- a known common word capitalised mid-sentence ("Apple" is handled by the gazetteer; "Is" after a colon is not a name)
        sc = 0.55
      end
      if u.form == "i" then ok = false end
      if ok then
        -- capitalisation is the ONLY evidence for a sentence-initial single word: flagged so memory does not treat it as an established entity
        local weak = (initial and not multi and not type_guess) or nil
        add(i, j, { kind = "name", type_guess = type_guess, text = an.original:sub(units[i].s, units[j].e), multiword = multi, weak = weak,
          head_cue = (lex:headcue(last.form) or lex:headcue(u.form)) and true or nil }, "name_guess", sc)
      end
      i = j + 1
    else
      i = i + 1
    end
  end

  -- 5b. case-less text ("who founded acme robotics"): capitalisation carries no information, so a run of words unknown to the lexicon that ends in an
  --     organisation / place HEAD WORD (robotics, labs, industries, university, ...) is a name guess typed by that head word.  Weak by construction.
  do
    local nocase = {}
    for _, u in ipairs(units) do
      if u.sent then
        if nocase[u.sent] == nil then nocase[u.sent] = true end
        if u.cap then nocase[u.sent] = false end
      end
    end
    local k = 1
    while k <= n do
      local u = units[k]
      if nocase[u.sent] and u.kind == "word" and not u.cap and not is_common(lex, u) and #u.form >= 3 then
        local j = k
        while true do
          local nx = units[j + 1]
          if nx and not nx.pre and nx.sent == u.sent and nx.kind == "word" and (lex:headcue(nx.form) or (not is_common(lex, nx) and #nx.form >= 3)) then j = j + 1 else break end
        end
        local head = j > k and lex:headcue(units[j].form) or nil
        if head then
          add(k, j, { kind = "name", type_guess = head, text = an.original:sub(units[k].s, units[j].e), multiword = true, weak = true, head_cue = true }, "name_guess", 0.7 + 0.3 * (j - k))
        end
        k = j + 1
      else k = k + 1 end
    end
  end

  -- 6. fuzzy readings for UNKNOWN words (typos): proposals only, flagged and down-weighted. Known words are never reinterpreted.
  --    4-letter words are too short to trust. Entities need a capitalised surface (or a strong match); relation words / senses any case.
  for ui, u in ipairs(units) do
    if u.alts and #u.alts > 0 and #u.form >= 5 then
      for _, a in ipairs(u.alts) do
        if a.conf >= 0.45 then
          local fake = { { form = a.form } }
          for _, m in ipairs(lex:match_at(fake, 1)) do
            for _, e in ipairs(m.entries) do
              -- a fuzzy span ties with a plain word in the cover search (0.1): the literal reading is never displaced by a guess;
              -- hypotheses decide, and a fuzzy lexeme earns no attestation credit and pays a penalty
              if e.kind == "entity" and not e.cs and a.kind == "entity" and (u.cap or a.conf >= 0.7) then
                add(ui, ui, { kind = "entity", entry = e, fuzzy = a.conf, fuzzy_from = u.raw, fuzzy_to = a.form }, "entity", 0.1)
              elseif e.kind == "relnoun" or e.kind == "relverb" then
                local ec = U.shallow(e); ec.fuzzy = a.conf
                add(ui, ui, { kind = e.kind, entry = ec, fuzzy = a.conf, fuzzy_from = u.raw }, "word_sense", 0.1)
              elseif e.kind == "sense" and not u.cap then
                add(ui, ui, { kind = "sense", sense = e.sense, num = e.num, fuzzy = a.conf, fuzzy_from = u.raw }, "word_sense", 0.1)
              end
            end
          end
        end
      end
    end
  end

  -- 7. compositional kind readings: an attested multiword concept "<kind> <relational noun>" ("financial capital") is ALSO read
  --    as the relation with a kind modifier, so the relation reading is not lost to the lexicalised concept.
  for _, sp in ipairs(spans) do
    if sp.j > sp.i then
      local last = by_ext[span_key(sp.j, sp.j)]
      if last then
        local prefix = joined_forms(units, sp.i, sp.j - 1)
        for _, r in ipairs(last.readings) do
          if r.kind == "relnoun" then
            local rel = lex:get_rel(r.entry.rel)
            if rel and rel.kinds and rel.kinds[prefix] then
              local ec = U.shallow(r.entry); ec.kind_prefix = prefix
              add(sp.i, sp.j, { kind = "relnoun", entry = ec }, sp.kind, sp.score)
            end
          end
        end
      end
    end
  end

  -- index
  local by_start = {}
  for _, sp in ipairs(spans) do
    by_start[sp.i] = by_start[sp.i] or {}
    table.insert(by_start[sp.i], sp)
  end
  for _, list in pairs(by_start) do table.sort(list, function(a, b) return (a.j - a.i) > (b.j - b.i) end) end

  local lat = { an = an, units = units, spans = spans, by_start = by_start, n = n }

  -- k-best covers: choose non-overlapping spans maximising total score; unit not in a span costs a small word score
  -- covers(k [, a, b]): k-best covers of unit range [a, b] (default: everything); spans must lie inside the range
  function lat:covers(k, a, b)
    k = k or 4
    a, b = a or 1, b or n
    local W = 0.1
    -- best[p] = list of {score, span|nil, next_rank} for suffix starting at p, size <= k
    local best = { [b + 1] = { { score = 0 } } }
    for p = b, a, -1 do
      local cand = {}
      for rank, bb in ipairs(best[p + 1]) do cand[#cand + 1] = { score = bb.score + W, span = nil, nxt = p + 1, rank = rank } end
      for _, sp in ipairs(by_start[p] or {}) do
        if sp.j <= b then
          for rank, bb in ipairs(best[sp.j + 1]) do
            cand[#cand + 1] = { score = bb.score + sp.score, span = sp, nxt = sp.j + 1, rank = rank }
          end
        end
      end
      table.sort(cand, function(a, b)
        if a.score ~= b.score then return a.score > b.score end
        local la = a.span and (a.span.j - a.span.i) or -1
        local lb = b.span and (b.span.j - b.span.i) or -1
        return la > lb
      end)
      -- k-best with distinct extents so alternatives are real segmentations, not duplicates
      local keep, seen = {}, {}
      for _, c in ipairs(cand) do
        local sig = (c.span and (c.span.j .. "") or "w") .. ":" .. c.nxt .. ":" .. c.rank
        if not seen[sig] then seen[sig] = true; keep[#keep + 1] = c end
        if #keep >= k then break end
      end
      best[p] = keep
    end
    local out = {}
    for rank = 1, #best[a] do
      local chosen, p, r = {}, a, rank
      local total = best[a][rank].score
      while p <= b do
        local c = best[p][r]
        chosen[#chosen + 1] = c.span or { i = p, j = p, kind = "word", readings = {}, score = W, text = an.original:sub(units[p].s, units[p].e) }
        p, r = c.nxt, c.rank
      end
      out[#out + 1] = { score = total, spans = chosen }
    end
    -- drop covers identical in extents to an earlier one
    local uniq, seen = {}, {}
    for _, c in ipairs(out) do
      local sig = {}
      for _, sp in ipairs(c.spans) do sig[#sig + 1] = sp.i .. "-" .. sp.j .. sp.kind end
      sig = table.concat(sig, ",")
      if not seen[sig] then seen[sig] = true; uniq[#uniq + 1] = c end
    end
    return uniq
  end

  -- segmentation confidence: margin between the best and runner-up cover (raw, uncalibrated)
  function lat:segmentation_margin()
    local cv = self:covers(2)
    if #cv < 2 then return 1.0, cv end
    local a, b = cv[1].score, cv[2].score
    return U.clamp((a - b) / math.max(a, 1e-6), 0, 1), cv
  end

  if meter then meter:tick("lattice_spans", #spans) end
  return lat
end

return Lattice

end

package.preload["asi.nlu.lex"] = function(...)
-- asi.nlu.lex: lexical front end.
--   * original text is NEVER modified; every token/unit carries exact byte (s,e) and code point (cs,ce) offsets
--     (1-based, inclusive:  original:sub(tok.s, tok.e) == tok.text).
--   * tokens = surface segmentation; units = comparison-level "match words" (hyphen parts, contraction
--     expansions) that still point back to their token.
--   * comparison forms (fold) are separate fields; case-sensitive kinds (identifiers, URLs, ...) keep raw case.
local U = require("asi.nlu.util")
local UC = require("asi.nlu.unicode")

local Lex = { SCHEMA = "nlu.lex/1" }

local S = U.set
local ABBR = S({ "mr", "mrs", "ms", "dr", "prof", "sr", "jr", "st", "mt", "vs", "etc", "inc", "ltd", "co", "corp", "dept",
