local function norm(s) return (s or ""):lower():gsub("%s+", " ") end

local function selected_text(m)
  local out = {}
  for _, it in ipairs(m.context and m.context.memory and m.context.memory.selected or {}) do out[#out + 1] = it.text or "" end
