    return out, "resolved"
  end
  if ref.kind == "unknown" or ref.kind == "typenoun" or ref.kind == "concept" then
    out[1] = { key = "term:" .. (ref.core or ref.text:lower()), text = ref.text, p = 1.0, via = "term" }
    return out, "term"
  end
  return out, ref.status or "unresolved"
end
