---------------------------------------------------------------- helpers
local function first_main(result)
  return result.main
end

local function ref_list(m)
  -- every entity-bearing argument of the interpretation, with its resolution state
  local out = {}
  local seen = {}
  local function add(role, ref)
    if not ref or ref.asked or seen[ref] then return end
    seen[ref] = true
    out[#out + 1] = { role = role, ref = ref }
  end
  for role, ref in pairs(m.roles or {}) do add("arg:" .. role, ref) end
  for _, k in ipairs({ "subject", "concept", "target", "focus", "object", "basis" }) do add(k, m[k]) end
  for i, it in ipairs(m.items or {}) do add("item" .. i, it) end
  if m.statement then add("stmt_subject", m.statement.subject); add("stmt_object", m.statement.object) end
  if m.clause then add("clause_subject", m.clause.subject); add("clause_object", m.clause.object) end
  for _, st in ipairs((m.query and m.query.steps) or {}) do add("chain" .. st.index, st.known) end
  table.sort(out, function(a, b) return a.role < b.role end)
  return out
end

local function entity_sections(m)
  local cands, resolved = {}, {}
  for _, e in ipairs(ref_list(m)) do
    local r = e.ref
    if r.candidates or r.status or r.senses then
      cands[#cands + 1] = { role = e.role, mention = r.text, span = r.span, status = r.status, candidates = r.candidates, rejected = r.rejected, senses = r.senses,
        pronoun = r.pronoun, backref = r.backref, ordinal = r.ordinal, head = r.head }
    end
    local key = (r.antecedent and r.antecedent.key) or r.resolved_id
    resolved[#resolved + 1] = { role = e.role, mention = r.text, key = key, type = r.type, status = r.status or "n/a", antecedent = r.antecedent,
      via = r.antecedent and (r.antecedent.via or "antecedent") or (r.status == "unseen" and "open-set mention") or (r.status == "resolved" and "lexicon") or nil,
      weak_name = r.weak_name, non_anaphoric = r.non_anaphoric, deictic = r.deictic }
  end
  return cands, resolved
end

---------------------------------------------------------------- confidence components (raw, each from a computed quantity)
local function confidence(result, m, evidence, calibration)
  local conf = {}
  -- (1) lexical segmentation: margin of the best cover over the runner-up
  local seg = 1.0
  if result.lattice and result.lattice.segmentation_margin then
    local margin = result.lattice:segmentation_margin()
    seg = margin
  end
  conf.lexical_segmentation = { raw = U.round(seg, 4), basis = "relative score margin between the best and the runner-up phrase segmentation" }
  -- (2) entity identity: weakest resolved-or-ambiguous entity mention
  local ent, n = 1.0, 0
  for _, e in ipairs(ref_list(m)) do
    local r = e.ref
    if r.candidates and #r.candidates > 0 and not r.pronoun then
      local top = r.candidates[1].p or 1
      if r.status == "ambiguous" then top = math.min(top, 0.5) end
      if r.status == "unseen" then top = math.min(top, 0.85) end   -- an open-set name is identified as a mention, not as a known individual
      ent = math.min(ent, top); n = n + 1
    elseif r.status == "unresolved" or r.status == "unknown_term" then ent = math.min(ent, 0.2); n = n + 1 end
  end
  conf.entity_identity = { raw = U.round(ent, 4), basis = "lowest top-candidate posterior over the entity mentions of the request", n_mentions = n }
  -- (3) semantic interpretation: posterior of the winning hypothesis among competing ones
  conf.semantic_interpretation = { raw = U.round((m.confidence and m.confidence.semantic_raw) or 0, 4), coverage = m.confidence and m.confidence.coverage,
    basis = "posterior probability of the winning semantic hypothesis (softmax over named-factor scores)" }
  -- (4) memory reference resolution
  local mem, nref = 1.0, 0
  for _, ref in ipairs((m.context and m.context.references) or {}) do
    nref = nref + 1
    if ref.status ~= "resolved" then mem = 0.0
    else mem = math.min(mem, (ref.antecedent and ref.antecedent.p) or 0.9) end
  end
  conf.memory_reference = { raw = U.round(mem, 4), n_references = nref, basis = "weakest posterior among resolved context references (0 if any is unresolved)" }
  -- (5) evidence sufficiency: ordinal, not a probability that the answer is right
  local ev = { raw = 0.0, status = evidence and evidence.status or "not_applicable", basis = "strength (noisy-OR of independent record reliabilities) of the best supported answer; 0 unless answerable" }
  if evidence and evidence.status == "answerable" and evidence.answers and evidence.answers[1] then ev.raw = U.round(evidence.answers[1].strength or 0, 4)
  elseif evidence and evidence.status == "answerable" and evidence.matches then ev.raw = 0.5 end
  conf.evidence_sufficiency = ev
  -- optional calibration: maps a raw value to the empirical accuracy of that value on labelled data
  if calibration then
    conf.calibration = "calibrated with " .. tostring(calibration.method) .. " on " .. tostring(calibration.n) .. " labelled dev examples (" .. tostring(calibration.source) .. ")"
    local function apply(c, which)
      local f = calibration.maps and calibration.maps[which]
      if f and c then c.calibrated = f(c.raw) end
    end
    if calibration.model then
      -- whole-interpretation calibration: P(primary reading correct) from interpretation-derived features, fitted and cross-validated offline
      local Cal = require("asi.nlu.calibration")
      local p = Cal.apply_features(calibration.model, Cal.features(m))
      conf.interpretation_correct = { calibrated = U.round(p, 4), method = calibration.model.method, basis = calibration.model.fit and calibration.model.fit.target,
        valid_for = calibration.model.fit and calibration.model.fit.valid_for, cross_fit_ece = calibration.model.fit and calibration.model.fit.cross_fit_ece_calibrated }
      conf.calibration = "interpretation_correct is calibrated (" .. tostring(calibration.model.method) .. " over interpretation features, " .. tostring(calibration.n) ..
        " labelled noisy examples; " .. tostring(calibration.source) .. "); the other components remain RAW scores, not probabilities"
    end
    apply(conf.semantic_interpretation, "semantic_interpretation")
    apply(conf.entity_identity, "entity_identity")
    apply(conf.lexical_segmentation, "lexical_segmentation")
  else
    conf.calibration = "uncalibrated: values are raw model scores, NOT probabilities of being correct"
  end
  return conf
end

---------------------------------------------------------------- build
function R.build(ctx)
  local result, evidence, plan = ctx.result, ctx.evidence, ctx.plan
  local an = result.analysis
  local m = first_main(result) or { status = "no_interpretation", speech_act = "unknown", intent = "unknown", roles = {}, constraints = {} }
  local cons = m.constraints or {}
  local cands, resolved = entity_sections(m)
  local toks = {}
  for i, u in ipairs(an and an.units or {}) do
    if i > 400 then break end
    toks[#toks + 1] = { form = u.form, raw = u.raw, s = u.s, e = u.e, kind = u.kind }
  end
  local sentences = {}
  for _, s in ipairs(an and an.sentences or {}) do sentences[#sentences + 1] = { id = s.id, s = s.s, e = s.e, terminal = s.terminal, question_mark = s.question_mark or nil } end
  local mem = m.context and m.context.memory
  -- A record is JSON: input that is not valid UTF-8 is shown with each invalid run as U+FFFD, and the exact bytes are kept in input_encoding.raw_hex.
  local raw_input = result.original or ""
  local clean_input, invalid_input = U.scrub_utf8(raw_input)
  local rec = {
    schema_version = R.SCHEMA,
    engine = { name = R.ENGINE, version = R.ENGINE_VERSION, flags = ctx.flags or {}, lexicon_revision = ctx.lexicon_revision, interpreter_version = ctx.interpreter_version },
    original_input = clean_input,
    input_encoding = invalid_input and { valid_utf8 = false, bytes = #raw_input, sha256 = U.sha256(raw_input), raw_hex = U.hex(raw_input:sub(1, 65536)), raw_hex_truncated = #raw_input > 65536 or nil,
      note = "the input contains bytes that are not valid UTF-8: original_input shows each invalid run as U+FFFD; raw_hex holds the exact bytes" } or { valid_utf8 = true, bytes = #raw_input },
    normalized_input = { text = (result.original or ""):gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", ""),
      note = "whitespace-collapsed only; the original request is preserved verbatim in original_input and is what the interpretation refers to" },
    lexical_analysis = { status = result.status or "ok", utf8 = an and an.utf8 or {}, n_tokens = an and #an.units or 0, tokens = toks, sentences = sentences,
      temporal = U.map(an and an.temporal or {}, function(t) return { kind = t.kind, op = t.op, text = t.text, year = t.year, lo = t.eff_lo or t.lo, hi = t.eff_hi or t.hi, s = t.s, e = t.e } end),
      numbers = U.map(an and an.numbers or {}, function(n) return { kind = n.kind, value = n.value, text = n.text } end), notes = an and an.notes or {} },
    semantic_intent = { speech_act = m.speech_act or "unknown", intent = m.intent or "unknown", op = m.op, frame = m.frame, status = m.status or "no_interpretation",
      wrapper = m.wrapper, polarity = m.polarity, tense = m.tense, task_verb = m.task_verb, recall = m.recall, instruction = m.instruction, persist = m.persist },
    entity_candidates = cands,
    resolved_entities = resolved,
    requested_relations = m.relation and { relation = m.relation, query = m.query } or {},
    requested_answer_type = m.query and (m.query.answer_type or m.query.relation_answer_type) or nil,
    temporal_constraints = cons.temporal or {},
    geographic_constraints = cons.geographic or {},
    positive_constraints = cons.positive or {},
    negative_constraints = cons.negative or {},
    preferences = cons.preferences or {},
    source_constraints = cons.source or {},
    restrictions = cons.restrictions or {},
    temporal_scope = m.temporal_scope,
    relevant_context = { dependency = m.context and m.context.dependency, references = m.context and m.context.references or {}, recent = ctx.recent or {} },
    relevant_memory = mem and mem.selected or {},
    active_constraints = m.context and m.context.active_constraints or {},
    memory_provenance = { namespace = mem and mem.namespace, revision = mem and mem.revision, turn = mem and mem.turn, n_selected = mem and mem.n_selected, n_excluded = mem and mem.n_excluded,
      excluded = mem and mem.excluded or {}, n_candidates = mem and mem.n_candidates, n_items = mem and mem.n_items },
    retrieval_candidates = { plan_kind = plan and plan.kind or "none", plan = plan and U.shallow(plan) or nil, topical = evidence and evidence.topical or {},
      n_assertions_examined = evidence and evidence.assertion_count or 0, knowledge_digest = evidence and evidence.knowledge_digest },
    selected_evidence = evidence and evidence.selected or {},
    rejected_evidence = evidence and evidence.rejected or {},
    conflicting_evidence = evidence and evidence.conflicting_evidence or {},
    partial_evidence = evidence and evidence.partial_evidence or {},
    refuting_evidence = evidence and evidence.refuting or {},
    ambiguity_state = m.ambiguity or { state = "unresolvable", points = {} },
    evidence_sufficiency = evidence and { status = evidence.status, reasons = evidence.reasons, notes = evidence.notes, answer = evidence.answer, answers = evidence.answers,
      alternative_answers = evidence.alternative_answers, answers_by_reading = evidence.answers_by_reading,
      conflicts = evidence.conflicts, claim_verdict = evidence.verdict, interpretation_incomplete = evidence.interpretation_incomplete }
      or { status = "not_applicable", reasons = { "no dataset was supplied" }, notes = {} },
    confidence = confidence(result, m, evidence, ctx.calibration),
    decision_provenance = m.provenance or {},
    hypotheses = m.hypotheses, rejected_hypotheses = m.rejected_hypotheses,
    unresolved_requirements = {},
    execution_cost = { interpretation_work = result.work and result.work.total or 0, work_by_stage = result.work and result.work.by_stage, status = result.status or "ok",
      retrieval = { assertions_examined = evidence and evidence.assertion_count or 0, selected = evidence and #evidence.selected or 0, rejected = evidence and #evidence.rejected or 0 } },
  }
  -- unresolved requirements: what is MISSING, stated explicitly
  local ur = rec.unresolved_requirements
  for _, u in ipairs(m.context and m.context.unresolved or {}) do ur[#ur + 1] = { kind = "context_reference", reference = u.reference, mention = u.mention, requirement = u.requirement } end
  for _, p in ipairs((m.ambiguity and m.ambiguity.points) or {}) do
    if p.material and not p.resolved then ur[#ur + 1] = { kind = "ambiguity", point = p.id, requirement = "choose between: " .. table.concat(U.map(p.candidates or {}, function(c) return tostring(c.id or c.summary) end), " | ") } end
  end
  for _, un in ipairs(m.unexplained or {}) do ur[#ur + 1] = { kind = "unexplained_text", text = un, requirement = "this part of the request was not understood and is not reflected in the interpretation" } end
  if evidence and evidence.interpretation_incomplete then ur[#ur + 1] = { kind = "entity_unidentified", requirement = "the entity the question is about could not be identified" } end
  if result.status == "limited" then ur[#ur + 1] = { kind = "resource_limit", requirement = "the work budget was exhausted; the interpretation is incomplete and was not completed by guessing" } end
  if evidence and (evidence.status == "insufficient" or evidence.status == "unsupported" or evidence.status == "potentially_answerable") then
    ur[#ur + 1] = { kind = "evidence", status = evidence.status, requirement = table.concat(evidence.reasons or {}, "; ") }
  end
  -- deterministic request id + integrity hash (hash covers every section except the integrity block itself)
  local enc_ok, body = pcall(U.json_encode, rec, { nan_null = true })
  if not enc_ok then
    -- the only way the strict encoder fails here is an invalid-UTF-8 string that reached the record from a source other than the request
    -- (dataset text, memory); make every string valid and say so instead of crashing or emitting broken JSON
    if not tostring(body):find("invalid UTF%-8", 1) then error(body, 0) end
    rec = U.scrub_tree(rec)
    rec.input_encoding.scrubbed_other_fields = true
    body = U.json_encode(rec, { nan_null = true })
  end
  rec.request_id = U.sha256(table.concat({ invalid_input and ("raw:" .. rec.input_encoding.sha256) or rec.original_input, tostring(rec.retrieval_candidates.knowledge_digest), tostring(rec.memory_provenance.namespace),
    tostring(rec.memory_provenance.revision), R.SCHEMA, R.ENGINE_VERSION }, "\0")):sub(1, 24)
  rec.integrity = { sha256 = U.sha256(body), covers = "canonical JSON of all other fields (before request_id was assigned)" }
  return rec
end

---------------------------------------------------------------- validation
function R.validate(rec)
  local ok, errs = U.validate(R.SPEC, rec)
  local extra = R.check_invariants(rec)
  for _, e in ipairs(extra) do errs[#errs + 1] = e end
  return #errs == 0, errs
end

-- semantic invariants the envelope schema cannot express
function R.check_invariants(rec)
  local errs = {}
  local function bad(m) errs[#errs + 1] = "invariant: " .. m end
  if type(rec) ~= "table" then return { "invariant: record is not a table" } end
  local st = rec.evidence_sufficiency and rec.evidence_sufficiency.status
  if st == "answerable" and #(rec.selected_evidence or {}) == 0 then bad("status answerable without selected evidence") end
  if st ~= "answerable" and st ~= "ambiguous" and rec.evidence_sufficiency and rec.evidence_sufficiency.answer and st ~= "contradictory" then
    if st == "insufficient" or st == "unsupported" then bad("an answer is attached to status " .. st) end
  end
  for i, ev in ipairs(rec.selected_evidence or {}) do
    if not ev.record or not ev.quote then bad("selected_evidence[" .. i .. "] lacks record/quote provenance") end
    if ev.role == "rejected" then bad("selected_evidence[" .. i .. "] has role rejected") end
  end
  local C = rec.confidence or {}
  for k, c in pairs(C) do
    if type(c) == "table" and c.raw ~= nil and (c.raw < 0 or c.raw > 1) then bad("confidence." .. k .. " outside [0,1]") end
    if type(c) == "table" and c.calibrated ~= nil and (c.calibrated < 0 or c.calibrated > 1) then bad("confidence." .. k .. " calibrated outside [0,1]") end
  end
  if rec.original_input == nil or rec.original_input == "" and rec.lexical_analysis and rec.lexical_analysis.n_tokens > 0 then bad("original input lost") end
  if rec.execution_cost and rec.execution_cost.status == "limited" then
    local found = false
    for _, u in ipairs(rec.unresolved_requirements or {}) do if u.kind == "resource_limit" then found = true end end
    if not found then bad("limited run without an explicit resource_limit requirement") end
  end
  return errs
end

function R.verify_integrity(rec)
  local copy = U.shallow(rec)
  local sha = rec.integrity and rec.integrity.sha256
  copy.integrity = nil
  copy.request_id = nil
  return sha == U.sha256(U.json_encode(copy, { nan_null = true }))
end

return R

end

package.preload["asi.nlu.repair"] = function(...)
-- asi.nlu.repair: the bounded "repair" reading of a sentence.
-- A cover (segmentation) is repaired by (1) correcting UNKNOWN words to the lexicon word they are one or two edits away from -- function words,
-- verbs, relation nouns, entity names, and words inside multiword phrases ("official langugae") -- and (2) ignoring filler / disfluency words.
-- The repaired cover is NOT a replacement: it competes with the literal covers, and every hypothesis built on it carries an explicit `repair`
-- penalty (asi.nlu.sem), so the literal reading wins whenever it is at least as good.  Nothing is rewritten: the original text, the unit offsets and
-- the list of repairs are all preserved for provenance.
local U = require("asi.nlu.util")

local R = {}

local POSITION_CLASS_PRIORITY = { wh = 4, aux_do = 3, aux_be = 3, aux_have = 3, modal = 3, prep = 2, det = 2, pron = 2, pron_poss = 2, conj = 1, polite = 1 }
local MIN_CONF, MIN_ENTITY_CONF = 0.45, 0.7
local MAX_WINDOW_BEFORE, MAX_WINDOW_AFTER = 3, 3

-- ranked correction candidates for one unknown unit
local function candidates(lex, u, idx, prev_wh)
  local out = {}
  local fsp = lex:function_spell()
  local maxd = (#u.form <= 5) and 1 or 2
  for _, c in ipairs(fsp:suggest(u.form, { max_edit = maxd, limit = 6 })) do
    local conf = 0.9 - 0.3 * (c.dist - 1) - (c.first_same and 0 or 0.15)
    local prio = POSITION_CLASS_PRIORITY[c.kind] or 0
    if idx == 1 and c.kind == "wh" then prio = prio + 3 end                                              -- a sentence-initial slot wants a wh-word
    if prev_wh and (c.kind == "aux_do" or c.kind == "aux_be") then prio = prio + 3 end                    -- the slot after a wh-phrase wants an auxiliary
    out[#out + 1] = { form = c.form, dist = c.dist, conf = conf, prio = prio, class = c.kind, source = "function" }
  end
  for _, a in ipairs(u.alts or {}) do
    if a.kind ~= "entity" or (u.cap and a.conf >= MIN_ENTITY_CONF) then
      out[#out + 1] = { form = a.form, dist = a.dist, conf = a.conf, prio = 0, class = a.kind, source = "lexicon" }
    end
  end
  table.sort(out, function(x, y)
    if x.dist ~= y.dist then return x.dist < y.dist end
    if x.prio ~= y.prio then return x.prio > y.prio end
    if x.conf ~= y.conf then return x.conf > y.conf end
    return x.form < y.form
  end)
  local keep = {}
  for _, c in ipairs(out) do if c.conf >= MIN_CONF then keep[#keep + 1] = c end end
  return keep
end

-- readings of a (possibly multiword) lexicon match for a corrected span, shaped like the lattice's own readings but flagged fuzzy
local function readings_of(entries, from_raw, conf, units, i, j)
  local rs = {}
  for _, e in ipairs(entries) do
    if e.kind == "entity" and not e.cs then rs[#rs + 1] = { kind = "entity", entry = e, fuzzy = conf, fuzzy_from = from_raw }
    elseif e.kind == "relnoun" or e.kind == "relverb" then
      local ec = U.shallow(e); ec.fuzzy = conf
      rs[#rs + 1] = { kind = e.kind, entry = ec, fuzzy = conf, fuzzy_from = from_raw }
    elseif e.kind == "sense" then rs[#rs + 1] = { kind = "sense", sense = e.sense, num = e.num, fuzzy = conf, fuzzy_from = from_raw } end
  end
  return rs
end

-- multiword phrases that contain unit `ui` once it is replaced by `cand` (e.g. "official langugae" -> "official language")
local function phrase_matches(lex, units, ui, cand, conf, from_raw)
  local best
  local sent = units[ui].sent
  for s = math.max(1, ui - MAX_WINDOW_BEFORE), ui do
    if units[s].sent == sent then
      local win = {}
      for k = s, math.min(#units, ui + MAX_WINDOW_AFTER) do
        if units[k].sent ~= sent then break end
        win[#win + 1] = { form = (k == ui) and cand or units[k].form, pre = units[k].pre }
      end
      for _, m in ipairs(lex:match_at(win, 1)) do
        local e = s + m.j - 1
        if e >= ui and e > s then
          local rs = readings_of(m.entries, from_raw, conf)
          if #rs > 0 and (not best or (e - s) > (best.j - best.i)) then best = { i = s, j = e, readings = rs } end
        end
      end
    end
  end
  return best
end

-- returns a repaired cover { score, spans, repair = true, repairs = {...} } or nil
function R.repair_cover(lex, units, cover, original)
  local spans = cover.spans
  local repairs = {}
  local drop, replace, inserts = {}, {}, {}      -- drop[idx]=true; replace[idx]=span; inserts = multiword spans that supersede several spans
  local unit_span = {}
  for idx, sp in ipairs(spans) do for k = sp.i, sp.j do unit_span[k] = idx end end
  local prev_wh = false
  for idx, sp in ipairs(spans) do
    local u = units[sp.i]
    local multi_name = sp.kind == "name_guess" and sp.j > sp.i and u.kind == "word" and (sp.i == 1 or units[sp.i - 1].sent ~= u.sent)
    if (sp.i == sp.j or multi_name) and u.kind == "word" and not drop[idx] and not replace[idx] then
      local cats = lex:cats(u.form)
      local only_fuzzy = true
      for _, r in ipairs(sp.readings) do if not r.fuzzy and r.kind ~= "name" then only_fuzzy = false end end
      local unknown = (not cats or not next(cats)) and #lex:readings(u.form) == 0 and only_fuzzy
        and ((sp.kind == "word" or sp.kind == "word_sense" or sp.kind == "entity") or (sp.kind == "name_guess" and (multi_name or (sp.readings[1] and sp.readings[1].weak))))
      if cats and cats.ignorable and not (#spans == 1) and sp.i == sp.j then
        repairs[#repairs + 1] = { kind = "ignored", word = u.raw, unit = sp.i }
        drop[idx] = true
      elseif unknown and #u.form >= 3 then
        local cands = candidates(lex, u, idx, prev_wh)
        local chosen = cands[1]
        -- a capitalised sentence-initial word swallowed by a multiword name guess ("Comoare Company A") is split off only for a NON-entity correction
        if chosen and multi_name and chosen.class == "entity" then chosen = nil end
        if chosen and multi_name then
          local rest = sp.readings[1] or {}
          local rr = {}
          for k2, v2 in pairs(rest) do rr[k2] = v2 end
          rr.multiword = (sp.j - 1) > sp.i
          rr.text = original and original:sub(units[sp.i + 1].s, units[sp.j].e) or rr.text
          rr.weak = nil
          inserts[#inserts + 1] = { i = sp.i + 1, j = sp.j, kind = "name_guess", readings = { rr }, score = sp.score, text = rr.text }
          replace[idx] = { i = sp.i, j = sp.i, kind = "word", readings = {}, score = sp.score, text = original and original:sub(u.s, u.e) or u.raw,
            fnword = { from = u.raw, to = chosen.form, dist = chosen.dist, class = chosen.class } }
          repairs[#repairs + 1] = { kind = (chosen.source == "function") and "function_word" or "word", from = u.raw, to = chosen.form, dist = chosen.dist, conf = chosen.conf, unit = sp.i }
          chosen = nil
        end
        if chosen then
          -- a multiword phrase that the correction completes takes priority over the single word
          local ph = phrase_matches(lex, units, sp.i, chosen.form, chosen.conf, u.raw)
          local ok_phrase = false
          if ph then
            local clash = false
            for k = ph.i, ph.j do
              local oi = unit_span[k]
              local os = spans[oi]
              if os.i < ph.i or os.j > ph.j or drop[oi] or replace[oi] then clash = true end
            end
            if not clash then
              for k = ph.i, ph.j do local oi = unit_span[k]; if oi ~= idx then drop[oi] = true end end
              ph.kind, ph.score = "mwe", sp.score
              ph.text = original and original:sub(units[ph.i].s, units[ph.j].e) or ""
              ph.fnword = { from = u.raw, to = chosen.form, dist = chosen.dist, class = chosen.class, phrase = true, unit = sp.i }
              replace[idx] = ph
              ok_phrase = true
              repairs[#repairs + 1] = { kind = "phrase_word", from = u.raw, to = chosen.form, dist = chosen.dist, conf = chosen.conf, unit = sp.i }
            end
          end
          if not ok_phrase then
            local entries = {}
            for _, m in ipairs(lex:match_at({ { form = chosen.form } }, 1)) do
              if m.j == 1 then for _, e in ipairs(m.entries) do entries[#entries + 1] = e end end
            end
            local rs = readings_of(entries, u.raw, chosen.conf)
            -- an entity needs a capitalised surface; a function word / verb needs none
            if chosen.class == "entity" and not u.cap then rs = {} end
            local fn = (lex:cats(chosen.form) and next(lex:cats(chosen.form))) or #lex:readings(chosen.form) > 0 or #rs > 0
            if fn then
              replace[idx] = { i = sp.i, j = sp.j, kind = (#rs > 0) and "word_sense" or "word", readings = rs, score = sp.score, text = sp.text,
                fnword = { from = u.raw, to = chosen.form, dist = chosen.dist, class = chosen.class } }
              repairs[#repairs + 1] = { kind = (chosen.source == "function") and "function_word" or "word", from = u.raw, to = chosen.form, dist = chosen.dist, conf = chosen.conf, unit = sp.i }
            end
          end
        end
      end
    end
    local eff = replace[idx]
    local cc = eff and eff.fnword and lex:cats(eff.fnword.to) or (sp.i == sp.j and lex:cats(u.form)) or nil
    if not drop[idx] then prev_wh = (cc and cc.wh) and true or false end
  end
  if #repairs == 0 then return nil end
  local out = {}
  for idx, sp in ipairs(spans) do
    if not drop[idx] then out[#out + 1] = replace[idx] or sp end
  end
  for _, sp in ipairs(inserts) do out[#out + 1] = sp end
  -- a replacement span may now overlap spans that were dropped for it; order by start unit
  table.sort(out, function(a, b) return a.i < b.i end)
  -- the repaired reading owns a copy of the unit array in which corrected words carry their corrected FORM (offsets, raw text and everything else are
  -- inherited from the original unit), so cue phrases, closed-class lookups and phrase matching all see the corrected word
  local units2 = {}
  for k, u in ipairs(units) do units2[k] = u end
  for _, sp in ipairs(out) do
    if sp.fnword and sp.i == sp.j then
      units2[sp.i] = setmetatable({ form = sp.fnword.to, lower = sp.fnword.to, surface_form = units[sp.i].form, repaired = true }, { __index = units[sp.i] })
    elseif sp.fnword and sp.fnword.phrase then
      local k = sp.fnword.unit
      units2[k] = setmetatable({ form = sp.fnword.to, lower = sp.fnword.to, surface_form = units[k].form, repaired = true }, { __index = units[k] })
    end
  end
  return { score = cover.score, spans = out, repair = true, repairs = repairs, units = units2 }
end

return R

end

package.preload["asi.nlu.resources"] = function(...)
-- asi.nlu.resources: builds (and caches) the core lexicon from the shipped DSL data modules.
local Lexicon = require("asi.nlu.lexicon")

local R = {}
R.MODULES = { "lex_core", "lex_rel", "lex_sense", "lex_typenoun", "lex_gaz" }

local cached
function R.core(fresh)
  if cached and not fresh then return cached end
  local lex = Lexicon.new()
  for _, m in ipairs(R.MODULES) do lex:load(require("asi.nlu.data." .. m), m) end
  lex:build_spell()
  if #lex.errors > 0 then error("core lexicon has errors:\n" .. table.concat(lex.errors, "\n", 1, math.min(#lex.errors, 10))) end
  cached = lex
  return lex
end

-- a dataset overlay: inherits everything, adds its own entities/relations/vocabulary
function R.overlay(core)
  core = core or R.core()
  local ov = Lexicon.new(core)
  return ov
end

return R

end

package.preload["asi.nlu.sem"] = function(...)
-- asi.nlu.sem: semantic interpretation of one sentence.
--   lattice covers (segmentation alternatives) x frames (constructions) -> competing hypotheses -> bounded selection.
-- Output is a plain, serialisable table (see Sem.render); every number in its provenance is a computed factor.
local U = require("asi.nlu.util")
local P = require("asi.nlu.parse")
local Cons = require("asi.nlu.constraints")
local H = require("asi.nlu.hyp")
local F = require("asi.nlu.frames2")

local Sem = {}

local FRAME_FUNCS = { "wh_copular", "wh_verb", "wh_do", "wh_passive", "wh_adverbial", "where_support", "wh_support_as", "wh_support_subject", "wh_role_holder", "yes_no", "wh_change", "compare_q",
  "request", "instruction", "exclusion_clause", "focus", "statement", "np_only", "segment_only", "recall", "what_means" }

local function sentence_unit_range(an, sid)
  local r = an._ranges
  if not r then
    r = {}
    for i, u in ipairs(an.units) do
      local e = r[u.sent]
      if not e then r[u.sent] = { i, i } else e[2] = i end
    end
    an._ranges = r
  end
  local e = r[sid]
  if e then return e[1], e[2] end
end
Sem.sentence_unit_range = sentence_unit_range

---------------------------------------------------------------- rendering of arguments
local function ref(S, np, depth)
  depth = depth or 0
  if not np then return nil end
  local r = { text = P.span_text(S, np), kind = np.head_kind, span = { S.units[np.u1].s, S.units[np.u2].e }, chunk_range = { np.c1, np.c2 } }
  -- "the company Apple", "CEO Dana Whitcombe": type nouns and titles in front of a name classify it; the mention is the name itself
  if np.head_kind == "entity" and np.head and np.head.u1 > np.u1 and #(np.mods or {}) > 0 then
    local all_cls = true
    for _, md in ipairs(np.mods) do
      local mc = md.chunk
      if not (md.kind == "mod" and mc and ((mc.senses and #mc.senses > 0) or (mc.relnouns and #mc.relnouns > 0))) then all_cls = false end
    end
    if all_cls then
      local first_mod = np.mods[1].chunk
      r.classifier = S.an.original:sub(S.units[first_mod.u1].s, S.units[np.head.u1 - 1].e)
      r.text = S.an.original:sub(S.units[np.head.u1].s, S.units[np.u2].e)
    end
  end
  if np.head then r.head = np.head.form end
  r.core = P.core_text(S, np)
  -- a multiword capitalised name without organisation / place cues is probably a person's name (weak evidence for animate pronouns)
  if np.head_kind == "entity" and np.head and np.head.names and np.head.names[1] then
    local nm = np.head.names[1]
    if nm.multiword and not nm.head_cue and not nm.type_guess then r.pname = true end
  end
  local b = np.bound
  if b and b.deictic then r.deictic = b.deictic end
  if b and (b.expletive or b.indefinite) then r.non_anaphoric = b.expletive and "expletive" or "indefinite" end
  if b and b.antecedent then r.antecedent = b.antecedent end
  if b then
    r.status = b.status
    if b.top then
      if b.top.weak then r.weak_name = true end
      if b.status == "resolved" or b.status == "unseen" then r.resolved_id, r.type = b.top.id, b.top.type
      else r.leading_candidate = b.top.id end -- ambiguous: a leading candidate is NOT a resolution
    end
    r.type = r.type or b.type
    if b.itype and not r.type then r.itype = b.itype end
    if b.cands and #b.cands > 0 then
      r.candidates = U.map(b.cands, function(c) return { id = c.id, type = c.type, name = c.name, p = c.p, score = c.score, reasons = c.reasons, unseen = c.unseen or nil, weak = c.weak or nil, fuzzy = c.fuzzy } end)
    end
    if b.rejected and #b.rejected > 0 then
      r.rejected = U.map(b.rejected, function(c) return { id = c.id, type = c.type, reason = c.reasons[#c.reasons] } end)
    end
    if b.senses then r.senses = U.map(b.senses, function(s) return { id = s.id, type = s.type, gloss = s.gloss } end) end
  end
  if np.head_kind == "var" then r.status, r.type, r.result_of_step = "chain_variable", np.type, np.step; r.var = np.var end
  if np.pron then
    r.pronoun = np.pron.form
    r.needs_antecedent = not (b and (b.deictic or b.expletive or b.indefinite or b.status == "resolved"))
    if b and b.topic_bound then r.topic_bound = true end
    if b and b.discourse and b.status ~= "resolved" and not b.deictic then r.antecedent_reason = b.none_reason end
  end
  if np.backref then r.backref = true; r.needs_context = true; r.backref_who = np.backref_who end
  if np.det then r.det = np.det end
  if np.plural then r.plural = true end
  if np.superlative then r.superlative = np.superlative end
  if np.ordinal then r.ordinal = np.ordinal end
  if np.count then r.count = np.count end
  if np.temporal_scope then r.temporal_scope = np.temporal_scope end
  if np.temporal_mod then r.temporal_mod = np.temporal_mod.text; r.temporal_mod_role = np.temporal_mod.role end
  if #np.mods > 0 then r.modifiers = U.map(np.mods, function(m) return { text = m.text, kind = m.kind } end) end
  if depth < 3 then
    if np.of_arg then r.of = ref(S, np.of_arg, depth + 1) end
    if np.possessor then r.possessor = ref(S, np.possessor, depth + 1) end
  end
  return r
end
Sem.ref = ref

---------------------------------------------------------------- run
Sem.SUFFIX_TRIGGER = 1.0
Sem.REPORT_WORDS = U.set({ "she", "he", "they", "someone", "somebody", "people", "told", "asked", "said", "says", "wants", "wanted", "suggested", "recommended", "thinks", "thought",
  "claims", "claimed", "insists", "insisted", "advised", "reminded", "mentioned" })
Sem.WEAK_INTENTS = { definition = true, entity_description = true, statement = true, unknown = true, explanation = true }
local SUFFIX_JOINERS = U.set({ "but", "so", "and", "then", "because", "that", "whether", "while", "though", "although" })
-- chunk indices (after the sentence's first chunk) where a new clause may start: after a comma / colon / dash / semicolon, after a joiner, or after "to" before a verb
function Sem.clause_starts(S)
  local out = {}
  for k = S.first + 1, S.last - 1 do
    local c, pc = S.chunks[k], S.chunks[k - 1]
    if c and not c.masked then
      local boundary = c.pre and (c.pre:find("comma") or c.pre:find("colon") or c.pre:find("dash") or c.pre:find("semi"))
      if not boundary and pc and pc.single and not pc.masked and SUFFIX_JOINERS[pc.unit.form] then boundary = true end
      if not boundary and pc and pc.single and not pc.masked and pc.unit.form == "to" and c.verbs then boundary = true end
      if boundary then out[#out + 1] = k end
    end
  end
  -- the later clauses are the likelier request; keep at most three
  while #out > 3 do table.remove(out, 1) end
  return out
end

function Sem.analyze_sentence(an, lat, lex, sent, ctx)
  ctx = ctx or {}
  local W = H.W
  local ua, ub = sentence_unit_range(an, sent.id)
  if not ua then return nil end
  local covers = lat:covers(ctx.max_covers or 3, ua, ub)
  local all, states = {}, {}
  local best_cover_score = covers[1] and covers[1].score or 0
  local meter = ctx.meter
  -- the repair variant of the best cover (misspelled function words, filler words) competes as one more reading, at an explicit cost
  local run_covers = {}
  for ci, cover in ipairs(covers) do run_covers[ci] = cover end
  if covers[1] and not (ctx.flags and ctx.flags.no_repair) then
    local rc = P.repair_cover(lex, an.units, covers[1], an.original)
    if rc then run_covers[#run_covers + 1] = rc end
  end
  for ci, cover in ipairs(run_covers) do
    local an_s = an
    if cover.units then an_s = setmetatable({ units = cover.units }, { __index = an }) end   -- repaired reading: corrected unit forms
    local S = P.new_state(an_s, lex, lat, cover, ctx)
    S.cover_index, S.cover_score = ci, cover.score
    S.repairs = cover.repairs
    S.sentence = sent
    states[ci] = S
    local _, wrapper = P.strip_wrapper(S)
    S.wrapper = wrapper
    local segs = Cons.find_segments(S)
    local seg_cons = Cons.parse_segments(S, segs)
    Cons.apply_masks(S, segs)
    S.segs, S.seg_cons = segs, seg_cons
    local hyps = {}
    for _, fname in ipairs(FRAME_FUNCS) do
      if meter and not meter:tick("frames", 1) then break end
      local fn = F[fname]
      if fn then fn(S, hyps) end
    end
    for _, h in ipairs(hyps) do
      h.cover_index = ci
      if cover.repair then
        local cost = 0
        for _, r in ipairs(cover.repairs) do
          -- an explicit, bounded price per repair: lower for a near-certain closed-class correction, higher for a doubtful content-word guess
          local base = (r.kind == "ignored" and 0.15) or (r.kind == "function_word" and 0.08) or 0.18
          cost = cost + base + 0.5 * (1 - (r.conf or 0.6))
        end
        h.factors[#h.factors + 1] = { name = "repair", v = -cost, note = "reading after repairs: " .. table.concat(U.map(cover.repairs, function(r)
          return r.kind ~= "ignored" and string.format("'%s' read as '%s'", r.from, r.to) or string.format("'%s' ignored", r.word) end), "; ") }
      elseif ci > 1 then
        h.factors[#h.factors + 1] = { name = "segmentation", v = -1.1 * math.min(1, (best_cover_score - cover.score) / math.max(best_cover_score, 1)) - 0.1,
          note = string.format("alternative segmentation #%d (cover score %.2f vs best %.2f)", ci, cover.score, best_cover_score) }
      end
      if sent.question_mark and h.speech_act == "statement" then
        h.factors[#h.factors + 1] = { name = "question_mark_vs_statement", v = -0.9, note = "the sentence ends with '?' but this reading is a declarative statement" }
      end
      if #seg_cons.unparsed > 0 then
        h.factors[#h.factors + 1] = { name = "unparsed_segment", v = -0.3 * #seg_cons.unparsed, note = "a negation/preference cue had no parsable target" }
      end
      H.finalize(S, ctx, h)
      if meter then meter:tick("hypotheses", 1) end
      all[#all + 1] = h
    end
  end
  -- Clause-suffix readings.  When no reading of the whole sentence is good, a clause that starts after a comma / "but" / "so" / "to" may be the request or
  -- question proper ("Sorry to loop back, but who is the CEO of ...?", "Time to find some organisations ...").  Everything before it is then explicitly
  -- unexplained (it counts against the reading like any other unexplained content), so a suffix reading wins only when the whole-sentence readings are poor.
  if not (ctx.flags and ctx.flags.no_suffix) and covers[1] and states[1] then
    local best, best_h = -math.huge, nil
    for _, h in ipairs(all) do if h.score > best then best, best_h = h.score, h end end
    -- only when the best whole-sentence reading is a fallback kind of reading (a bare definition / description / statement) or a poor one
    if best_h == nil or Sem.WEAK_INTENTS[best_h.intent or "?"] or best < Sem.SUFFIX_TRIGGER then
      local cover = covers[1]
      local an_s = an
      local S1 = states[1]
      for si, p in ipairs(Sem.clause_starts(S1)) do
        if meter and not meter:tick("frames", 1) then break end
        local S2 = P.new_state(an_s, lex, lat, cover, ctx)
        S2.cover_index, S2.cover_score, S2.sentence = 1, cover.score, sent
        S2.first = p
        S2.prefix_chunks = {}
        for k = S1.first, p - 1 do
          local ck = S2.chunks[k]
          if ck and not P.is_function_chunk(S2, ck) then S2.prefix_chunks[#S2.prefix_chunks + 1] = ck end
        end
        -- "She told me to switch to the 2021 edition": an instruction reported from a third party is not an instruction to the system
        local reported_prefix = false
        for k = S1.first, p - 1 do
          local ck = S2.chunks[k]
          local f = ck and ck.single and ck.unit and ck.unit.form
          if f and Sem.REPORT_WORDS[f] then reported_prefix = true end
        end
        local key = 100 + si
        states[key] = S2
        local _, wrapper = P.strip_wrapper(S2)
        S2.wrapper = wrapper
        local segs = Cons.find_segments(S2)
        local seg_cons = Cons.parse_segments(S2, segs)
        Cons.apply_masks(S2, segs)
        S2.segs, S2.seg_cons = segs, seg_cons
        local hyps = {}
        for _, fname in ipairs(FRAME_FUNCS) do
          local fn = F[fname]
          if fn then fn(S2, hyps) end
        end
        for hi = #hyps, 1, -1 do
          local hh = hyps[hi]
          if reported_prefix and (hh.intent == "instruction_update" or hh.instruction) then table.remove(hyps, hi) end
        end
        for _, h in ipairs(hyps) do
          h.cover_index = key
          h.factors[#h.factors + 1] = { name = "clause_suffix", v = -0.15, note = "reading of the clause that starts at '" .. tostring(S2.chunks[p] and S2.chunks[p].text) .. "'; the words before it are not explained" }
          if #seg_cons.unparsed > 0 then
            h.factors[#h.factors + 1] = { name = "unparsed_segment", v = -0.3 * #seg_cons.unparsed, note = "a negation/preference cue had no parsable target" }
          end
          H.finalize(S2, ctx, h)
          -- a clause reading is only justified when it explains clearly MORE of the sentence than the whole-sentence reading did
          if best_h and (h.coverage or 0) < (best_h.coverage or 0) + 0.15 then
            h.factors[#h.factors + 1] = { name = "suffix_explains_no_more", v = -1.0, note = "the clause reading does not explain more of the sentence than the whole-sentence reading" }
            h.score = h.score - 1.0
          end
          if meter then meter:tick("hypotheses", 1) end
          all[#all + 1] = h
        end
      end
    end
  end
  if ctx.flags and ctx.flags.no_hypotheses then
    -- ablation: commit to the first hypothesis generated (no competition, no ambiguity retention)
    local first = all[1]
    all = first and { first } or {}
  end
  local sel = H.select(states[1] or {}, ctx, all)
  -- the state that owns the winning hypothesis (it carries chunks used for rendering)
  local top = sel.ranked[1]
  local S = top and states[top.cover_index] or states[1]
  if top then
    H.rebind(S, ctx, top)   -- NP bindings are shared between hypotheses: restore the winner's own before rendering / auditing
    sel = H.select(S, ctx, all)
    top = sel.ranked[1]
  end
  local amb = top and H.ambiguity(S, ctx, sel) or { state = "unresolvable", points = {} }
  if ctx.flags and ctx.flags.no_hypotheses and top then amb = { state = "resolved", points = {} } end
  return { sentence = sent, S = S, states = states, covers = covers, sel = sel, ranked = sel.ranked, rejected = sel.rejected, top = top,
    ambiguity = amb, seg_cons = S and S.seg_cons or nil, n_hyps = #all }
end

---------------------------------------------------------------- rendering
local function factor_list(h)
  local out = {}
  for _, f in ipairs(h.factors) do out[#out + 1] = { factor = f.name, value = U.round(f.v, 3), note = f.note } end
  return out
end

local function relation_info(S, h)
  if not h.rel_obj then return nil end
  local r = h.rel_obj
  return { id = r.id, label = r.label, from_type = r.from, to_type = r.to, derived_from = r.derived, kind_modifier = h.kind_mod, lexicalization = r.source,
    attribute = r.attr or nil, derived_via = h.derived_via }
end

local function filter_to_constraint(S, f)
  if f.kind == "temporal_relation" then
    local ex = f.expr
    return { kind = "temporal", relation = f.rel, via = f.via, target_role = f.role, op = ex.op, eff_lo = ex.eff_lo, eff_hi = ex.eff_hi, text = ex.text, polarity = "positive" }
  elseif f.kind == "relation" then
    return { kind = "relation", relation = f.rel, target_role = f.target_role, value = ref(S, f.value), polarity = f.polarity or "positive", temporal_scope = f.adv }
  elseif f.kind == "geo" then
    return { kind = "geographic", prep = f.prep, value = ref(S, f.value), polarity = "positive" }
  elseif f.kind == "has" then
    return { kind = "has", value = ref(S, f.value), polarity = "positive" }
  end
  return { kind = f.kind }
end

local function describe_target(t)
  if not t then return nil end
  local out = { text = t.text, scope = t.scope, type = t.type, plural = t.plural, superlative = t.superlative, count = t.count, pronoun = t.pron }
  if t.cands then out.candidates = U.map(t.cands, function(c) return { id = c.id, type = c.type } end) end
  if t.of then out.of = describe_target(t.of) end
  if t.possessor then out.possessor = describe_target(t.possessor) end
  return out
end

function Sem.render(res, ctx)
  local top = res.top
  local S = res.S
  local interp = { schema = "nlu.sem/1" }
  local sent = res.sentence
  interp.sentence = { id = sent.id, text = S and S.an.original:sub(sent.s, sent.e) or "", s = sent.s, e = sent.e, terminal = sent.terminal }
  if not top then
    interp.status = "no_interpretation"
    interp.speech_act = (sent.question_mark and "question") or "unknown"
    interp.intent = "unknown"
    interp.ambiguity = { state = "unresolvable", points = {} }
    interp.hypotheses = {}
    interp.rejected_hypotheses = U.map(res.rejected or {}, function(h) return { summary = H.summarize(S, h), veto = h.veto, frame = h.frame } end)
    interp.unexplained = {}
    interp.constraints = { positive = {}, negative = {}, preferences = {}, restrictions = {}, temporal = {}, geographic = {}, source = {} }
    if S and S.seg_cons then
      for _, n in ipairs(S.seg_cons.negative) do interp.constraints.negative[#interp.constraints.negative + 1] = { cue = n.cue, text = n.scope_text, target = describe_target(n.target) } end
    end
    interp.requires_external_evidence = false
    interp.reasons = { "no construction matched the sentence" }
    return interp
  end
  interp.status = "ok"
  interp.speech_act = top.speech_act
  -- a question put politely ("Could you tell me who ...", "I want to know ...") is a request for the answer
  if interp.speech_act == "question" and S.wrapper then
    for _, k in ipairs(S.wrapper.kinds) do if k == "polite_question" or k == "request_open" then interp.speech_act = "request" end end
  end
  interp.intent, interp.op, interp.frame = top.intent, top.op, top.frame
  interp.wrapper = (S.wrapper and #S.wrapper.kinds > 0) and { kinds = S.wrapper.kinds, polite = S.wrapper.polite } or nil
  interp.relation = relation_info(S, top)
  if S.topic then
    H.bind_np(S, ctx or {}, S.topic, nil, nil, "topic")
    interp.topic = ref(S, S.topic)
  end
  interp.polarity = top.polarity
  interp.roles = {}
  for role, np in pairs(top.roles) do interp.roles[role] = ref(S, np) end
  -- the asked role carries the wh-noun when there is one ("Which claims ..."): it constrains the answer, it is not a known argument
  if top.wh and top.wh.np and not top.wh.relnoun and top.ask and not interp.roles[top.ask] then
    interp.roles[top.ask] = ref(S, top.wh.np)
    interp.roles[top.ask].asked = true
  end
  if top.rel then
    -- the answer type is the narrower of the wh-type ("who" -> agent) and the relation's range type (person)
    local answer_type = top.wh_type or top.ask_type
    if top.wh_type and top.ask_type and S.lex:compat(top.ask_type, top.wh_type) >= 0.9 then answer_type = top.ask_type end
    interp.query = { known_role = top.known_role, ask = top.ask, answer_type = answer_type, relation_answer_type = top.ask_type,
      answer_form = top.answer_form, dimension = top.dimension, count = top.count_target or nil }
    if top.wh then interp.query.wh = top.wh.wh end
    if top.chain then
      interp.query.chain, interp.query.steps = {}, {}
      for i, st in ipairs(top.chain) do
        interp.query.chain[#interp.query.chain + 1] = st.rel
        interp.query.steps[#interp.query.steps + 1] = { index = i, relation = st.rel, known_role = st.known_role, known = ref(S, st.known), ask_role = st.ask_role,
          result_var = "?" .. i, result_type = st.result_type }
      end
      interp.query.chain[#interp.query.chain + 1] = top.rel
    end
    if top.qualifier then interp.query.qualifier = { relation = top.qualifier.rel, role = top.qualifier.role, arg = ref(S, top.qualifier.np) } end
    if top.verify then interp.query.verify = { from = ref(S, top.verify.from), to = ref(S, top.verify.to) } end
  end
  if top.basis then interp.basis = ref(S, top.basis.np); interp.basis_cue = top.basis.cue end
  if top.recall then
    interp.recall = { verb = top.recall.verb, wh = top.recall.wh, participant = top.recall.participant, topic = ref(S, top.recall.topic) }
    interp.subject = interp.subject or ref(S, top.recall.topic)
  end
  if top.concept then interp.concept = ref(S, top.concept) end
  if top.subject then interp.subject = ref(S, top.subject) end
  if top.target then interp.target = ref(S, top.target) end
  if top.focus then interp.focus = ref(S, top.focus) end
  if top.object then interp.object = ref(S, top.object); interp.task_verb = top.task_verb end
  if top.items then interp.items = U.map(top.items, function(np) return ref(S, np) end); interp.dimension = top.dimension; interp.degree = top.degree end
  if top.instruction then
    local ins = top.instruction
    interp.instruction = { verb = ins.verb, act = ins.act, slot = ins.slot, value = ins.value and { year = ins.value.year, label = ins.value.label, word = ins.value.word } or nil,
      object = ref(S, ins.np), correction = ins.correction or nil, persist = ins.persist or nil }
  end
  if top.clause then
    interp.clause = { subject = ref(S, top.clause.subj), lemma = top.clause.lemma, object = ref(S, top.clause.obj), negated = top.clause.neg or nil, voice = top.clause.voice }
  end
  if top.statement then
    local st = top.statement
    interp.statement = { subject = ref(S, st.subj), lemma = st.lemma, object = ref(S, st.obj), negated = st.neg or nil }
  end
  -- constraints -------------------------------------------------------------
  local cons = { positive = {}, negative = {}, preferences = {}, restrictions = {}, temporal = {}, geographic = {}, source = {} }
  for _, f in ipairs(top.filters or {}) do cons.positive[#cons.positive + 1] = filter_to_constraint(S, f) end
  for _, t in ipairs(top.constraints.temporal or {}) do cons.temporal[#cons.temporal + 1] = t end
  for _, g in ipairs(top.constraints.geographic or {}) do cons.geographic[#cons.geographic + 1] = { prep = g.prep, value = ref(S, g.value), text = g.text } end
  for _, s in ipairs(top.constraints.source or {}) do cons.source[#cons.source + 1] = s end
  local sc = S.seg_cons
  for _, n in ipairs(sc.negative) do
    local applies = "result_set"
    if top.op == "lookup" or top.op == "verify" then applies = "answer" end
    cons.negative[#cons.negative + 1] = { cue = n.cue, text = n.scope_text, target = describe_target(n.target), applies_to = applies,
      filters = U.map(n.target.filters or {}, function(f) return filter_to_constraint(S, f) end),
      inherits_scope = (top.op == "lookup" and n.target.scope == "description") and (top.roles[top.known_role] and ref(S, top.roles[top.known_role]).text) or nil }
  end
  for _, n in ipairs(sc.preferences) do
    cons.preferences[#cons.preferences + 1] = { cue = n.cue, text = n.scope_text, target = describe_target(n.target),
      filters = U.map(n.target.filters or {}, function(f) return filter_to_constraint(S, f) end), strength = "soft" }
  end
  for _, n in ipairs(sc.restrictions) do
    cons.restrictions[#cons.restrictions + 1] = { cue = n.cue, text = n.scope_text, resource = n.resource, label = n.label, qualifiers = n.qualifiers, mode = "only" }
  end
  -- a labelled source ("the 2020 dataset") also fixes the state of the world being asked about, softly and with provenance
  if #cons.temporal == 0 then
    for _, s in ipairs(cons.source) do
      if s.label_year then
        cons.temporal[#cons.temporal + 1] = { kind = "as_of", year = s.label_year, text = s.label, role = "derived", basis = "source_label", strength = "soft",
          eff_lo = s.label_year * 10000 + 101, eff_hi = s.label_year * 10000 + 1231 }
        top.temporal_scope = top.temporal_scope or "as_of_source"
        break
      end
    end
  end
  interp.constraints = cons
  if top.ordering then interp.ordering = top.ordering end
  interp.temporal_scope = top.temporal_scope or ((#cons.temporal == 0) and (top.op == "lookup" or top.op == "describe") and "current_unspecified") or nil
  -- grammatical tense of the question's own predicate ("was the capital" -> past); "did" is neutral
  do
    local past = false
    for k in pairs(top.used) do
      local c = S.chunks[k]
      if c and c.single then
        local f = c.unit.form
        if f == "was" or f == "were" or f == "had" then past = true end
      end
    end
    interp.tense = past and "past" or "present"
  end
  interp.persist = top.persist or nil
  interp.unexplained = U.map(top.unexplained or {}, function(k) return S.chunks[k].text end)
  -- context dependencies -----------------------------------------------------
  local deps = {}
  local function scan_dep(np)
    if not np then return end
    local person = np.pron and tostring(np.pron.feats and np.pron.feats.person or "3")
    if np.head_kind == "pronoun" and person ~= "1" and person ~= "2" and not (np.bound and (np.bound.deictic or np.bound.expletive or np.bound.indefinite)) then deps[#deps + 1] = { kind = "pronoun", text = P.span_text(S, np), pronoun = np.pron.form } end
    if np.backref then deps[#deps + 1] = { kind = "backref", text = P.span_text(S, np) } end
    if np.ordinal and np.head_kind ~= "temporal" then deps[#deps + 1] = { kind = "ordinal_reference", text = P.span_text(S, np), ordinal = np.ordinal } end
    if np.of_arg then scan_dep(np.of_arg) end
    if np.possessor then scan_dep(np.possessor) end
  end
  for _, np in pairs(top.roles) do scan_dep(np) end
  scan_dep(top.concept); scan_dep(top.subject); scan_dep(top.target); scan_dep(top.focus); scan_dep(top.object)
  if top.recall then deps[#deps + 1] = { kind = "conversation_history", text = interp.sentence.text } end
  if top.basis then scan_dep(top.basis.np) end
  if top.intent == "comparison" and (not top.items or #top.items < 2) then deps[#deps + 1] = { kind = "comparison_set", text = interp.sentence.text } end
  for _, it in ipairs(top.items or {}) do scan_dep(it) end
  if top.statement then scan_dep(top.statement.subj); scan_dep(top.statement.obj) end
  if top.instruction then scan_dep(top.instruction.np) end
  if top.clause then scan_dep(top.clause.subj); scan_dep(top.clause.obj) end
  interp.dependencies = deps
  interp.requires_external_evidence = top.requires_evidence == true
  interp.requires_context = top.requires_context or nil
  -- hypotheses with provenance -------------------------------------------------
  interp.hypotheses = {}
  for i, h in ipairs(res.ranked) do
    if i > 6 then break end
    interp.hypotheses[#interp.hypotheses + 1] = { rank = i, summary = H.summarize(S, h), p = U.round(h.p, 4), score = U.round(h.score, 3), frame = h.frame,
      coverage = U.round(h.coverage or 0, 3), factors = factor_list(h), agreeing_frames = h.agreeing_frames }
  end
  interp.rejected_hypotheses = {}
  for i, h in ipairs(res.rejected) do
    if i > 8 then break end
    interp.rejected_hypotheses[#interp.rejected_hypotheses + 1] = { summary = H.summarize(S, h), frame = h.frame, veto = h.veto }
  end
  interp.ambiguity = res.ambiguity
  interp.confidence = { semantic_raw = U.round(top.p, 4), coverage = U.round(top.coverage or 0, 3) }
  do
    -- lexical evidence about the surface: words the lexicon does not know (lower-case ones are the usual symptom of a misspelling)
    local ua, ub = sentence_unit_range(S.an, res.sentence.id)
    local unk_lower, unk_cap = 0, 0
    if ua then
      for k = ua, ub do
        local u = S.an.units[k]
        if u.unknown then if u.cap then unk_cap = unk_cap + 1 else unk_lower = unk_lower + 1 end end
      end
    end
    interp.lexical = { unknown_lowercase = unk_lower, unknown_capitalised = unk_cap }
  end
  if S.repairs then interp.repairs = U.map(S.repairs, function(r) return { kind = r.kind, from = r.from, to = r.to, word = r.word, dist = r.dist } end) end
  -- provenance: the computed factors of the winning hypothesis, plus explicit rejections
  local prov = {}
  for _, f in ipairs(top.factors) do prov[#prov + 1] = { step = f.name, detail = f.note, value = U.round(f.v, 3) } end
  for _, rj in ipairs(interp.rejected_hypotheses) do prov[#prov + 1] = { step = "rejected", detail = rj.summary .. " -- " .. tostring(rj.veto) } end
  interp.provenance = prov
  return interp
end

return Sem

end

package.preload["asi.nlu.spell"] = function(...)
-- asi.nlu.spell: conservative typo candidates via a symmetric-delete index (prefix-bounded).
-- It NEVER rewrites input: it returns alternatives with distances; the semantic layer decides whether to use them.
-- Known words are never "corrected". Words shorter than 4 code points get no suggestions.
local U = require("asi.nlu.util")

local Spell = {}
Spell.__index = Spell

local PREFIX = 7

local function len(s) return utf8.len(s) or #s end

local function char_deletes(s, maxd, out, seen)
  out = out or {}
  seen = seen or {}
  local function rec(str, d)
    if d == 0 then return end
    local n = len(str)
    for i = 1, n do
      local a = utf8.offset(str, i)
      local b = utf8.offset(str, i + 1) or (#str + 1)
      local del = str:sub(1, a - 1) .. str:sub(b)
      if not seen[del] then seen[del] = true; out[#out + 1] = del; rec(del, d - 1) end
    end
  end
  seen[s] = true
  out[#out + 1] = s
  rec(s, maxd)
  return out
end

local function max_edit_for(n)
  if n < 4 then return 0 elseif n <= 7 then return 1 else return 2 end
end

function Spell.new(opts)
  opts = opts or {}
  return setmetatable({ words = {}, index = {}, n = 0, kinds = {} }, Spell)
end

function Spell:known(form)
  return self.words[form] ~= nil or (self.parent ~= nil and self.parent:known(form))
end

-- a Spell may chain to a parent (core vocabulary) so dataset overlays add words without copying the index
function Spell:chain(parent) self.parent = parent; return self end

function Spell:add(form, weight, kind)
  self.rev = (self.rev or 0) + 1
  if not form or form == "" then return end
  local cur = self.words[form]
  if cur then
    if weight and weight > cur then self.words[form] = weight end
    if kind and not self.kinds[form] then self.kinds[form] = kind end
    return
  end
  self.words[form] = weight or 1
  self.kinds[form] = kind
  self.n = self.n + 1
  local n = len(form)
  if n < 3 then return end
  local pre = form
  if n > PREFIX then pre = form:sub(1, utf8.offset(form, PREFIX + 1) - 1) end
  for _, d in ipairs(char_deletes(pre, 2)) do
    local bucket = self.index[d]
    if not bucket then bucket = {}; self.index[d] = bucket end
    bucket[#bucket + 1] = form
  end
end

function Spell:add_all(list, weight, kind)
  for _, w in ipairs(list) do self:add(w, weight, kind) end
end

function Spell:_cands(form, maxd, deletes, cands, seen)
  for _, d in ipairs(deletes) do
    local bucket = self.index[d]
    if bucket then
      for _, w in ipairs(bucket) do
        if not seen[w] then
          seen[w] = true
          local dist = U.osa(form, w, maxd)
          if dist <= maxd then
            local c = { form = w, dist = dist, weight = self.words[w], kind = self.kinds[w] }
            c.first_same = form:sub(1, 1) == w:sub(1, 1) -- typos rarely hit the first letter
            cands[#cands + 1] = c
          end
        end
      end
    end
  end
  if self.parent then self.parent:_cands(form, maxd, deletes, cands, seen) end
end

-- returns up to opts.limit candidates {form, dist, weight, kind, first_same, conf}
function Spell:rev_total()
  local r, sp = 0, self
  while sp do r = r + (sp.rev or 0); sp = sp.parent end
  return r
end

function Spell:suggest(form, o)
  o = o or {}
  local n = len(form)
  local maxd = o.max_edit or max_edit_for(n)
  if maxd == 0 or self:known(form) then return {} end
  -- memoised per (form, edit budget, limit); the cache is dropped when any dictionary in the chain changes, and bounded
  local rev = self:rev_total()
  if self._cache_rev ~= rev or (self._cache_n or 0) > 4096 then self._cache, self._cache_n, self._cache_rev = {}, 0, rev end
  local ck = form .. "\0" .. maxd .. "\0" .. (o.limit or 3)
  local hit = self._cache[ck]
  if hit then return hit end
  local out = self:_suggest(form, n, maxd, o)
  self._cache[ck] = out
  self._cache_n = self._cache_n + 1
  return out
end

function Spell:_suggest(form, n, maxd, o)
  local pre = form
  if n > PREFIX then pre = form:sub(1, utf8.offset(form, PREFIX + 1) - 1) end
  local cands = {}
  self:_cands(form, maxd, char_deletes(pre, maxd), cands, {})
  table.sort(cands, function(a, b)
    if a.dist ~= b.dist then return a.dist < b.dist end
    if a.first_same ~= b.first_same then return a.first_same end
    if a.weight ~= b.weight then return a.weight > b.weight end
    return a.form < b.form
  end)
  local out = {}
  local lim = o.limit or 3
  for i = 1, math.min(lim, #cands) do
    local c = cands[i]
    -- raw (uncalibrated) confidence: unique best at its distance, first letter preserved, longer words
    local rivals = 0
    for j = 1, #cands do if j ~= i and cands[j].dist <= c.dist then rivals = rivals + 1 end end
    local conf = 0.9 - 0.3 * (c.dist - 1) - 0.15 * math.min(rivals, 3) - (c.first_same and 0 or 0.2)
    if n <= 4 then conf = conf - 0.2 end
    c.conf = U.clamp(conf, 0.05, 0.95)
    out[#out + 1] = c
  end
  return out
end

return Spell

end

