      elseif PAST_WORDS[w] and w ~= "old" and w ~= "once" and w ~= "ex" and w ~= "past" and w ~= "earlier" then units[idx].temporal_scope = "past"
      elseif FUTURE_WORDS[w] then units[idx].temporal_scope = "future" end
    end
  end

