    before = "before", ["until"] = "until", till = "until", by = "by", ["up"] = nil,
    after = "after", since = "since", following = "after", from = "from",
    around = "approx", circa = "approx", c = "approx", approximately = "approx", about = "approx",
    ["between"] = "between",
