        -- find the closing X "to|and|until|through|-" Y
        local nxt = exprs[k + 1]
        if nxt and nxt.u1 > ex.u2 then
          local between = {}
          for z = ex.u2 + 1, nxt.u1 - 1 do between[#between + 1] = units[z].form end
          local joiner = table.concat(between, " ")
          local pre = units[nxt.u1].pre or ""
          local ok = (op == "between" and joiner == "and") or (op == "from" and (joiner == "to" or joiner == "until" or joiner == "till" or joiner == "through" or joiner == "and"))
            or (joiner == "" and pre:find("dash") ~= nil)
          if ok and has_date_bounds(ex) and has_date_bounds(nxt) then
            ex.range_end = nxt
            ex.hi = nxt.hi
            ex.kind = "interval"
            ex.u2 = nxt.u2; ex.e = nxt.e
            ex.text = an.original:sub(ex.s, ex.e)
            ex.op = op == "between" and "between" or "from_to"
            ex.u1 = op_u; ex.s = units[op_u].s; ex.text = an.original:sub(ex.s, ex.e)
            table.remove(exprs, k + 1)
            for z = ex.u1, ex.u2 do used[z] = ex end
            ex.role = "scope"
            ex.eff_lo, ex.eff_hi = ex.lo, ex.hi
            goto continue
          end
        end
        ex.op = (op == "between") and "between_open" or "from"
        ex.op_u = op_u
      elseif op then
        ex.op = op; ex.op_u = op_u
        ex.u1 = op_u; ex.s = units[op_u].s; ex.text = an.original:sub(ex.s, ex.e)
        for z = ex.u1, ex.u2 do used[z] = ex end
      else
        -- bare dash range "2010-2015"
        local nxt = exprs[k + 1]
        if nxt and nxt.u1 == ex.u2 + 1 and has_date_bounds(ex) and has_date_bounds(nxt) and units[nxt.u1].pre and units[nxt.u1].pre:find("dash") and (ex.kind == "year" or ex.kind == "date") then
          ex.range_end = nxt; ex.hi = nxt.hi; ex.kind = "interval"; ex.u2 = nxt.u2; ex.e = nxt.e
          ex.text = an.original:sub(ex.s, ex.e); ex.op = "from_to"; ex.role = "scope"
          ex.eff_lo, ex.eff_hi = ex.lo, ex.hi
          table.remove(exprs, k + 1)
          for z = ex.u1, ex.u2 do used[z] = ex end
          goto continue
        end
      end
      -- derive the effective interval from the operator
      if ex.kind ~= "interval" and has_date_bounds(ex) then
        local o = ex.op
        ex.eff_lo, ex.eff_hi = ex.lo, ex.hi
        if o == "before" then ex.eff_lo, ex.eff_hi = nil, ex.lo - 1
        elseif o == "until" or o == "by" then ex.eff_lo, ex.eff_hi = nil, ex.hi
        elseif o == "after" then ex.eff_lo, ex.eff_hi = ex.hi + 1, nil
        elseif o == "since" or o == "from" then ex.eff_lo, ex.eff_hi = ex.lo, nil end
      elseif ex.kind == "interval" then ex.eff_lo, ex.eff_hi = ex.lo, ex.hi end
      if ex.kind == "year" and ex.role == "ambiguous" and ex.op and ex.op ~= "approx" then ex.role = "scope"; ex.confidence = 0.9 end
    end
    ::continue::
    k = k + 1
  end

  -- "approx" widens year-precision points by +-2 years (documented heuristic)
  for _, ex in ipairs(exprs) do
    if ex.op == "approx" and ex.eff_lo and ex.eff_hi and ex.precision == "year" then
      ex.eff_lo = ex.eff_lo - 20000; ex.eff_hi = ex.eff_hi + 20000; ex.widened = true
    end
  end

  an.temporal = exprs
  an.temporal_now = now
  return exprs, numbers
end

return T

end

package.preload["asi.nlu.textutil"] = function(...)
-- asi.nlu.textutil: index-side tokenisation shared by memory and dataset retrieval.
-- This is NOT the interpreter's lexer (asi.nlu.lex keeps offsets, case and ambiguity for understanding); it produces folded, lightly stemmed
-- terms with positions for retrieval.  Non-ASCII bytes are treated as word characters and folded with the documented unicode subset.
local UC = require("asi.nlu.unicode")

local TU = {}

TU.STOP = {}
for w in ([[the a an of and or to in on at by for with is are was were be been being it its as that this which what who whom how do does did
  i you we me my your our please can could would should will shall may might from into than then there their they them he she his her not no]]):gmatch("%S+") do
  TU.STOP[w] = true
end

-- deterministic light stemmer: inflection only (decided/decide/deciding -> decid), applied identically to documents and queries
function TU.stem(w)
  if #w <= 3 then return w end
  local s = w
  if s:match("ies$") and #s > 4 then s = s:sub(1, -4) .. "y"
  elseif s:match("ied$") and #s > 4 then s = s:sub(1, -4) .. "y"
  elseif s:match("ing$") and #s > 5 then s = s:sub(1, -4)
  elseif s:match("ed$") and #s > 4 then s = s:sub(1, -3)
  elseif s:match("es$") and #s > 4 then s = s:sub(1, -3)
  elseif s:match("s$") and not s:match("ss$") and #s > 3 then s = s:sub(1, -2) end
  s = s:gsub("e$", "")
  return s
end

-- tokens(text, {keep_stop, raw}) -> list of {t = term, w = folded word, pos = ordinal, s = byte start, e = byte end}
function TU.tokens(text, opts)
  opts = opts or {}
  local out = {}
  local pos = 0
  local i, n = 1, #text
  while i <= n do
    local s, e = text:find("[%w\128-\255][%w\128-\255]*", i)
    if not s then break end
    local w = text:sub(s, e)
    if w:find("[\128-\255]") then w = UC.fold(w) else w = w:lower() end
    -- possessive / clitic: "France's" -> "france"
    local nxt = text:sub(e + 1, e + 2)
    if nxt == "'s" or nxt == "\226\128\153" then end
    pos = pos + 1
    if opts.keep_stop or not TU.STOP[w] then
      out[#out + 1] = { t = opts.raw and w or TU.stem(w), w = w, pos = pos, s = s, e = e }
    end
    i = e + 1
  end
  return out
end

function TU.terms(text, opts)
  local out = {}
  for _, t in ipairs(TU.tokens(text, opts)) do out[#out + 1] = t.t end
  return out
end

return TU

end

