  { "D", "ĎĐÐ" }, { "d", "ďđð" }, { "E", "ÈÉÊËĒĔĖĘĚ" }, { "e", "èéêëēĕėęě" }, { "G", "ĜĞĠĢ" }, { "g", "ĝğġģ" },
