  { "J", "Ĵ" }, { "j", "ĵ" }, { "K", "Ķ" }, { "k", "ķĸ" }, { "L", "ĹĻĽĿŁ" }, { "l", "ĺļľŀł" },
  { "N", "ÑŃŅŇŊ" }, { "n", "ñńņňŋ" }, { "'n", "ŉ" }, { "O", "ÒÓÔÕÖØŌŎŐ" }, { "o", "òóôõöøōŏő" },
